def database_get_daily_counter(storage_key: str, counter_type: str) -> int:
    if not ACCOUNT_STATE_DB_READY:
        target = DAILY_BRUSH_COUNTS if counter_type == "brushYellow" else DAILY_DUNGEON_COUNTS
        return int(target.get(storage_key, 0))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        row = connection.execute(
            """
            SELECT count FROM daily_counters
            WHERE storage_key=? AND counter_type=?
            """,
            (str(storage_key), str(counter_type)),
        ).fetchone()
    return int(row["count"] or 0) if row else 0


def database_increment_daily_counter(storage_key: str, counter_type: str) -> int:
    if not ACCOUNT_STATE_DB_READY:
        raise RuntimeError("账号状态数据库尚未初始化")
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute("BEGIN IMMEDIATE")
        try:
            connection.execute(
                """
                INSERT INTO daily_counters(storage_key, counter_type, count, updated_at)
                VALUES (?, ?, 1, ?)
                ON CONFLICT(storage_key, counter_type) DO UPDATE SET
                    count=daily_counters.count + 1,
                    updated_at=excluded.updated_at
                """,
                (str(storage_key), str(counter_type), now_ms()),
            )
            row = connection.execute(
                """
                SELECT count FROM daily_counters
                WHERE storage_key=? AND counter_type=?
                """,
                (str(storage_key), str(counter_type)),
            ).fetchone()
            connection.execute("COMMIT")
        except Exception:
            connection.execute("ROLLBACK")
            raise
    return int(row["count"] or 0)


