def normalize_military_future_settings(feature: str, settings: Any) -> dict[str, Any]:
    key = str(feature or "").strip()
    if key not in MILITARY_FUTURE_READINESS:
        raise RuntimeError(f"未知军事功能：{feature}")
    if not isinstance(settings, dict):
        settings = {}
    # 这里只做轻量规范化：前端控件的语义先完整落库，等抓包充足后再接真实协议。
    rows = settings.get("rows")
    if isinstance(rows, list):
        next_rows = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            general_ids = row.get("generalIds")
            if isinstance(general_ids, list):
                gids = [str(x) for x in general_ids if str(x or "").strip()]
            elif row.get("generalId"):
                gids = [str(row.get("generalId"))]
            else:
                gids = []
            next_row = dict(row)
            if key in {"dungeon", "lossless"}:
                next_row["enabled"] = row.get("enabled") is True
            next_row["generalIds"] = list(dict.fromkeys(gids))
            next_row["generalId"] = next_row["generalIds"][0] if next_row["generalIds"] else ""
            next_rows.append(next_row)
        settings = dict(settings)
        settings["rows"] = next_rows
    if key == "dungeon":
        settings = dict(settings)
        # Backward-compatible alias: older clients may send clearStages=true.
        mode_value = settings.get("mode")
        if mode_value in (None, "") and "clearStages" in settings:
            mode_value = settings.get("clearStages")
        settings["mode"] = normalize_dungeon_mode(mode_value)
    return settings


def printable(bs: bytes, limit: int = 512) -> str:
    s = bs.decode("utf-8", errors="ignore")
    s = "".join(ch if (0x20 <= ord(ch) <= 0x7e or "\u4e00" <= ch <= "\u9fff") else " " for ch in s)
    return re.sub(r"\s+", " ", s).strip()[:limit]


def recover_generals_from_8004(hexstr: str) -> list[dict[str, Any]]:
    bs = bytes.fromhex(hexstr)
    res = []
    BODY_LEN = 114
    # 体力/体力上限字段是无符号 16 位值，不是固定的 0~300。1608600
    # 当前 0x8004 响应中已有真实将领的体力上限为 305；原先的 300
    # 上限会把这些合法将领整条记录判成无效，导致英雄页少显示将领。
    # 这里使用字段本身的完整取值范围，不再引入会随等级失效的人为上限。
    GENERAL_ENERGY_WIRE_MAX = 0xFFFF
    REPEATED_ID_OFFSET = 0x3a
    PROFESSION_OFFSET = 0x03
    GROWTH_OFFSET = 0x06
    LEVEL_OFFSET = 0x08
    ATTACK_OFFSET = 0x17
    DEFENSE_OFFSET = 0x19
    ENERGY_OFFSET = 0x1b
    ENERGY_LIMIT_OFFSET = 0x1d
    TROOP_LIMIT_OFFSET = 0x23
    LOYALTY_OFFSET = 0x27
    LOYALTY_LIMIT_OFFSET = 0x28
    PLACE_ID_OFFSET = 0x32
    # 原客户端 Lo/a.b6 解析 0x8215/0x8004 将领体时：
    #   body+0x56 -> Lo/a.Vo，将领当前细状态，界面用它判断空闲/出征/修炼等；
    #   body+0x58 是 Po 的高字节，实测空闲结构也常为 0，不能当状态。
    HERO_STATUS_OFFSET = 0x56
    LEGACY_STATUS58_OFFSET = 0x58
    S5_ENTRY_LEN = 21

    def u8(off: int) -> int | None:
        return bs[off] if 0 <= off < len(bs) else None

    def u16(off: int) -> int | None:
        return int.from_bytes(bs[off:off + 2], "big") if 0 <= off <= len(bs) - 2 else None

    def u32(off: int) -> int | None:
        return int.from_bytes(bs[off:off + 4], "big") if 0 <= off <= len(bs) - 4 else None

    def i64(off: int) -> int | None:
        return int.from_bytes(bs[off:off + 8], "big", signed=True) if 0 <= off <= len(bs) - 8 else None

    def profession_label(code: int | None) -> str:
        return {0: "步将", 1: "弓将", 2: "骑将", 4: "勇士"}.get(code, "" if code is None else f"职业{code}")

    def looks_like_body(body_off: int, gid: int) -> bool:
        if body_off + BODY_LEN > len(bs):
            return False
        # Some live 0x8004 packets contain a valid general body whose
        # embedded/repeated ID is offset from the preceding name record.
        # Keep the repeated ID as evidence, but do not discard an otherwise
        # structurally valid owned-general record because of that mismatch.
        if bs[body_off + 112] != 0xFF or bs[body_off + 113] != 0xFF:
            return False
        profession = u8(body_off + PROFESSION_OFFSET)
        growth = u16(body_off + GROWTH_OFFSET)
        level = u8(body_off + LEVEL_OFFSET)
        tili = u16(body_off + ENERGY_OFFSET)
        tili_limit = u16(body_off + ENERGY_LIMIT_OFFSET)
        troop_limit = u32(body_off + TROOP_LIMIT_OFFSET)
        loyalty = u8(body_off + LOYALTY_OFFSET)
        loyalty_limit = u8(body_off + LOYALTY_LIMIT_OFFSET)
        hero_status = u8(body_off + HERO_STATUS_OFFSET)
        legacy_status58 = u8(body_off + LEGACY_STATUS58_OFFSET)
        return (
            profession is not None and 0 <= profession <= 8 and
            growth is not None and 1 <= growth <= 200 and
            level is not None and 1 <= level <= 200 and
            tili is not None and 0 <= tili <= GENERAL_ENERGY_WIRE_MAX and
            tili_limit is not None and 1 <= tili_limit <= GENERAL_ENERGY_WIRE_MAX and
            troop_limit is not None and 0 <= troop_limit <= 50000 and
            loyalty is not None and 0 <= loyalty <= 200 and
            loyalty_limit is not None and 1 <= loyalty_limit <= 200 and
            hero_status is not None and 0 <= hero_status <= 16 and
            legacy_status58 is not None and 0 <= legacy_status58 <= 16
        )

    # The name is a user-editable label, not an identity field.  Do not
    # reject a structurally valid general because the player used a space,
    # punctuation, Latin text, or a name without Chinese characters.
    GENERAL_NAME_WIRE_MAX = 64
    for pos in range(8, len(bs) - 2):
        ln = int.from_bytes(bs[pos:pos + 2], "big")
        if not (1 <= ln <= GENERAL_NAME_WIRE_MAX) or pos + 2 + ln > len(bs):
            continue
        raw_name = bs[pos + 2:pos + 2 + ln]
        try:
            name = raw_name.decode("utf-8").strip()
        except UnicodeDecodeError:
            continue
        if not name:
            continue
        if any(ord(ch) < 0x20 or ord(ch) == 0x7F for ch in name):
            continue
        gid = int.from_bytes(bs[pos - 8:pos], "big")
        if gid <= 0:
            continue
        body_off = pos + 2 + ln
        item = {"id": gid, "idHex": f"{gid:016x}", "name": name, "offset": pos, "nameUtf8Offset": pos}
        if looks_like_body(body_off, gid):
            place_id = i64(body_off + PLACE_ID_OFFSET)
            profession = u8(body_off + PROFESSION_OFFSET)
            hero_status = u8(body_off + HERO_STATUS_OFFSET)
            status_text = general_status_text_from_code(hero_status)
            item.update({
                "source": "state8004-binary-jiangling",
                "layout": "i64_id_u16_name_114_body_b6_common_v20260708b",
                "bodyOffset": body_off,
                "repeatedIdHex": bs[body_off + REPEATED_ID_OFFSET:body_off + REPEATED_ID_OFFSET + 8].hex(),
                "repeatedIdMatches": bs[body_off + REPEATED_ID_OFFSET:body_off + REPEATED_ID_OFFSET + 8] == gid.to_bytes(8, "big", signed=False),
                "status": hero_status,
                "heroStatusCode": hero_status,
                "stateCode56": hero_status,
                "statusText": status_text,
                "displayStatus": status_text,
                "busy": False if status_text == "闲" else True,
                "rawStatus58": u8(body_off + LEGACY_STATUS58_OFFSET),
                "status58": u8(body_off + LEGACY_STATUS58_OFFSET),
                "energyReliable": True,
                "tili": u16(body_off + ENERGY_OFFSET),
                "tiliLimit": u16(body_off + ENERGY_LIMIT_OFFSET),
                "level": u8(body_off + LEVEL_OFFSET),
                "growth": u16(body_off + GROWTH_OFFSET),
                "kind": profession_label(profession),
                "professionCode": profession,
                "gongji": u16(body_off + ATTACK_OFFSET),
                "fangyu": u16(body_off + DEFENSE_OFFSET),
                "loyalty": u8(body_off + LOYALTY_OFFSET),
                "loyaltyLimit": u8(body_off + LOYALTY_LIMIT_OFFSET),
                "troopLimit": u32(body_off + TROOP_LIMIT_OFFSET),
                "daiBingLimit": u32(body_off + TROOP_LIMIT_OFFSET),
            })
            if place_id and place_id > 0:
                item.update({"placeID": place_id, "fiefId": place_id, "fiefIdHex": f"{place_id:016x}"})
        else:
            # 兼容旧的弱扫描候选；不要把名字后 byte 误当可靠体力。
            item.update({
                "source": "state8004-binary-name-candidate",
                "status": bs[pos + 2 + ln] if pos + 2 + ln < len(bs) else None,
                "tili": None,
                "energyReliable": False,
            })
        res.append(item)
    # Prefer a verified body over a weak name-only hit when the same ID is
    # encountered more than once while scanning the binary payload.
    by_id: dict[int, dict[str, Any]] = {}
    for g in res:
        # General IDs are not globally six/seven digit values. Newer records
        # can use IDs such as 292989, so validate the structured body above
        # instead of imposing an arbitrary lower bound.
        if not (0 < g["id"] <= 0x7FFFFFFFFFFFFFFF):
            continue
        previous = by_id.get(int(g["id"]))
        if previous is None or (
            g.get("source") == "state8004-binary-jiangling"
            and previous.get("source") != "state8004-binary-jiangling"
        ):
            by_id[int(g["id"])] = g
    out = list(by_id.values())
    # Only structured records with the verified 114-byte body are real owned generals.
    # Name-only hits can be famous-general card descriptions inside 0x8004, e.g. "少·刘协之".
    final = [g for g in out if g.get("source") == "state8004-binary-jiangling"]
    if not final:
        final = [g for g in res if g.get("source") == "state8004-binary-jiangling"]

    # Recover the following Lo/a.S5 troop table: count + repeated
    # (generalId, generalId, soldierTypeCode, currentSoldierCount) entries.
    ids = {int(g["id"]) for g in final}
    min_off = max((int(g.get("bodyOffset", 0)) + BODY_LEN for g in final if g.get("bodyOffset")), default=0)
    best: tuple[int, list[dict[str, Any]]] | None = None
    for pos in range(max(0, min_off), len(bs)):
        count = bs[pos]
        if not (1 <= count <= 30) or pos + 1 + count * S5_ENTRY_LEN > len(bs):
            continue
        assignments = []
        plausible = True
        for idx in range(count):
            off = pos + 1 + idx * S5_ENTRY_LEN
            nm = i64(off); om = i64(off + 8); typ = u8(off + 16); cnt = int.from_bytes(bs[off + 17:off + 21], "big", signed=True)
            if nm is None or om is None or typ is None or not (0 <= typ <= 32) or not (0 <= cnt <= 500000):
                plausible = False; break
            # Most captures repeat the same general ID in both fields. Some
            # live packets use a linked pair instead; the second ID points to
            # the owned general whose troop row should be displayed.
            assignment_id = (
                om if om in ids
                else nm if nm in ids
                else None
            )
            if assignment_id is not None:
                assignments.append({
                    "generalId": assignment_id,
                    "soldierTypeCode": typ,
                    "soldierCount": cnt,
                    "s5Offset": pos,
                    "s5Count": count,
                })
        if plausible and assignments:
            score = (len(assignments), 1 if count == len(assignments) else 0, -pos)
            if best is None or score > (len(best[1]), 1 if count == len(best[1]) else 0, -best[0]):
                best = (pos, assignments)
    if best:
        by_gid = {a["generalId"]: a for a in best[1]}
        for g in final:
            a = by_gid.get(int(g["id"]))
            if a:
                g.update({
                    "soldierTypeCode": a["soldierTypeCode"],
                    "soldierType": soldier_type_name(a["soldierTypeCode"]),
                    "soldierCount": a["soldierCount"],
                    "currentSoldierCount": a["soldierCount"],
                    "s5Offset": a["s5Offset"],
                    "s5Count": a["s5Count"],
                })
            else:
                # The troop table only contains generals that currently carry soldiers.
                # A missing row after a valid table means "无配兵", not "unknown".
                g.update({
                    "soldierTypeCode": -1,
                    "soldierType": "无配兵",
                    "soldierCount": 0,
                    "currentSoldierCount": 0,
                    "s5Offset": best[0],
                    "s5Count": len(best[1]),
                })
    return final


def parse_idle_army_from_8004(hexstr: str, generals: list[dict[str, Any]] | None = None) -> list[dict[str, Any]]:
    """Parse idle/unassigned soldiers from 0x8004.

    Correct 0x8004 fief soldier block observed in live captures is compact:
      0x1d, idleTypeCount, repeated(byte soldierType, int idleCount),
      woundedTypeCount, repeated(byte soldierType, int woundedCount).

    The older int-count/short-type table-like data later in 0x8004 belongs to other
    config/reward sections and must not be shown as role -> army.
    """
    if not hexstr:
        return []
    try:
        bs = bytes.fromhex(hexstr)
    except Exception:
        return []
    valid_codes = set(SOLDIER_CODE_NAMES.keys())

    def prev_fief_name(pos: int) -> str:
        try:
            strings = extract_utf_strings(bs[max(0, pos - 700):pos], min_len=2, max_len=40)
        except Exception:
            return ""
        for item in reversed(strings):
            text = str(item.get("text") or "")
            if any(k in text for k in ["基地", "封地", "城", "县", "郡"]):
                return text
        return ""

    candidates: list[dict[str, Any]] = []
    for marker in range(0, max(0, len(bs) - 3)):
        if bs[marker] != 0x1D:
            continue
        pos = marker + 1
        idle_type_count = bs[pos]
        pos += 1
        if not (0 <= idle_type_count <= 16):
            continue
        idle_rows: list[tuple[int, int]] = []
        ok = True
        for _ in range(idle_type_count):
            if pos + 5 > len(bs):
                ok = False
                break
            typ = bs[pos]
            amount = int.from_bytes(bs[pos + 1:pos + 5], "big", signed=True)
            pos += 5
            if typ not in valid_codes or amount < 0 or amount > 500000:
                ok = False
                break
            idle_rows.append((typ, amount))
        if not ok or pos >= len(bs):
            continue
        wounded_type_count = bs[pos]
        pos += 1
        if not (0 <= wounded_type_count <= 16):
            continue
        wounded_rows: list[tuple[int, int]] = []
        for _ in range(wounded_type_count):
            if pos + 5 > len(bs):
                ok = False
                break
            typ = bs[pos]
            amount = int.from_bytes(bs[pos + 1:pos + 5], "big", signed=True)
            pos += 5
            if typ not in valid_codes or amount < 0 or amount > 500000:
                ok = False
                break
            wounded_rows.append((typ, amount))
        if not ok:
            continue
        if not any(v for _, v in idle_rows + wounded_rows):
            continue
        fief_name = prev_fief_name(marker)
        if not fief_name:
            continue
        merged: dict[int, dict[str, Any]] = {}
        order: list[int] = []
        for typ, amount in idle_rows:
            if typ not in merged:
                merged[typ] = {
                    "soldierTypeCode": typ,
                    "soldierType": soldier_type_name(typ),
                    "idleCount": 0,
                    "count": 0,
                    "amount": 0,
                    "woundedCount": 0,
                    "hurtSoldierCount": 0,
                    "fiefName": fief_name,
                    "offset": marker,
                }
                order.append(typ)
            merged[typ]["idleCount"] += amount
            merged[typ]["count"] = merged[typ]["idleCount"]
            merged[typ]["amount"] = merged[typ]["idleCount"]
        for typ, amount in wounded_rows:
            if typ not in merged:
                merged[typ] = {
                    "soldierTypeCode": typ,
                    "soldierType": soldier_type_name(typ),
                    "idleCount": 0,
                    "count": 0,
                    "amount": 0,
                    "woundedCount": 0,
                    "hurtSoldierCount": 0,
                    "fiefName": fief_name,
                    "offset": marker,
                }
                order.append(typ)
            merged[typ]["woundedCount"] += amount
            merged[typ]["hurtSoldierCount"] = merged[typ]["woundedCount"]
        rows = [merged[t] for t in order]
        # UI's role-army page defaults to the current/base fief. Prefer the 基地 block
        # when several fief-like blocks are present.
        score = (1 if "基地" in fief_name else 0, len(rows), sum(int(r["idleCount"]) + int(r["woundedCount"]) for r in rows), -marker)
        candidates.append({"marker": marker, "fiefName": fief_name, "rows": rows, "score": score})
    if not candidates:
        return []
    # Return all fief army blocks, not only the base fief. The role -> army page
    # should show idle/wounded soldiers for every fief separately.
    out: list[dict[str, Any]] = []
    merged: dict[tuple[str, int], dict[str, Any]] = {}
    for cand in sorted(candidates, key=lambda x: int(x.get("marker") or 0)):
        for row in cand.get("rows") or []:
            key = (str(row.get("fiefName") or ""), int(row.get("soldierTypeCode") or 0))
            if key not in merged:
                item = dict(row)
                merged[key] = item
                out.append(item)
            else:
                item = merged[key]
                item["idleCount"] = int(item.get("idleCount") or 0) + int(row.get("idleCount") or 0)
                item["count"] = item["idleCount"]
                item["amount"] = item["idleCount"]
                item["woundedCount"] = int(item.get("woundedCount") or 0) + int(row.get("woundedCount") or 0)
                item["hurtSoldierCount"] = item["woundedCount"]
    return out


def extract_utf_strings(payload: bytes, *, min_len: int = 2, max_len: int = 180) -> list[dict[str, Any]]:
    strings: list[dict[str, Any]] = []
    for pos in range(0, max(0, len(payload) - 2)):
        ln = int.from_bytes(payload[pos:pos + 2], "big")
        if not (min_len <= ln <= max_len) or pos + 2 + ln > len(payload):
            continue
        raw = payload[pos + 2:pos + 2 + ln]
        try:
            text = raw.decode("utf-8")
        except Exception:
            continue
        if not any("\u4e00" <= ch <= "\u9fff" for ch in text):
            continue
        if any(ord(ch) < 0x20 and ch not in "\r\n\t" for ch in text):
            continue
        strings.append({"offset": pos, "length": ln, "text": text})
    return strings


def extract_utf_fields(payload: bytes, *, min_len: int = 1, max_len: int = 220) -> list[dict[str, Any]]:
    """Extract ordered modified-UTF-like fields, including ASCII progress values.

    0xe200 日常任务包里同一条任务通常是：
    任务文本 UTF、进度 UTF（如 0/1）、奖励 UTF（如 +10）。旧的
    extract_utf_strings 只保留中文字符串，无法拿到 0/1，所以这里保留
    ASCII 进度字段。
    """
    fields: list[dict[str, Any]] = []
    for pos in range(0, max(0, len(payload) - 2)):
        ln = int.from_bytes(payload[pos:pos + 2], "big")
        if not (min_len <= ln <= max_len) or pos + 2 + ln > len(payload):
            continue
        raw = payload[pos + 2:pos + 2 + ln]
        try:
            text = raw.decode("utf-8")
        except Exception:
            continue
        if not text:
            continue
        if any(ord(ch) < 0x20 and ch not in "\r\n\t" for ch in text):
            continue
        # Keep fields that are useful for UI/debug: Chinese labels, n/m progress,
        # signed rewards, or reward/resource text containing digits.
        useful = (
            any("\u4e00" <= ch <= "\u9fff" for ch in text)
            or re.fullmatch(r"\d+\s*/\s*\d+", text.strip())
            or re.fullmatch(r"[+-]\d+", text.strip())
            or bool(re.search(r"\d", text) and len(text) <= 80)
        )
        if useful:
            fields.append({"offset": pos, "length": ln, "text": text})
    fields.sort(key=lambda x: int(x.get("offset") or 0))
    # Remove overlapping duplicate hits caused by scanning every byte.
    deduped: list[dict[str, Any]] = []
    last_end = -1
    for item in fields:
        off = int(item["offset"])
        end = off + 2 + int(item["length"])
        if off < last_end and deduped and item["text"] == deduped[-1]["text"]:
            continue
        deduped.append(item)
        last_end = max(last_end, end)
    return deduped


def parse_e200_daily_activity(payload: bytes, source_opcode: str = "0x6200/0xe200") -> dict[str, Any]:
    fields = extract_utf_fields(payload, min_len=1, max_len=220)
    result: dict[str, Any] = {
        "sourceOpcode": source_opcode,
        "updatedAt": now_ms(),
        "payloadByteCount": len(payload),
        "treasureOccupied": {},
        "tasks": [],
    }
    progress_re = re.compile(r"^\s*(\d+)\s*/\s*(\d+)\s*$")
    for idx, item in enumerate(fields):
        text = str(item.get("text") or "")
        progress_item = next((x for x in fields[idx + 1:idx + 6] if progress_re.match(str(x.get("text") or ""))), None)
        reward_item = next((x for x in fields[idx + 1:idx + 8] if re.fullmatch(r"\s*[+-]\d+\s*", str(x.get("text") or ""))), None)
        if any("\u4e00" <= ch <= "\u9fff" for ch in text):
            task: dict[str, Any] = {"text": text, "offset": item.get("offset")}
            if progress_item:
                m = progress_re.match(str(progress_item.get("text") or ""))
                if m:
                    task.update({
                        "progress": progress_item.get("text"),
                        "current": int(m.group(1)),
                        "target": int(m.group(2)),
                    })
            if reward_item:
                task["reward"] = str(reward_item.get("text") or "").strip()
            result["tasks"].append(task)
            if "宝藏" in text and any(k in text for k in ["占领", "佔領"]):
                result["treasureOccupied"] = dict(task)
    if not result["treasureOccupied"]:
        text_preview = printable(payload, 2000)
        m = re.search(r"(?:成功)?占领\s*(\d+)个宝藏.*?(\d+)\s*/\s*(\d+)", text_preview)
        if m:
            result["treasureOccupied"] = {
                "text": f"成功占领{m.group(1)}个宝藏",
                "progress": f"{m.group(2)}/{m.group(3)}",
                "current": int(m.group(2)),
                "target": int(m.group(3)),
                "source": "textPreviewFallback",
            }
    return result


def general_status_text_from_code(status_code: Any) -> str:
    if status_code is None or status_code == "":
        return "未知"
    try:
        code = int(status_code)
    except Exception:
        return str(status_code)
    # 原客户端 LscriptPages/game/z.<clinit>/z() 的将领状态表：
    # 0 空闲、1 出征、2 防守/驻防、3 被俘虏、4 阵亡、5 修炼/修炼中、
    # 6 作战中、7 待招募、8 返回、9 解雇。
    # 桌面端表格为节省列宽显示为短标签；状态机仍只允许 code=0/“闲”出征。
    return {
        0: "闲",
        1: "征",
        2: "防",
        3: "俘",
        4: "亡",
        5: "修",
        6: "战",
        7: "招",
        8: "返",
        9: "解雇",
    }.get(code, f"状态{code}")


def parse_a110_general_statuses(payload: bytes, generals: list[dict[str, Any]]) -> dict[str, Any]:
    """Recover explicit general status codes from 0xa110 general records.

    Important correction: the fields at body+0x42/body+0x46 are also non-zero in
    ordinary 0x8004 idle general records, so they are *not* reliable march/task flags.
    The stable UI status byte is the same 114-byte body field used by 0x8004:
    body+0x56 (Lo/a.Vo in the original client). body+0x58 is not the state.
    """
    BODY_LEN = 114
    REPEATED_ID_OFFSET = 0x3A
    HERO_STATUS_OFFSET = 0x56
    LEGACY_STATUS58_OFFSET = 0x58

    status_by_name: dict[str, str] = {}
    status_by_id: dict[str, str] = {}
    records: list[dict[str, Any]] = []
    seen: set[int] = set()

    for g in generals:
        try:
            gid = int(g.get("id") or 0)
        except Exception:
            continue
        name = str(g.get("name") or "")
        if gid <= 0 or not name:
            continue
        gid_bytes = gid.to_bytes(8, "big", signed=False)
        name_bytes = name.encode("utf-8")
        needle = gid_bytes + len(name_bytes).to_bytes(2, "big") + name_bytes
        start = 0
        while True:
            pos = payload.find(needle, start)
            if pos < 0:
                break
            start = pos + 1
            body_off = pos + len(needle)
            if body_off + BODY_LEN > len(payload):
                continue
            body = payload[body_off:body_off + BODY_LEN]
            if body[REPEATED_ID_OFFSET:REPEATED_ID_OFFSET + 8] != gid_bytes:
                continue
            if body[-2:] != b"\xff\xff":
                continue
            status_code = body[HERO_STATUS_OFFSET]
            state = general_status_text_from_code(status_code)
            if gid in seen:
                continue
            seen.add(gid)
            status_by_name[name] = state
            status_by_id[str(gid)] = state
            status_by_id[f"{gid:016x}"] = state
            records.append({
                "id": gid,
                "idHex": f"{gid:016x}",
                "name": name,
                "state": state,
                "statusCode": status_code,
                "heroStatusCode": status_code,
                "stateCode56": status_code,
                "rawStatus58": body[LEGACY_STATUS58_OFFSET],
                "status58": body[LEGACY_STATUS58_OFFSET],
                "busy": False if state == "闲" else True,
                "recordOffset": pos,
                "bodyOffset": body_off,
                "source": "0x3110/0xa110-general-status-code56",
            })
            break

    return {
        "statusByName": status_by_name,
        "statusById": status_by_id,
        "records": records,
    }


def parse_military_intel_from_a110(payload: bytes, generals: list[dict[str, Any]]) -> dict[str, Any]:
    names = [str(g.get("name") or "") for g in generals if g.get("name")]
    events = []
    for item in extract_utf_strings(payload):
        text = str(item["text"])
        if not any(k in text for k in ["【返回】", "返回", "出征", "战斗", "攻打", "行军", "剿灭", "胜利", "失败"]):
            continue
        matched = [name for name in names if name and name in text]
        if not matched and not any(k in text for k in ["【返回】", "返回", "剿灭"]):
            continue
        state = ""
        if "返回" in text:
            state = "返回"
        elif any(k in text for k in ["出征", "战斗", "攻打", "行军", "剿灭"]):
            state = "征"
        event = {
            "text": text,
            "offset": item["offset"],
            "state": state,
            "generalNames": matched,
        }
        events.append(event)
    status = parse_a110_general_statuses(payload, generals)
    return {
        "sourceOpcode": "0x3110/0xa110",
        "events": events,
        "statusByName": status["statusByName"],
        "statusById": status["statusById"],
        "generalStatusRecords": status["records"],
        "updatedAt": now_ms(),
    }


def update_military_intel_from_packets(sess: dict[str, Any], packets: list[dict[str, Any]], http_code: int = 200, persist: bool = False) -> dict[str, Any]:
    generals = sess.get("generals") or []
    merged = {"sourceOpcode": "0x3110/0xa110", "events": [], "statusByName": {}, "statusById": {}, "generalStatusRecords": [], "updatedAt": now_ms(), "http": http_code}
    for pkt in packets:
        if pkt.get("opcode") != 0xA110 or "payload" not in pkt:
            continue
        parsed = parse_military_intel_from_a110(pkt["payload"], generals)
        for event in parsed.get("events") or []:
            merged["events"].append(event)
        for name, state in (parsed.get("statusByName") or {}).items():
            merged["statusByName"][name] = state
        for gid, state in (parsed.get("statusById") or {}).items():
            merged["statusById"][gid] = state
        for record in parsed.get("generalStatusRecords") or []:
            merged["generalStatusRecords"].append(record)
    sess["militaryIntel"] = merged
    apply_military_status_to_generals(sess)
    if persist:
        persist_runtime_state()
    return merged


def apply_military_status_to_generals(sess: dict[str, Any]) -> None:
    intel = sess.get("militaryIntel") or {}
    intel_updated_at = int(intel.get("updatedAt") or 0)
    status_by_name = intel.get("statusByName") or {}
    status_by_id = intel.get("statusById") or {}
    records_by_id = {}
    for record in intel.get("generalStatusRecords") or []:
        if record.get("id") is not None:
            records_by_id[str(record.get("id"))] = record
        if record.get("idHex"):
            records_by_id[str(record.get("idHex"))] = record
    generals = sess.get("generals") or []
    for g in generals:
        name = str(g.get("name") or "")
        gid = str(g.get("id") or "")
        gid_hex = str(g.get("idHex") or "")
        state = status_by_id.get(gid) or status_by_id.get(gid_hex) or status_by_name.get(name)
        record = records_by_id.get(gid) or records_by_id.get(gid_hex) or {}
        role_state_updated_at = int(g.get("roleStateStatusUpdatedAt") or 0)
        role_state = (
            str(g.get("roleStateStatusText") or "")
            or general_status_text_from_code(g.get("roleStateStatusCode", g.get("status")))
        )
        if state:
            g["a110StatusKnown"] = True
            g["a110StatusCode"] = record.get("statusCode")
            g["a110StatusText"] = state
            g["a110StatusUpdatedAt"] = intel_updated_at
            g["a110StatusSource"] = record.get("source") or "0x3110/0xa110-general-status"
        else:
            g["a110StatusKnown"] = False
            g.pop("a110StatusCode", None)
            g.pop("a110StatusText", None)
            g.pop("a110StatusUpdatedAt", None)
            g.pop("a110StatusSource", None)

        # 0x8004 是一次完整快照；只有真正更新的 0xa110 才能覆盖它。
        # 不能再把旧心跳缓存写回刚刷新的完整状态。
        use_a110 = bool(state) and intel_updated_at > role_state_updated_at
        effective_state = str(state) if use_a110 else role_state
        g["displayStatus"] = effective_state
        g["statusText"] = effective_state
        g["busy"] = effective_state != "闲"
        g["effectiveStatusSource"] = "0xa110" if use_a110 else "0x8004"
        g["effectiveStatusUpdatedAt"] = (
            intel_updated_at if use_a110 else role_state_updated_at
        )
        if use_a110 and record.get("statusCode") is not None:
            g["status"] = record.get("statusCode")
            g["heroStatusCode"] = record.get("statusCode")
            g["stateCode56"] = record.get("statusCode")
        if use_a110 and record.get("rawStatus58") is not None:
            g["rawStatus58"] = record.get("rawStatus58")
            g["status58"] = record.get("status58")
        g.pop("a110TaskA", None)
        g.pop("a110TaskB", None)
    with GENERAL_STATE_CONDITION:
        GENERAL_STATE_CONDITION.notify_all()


def refresh_military_intel(sess: dict[str, Any]) -> dict[str, Any]:
    code, data, packets = post_game(sess["gameHttp"], [(0x3110, b"\x01\x00")], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    return update_military_intel_from_packets(sess, packets, code, persist=True)


OFFICE_NAMES_BY_ID: dict[int, str] = {
    # 游民/细作是没有正式官职的身份，但客户端使用同一字段表示。
    0x0000: "游民",
    0x0001: "细作",
    0x0100: "国民",
    0x0400: "丞相",
    0x0401: "丞相",
    0x0480: "大都督",
    0x0481: "大都督",
    0x0500: "国王",
}
OFFICE_NAMES_BY_ID.update({0x0200 + index: "侍郎" for index in range(0x19)})
OFFICE_NAMES_BY_ID.update({0x0280 + index: "都尉" for index in range(0x19)})
OFFICE_NAMES_BY_ID.update({
    0x0300: "兵部尚书",
    0x0301: "吏部尚书",
    0x0302: "民部尚书",
    0x0303: "刑部尚书",
    0x0304: "工部尚书",
    0x0305: "户部尚书",
    0x0306: "礼部尚书",
    0x0307: "学部尚书",
    0x0380: "虎威将军",
    0x0381: "破虏将军",
    0x0382: "奋武将军",
    0x0383: "抚远将军",
    0x0384: "征东将军",
    0x0385: "平西将军",
    0x0386: "镇北将军",
    0x0387: "定南将军",
})


def office_name_from_id(office_id: Any) -> str:
    """Return the client-visible office name for the 0x8004 office short."""
    try:
        normalized = int(office_id) & 0xFFFF
    except (TypeError, ValueError):
        return ""
    return OFFICE_NAMES_BY_ID.get(normalized, "")


def role_is_national_citizen(sess: dict[str, Any]) -> bool:
    """Return true only when live role data identifies the office as 国民."""
    role_state = sess.get("roleState") if isinstance(sess.get("roleState"), dict) else {}
    role = sess.get("role") if isinstance(sess.get("role"), dict) else {}
    for source in (role_state, role):
        office_name = str(source.get("officeName") or "").strip()
        has_office_data = bool(office_name)
        office_matches_citizen = office_name == "国民"
        for field in ("officeIdUnsigned", "officeId", "officeIdRaw"):
            value = source.get(field)
            if value in (None, ""):
                continue
            has_office_data = True
            try:
                if isinstance(value, str):
                    try:
                        parsed = int(value, 0)
                    except ValueError:
                        parsed = int(value)
                else:
                    parsed = int(value)
                normalized = parsed & 0xFFFF
            except (TypeError, ValueError):
                continue
            if normalized == 0x0100:
                office_matches_citizen = True
        if has_office_data:
            # roleState is the live source.  Do not let stale role-list data
            # override a current, non-citizen office value.
            return office_matches_citizen
        if any(
            source.get(field) not in (None, "")
            for field in ("officeIdUnsigned", "officeId", "officeIdRaw")
        ):
            return office_matches_citizen
    return False


def national_citizen_daily_skip_result(sess: dict[str, Any]) -> dict[str, Any] | None:
    """Build the terminal daily-task result used by office-gated features."""
    if not role_is_national_citizen(sess):
        return None
    return {
        "success": True,
        "completed": True,
        "skipped": True,
        "skipReason": "national-citizen",
        "message": "国民跳过",
        "statusText": "已做（国民跳过）",
        "officeId": 0x0100,
        "officeName": "国民",
    }


def parse_8004_head(payload: bytes, source_opcode: str = "0x1016/0x8004") -> dict[str, Any]:
    """Parse the stable monarch/resource head of 0x8004.

    This mirrors the Android RealGameProtocolClient.parse8004Head() parser so the
    desktop UI can replace prototype/hardcoded role rows with live account data.
    """
    p = 0

    def i8() -> int:
        nonlocal p
        v = payload[p]
        p += 1
        return v

    def i16() -> int:
        nonlocal p
        v = int.from_bytes(payload[p:p + 2], "big", signed=True)
        p += 2
        return v

    def i32() -> int:
        nonlocal p
        v = int.from_bytes(payload[p:p + 4], "big", signed=True)
        p += 4
        return v

    def i64() -> int:
        nonlocal p
        v = int.from_bytes(payload[p:p + 8], "big", signed=True)
        p += 8
        return v

    def utf_at_cursor() -> str:
        nonlocal p
        s, p2 = read_utf(payload, p)
        p = p2
        return s

    if len(payload) < 96:
        return {"sourceOpcode": source_opcode, "payloadByteCount": len(payload), "parseError": "0x8004 payload too short"}
    try:
        status1 = i8()
        status2 = i8()
        server_time = i64()
        role_id = i64()
        role_name = utf_at_cursor()
        flag_b = i8()
        level = i8()
        copper = i64()
        food = i64()
        field_f = i64()
        flag_g = i8()
        # 这里的 short 是头像资源编号（data.i.h），不是官职。
        avatar_short_raw = i16()
        flag_x = i8()
        prestige = i64()
        prestige_prev = i64()
        prestige_next = i64()
        skip_long = i64()
        flag_l = i8()
        copper_per_hour = i32()
        food_per_hour = i32()
        battle_merit_candidate = i64()
        field_p = i64()
        population_current = i64()
        population_cap = i64()
        fief_limit = i8()
        general_limit = i8()
        resource_point_current = i8()
        resource_point_cap = i8()
        # data.i.x 在资源点上限后还会读一个保留 byte，再读官职 short（data.i.w）。
        office_field_flag = None
        office_id_raw = None
        if len(payload) - p >= 3:
            office_field_flag = i8()
            office_id_raw = i16()
        parsed = p
        tail = payload[parsed:]
        return {
            "roleId": role_id,
            "roleName": role_name,
            "level": level,
            "copper": copper,
            "food": food,
            "prestige": prestige,
            "prestigePrevThreshold": prestige_prev,
            "prestigeNextThreshold": prestige_next,
            "copperPerHour": copper_per_hour,
            "foodPerHour": food_per_hour,
            "populationCurrent": population_current,
            "populationCap": population_cap,
            "fiefLimit": fief_limit,
            "generalLimit": general_limit,
            "resourcePointCurrent": resource_point_current,
            "resourcePointCap": resource_point_cap,
            "serverTimeMillis": server_time,
            # 中段未完全定性字段：保留原始值，供协议差分/后续映射。
            "status1": status1,
            "status2": status2,
            "flagB": flag_b,
            "fieldF": field_f,
            "flagG": flag_g,
            # 兼容旧字段名：历史版本误把头像 short 标成了 officeShort。
            "officeShortRaw": avatar_short_raw,
            "officeShortUnsigned": avatar_short_raw & 0xFFFF,
            "avatarShortRaw": avatar_short_raw,
            "avatarShortUnsigned": avatar_short_raw & 0xFFFF,
            "officeFieldFlag": office_field_flag,
            "officeId": office_id_raw,
            "officeIdRaw": office_id_raw,
            "officeIdUnsigned": (
                office_id_raw & 0xFFFF if office_id_raw is not None else None
            ),
            "officeName": office_name_from_id(office_id_raw),
            "flagX": flag_x,
            "skipLong": skip_long,
            "flagL": flag_l,
            "battleMeritCandidate": battle_merit_candidate,
            "fieldP": field_p,
            "sourceOpcode": source_opcode,
            "payloadByteCount": len(payload),
            "parsedHeadByteCount": parsed,
            "tailByteCount": len(tail),
            "tailUtf8Preview": printable(tail, 300),
        }
    except Exception as e:
        return {"sourceOpcode": source_opcode, "payloadByteCount": len(payload), "parseError": str(e)}


def item_names_by_id() -> dict[int, str]:
    global ITEM_NAMES_BY_ID
    if ITEM_NAMES_BY_ID is not None:
        return ITEM_NAMES_BY_ID
    names = dict(ITEM_NAME_FALLBACK)
    try:
        data = json.loads(ITEM_MAPPING_FILE.read_text(encoding="utf-8-sig"))
        for row in data if isinstance(data, list) else []:
            item_id = int(row.get("item_id"))
            name = str(row.get("name") or "").strip()
            if name:
                names[item_id] = name
    except Exception:
        pass
    ITEM_NAMES_BY_ID = names
    return names


def equipment_templates_by_id() -> dict[int, dict[str, Any]]:
    global EQUIPMENT_TEMPLATES_BY_ID
    if EQUIPMENT_TEMPLATES_BY_ID is not None:
        return EQUIPMENT_TEMPLATES_BY_ID
    templates: dict[int, dict[str, Any]] = {}
    try:
        with EQUIPMENT_MAPPING_FILE.open("r", encoding="utf-8-sig", newline="") as handle:
            for row in csv.DictReader(handle):
                template_id = int(row.get("template_id_In") or -1)
                if template_id < 0:
                    continue
                templates[template_id] = {
                    "templateId": template_id,
                    "name": str(row.get("name_Mn") or f"装备#{template_id}").strip(),
                    "level": int(row.get("level_Kn") or 0),
                    "typeCode": int(row.get("stat_type_Nn") or -1),
                    "famous": bool(int(row.get("famous_flag_Jn") or 0)),
                    "description": str(row.get("description_On") or "").strip(),
                }
    except Exception:
        pass
    EQUIPMENT_TEMPLATES_BY_ID = templates
    return templates


def parse_8104_equipment_records(payload: bytes, offset: int) -> tuple[list[dict[str, Any]], int, str]:
    """Parse the V5 bank-0 equipment block following the fixed item table."""
    if offset + 2 > len(payload):
        return [], offset, "缺少装备数量"
    p = offset
    count = int.from_bytes(payload[p:p + 2], "big", signed=False)
    p += 2
    if count > 1000:
        return [], offset, f"装备数量异常：{count}"
    templates = equipment_templates_by_id()
    equipment: list[dict[str, Any]] = []
    try:
        for index in range(count):
            if p + 11 > len(payload):
                raise ValueError(f"第 {index + 1} 条装备记录不完整")
            record_offset = p
            instance_id = int.from_bytes(payload[p:p + 8], "big", signed=True)
            p += 8
            template_id = int.from_bytes(payload[p:p + 2], "big", signed=False)
            p += 2
            attr_len = payload[p]
            p += 1
            if attr_len > 64 or p + attr_len + 10 > len(payload):
                raise ValueError(f"第 {index + 1} 条装备属性长度异常：{attr_len}")
            attrs = list(payload[p:p + attr_len])
            p += attr_len
            strengthen_effect = int.from_bytes(payload[p:p + 2], "big", signed=False)
            p += 2
            risk0 = payload[p]
            risk1 = payload[p + 1]
            p += 2
            protocol_j = int.from_bytes(payload[p:p + 2], "big", signed=False)
            p += 2
            pity_current = int.from_bytes(payload[p:p + 2], "big", signed=False)
            p += 2
            pity_target = int.from_bytes(payload[p:p + 2], "big", signed=False)
            p += 2
            extra_text, p = read_utf(payload, p)
            template = templates.get(template_id) or {
                "templateId": template_id,
                "name": f"装备#{template_id}",
                "level": 0,
                "typeCode": -1,
                "famous": False,
                "description": "",
            }
            quality = attrs[0] if attrs else -1
            strengthen = attrs[1] if len(attrs) > 1 else 0
            equipment.append({
                "index": index,
                "instanceId": instance_id,
                "id": instance_id,
                "instanceIdHex": f"{instance_id:016x}" if instance_id >= 0 else "",
                "templateId": template_id,
                "name": template["name"],
                "level": int(template["level"]),
                "typeCode": int(template["typeCode"]),
                "famous": bool(template["famous"]),
                "quality": quality,
                "qualityName": EQUIPMENT_QUALITY_NAMES[quality] if 0 <= quality < len(EQUIPMENT_QUALITY_NAMES) else f"品质{quality}",
                "strengthen": strengthen,
                "attributes": attrs,
                "strengthenEffect": strengthen_effect,
                "risk": [risk0, risk1],
                "protocolJ": protocol_j,
                "pityCurrent": pity_current,
                "pityTarget": pity_target,
                "extraText": extra_text,
                "templateDescription": template["description"],
                "offset": record_offset,
                "rawHex": payload[record_offset:p].hex(),
            })
        return equipment, p, ""
    except Exception as e:
        return equipment, p, str(e)


def parse_8104_inventory(payload: bytes, source_opcode: str = "0x1104/0x8104") -> dict[str, Any]:
    """Conservative 0x8104 inventory parser.

    The stable header is:
      14 bytes reserved/account context, u16 capacity, u16 itemCount.

    Observed 20260710 samples contain the visible bag list immediately after
    the header as itemCount fixed records:
      u16 itemId, u16 count, 8 reserved zero bytes.

    Bytes after those itemCount records are detail/metadata blocks. Do not scan
    them as bag items, otherwise overlapping bytes create false goods such as
    "黄金包 x256" or huge "活血丹" counts.
    """
    if len(payload) < 18:
        return {"sourceOpcode": source_opcode, "items": [], "parseError": f"0x8104 payload too short: {len(payload)}"}
    capacity = int.from_bytes(payload[14:16], "big", signed=False)
    item_count = int.from_bytes(payload[16:18], "big", signed=False)
    names = item_names_by_id()
    items: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()

    def add_item(item_id: int, count: int, off: int, layout: str, raw_len: int = 16) -> None:
        if item_id not in names or count <= 0 or count > 500000:
            return
        key = (item_id, off)
        if key in seen:
            return
        seen.add(key)
        items.append({
            "index": len(items),
            "itemId": item_id,
            "id": item_id,
            "name": names.get(item_id, f"道具#{item_id}"),
            "count": count,
            "offset": off,
            "layout": layout,
            "rawHex": payload[off:min(off + raw_len, len(payload))].hex(),
            "source": source_opcode,
        })

    # Preferred live layout: exact fixed-size visible bag table.
    table_off = 18
    table_len = item_count * 12
    if item_count > 0 and table_off + table_len <= len(payload):
        fixed_rows: list[tuple[int, int, int]] = []
        fixed_ok = True
        for idx in range(item_count):
            off = table_off + idx * 12
            item_id = int.from_bytes(payload[off:off + 2], "big", signed=False)
            count = int.from_bytes(payload[off + 2:off + 4], "big", signed=False)
            reserved = payload[off + 4:off + 12]
            # itemId 0 is valid: 徭役令.
            if item_id not in names or count <= 0 or count > 500000 or reserved != b"\x00" * 8:
                fixed_ok = False
                break
            fixed_rows.append((off, item_id, count))
        if fixed_ok and (fixed_rows or item_count == 0):
            for off, item_id, count in fixed_rows:
                add_item(item_id, count, off, "u16-id-u16-count-reserved8", 12)
            equipment, v5_end, equipment_error = parse_8104_equipment_records(payload, table_off + table_len)
            parsed = {
                "sourceOpcode": source_opcode,
                "capacity": capacity,
                "itemCount": item_count,
                "items": items,
                "equipmentCount": len(equipment),
                "equipment": equipment,
                "payloadByteCount": len(payload),
                "parsedItemCount": len(items),
                "dictionarySize": len(names),
                "layout": "u16-id-u16-count-reserved8-table",
                "v5EndOffset": v5_end,
            }
            if equipment_error:
                parsed["equipmentParseError"] = equipment_error
            return parsed

    # Fallback for older/uncertain captures. Kept conservative and bounded by
    # itemCount; preferred table parser above should handle current live 0x8104.
    first_off = 18
    if first_off + 16 <= len(payload):
        item_id = int.from_bytes(payload[first_off:first_off + 4], "big", signed=False)
        count_a = int.from_bytes(payload[first_off + 12:first_off + 14], "big", signed=False)
        count_b = int.from_bytes(payload[first_off + 14:first_off + 16], "big", signed=False)
        add_item(item_id, count_b or count_a, first_off, "int-id-reserved-count-slot", 16)

    for off in range(18, max(18, len(payload) - 3)):
        if first_off <= off < first_off + 16:
            continue
        item_id = int.from_bytes(payload[off:off + 2], "big", signed=False)
        count = int.from_bytes(payload[off + 2:off + 4], "big", signed=False)
        if item_id not in names or count <= 0:
            continue
        prefix8 = payload[max(18, off - 8):off]
        prefix6 = payload[max(18, off - 6):off]
        if prefix8 == b"\x00" * 8 or prefix6 == b"\x00" * 6:
            # Ignore the low half of the first int-id record; it was already handled above.
            if off == first_off + 2:
                continue
            add_item(item_id, count, off, "zero-prefix-u16-id-u16-count", 12)
        if len(items) >= item_count:
            break
    return {
        "sourceOpcode": source_opcode,
        "capacity": capacity,
        "itemCount": item_count,
        "items": items,
        "payloadByteCount": len(payload),
        "parsedItemCount": len(items),
        "dictionarySize": len(names),
    }


def parse_status_utf(payload: bytes) -> tuple[int | None, str, int]:
    if not payload:
        return None, "空响应", 0
    status = struct.unpack(">b", payload[:1])[0]
    if len(payload) < 3:
        return status, "", 1
    message, p = read_utf(payload, 1)
    return status, message, p


def build_use_general_item_payload(general_id: int | str, item_id: int, count: int = 1) -> bytes:
    gid = int(str(general_id), 16) if isinstance(general_id, str) and any(c in "abcdefABCDEF" for c in general_id) else int(general_id)
    if gid <= 0:
        raise RuntimeError("使用道具缺少有效将领 ID")
    if not (0 <= int(item_id) <= 0xFFFF):
        raise RuntimeError(f"道具 ID 超出范围：{item_id}")
    if not (1 <= int(count) <= 0xFFFF):
        raise RuntimeError(f"道具数量超出范围：{count}")
    return struct.pack(">qHH", gid, int(item_id), int(count))


def execute_use_energy_item(sess: dict[str, Any], general_id: str, *, confirm: str = "") -> dict[str, Any]:
    if confirm != "use-energy-item":
        raise RuntimeError("真实使用活血丹需要 confirm=use-energy-item")
    general = next((
        g for g in sess.get("generals") or []
        if str(g.get("id")) == str(general_id) or str(g.get("idHex")) == str(general_id)
    ), None)
    if not general:
        raise RuntimeError(f"未找到使用活血丹的将领：{general_id}")
    payload = build_use_general_item_payload(int(general["id"]), 12, 1)
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x1218, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p["payload"] for p in packets if p.get("opcode") == 0x8218 and "payload" in p), None)
    if response is None:
        return {"success": False, "message": "未收到 0x8218 活血丹响应", "http": code, "payloadHex": payload.hex()}
    status = struct.unpack(">b", response[:1])[0] if response else None
    message = ""
    inventory = None
    if status == 0:
        # 2026-07-10 live response: status byte followed directly by the 0x8104
        # inventory body. There is no success UTF between them.
        inventory = parse_8104_inventory(response[1:], "live/0x1218/0x8218")
    elif response:
        _status, message, _p = parse_status_utf(response)
    if inventory and not inventory.get("parseError"):
        sess["inventory"] = inventory
    return {
        "success": status == 0,
        "status": status,
        "message": message or ("活血丹使用成功" if status == 0 else f"使用失败状态 {status}"),
        "generalId": int(general["id"]),
        "generalName": general.get("name") or "",
        "itemId": 12,
        "itemName": "活血丹",
        "http": code,
        "payloadHex": payload.hex(),
        "inventory": inventory,
    }


def build_resource_exchange_payload(direction: int, amount: int) -> bytes:
    if direction not in (0, 1):
        raise RuntimeError(f"资源转换方向无效：{direction}")
    if amount <= 0:
        raise RuntimeError("资源转换数量必须大于 0")
    return struct.pack(">Bq", direction, int(amount))


def parse_resource_exchange_response(payload: bytes) -> dict[str, Any]:
    if not payload:
        return {"status": None, "success": False, "message": "资源转换响应为空", "rawHex": ""}
    status = struct.unpack(">b", payload[:1])[0]
    message = ""
    p = 1
    if status != 0 and len(payload) >= 3:
        _status, message, p = parse_status_utf(payload)
    out: dict[str, Any] = {
        "status": status,
        "success": status == 0,
        "message": message or ("资源转换成功" if status == 0 else f"资源转换失败状态 {status}"),
        "rawHex": payload.hex(),
    }
    # 2026-07-10 live response: status + i64 copper + i64 food.
    if status == 0 and len(payload) >= 17:
        out["copper"] = struct.unpack(">q", payload[p:p + 8])[0]
        out["food"] = struct.unpack(">q", payload[p + 8:p + 16])[0]
    return out


def execute_food_to_copper(sess: dict[str, Any], food_amount: int, *, confirm: str = "") -> dict[str, Any]:
    if confirm != "food-to-copper":
        raise RuntimeError("真实粮食转铜需要 confirm=food-to-copper")
    payload = build_resource_exchange_payload(1, int(food_amount))
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x1152, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p["payload"] for p in packets if p.get("opcode") == 0x8152 and "payload" in p), None)
    parsed = parse_resource_exchange_response(response) if response is not None else {
        "success": False,
        "message": "未收到 0x8152 粮食转铜响应",
    }
    if parsed.get("success"):
        role_state = sess.setdefault("roleState", {})
        if parsed.get("copper") is not None:
            role_state["copper"] = parsed["copper"]
        if parsed.get("food") is not None:
            role_state["food"] = parsed["food"]
    return {
        **parsed,
        "direction": "food-to-copper",
        "foodAmount": int(food_amount),
        "expectedCopper": int(food_amount) * 3 // 10,
        "http": code,
        "payloadHex": payload.hex(),
    }


def build_delete_all_mail_payload() -> bytes:
    return b"\x00\x01" + struct.pack(">q", -1)


def parse_delete_mail_response(payload: bytes) -> dict[str, Any]:
    if len(payload) < 4:
        return {"success": False, "message": "邮件删除响应过短", "rawHex": payload.hex()}
    action = payload[0]
    box_type = payload[1]
    remaining = int.from_bytes(payload[2:4], "big", signed=False)
    success = action == 0 and box_type == 1
    return {
        "success": success,
        "action": action,
        "boxType": box_type,
        "remaining": remaining,
        "message": "邮件清理完成" if success else f"邮件清理响应异常 action={action} box={box_type}",
        "rawHex": payload.hex(),
    }


def execute_delete_all_mail(sess: dict[str, Any], *, confirm: str = "") -> dict[str, Any]:
    if confirm != "delete-all-mail":
        raise RuntimeError("真实清空邮件需要 confirm=delete-all-mail")
    payload = build_delete_all_mail_payload()
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x1116, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p["payload"] for p in packets if p.get("opcode") == 0x8116 and "payload" in p), None)
    parsed = parse_delete_mail_response(response) if response is not None else {
        "success": False,
        "message": "未收到 0x8116 邮件清理响应",
    }
    return {**parsed, "http": code, "payloadHex": payload.hex()}


def build_discard_inventory_payload(kind: int, object_id: int, count: int = 1) -> bytes:
    if kind not in (0, 1):
        raise RuntimeError(f"宝库丢弃类型无效：{kind}")
    if object_id < 0:
        raise RuntimeError("宝库丢弃对象 ID 无效")
    if count <= 0:
        raise RuntimeError("宝库丢弃数量必须大于 0")
    return struct.pack(">Bqi", kind, int(object_id), int(count)) + struct.pack(">q", -1)


def parse_discard_inventory_response(payload: bytes) -> dict[str, Any]:
    status, message, p = parse_status_utf(payload)
    inventory = parse_8104_inventory(payload[p:], "live/0x1103/0x8103") if status == 0 and p < len(payload) else None
    return {
        "success": status == 0,
        "status": status,
        "message": message or ("丢弃成功" if status == 0 else f"丢弃失败状态 {status}"),
        "inventory": inventory,
        "rawHex": payload.hex(),
    }


def execute_discard_inventory(
    sess: dict[str, Any],
    *,
    kind: int,
    object_id: int,
    count: int = 1,
    confirm: str = "",
) -> dict[str, Any]:
    if confirm != "discard-inventory":
        raise RuntimeError("真实宝库丢弃需要 confirm=discard-inventory")
    payload = build_discard_inventory_payload(kind, object_id, count)
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x1103, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p["payload"] for p in packets if p.get("opcode") == 0x8103 and "payload" in p), None)
    parsed = parse_discard_inventory_response(response) if response is not None else {
        "success": False,
        "message": "未收到 0x8103 宝库丢弃响应",
    }
    inventory = parsed.get("inventory")
    if parsed.get("success") and inventory and not inventory.get("parseError"):
        sess["inventory"] = inventory
    return {
        **parsed,
        "kind": "item" if kind == 0 else "equipment",
        "objectId": object_id,
        "count": count,
        "http": code,
        "payloadHex": payload.hex(),
    }


def equipment_is_safe_to_discard(equipment: dict[str, Any], *, max_quality: int, max_level: int) -> tuple[bool, str]:
    if int(equipment.get("instanceId") or -1) <= 0:
        return False, "装备实例 ID 无效"
    if bool(equipment.get("famous")):
        return False, "名将装备"
    if int(equipment.get("strengthen") or 0) > 0:
        return False, "已经强化"
    if str(equipment.get("extraText") or "").strip():
        return False, "存在炼魂/额外描述"
    level = int(equipment.get("level") or 0)
    if level >= 80:
        return False, "80级以上保护"
    if level >= int(max_level):
        return False, f"等级不低于{max_level}"
    quality = int(equipment.get("quality") if equipment.get("quality") is not None else -1)
    if quality < 0 or quality > int(max_quality):
        return False, f"品质高于{EQUIPMENT_QUALITY_NAMES[max_quality]}"
    return True, ""


def clean_inventory_by_policy(sess: dict[str, Any], policy: dict[str, Any]) -> dict[str, Any]:
    inventory = refresh_inventory(sess)
    actions: list[dict[str, Any]] = []
    item_names = [
        name.strip()
        for name in re.split(r"[,，;；|]+", str(policy.get("discardItemNames") or ""))
        if name.strip()
    ]
    max_actions = max(1, min(int(policy.get("maxActions") or 50), 200))
    for item in list(inventory.get("items") or []):
        if len(actions) >= max_actions or item.get("name") not in item_names:
            continue
        discard_count = int(item.get("count") or 0)
        if discard_count <= 0:
            continue
        result = execute_discard_inventory(
            sess,
            kind=0,
            object_id=int(item["itemId"]),
            count=discard_count,
            confirm="discard-inventory",
        )
        action = {
            "type": "item",
            "name": item.get("name"),
            "count": discard_count,
            "success": result.get("success"),
            "message": result.get("message"),
        }
        actions.append(action)
        if not result.get("success"):
            raise RuntimeError(f"丢弃道具 {item.get('name')} x{discard_count} 失败：{result.get('message')}")
        record_success_action(
            str(sess.get("sessionId") or ""),
            "丢弃物品",
            f"{item.get('name') or item.get('itemId')} x{discard_count}",
            detail=action,
        )
    if bool(policy.get("discardEquipment", False)):
        quality_name = str(policy.get("maxEquipmentQuality") or "良好")
        max_quality = EQUIPMENT_QUALITY_NAMES.index(quality_name) if quality_name in EQUIPMENT_QUALITY_NAMES else 1
        max_level = max(1, min(int(policy.get("maxEquipmentLevel") or 60), 100))
        for equipment in list(inventory.get("equipment") or []):
            if len(actions) >= max_actions:
                break
            allowed, reason = equipment_is_safe_to_discard(
                equipment,
                max_quality=max_quality,
                max_level=max_level,
            )
            if not allowed:
                continue
            result = execute_discard_inventory(
                sess,
                kind=1,
                object_id=int(equipment["instanceId"]),
                count=1,
                confirm="discard-inventory",
            )
            action = {
                "type": "equipment",
                "name": equipment.get("name"),
                "level": equipment.get("level"),
                "quality": equipment.get("qualityName"),
                "instanceId": equipment.get("instanceId"),
                "success": result.get("success"),
                "message": result.get("message"),
            }
            actions.append(action)
            if not result.get("success"):
                raise RuntimeError(
                    f"丢弃装备 {equipment.get('qualityName')}{equipment.get('level')}级"
                    f"{equipment.get('name')} 失败：{result.get('message')}"
                )
            record_success_action(
                str(sess.get("sessionId") or ""),
                "丢弃装备",
                f"{equipment.get('qualityName') or ''}{equipment.get('level') or 0}级"
                f"{equipment.get('name') or equipment.get('instanceId')}",
                detail=action,
            )
    return {
        "success": True,
        "actions": actions,
        "actionCount": len(actions),
        "itemCount": len([x for x in actions if x.get("type") == "item"]),
        "equipmentCount": len([x for x in actions if x.get("type") == "equipment"]),
    }


def encode_xy(x: int, y: int) -> str:
    return f"{x:04x}{y:04x}"


def read_only_gamehex_to_cmd(gamehex: str) -> tuple[int, bytes]:
    body = gamehex[18:]
    declared = int(body[:2], 16)
    op = int(body[2:6], 16)
    payload = bytes.fromhex(body[6:])
    if len(payload) != declared:
        raise ValueError(f"bad readonly gamehex declared={declared} actual={len(payload)}")
    return op, payload


def action_gamehex_to_cmd(gamehex: str) -> tuple[int, int, bytes]:
    body = gamehex[18:]
    declared = int(body[:2], 16)
    op = int(body[2:6], 16)
    payload = bytes.fromhex(body[6:])
    return declared, op, payload


def build_brush_payloads(general_chunks: list[str], target_hex: str) -> tuple[str, str]:
    payloads = build_brush_payloads_variant(general_chunks, target_hex, variant=0)
    return payloads["prepare"], payloads["expedition"]


def build_brush_payloads_variant(general_chunks: list[str], target_hex: str, variant: int = 0) -> dict[str, Any]:
    n = len(general_chunks)
    ids = "".join(general_chunks)
    prefix = "0" * 18
    variants = {
        # Canonical client shape recovered from unpacked game dex:
        # LscriptPages/game/p;->O(I [J J)V:
        #   writeByte(type), writeByte(count), writeLong(general)*, writeLong(target), send 0x1520
        # LscriptPages/game/p;->N(I [J J B B B J)V:
        #   writeByte(type), writeByte(count), writeLong(general)*, writeLong(target),
        #   writeLong(-1), writeByte(0), writeByte(0), writeByte(0), send 0x1522
        # Earlier reports inserted an extra 0000 before target; that made declared length and
        # actual payload diverge and caused the game server to return 0x8522=ff0000.
        0: {"prepareOp": "1520030", "prepareTrailer": target_hex, "prepareExtra": 0x0a, "expeditionOp": "1522030", "expeditionTrailer": target_hex + "ffffffffffffffff000000", "expeditionExtra": 0x15},
        # Retained only for offline protocol comparison. The live product path uses
        # variant 0/actionType=3, matching capture 20260710_215812 flows 074/075.
        10: {"prepareOp": "15200a0", "prepareTrailer": target_hex, "prepareExtra": 0x0a, "expeditionOp": "15220a0", "expeditionTrailer": target_hex + "ffffffffffffffff000000", "expeditionExtra": 0x15},
        1: {"prepareOp": "1520020", "prepareTrailer": "0000" + target_hex, "prepareExtra": 0x0a, "expeditionOp": "1522020", "expeditionTrailer": "0000" + target_hex + "ffffffffffffffff000000", "expeditionExtra": 0x15},
        2: {"prepareOp": "15200e0", "prepareTrailer": "ffffffff0004" + target_hex, "prepareExtra": 0x0e, "expeditionOp": "15220e0", "expeditionTrailer": "ffffffff0004" + target_hex + "ffffffffffffffff000000", "expeditionExtra": 0x19},
        3: {"prepareOp": "1520010", "prepareTrailer": target_hex, "prepareExtra": 0x08, "expeditionOp": "1522010", "expeditionTrailer": target_hex + "ffffffffffffffff000000", "expeditionExtra": 0x13},
        4: {"prepareOp": "15200b0", "prepareTrailer": target_hex, "prepareExtra": 0x08, "expeditionOp": "15220b0", "expeditionTrailer": target_hex + "ffffffffffffffff000000", "expeditionExtra": 0x13},
    }
    spec = variants.get(int(variant))
    if spec is None:
        raise RuntimeError(f"未知刷黄出征 payload 变体：{variant}")
    prepare = prefix + f"{n * 8 + spec['prepareExtra']:x}" + spec["prepareOp"] + str(n) + ids + spec["prepareTrailer"]
    expedition = prefix + f"{n * 8 + spec['expeditionExtra']:x}" + spec["expeditionOp"] + str(n) + ids + spec["expeditionTrailer"]
    return {"variant": int(variant), "prepare": prepare, "expedition": expedition, **spec}


def normalize_hex_id(id_value: Any) -> str:
    clean = "".join(c for c in str(id_value or "") if c in "0123456789abcdefABCDEF").lower()
    if not clean:
        raise RuntimeError("缺少将领 ID")
    significant = clean.lstrip("0") or "0"
    if len(significant) > 16:
        raise RuntimeError(f"将领 ID 超过 8 字节：{id_value}")
    return significant.rjust(16, "0")


def build_refill_payload(general_chunks: list[str]) -> bytes:
    """构造 0x1229 批量补兵 payload：count(byte) + 8-byte general ids."""
    if not general_chunks:
        raise RuntimeError("批量补兵至少需要一个将领")
    if len(general_chunks) > 0xFF:
        raise RuntimeError("批量补兵将领数量超过 255")
    payload = bytearray([len(general_chunks)])
    for chunk in general_chunks:
        payload += bytes.fromhex(normalize_hex_id(chunk))
    return bytes(payload)


SOLDIER_TYPE_CODES = {
    "民兵": 0, "弩兵": 1, "弓兵": 2, "轻骑兵": 3, "弩车": 4, "冲城车": 5,
    "轻步兵": 6, "近卫兵": 7, "重步兵": 8, "弩骑兵": 9, "重骑兵": 10,
    "铁骑兵": 11, "投石车": 12, "重弩车": 13, "强弩兵": 14, "骁骑兵": 15,
}
SOLDIER_CODE_NAMES = {v: k for k, v in SOLDIER_TYPE_CODES.items()}


def soldier_type_code(name_or_code: Any) -> int:
    if isinstance(name_or_code, int):
        return int(name_or_code)
    s = str(name_or_code or "").strip()
    if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
        return int(s)
    return SOLDIER_TYPE_CODES.get(s, 3)


def soldier_type_name(code: Any) -> str:
    try:
        c = int(code)
    except Exception:
        return str(code)
    if c == -1:
        return "无配兵"
    return SOLDIER_CODE_NAMES.get(c, f"兵种{c}")


def build_assign_troops_payload(general_id_hex: str, soldier_type_name_or_code: Any, count: int, group: int = 0) -> bytes:
    """构造 0x1226 generalWithSoldier 配兵 payload。

    逆向证据：LscriptPages/game/z;->R(J I I I)V:
      writeLong(generalId), writeByte(group), writeShort(soldierType), writeInt(count), send 4646/0x1226.
    group 在客户端普通“补满/调整兵力”路径中为 0。
    """
    gid = int(normalize_hex_id(general_id_hex), 16)
    return struct.pack(">qbhi", gid, int(group), soldier_type_code(soldier_type_name_or_code), int(count))


def parse_assign_troops_response(payload: bytes) -> dict[str, Any]:
    """解析 0x8226 配兵响应核心字段。

    Handler `LscriptPages/game/z;->S(Ljava/lang/String;)V` 读取：
    status(byte), generalId(long), oldType(short), oldCount(short),
    newType(short), newCount(short)，
    status==1 时继续读取库存/兵种数组。
    """
    p = 0
    out: dict[str, Any] = {"rawHex": payload.hex()[:4096], "textPreview": printable(payload, 1200)}
    try:
        if len(payload) < 17:
            return {**out, "success": False, "message": "0x8226 响应过短"}
        status = struct.unpack(">b", payload[p:p + 1])[0]; p += 1
        general_id = struct.unpack(">q", payload[p:p + 8])[0]; p += 8
        old_type = struct.unpack(">h", payload[p:p + 2])[0]; p += 2
        old_count = struct.unpack(">h", payload[p:p + 2])[0]; p += 2
        new_type = struct.unpack(">h", payload[p:p + 2])[0]; p += 2
        new_count = struct.unpack(">h", payload[p:p + 2])[0]; p += 2
        if status == 1:
            current_desc = "无配兵" if new_type == -1 and new_count == 0 else f"{new_count} {soldier_type_name(new_type)}"
            message = f"配兵成功：当前 {current_desc}"
        else:
            message = f"配兵失败(status={status}，通常表示兵种/数量不可用、库存不足或将领当前不可配兵)"
        out.update({
            "status": status,
            "success": status == 1,
            "message": message,
            "generalId": general_id,
            "generalIdHex": f"{general_id:016x}",
            "oldSoldierTypeCode": old_type,
            "oldSoldierType": soldier_type_name(old_type),
            "oldSoldierCount": old_count,
            "assignedSoldierTypeCode": new_type,
            "assignedSoldierType": soldier_type_name(new_type),
            "assignedSoldierCount": new_count,
            "echoSoldierTypeCode": new_type,
            "echoSoldierCount": new_count,
            # 兼容旧前端/旧报告字段：fieldA/B 是旧状态，current/soldierLimit 指向新状态。
            "fieldA": old_type,
            "fieldB": old_count,
            "currentSoldierCount": new_count,
            "soldierLimit": new_count,
        })
        if status == 1 and p < len(payload):
            n = payload[p]; p += 1
            inventory = []
            for _ in range(n):
                if p + 5 > len(payload):
                    break
                code = struct.unpack(">b", payload[p:p + 1])[0]; p += 1
                amount = struct.unpack(">i", payload[p:p + 4])[0]; p += 4
                inventory.append({"soldierTypeCode": code, "amount": amount})
            out["soldierInventory"] = inventory
    except Exception as e:
        out.update({"success": False, "parseError": str(e), "message": "配兵响应解析失败"})
    return out


def build_heal_preinfo_payload(fief_id: int | str, soldier_code: int, count: int) -> bytes:
    """0x1231 reqHurtSoldierCurePreInfo: writeLong(fiefId), writeShort(soldierType), writeInt(count)."""
    return struct.pack(">qhi", int(fief_id), int(soldier_code), int(count))


def build_heal_payload(fief_id: int | str, soldier_group: int, soldier_code: int, count: int, use_gold: bool = False) -> bytes:
    """0x1230 治疗伤兵: writeLong(fiefId), writeByte(group), writeShort(soldierType), writeInt(count), writeByte(useGold).

    离线证据：LscriptPages/game/q;->d0(J I I I I)V 依次写 long/byte/short/int/byte 后发送 4656(0x1230)。
    旧 shape `02 0000 ffffffff 00` 正好对应 group=2、soldierType=0、count=-1、useGold=false。
    """
    return struct.pack(">qbhib", int(fief_id), int(soldier_group), int(soldier_code), int(count), 1 if use_gold else 0)


def build_heal_all_payloads(fief_id: int | str) -> tuple[bytes, bytes]:
    """构造“治疗全部伤兵”的 0x1231/0x1230 payload。

    证据：
    - `q.l1()` 对 0x8231 的 readShort 为负数时展示 `re_提示治疗全部`；
    - 旧辅助 shape 的 0x1230 tail 为 `02 0000 ffffffff 00`，即 group=2、soldierType=0、count=-1、useGold=0。
    """
    return build_heal_preinfo_payload(fief_id, -1, -1), build_heal_payload(fief_id, 2, 0, -1, use_gold=False)


def parse_heal_preinfo_response(payload: bytes) -> dict[str, Any]:
    """解析 0x8231 治疗预估响应：readLong, readShort, readLong, readLong。"""
    out: dict[str, Any] = {"rawHex": payload.hex()[:4096], "textPreview": printable(payload, 1200)}
    try:
        if len(payload) < 26:
            return {**out, "success": False, "message": "0x8231 响应过短"}
        out.update({
            "success": True,
            "fiefId": struct.unpack(">q", payload[0:8])[0],
            "soldierType": struct.unpack(">h", payload[8:10])[0],
            "copperCost": struct.unpack(">q", payload[10:18])[0],
            "goldCost": struct.unpack(">q", payload[18:26])[0],
        })
    except Exception as e:
        out.update({"success": False, "parseError": str(e)})
    return out


def parse_heal_response(payload: bytes) -> dict[str, Any]:
    """解析 0x8230 治疗响应：readByte status, readLong, readLong, readByte hasExtraState。"""
    out: dict[str, Any] = {"rawHex": payload.hex()[:4096], "textPreview": printable(payload, 1200)}
    try:
        if len(payload) < 18:
            return {**out, "success": False, "message": "0x8230 响应过短"}
        status = struct.unpack(">b", payload[0:1])[0]
        messages = {0: "治疗成功", -1: "铜钱不足", -2: "治疗失败", -3: "黄金不足"}
        out.update({
            "status": status,
            "success": status == 0,
            "message": messages.get(status, f"未知治疗状态 {status}"),
            "firstLong": struct.unpack(">q", payload[1:9])[0],
            "secondLong": struct.unpack(">q", payload[9:17])[0],
            "hasExtraState": bool(payload[17]),
        })
    except Exception as e:
        out.update({"success": False, "parseError": str(e)})
    return out


def action_target_hex(target: dict[str, Any]) -> str:
    raw = "".join(c for c in str(target.get("rawRecord") or "") if c in "0123456789abcdefABCDEF").lower()
    # 结构化 0x8540 记录开头就是 8-byte target id，随后才是 UTF 名称长度。
    # 不能取“前10字节尾8字节”，那会把名称长度 000a 拼进 target long，
    # 造成 0x1522 被游戏服以 0x8522=ff0000 拒绝。
    if target.get("source") == "8540-structured" and len(raw) >= 16:
        return raw[:16]
    if len(raw) >= 18:
        return raw[:18][-16:]
    return str(target.get("idHex") or format(int(target["id"]), "x")).removeprefix("0x").rjust(16, "0")


def action_target_hex_candidates(target: dict[str, Any]) -> list[dict[str, str]]:
    """Return target encodings worth trying for 山贼 dispatch.

    For structured 0x8540 records the first 8 bytes are the map target id.  A later
    live dispatch matrix also showed actionType=10 with the "id+UTF-name-len shifted"
    long returning a non-ff 0x8522 on this server family, so we keep both encodings
    but try the type-10 shifted form first.  Each candidate records its evidence label
    so reports/logs explain exactly what was sent.
    """
    raw = "".join(c for c in str(target.get("rawRecord") or "") if c in "0123456789abcdefABCDEF").lower()
    candidates: list[dict[str, str]] = []

    def add(label: str, hx: str) -> None:
        clean = "".join(c for c in str(hx or "") if c in "0123456789abcdefABCDEF").lower()
        if len(clean) < 16:
            return
        # 1520/1522 Java client methods pass target as a long, so canonical candidates
        # are exactly 8 bytes.  Longer "raw10" probes were useful diagnostically but
        # are not safe as production dispatch because they append unread bytes.
        clean = clean[-16:]
        if not any(x["targetHex"] == clean for x in candidates):
            candidates.append({"label": label, "targetHex": clean})

    if len(raw) >= 20:
        add("raw10_tail8_id_plus_utf_len", raw[:20][-16:])
    if target.get("source") == "8540-structured" and len(raw) >= 16:
        add("structured_record_first8_id", raw[:16])
    if len(raw) >= 18:
        add("legacy_first10_tail8", raw[:18][-16:])
    add("id_hex", str(target.get("idHex") or format(int(target["id"]), "x")).removeprefix("0x").rjust(16, "0"))
    return candidates


def composition_code(target: dict[str, Any]) -> str:
    comp = target.get("composition")
    if not isinstance(comp, dict) or comp.get("source") != "8540-units":
        return ""
    return "".join(str(int(comp.get(key, 0))) for key in ("foot", "bow", "cavalry", "chariot"))


def bandit_drop_categories(description: Any) -> list[str]:
    text = str(description or "")
    return [category for category in ("资源", "宝箱", "装备", "宝物") if category in text]


def parse_8540_targets(payload: bytes) -> list[dict[str, Any]]:
    """优先用 8540 的结构化记录解析真实目标；失败则回退 marker 扫描。"""
    targets = []
    try:
        if len(payload) < 5:
            return []
        map_w = int.from_bytes(payload[0:2], "big")
        map_h = int.from_bytes(payload[2:4], "big")
        count = payload[4]
        p = 5
        for _ in range(count):
            start = p
            rid = int.from_bytes(payload[p:p + 8], "big"); p += 8
            name, p = read_utf(payload, p)
            raw_after_name = payload[p:p + 7].hex().upper()
            # 已观察到：byte2 与 name 中的等级一致；后续包含目标列表元数据。
            meta_a = payload[p]; meta_b = payload[p + 1]; level_byte = payload[p + 2]; p += 3
            meta_d = int.from_bytes(payload[p:p + 2], "big"); p += 2
            meta_e = int.from_bytes(payload[p:p + 2], "big"); p += 2
            resource, p = read_utf(payload, p)
            resource_1 = int.from_bytes(payload[p:p + 4], "big", signed=True); p += 4
            resource_2 = int.from_bytes(payload[p:p + 4], "big", signed=True); p += 4
            x, y = meta_d, meta_e
            loot_count = payload[p]; p += 1
            loot_ids = []
            for _loot_index in range(loot_count):
                loot_ids.append(int.from_bytes(payload[p:p + 4], "big")); p += 4
            unit_count = payload[p]; p += 1
            composition = {"foot": 0, "bow": 0, "cavalry": 0, "chariot": 0, "source": "8540-units"}
            units = []
            major_keys = {0: "foot", 1: "bow", 2: "cavalry", 4: "chariot"}
            for _unit_index in range(unit_count):
                general_name, p = read_utf(payload, p)
                unit_a = int.from_bytes(payload[p:p + 2], "big"); p += 2
                unit_uid = int.from_bytes(payload[p:p + 2], "big"); p += 2
                unit_b = payload[p]; major_code = payload[p + 1]; soldier_code = payload[p + 2]; p += 3
                soldier_count = int.from_bytes(payload[p:p + 4], "big", signed=True); p += 4
                major_key = major_keys.get(major_code)
                if major_key is None:
                    raise ValueError(f"未知山贼兵种大类码 {major_code}")
                composition[major_key] += 1
                units.append({
                    "generalName": general_name, "a": unit_a, "uid": unit_uid, "b": unit_b,
                    "majorCode": major_code, "soldierTypeCode": soldier_code, "soldierCount": soldier_count,
                })
            m = re.search(r"(\d+)级", name)
            level = int(m.group(1)) if m else int(level_byte)
            kind = "山贼" if "山贼" in name or "山賊" in name else ("黄巾" if "黄巾" in name or "黃巾" in name else name)
            raw_record = f"{rid:016X}" + utf(name).hex().upper()
            target = {
                "id": rid,
                "idHex": f"{rid:012x}",
                "kind": kind,
                "name": name,
                "level": level,
                "x": x,
                "y": y,
                "rank": level,
                "resource": resource,
                "resource1": resource_1,
                "resource2": resource_2,
                "rawRecord": raw_record,
                "lootIds": loot_ids,
                "dropCategories": bandit_drop_categories(resource),
                "units": units,
                "meta": {"mapWidth": map_w, "mapHeight": map_h, "a": meta_a, "b": meta_b, "levelByte": level_byte, "d": meta_d, "e": meta_e},
                "composition": composition,
                "compositionCode": "".join(str(composition[key]) for key in ("foot", "bow", "cavalry", "chariot")),
                "source": "8540-structured",
            }
            targets.append(target)
            if p >= len(payload):
                break
    except Exception:
        targets = []
    return targets or scan_targets(payload.hex())


def parse_8542_resources(payload: bytes) -> list[dict[str, Any]]:
    """Parse the original client's reqResourceList (0x8542) response.

    The field order follows scriptPages/game/p.i1(String). Unknown fields are
    deliberately retained under ``detail`` instead of being assigned guessed
    business meanings.
    """
    p = 0

    def need(size: int, field: str) -> None:
        if p + size > len(payload):
            raise ValueError(
                f"0x8542 truncated at {field}: pos={p} need={size} size={len(payload)}"
            )

    def u8(field: str) -> int:
        nonlocal p
        need(1, field)
        value = payload[p]
        p += 1
        return value

    def u16(field: str) -> int:
        nonlocal p
        need(2, field)
        value = struct.unpack(">H", payload[p:p + 2])[0]
        p += 2
        return value

    def i32(field: str) -> int:
        nonlocal p
        need(4, field)
        value = struct.unpack(">i", payload[p:p + 4])[0]
        p += 4
        return value

    def i64(field: str) -> int:
        nonlocal p
        need(8, field)
        value = struct.unpack(">q", payload[p:p + 8])[0]
        p += 8
        return value

    def text(field: str) -> str:
        nonlocal p
        need(2, field)
        length = struct.unpack(">H", payload[p:p + 2])[0]
        p += 2
        need(length, field)
        value = payload[p:p + length].decode("utf-8", errors="replace")
        p += length
        return value

    if len(payload) < 5:
        raise ValueError(f"0x8542 response too short: {len(payload)}")
    center_x = u16("centerX")
    center_y = u16("centerY")
    count = u8("resourceCount")
    resources: list[dict[str, Any]] = []
    for index in range(count):
        start = p
        resource_id = i64(f"resource[{index}].id")
        type_code = u8(f"resource[{index}].type")
        level = u8(f"resource[{index}].level")
        x = u16(f"resource[{index}].x")
        y = u16(f"resource[{index}].y")
        detail_flag = u8(f"resource[{index}].detailFlag")
        detail: dict[str, Any] = {
            "flag": detail_flag,
            "ownerName": "",
            "ownerCountry": "",
            # 保留旧键，兼容已经打开的前端和旧设置读取。
            "text1": "",
            "text2": "",
            "amountA": None,
            "amountB": None,
            "description": "",
            "valueJ": None,
            "valueK": None,
        }
        if detail_flag == 0:
            owner_name = text(f"resource[{index}].ownerName")
            owner_country = text(f"resource[{index}].ownerCountry")
            detail.update({
                "ownerName": owner_name,
                "ownerCountry": owner_country,
                "text1": owner_name,
                "text2": owner_country,
            })
        # 抓包和原客户端 p.i1(String) 均证明以下字段对所有记录都存在。
        # 旧代码仅在 detailFlag==0 时读取，遇到普通 NPC 矿就会从这里开始错位。
        detail.update({
            "amountA": i32(f"resource[{index}].amountA"),
            "amountB": i32(f"resource[{index}].amountB"),
            "description": text(f"resource[{index}].description"),
            "valueJ": i32(f"resource[{index}].valueJ"),
            "valueK": i32(f"resource[{index}].valueK"),
        })
        troop_groups = []
        for troop_index in range(u8(f"resource[{index}].troopGroupCount")):
            troop_groups.append({
                "typeCode": u8(
                    f"resource[{index}].troops[{troop_index}].type"
                ),
                "count": u16(
                    f"resource[{index}].troops[{troop_index}].count"
                ),
                "levelOrStatus": u8(
                    f"resource[{index}].troops[{troop_index}].levelOrStatus"
                ),
            })
        defenders = []
        for defender_index in range(u8(f"resource[{index}].defenderCount")):
            defenders.append({
                "generalName": text(
                    f"resource[{index}].defenders[{defender_index}].name"
                ),
                "fieldS": u16(
                    f"resource[{index}].defenders[{defender_index}].fieldS"
                ),
                "fieldR": u16(
                    f"resource[{index}].defenders[{defender_index}].fieldR"
                ),
                "fieldT": u8(
                    f"resource[{index}].defenders[{defender_index}].fieldT"
                ),
                "troopTypeCode": u8(
                    f"resource[{index}].defenders[{defender_index}].troopType"
                ),
                "generalLevelOrStatus": u8(
                    f"resource[{index}].defenders[{defender_index}].generalLevelOrStatus"
                ),
                "troopCount": i32(
                    f"resource[{index}].defenders[{defender_index}].troopCount"
                ),
            })
        protocol_name = RESOURCE_POINT_NAMES.get(type_code, f"资源点{type_code}")
        kind = (
            {1: "一级牧场", 2: "二级牧场", 3: "三级牧场"}.get(
                level, f"{level}级牧场"
            )
            if type_code == 0x05
            else protocol_name
        )
        owner_name = str(detail.get("ownerName") or "").strip()
        owner_country = str(detail.get("ownerCountry") or "").strip()
        player_occupied = bool(owner_name or owner_country)
        resources.append({
            "id": resource_id,
            "idHex": f"{resource_id & 0xffffffffffffffff:016x}",
            "kind": kind,
            "protocolKind": protocol_name,
            "name": kind if type_code == 0x05 else f"{level}级{kind}",
            "typeCode": type_code,
            "businessId": MINE_BUSINESS_IDS.get(kind),
            "level": level,
            "rank": level,
            "x": x,
            "y": y,
            "detailFlag": detail_flag,
            "detail": detail,
            "ownerName": owner_name,
            "ownerCountry": owner_country,
            "playerOccupied": player_occupied,
            "unoccupiedByPlayer": not player_occupied,
            "troopGroups": troop_groups,
            "defenders": defenders,
            "defenderCount": len(defenders),
            "hasDefenders": bool(defenders),
            # “空矿”在业务中指没有玩家占领，而不是没有 NPC 守军。
            "isEmpty": not player_occupied,
            "occupied": player_occupied,
            "amountA": detail.get("amountA"),
            "amountB": detail.get("amountB"),
            # 兼容旧字段名；字段真实业务含义尚未由客户端静态表完全命名。
            "storage": detail.get("amountA"),
            "productionPerHour": detail.get("amountB"),
            "description": detail.get("description"),
            "valueJ": detail.get("valueJ"),
            "valueK": detail.get("valueK"),
            "rawRecord": payload[start:p].hex(),
            "source": "8542-structured",
            "meta": {
                "centerX": center_x,
                "centerY": center_y,
                "recordIndex": index,
            },
        })
    if p != len(payload):
        for resource in resources:
            resource.setdefault("meta", {})["trailingHex"] = payload[p:].hex()
    return resources


def scan_targets(response_hex: str) -> list[dict[str, Any]]:
    norm = "".join(c for c in response_hex.upper() if c in "0123456789ABCDEF")
    out: list[dict[str, Any]] = []
    for marker, kind in KIND_MARKERS.items():
        start = 0
        while True:
            idx = norm.find(marker, start)
            if idx < 0:
                break
            for prefix in (26, 24, 22, 20, 18):
                s = idx - prefix
                if s < 0:
                    continue
                rec = norm[s:idx + len(marker)]
                if len(rec) < 20:
                    continue
                try:
                    id_hex = rec[:12]
                    tid = int(id_hex, 16)
                    m = re.search(r"000A([0-9A-F]{2})" + marker + r"$", rec)
                    level = 0
                    if m:
                        b = int(m.group(1), 16)
                        if 48 <= b <= 57:
                            level = b - 48
                    rank = {"渠帅": 11, "主将": 12, "主帅": 13}.get(kind, level)
                    if tid > 0:
                        out.append({
                            "id": tid, "idHex": id_hex.lower(), "kind": kind, "name": f"{level}级{kind}" if level else kind,
                            "rank": rank, "level": level, "x": 0, "y": 0, "rawRecord": rec,
                            "composition": None, "compositionCode": "", "source": "marker-scan"
                        })
                        break
                except Exception:
                    pass
            start = idx + len(marker)
    seen = set(); res = []
    for t in out:
        k = (t["id"], t["kind"], t.get("level"), t.get("rawRecord"))
        if k not in seen:
            seen.add(k); res.append(t)
    return res


def match_composition(target: dict[str, Any], filt: dict[str, Any]) -> bool:
    if not filt:
        return True
    comp = target.get("composition") or {}
    if comp.get("source") != "8540-units":
        return False
    foot = int(comp.get("foot", 0)); bow = int(comp.get("bow", 0)); cav = int(comp.get("cavalry", 0)); car = int(comp.get("chariot", 0))
    max_foot = int(filt.get("maxFoot", 9)); max_bow = int(filt.get("maxBow", 9)); max_cav = int(filt.get("maxCavalry", 9)); max_car = int(filt.get("maxChariot", 9))
    require_foot = bool(filt.get("requireFoot", False))
    if require_foot and foot <= 0:
        return False
    return foot <= max_foot and bow <= max_bow and cav <= max_cav and car <= max_car


def normalize_drop_keyword(drop: Any) -> str:
    text = str(drop or "").strip()
    if text in {"宝物", "资源", "装备", "宝箱"}:
        return text
    if text in {"铜钱", "粮食", "粮草", "资源类"}:
        return "资源"
    return ""


def normalize_drop_keywords(drop: Any, drops: Any = None) -> list[str]:
    raw_values: list[Any] = []
    if isinstance(drops, list):
        raw_values.extend(drops)
    elif drops not in (None, ""):
        raw_values.extend(re.split(r"[,，;；|\s]+", str(drops)))
    if isinstance(drop, list):
        raw_values.extend(drop)
    elif drop not in (None, ""):
        raw_values.extend(re.split(r"[,，;；|\s]+", str(drop)))
    if any(str(x).strip() == "不限" for x in raw_values):
        return ["宝物", "资源", "装备", "宝箱"]
    out: list[str] = []
    for item in raw_values:
        keyword = normalize_drop_keyword(item)
        if keyword and keyword not in out:
            out.append(keyword)
    return out


def match_drop(target: dict[str, Any], drop: Any) -> bool:
    keywords = normalize_drop_keywords(drop)
    if not keywords:
        return True
    if set(keywords) == {"宝物", "资源", "装备", "宝箱"}:
        return True
    haystack = " ".join(str(v or "") for v in [
        target.get("resource"),
        target.get("reward"),
        target.get("drop"),
        target.get("name"),
        target.get("rawRecord"),
    ])
    return any(keyword in haystack for keyword in keywords)


def parse_passport_area_list(text: str) -> tuple[str, str, list[dict[str, str]]]:
    lines = [x.strip() for x in text.splitlines() if x.strip()]
    if not lines or "`" not in lines[0]:
        raise RuntimeError("账号登录失败或 passport 返回异常")
    head = lines[0].split("`")
    if len(head) < 2:
        raise RuntimeError("passport 区服列表响应缺少 session/userId")
    session, user_id = head[0], head[1]
    areas: list[dict[str, str]] = []
    for line in lines[1:]:
        p = line.split("`")
        if len(p) >= 12:
            areas.append({"target": p[0], "areaId": p[1], "areaName": p[2], "serverUrl": p[3], "serverKey": p[11]})
    if not areas:
        raise RuntimeError("passport 未返回任何区服")
    return session, user_id, areas


def fetch_passport_area_list(
    username: str,
    password: str,
    platform: Any = None,
) -> tuple[str, str, list[dict[str, str]]]:
    profile = platform_profile(platform)
    params: dict[str, Any] = {
        "username": username,
        "password": password,
        "channelId": profile["channel"],
        "source": SOURCE,
        "cType": CTYPE,
        "cVersion": VERSION,
        "gameKey": GAME_KEY,
        "target": TARGETS,
    }
    if profile.get("auth") == "downjoy_sdk":
        sdk_login = downjoy_sdk_login(username, password)
        # Exact DangleYAPI callback data flow:
        # P=umid, Q=urlEncode(LoginInfo.userName), O=token. The bundled
        # Downjoy SDK constructs successful LoginInfo with userName="".
        params.update({
            "session": sdk_login["token"],
            "username": sdk_login["umid"],
            "password": sdk_login["callbackUsername"],
            "imei": "",
            "macId": "",
        })
    text = http_get(
        str(profile["passport"]) + "common/area/list.action",
        params,
    )
    return parse_passport_area_list(text)


def area_catalog_signature(areas: list[dict[str, Any]]) -> str:
    normalized = sorted(
        [{
            "target": str(area.get("target") or ""),
            "areaId": str(area.get("areaId") or ""),
            "areaName": str(area.get("areaName") or ""),
            "serverUrl": str(area.get("serverUrl") or ""),
            "serverKey": str(area.get("serverKey") or ""),
        } for area in areas],
        key=lambda area: (area["serverKey"], area["areaId"], area["areaName"]),
    )
    return json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def read_area_catalog(platform: Any = None) -> dict[str, Any]:
    if not ACCOUNT_STATE_DB_READY:
        return {"areas": [], "updatedAt": None, "count": 0}
    platform_key = normalize_platform_key(platform)
    with AREA_CATALOG_LOCK, ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT target, area_id, area_name, server_url, server_key, updated_at
            FROM area_catalog
            WHERE platform=?
            ORDER BY server_key, area_id, area_name
            """,
            (platform_key,),
        ).fetchall()
    areas = [{
        "target": str(row["target"] or ""),
        "areaId": str(row["area_id"] or ""),
        "areaName": str(row["area_name"] or ""),
        "serverUrl": str(row["server_url"] or ""),
        "serverKey": str(row["server_key"] or ""),
    } for row in rows]
    return {
        "areas": areas,
        "updatedAt": max((int(row["updated_at"]) for row in rows), default=None),
        "count": len(areas),
        "platform": platform_display_name(platform_key),
        "platformKey": platform_key,
    }


def update_area_catalog_if_changed(
    areas: list[dict[str, Any]],
    platform: Any = None,
) -> bool:
    platform_key = normalize_platform_key(platform)
    clean_areas: list[dict[str, str]] = []
    by_identity: dict[tuple[str, str, str], dict[str, str]] = {}
    for area in areas:
        area_name = str(area.get("areaName") or "").strip()
        if not area_name:
            continue
        area_id = str(area.get("areaId") or "")
        server_key = str(area.get("serverKey") or "")
        identity = (server_key, area_id, area_name)
        target = str(area.get("target") or "")
        existing = by_identity.get(identity)
        if existing:
            targets = [x for x in existing.get("target", "").split(",") if x]
            if target and target not in targets:
                existing["target"] = ",".join([*targets, target])
            continue
        item = {
            "target": target,
            "areaId": area_id,
            "areaName": area_name,
            "serverUrl": str(area.get("serverUrl") or ""),
            "serverKey": server_key,
        }
        by_identity[identity] = item
        clean_areas.append(item)
    with AREA_CATALOG_LOCK:
        current = read_area_catalog(platform_key)
        if area_catalog_signature(current.get("areas") or []) == area_catalog_signature(clean_areas):
            return False
        updated_at = now_ms()
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                connection.execute(
                    "DELETE FROM area_catalog WHERE platform=?",
                    (platform_key,),
                )
                connection.executemany(
                    """
                    INSERT INTO area_catalog
                        (platform, server_key, area_id, area_name, target, server_url, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                    """,
                    [(
                        platform_key,
                        area["serverKey"], area["areaId"], area["areaName"],
                        area["target"], area["serverUrl"], updated_at,
                    ) for area in clean_areas],
                )
                connection.execute("COMMIT")
            except Exception:
                connection.execute("ROLLBACK")
                raise
    system_log(
        f"{platform_display_name(platform_key)}区服目录已更新：共 {len(clean_areas)} 个区服",
        source="area-catalog",
    )
    return True


def find_login_area(areas: list[dict[str, str]], server_query: str) -> dict[str, str] | None:
    query = str(server_query or "").strip()
    if not query:
        return None
    exact = next((
        area for area in areas
        if query in {area.get("areaName"), area.get("serverKey"), area.get("areaId")}
    ), None)
    if exact:
        return exact
    query_lower = query.lower()
    zone_match = (
        re.search(r"qzone[_-]?(\d+)", query_lower)
        or re.search(r"(\d+)\s*区", query_lower)
    )
    if zone_match:
        zone_number = zone_match.group(1)
        expected_key = f"qzone_{zone_number}"
        by_key = next((
            area for area in areas
            if str(area.get("serverKey") or "").strip().lower() == expected_key
        ), None)
        if by_key:
            return by_key
        by_zone = next((
            area for area in areas
            if (
                (match := re.search(r"(\d+)\s*区", str(area.get("areaName") or "")))
                and match.group(1) == zone_number
            )
        ), None)
        if by_zone:
            return by_zone
    return next((
        area for area in areas
        if (
            query_lower in str(area.get("areaName") or "").lower()
            or str(area.get("areaName") or "").lower() in query_lower
        )
    ), None)


def fresh_login(
    username: str,
    password: str,
    server_query: str = "",
    account_id: str | None = None,
    *,
    allow_reconnecting: bool = False,
    create_role_if_missing: bool = False,
    platform: Any = None,
) -> dict[str, Any]:
    profile = platform_profile(platform)
    platform_key = str(profile["key"])
    server_query = str(server_query or default_server_query(platform_key)).strip()
    session, user_id, areas = fetch_passport_area_list(
        username,
        password,
        platform_key,
    )
    update_area_catalog_if_changed(areas, platform_key)
    area = find_login_area(areas, server_query)
    if not area:
        raise RuntimeError("未找到区服：" + server_query)
    enter = http_get(
        str(profile["passport"]) + "common/area/enter.action",
        dict(session=session, areaKey=area["serverKey"]),
    ).strip()
    if enter != "1":
        raise RuntimeError("进入区服失败：" + enter)
    game_http = area["serverUrl"].rstrip("/") + "/kingWapServer/HttpClient"
    code, data, packets = post_game(
        game_http,
        [(0x1003, utf(user_id) + utf(session) + utf(str(profile["channel"])))],
        0,
        account_id=account_id,
        allow_reconnecting=allow_reconnecting,
        platform=platform_key,
    )
    p8003 = next((p for p in packets if p.get("opcode") == 0x8003), None)
    if not p8003:
        raise GameProtocolResponseError(
            "0x1003 未返回 0x8003，且未发现已确认的登录拒绝帧："
            + json.dumps(summarize_packets(packets), ensure_ascii=False)
        )
    info = parse8003(p8003["payload"])
    if (
        info["status"] != 0
        and create_role_if_missing
        and "角色" in str(info.get("message") or "")
    ):
        # 已有无痕抓包确认：0x1007 body=UTF角色名+i16头像(7)+i64阵营(1)，
        # 成功返回0x8007 status=0/“角色创建成功”。仅起号模式允许进入此分支。
        seed = int(hashlib.sha256(f"{platform_key}:{username}:{server_query}".encode()).hexdigest()[:12], 16)
        family = "赵钱孙李周吴郑王冯陈褚卫蒋沈韩杨朱秦许何吕施张孔曹严华金魏陶姜"
        given = "天宇文武明杰浩然俊豪志远博雅承安景行修远星河云舟"
        create_errors: list[str] = []
        for attempt in range(8):
            value = seed + attempt * 7919
            role_name = (
                family[value % len(family)]
                + given[(value // len(family)) % len(given)]
                + given[(value // (len(family) * len(given))) % len(given)]
            )
            _create_code, _create_data, create_packets = post_game(
                game_http,
                [(0x1007, utf(role_name) + struct.pack(">hq", 7, 1))],
                int(info["dm"]),
                account_id=account_id,
                allow_reconnecting=allow_reconnecting,
                platform=platform_key,
            )
            p8007 = next((p for p in create_packets if p.get("opcode") == 0x8007), None)
            parsed_create = (
                parse_status_message_payload(p8007.get("payload") or b"")
                if p8007 else
                {"success": False, "message": "未收到0x8007"}
            )
            if parsed_create.get("success"):
                system_log(
                    f"起号账号 {username}@{server_query} 自动创建角色成功：{role_name}",
                    source="starter",
                )
                code, data, packets = post_game(
                    game_http,
                    [(0x1003, utf(user_id) + utf(session) + utf(str(profile["channel"])))],
                    0,
                    account_id=account_id,
                    allow_reconnecting=allow_reconnecting,
                    platform=platform_key,
                )
                p8003 = next((p for p in packets if p.get("opcode") == 0x8003), None)
                if not p8003:
                    raise GameProtocolResponseError("创建角色后重新登录未收到0x8003")
                info = parse8003(p8003["payload"])
                break
            create_errors.append(str(parsed_create.get("message") or "创建失败"))
        else:
            raise RuntimeError("自动创建角色失败：" + "；".join(create_errors[-3:]))
    if info["status"] != 0:
        raise GameServerRejected(
            f"游戏服登录失败：0x8003 status={info['status']}；{info.get('message', '')}"
        )
    role = info["roles"][max(0, int(info["selected"]))] if info["roles"] else None
    if not role:
        raise RuntimeError("账号在该区服无角色")
    post_game(
        game_http,
        [(0x1004, struct.pack(">q", -1))],
        int(info["dm"]),
        account_id=account_id,
        allow_reconnecting=allow_reconnecting,
        platform=platform_key,
    )
    code2, data2, packets2 = post_game(
        game_http,
        [(0x1016, struct.pack(">q", int(role["roleId"])))],
        int(info["dm"]),
        account_id=account_id,
        allow_reconnecting=allow_reconnecting,
        platform=platform_key,
    )
    p8004 = next((p for p in packets2 if p.get("opcode") == 0x8004), None)
    if not p8004:
        raise GameProtocolResponseError(
            "0x1016 未返回 0x8004 角色状态，且未发现0x8016或已抓包确认的拒绝帧："
            + json.dumps(summarize_packets(packets2), ensure_ascii=False)
        )
    state8004 = p8004["payload"].hex() if p8004 else ""
    role_state = parse_8004_head(p8004["payload"], "0x1016/0x8004") if p8004 else {}
    generals = recover_generals_from_8004(state8004) if state8004 else []
    army_state = parse_idle_army_from_8004(state8004, generals) if state8004 else []
    if role_state is not None:
        role_state["idleArmy"] = army_state
    inventory_state = {"items": []}
    try:
        _code_inv, _data_inv, packets_inv = post_game(
            game_http,
            [(0x1104, b"\x00")],
            int(info["dm"]),
            account_id=account_id,
            allow_reconnecting=allow_reconnecting,
            platform=platform_key,
        )
        p8104 = next((p for p in packets_inv if p.get("opcode") == 0x8104), None)
        if p8104:
            inventory_state = parse_8104_inventory(p8104["payload"], "0x1104/0x8104")
    except (GameServerRejected, GameServerThrottled):
        raise
    except Exception as e:
        inventory_state = {"items": [], "parseError": str(e), "sourceOpcode": "0x1104/0x8104"}
    sid = uuid4().hex
    sess = {
        "sessionId": sid,
        "username": username,
        "platform": str(profile["name"]),
        "platformKey": platform_key,
        "gameHttp": game_http,
        "dm": int(info["dm"]),
        "role": role,
        "roleState": role_state,
        "inventory": inventory_state,
        "area": area,
        "passportSession": session,
        "userId": user_id,
        "state8004PayloadHex": state8004,
        "generals": generals,
        "army": army_state,
        "createdAt": now_ms(),
        "lastTargets": [],
    }
    SESSIONS[sid] = sess
    ensure_account_for_session(sess)
    # The account record is migrated from the temporary/local session id only
    # after fresh_login returns. Querying own fiefs here would be rejected by
    # the account request gate. start_account performs this query immediately
    # after that migration instead.
    try:
        refresh_daily_activity(sess)
    except Exception:
        pass
    apply_account_habits_to_session(sess)
    sess["savedCommonTasksStarted"] = False
    sess["savedTasksStarted"] = False
    sess["savedTasksStartedAt"] = None
    account_log(sid, "真实登录成功并已加载该账号保存习惯", source="server")
    persist_runtime_state()
    return sess


def get_session(sid: str) -> dict[str, Any]:
    sess = SESSIONS.get(sid)
    if not sess:
        raise RuntimeError("session 不存在或已过期，请重新登录")
    return sess


