def starter_allowed_extra_fief_count(level: Any) -> int:
    """10级起每10级增加一个不含基地的封地名额。"""
    return max(0, int(level or 0) // 10)


def starter_target_general_count(level: Any) -> int:
    """<10级3将；10级4将；此后每5级增加1将。"""
    value = max(0, int(level or 0))
    if value < 10:
        return 3
    return 4 + max(0, (value - 10) // 5)


def starter_restore_five_stage_state_from_actions(
    job_id: str, sess: dict[str, Any],
) -> None:
    """Recover milestones that must survive reconnect-created session objects."""
    if not job_id:
        return
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT action_type,status,result_json,finished_at,updated_at
            FROM starter_action_queue
            WHERE job_id=?
            ORDER BY id ASC
            """,
            (str(job_id),),
        ).fetchall()
    bandits = {
        int(value)
        for value in sess.get("starterEarlyBanditCompletedLevels") or []
    }
    dungeon_stage = int(sess.get("starterEarlyDungeonCompletedStages") or 0)
    latest_cavalry_state: dict[str, Any] = {}
    latest_dungeon_pending: dict[str, Any] = {}
    dungeon_pending_cleared = False
    latest_dungeon_general_id = str(
        sess.get("starterFiveStageDungeonGeneralId") or ""
    )
    onboarding_complete = bool(sess.get("starterFiveStageOnboardingComplete"))
    for row in rows:
        try:
            result = json.loads(str(row["result_json"] or "{}"))
        except Exception:
            continue
        action_type = str(row["action_type"] or "")
        if result.get("success"):
            target_level = int(result.get("targetLevel") or 0)
            if (
                target_level <= 0
                and action_type == "five-stage-initial-combat"
            ):
                target_match = re.search(
                    r"([123])级山贼", str(result.get("message") or ""),
                )
                target_level = (
                    int(target_match.group(1)) if target_match else 0
                )
            if (
                action_type in {"bandit-cycle", "five-stage-initial-combat"}
                and target_level in {1, 2, 3}
            ):
                bandits.add(target_level)
            stage = result.get("stage") or {}
            general = result.get("general") or {}
            dungeon_general_id = str(
                general.get("id") or general.get("idHex") or ""
            )
            if (
                action_type in {
                    "five-stage-initial-combat", "five-stage-growth",
                }
                and int(stage.get("chapter") or 0) == 0
                and int(stage.get("stage") or 0) in {1, 2}
                and dungeon_general_id
                and (
                    result.get("deploymentSuccess")
                    or (result.get("battle") or {}).get("success")
                )
            ):
                latest_dungeon_general_id = dungeon_general_id
            if (
                action_type in {"dungeon-next", "five-stage-initial-combat"}
                and int(stage.get("chapter") or 0) == 0
                and 1 <= int(stage.get("stage") or 0) <= 2
                and (
                    not result.get("dungeonLaunchedOnly")
                    or bool(result.get("stageCompleted"))
                )
            ):
                dungeon_stage = max(
                    dungeon_stage, int(stage.get("stage") or 0),
                )
            if action_type == "five-stage-onboarding":
                onboarding_complete = True
        state = result.get("state")
        if (
            action_type == "five-stage-growth"
            and isinstance(state, dict)
            and int(state.get("targetCount") or 0) == 200
            and int(state.get("fiefId") or 0) > 0
        ):
            latest_cavalry_state = dict(state)
        pending = result.get("dungeonPending")
        if result.get("dungeonPendingCleared"):
            latest_dungeon_pending = {}
            dungeon_pending_cleared = True
        elif (
            action_type in {
                "five-stage-initial-combat", "five-stage-growth",
            }
            and isinstance(pending, dict)
            and int(pending.get("stage") or 0) in {1, 2}
        ):
            latest_dungeon_pending = dict(pending)
            dungeon_pending_cleared = False
            if str(pending.get("generalId") or ""):
                latest_dungeon_general_id = str(pending["generalId"])
    sess["starterEarlyBanditCompletedLevels"] = sorted(bandits)
    sess["starterEarlyDungeonCompletedStages"] = dungeon_stage
    if onboarding_complete:
        sess["starterFiveStageOnboardingComplete"] = True
    if latest_cavalry_state and not sess.get("starterFiveStageBaseCavalry"):
        sess["starterFiveStageBaseCavalry"] = latest_cavalry_state
    if latest_dungeon_general_id:
        sess["starterFiveStageDungeonGeneralId"] = latest_dungeon_general_id
    if (
        latest_dungeon_pending
        and not sess.get("starterFiveStageDungeonPending")
    ):
        sess["starterFiveStageDungeonPending"] = latest_dungeon_pending
    elif dungeon_pending_cleared and not latest_dungeon_pending:
        sess.pop("starterFiveStageDungeonPending", None)


def starter_initial_combat_complete(
    sess: dict[str, Any], job_id: str = "",
) -> bool:
    starter_restore_five_stage_state_from_actions(job_id, sess)
    completed_bandits = {
        int(value)
        for value in sess.get("starterEarlyBanditCompletedLevels") or []
    }
    return (
        {1, 2, 3}.issubset(completed_bandits)
        and int(sess.get("starterEarlyDungeonCompletedStages") or 0) >= 2
    )


def starter_total_soldiers(sess: dict[str, Any]) -> dict[str, int]:
    """Return soldiers that can be reassigned now.

    Troops carried by marching/fighting/defending generals are real inventory,
    but unavailable to the next formation. Counting them caused the planner to
    request 180 crossbows when only 90 could actually be released.
    """
    totals: dict[str, int] = {}
    army_rows = list(
        sess.get("army")
        or (sess.get("roleState") or {}).get("idleArmy")
        or []
    )
    base_fief_name = next(
        (
            str(row.get("fiefName") or "")
            for row in army_rows
            if str(row.get("fiefName") or "").endswith("基地")
        ),
        "",
    )
    for row in army_rows:
        # Troops still inside the temporary cart fief cannot be assigned to
        # generals stationed at the base. Counting them made the planner ask
        # for 133 carts when the server correctly exposed only 92. They become
        # usable here only after the fief is abandoned and transfer is proven.
        row_fief_name = str(row.get("fiefName") or "")
        if (
            base_fief_name
            and row_fief_name
            and row_fief_name != base_fief_name
        ):
            continue
        name = str(row.get("soldierType") or soldier_type_name(row.get("soldierTypeCode")))
        totals[name] = totals.get(name, 0) + int(
            row.get("idleCount", row.get("count", row.get("amount", 0))) or 0
        )
    for general in sess.get("generals") or []:
        status = general.get("displayStatus") or general.get("statusText") or "未知"
        if status != "闲":
            continue
        count = int(general.get("soldierCount", general.get("currentSoldierCount", 0)) or 0)
        if count <= 0:
            continue
        name = str(general.get("soldierType") or soldier_type_name(general.get("soldierTypeCode")))
        totals[name] = totals.get(name, 0) + count
    return totals


def starter_inventory_soldiers(sess: dict[str, Any]) -> dict[str, int]:
    """Return total owned soldiers, including troops on busy generals."""
    totals: dict[str, int] = {}
    for row in (sess.get("army") or (sess.get("roleState") or {}).get("idleArmy") or []):
        name = str(row.get("soldierType") or soldier_type_name(row.get("soldierTypeCode")))
        totals[name] = totals.get(name, 0) + int(
            row.get("idleCount", row.get("count", row.get("amount", 0))) or 0
        )
    for general in sess.get("generals") or []:
        count = int(general.get("soldierCount", general.get("currentSoldierCount", 0)) or 0)
        if count <= 0:
            continue
        name = str(general.get("soldierType") or soldier_type_name(general.get("soldierTypeCode")))
        totals[name] = totals.get(name, 0) + count
    return totals


def starter_wounded_total(sess: dict[str, Any]) -> int:
    army_wounded = sum(
        max(0, int(
            row.get("woundedCount", row.get("hurtSoldierCount", 0)) or 0
        ))
        for row in (
            sess.get("army")
            or (sess.get("roleState") or {}).get("idleArmy")
            or []
        )
    )
    # 0x8246 list2 is the authoritative wounded list after all generals have
    # returned. The role-state parser can temporarily omit zero-idle troop
    # types, which previously stranded all 180 wounded carts forever.
    all_idle = all(
        (row.get("displayStatus") or row.get("statusText") or "闲") == "闲"
        for row in sess.get("generals") or []
    )
    fief_wounded = 0
    if all_idle:
        fief_wounded = sum(
            max(0, int(row.get("value") or 0))
            for fief in (sess.get("starterFiefBuildings") or {}).get("fiefs") or []
            for row in fief.get("list2") or []
        )
    return max(army_wounded, fief_wounded)


def starter_front_general_score(general: dict[str, Any]) -> tuple[int, int, int]:
    kind = str(general.get("kind") or "")
    kind_score = {"步将": 300, "勇士": 240}.get(kind, 0)
    return (
        kind_score + int(general.get("fangyu") or general.get("defense") or 0),
        int(general.get("troopLimit") or general.get("daiBingLimit") or 0),
        int(general.get("growth") or 0),
    )


def starter_rear_general_score(general: dict[str, Any]) -> tuple[int, int, int]:
    return (
        int(general.get("troopLimit") or general.get("daiBingLimit") or 0),
        int(general.get("gongji") or general.get("attack") or 0),
        int(general.get("growth") or 0),
    )


def starter_general_ref(general: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": str(general.get("id") or general.get("idHex") or ""),
        "idHex": general.get("idHex"),
        "name": general.get("name") or "",
        "kind": general.get("kind") or "",
        "troopLimit": int(general.get("troopLimit") or general.get("daiBingLimit") or 0),
        "status": general.get("displayStatus") or general.get("statusText") or "未知",
        "energy": int(general.get("tili") or 0),
    }


def starter_first_pack_opened(sess: dict[str, Any]) -> bool:
    """Return whether the first beginner pack has definitely been opened."""
    if bool(sess.get("starterFirstPackOpened")):
        return True
    inventory = sess.get("inventory") or {}
    opened = any(
        str(row.get("name") or "").startswith("新手礼包")
        and str(row.get("name") or "") != "新手礼包"
        and int(row.get("count") or 0) > 0
        for row in inventory.get("items") or []
    )
    if opened:
        sess["starterFirstPackOpened"] = True
        persist_runtime_state()
    return opened


def starter_refill_low_energy_generals(
    sess: dict[str, Any],
    *,
    threshold: int = 20,
) -> list[dict[str, Any]]:
    """Use one blood pill for each idle general below the dispatch threshold."""
    low = [
        row for row in sess.get("generals") or []
        if (row.get("displayStatus") or row.get("statusText") or "闲") == "闲"
        and row.get("energyReliable", True)
        and row.get("tili") is not None
        and int(row.get("tili") or 0) < int(threshold)
    ]
    if not low:
        return []
    inventory = refresh_inventory(sess)
    available = sum(
        int(row.get("count") or row.get("amount") or 0)
        for row in inventory.get("items") or []
        if int(row.get("itemId") or -1) == 12
    )
    results: list[dict[str, Any]] = []
    for general in low[:available]:
        result = execute_use_energy_item(
            sess,
            str(general.get("id") or general.get("idHex") or ""),
            confirm="use-energy-item",
        )
        results.append(result)
        if result.get("success"):
            record_success_action(
                str(sess.get("sessionId") or ""),
                "加体",
                f"起号自动加体 > {general.get('name') or general.get('id')}使用1枚活血丹",
                detail=result,
            )
        time.sleep(0.2)
    if results:
        refresh_generals(sess)
    return results


def starter_military_plan(sess: dict[str, Any]) -> dict[str, Any]:
    """Build dynamic dungeon/bandit/lossless formations without fixed IDs."""
    level = int((sess.get("roleState") or {}).get("level") or (sess.get("role") or {}).get("level") or 0)
    idle = [
        row for row in sess.get("generals") or []
        if (row.get("displayStatus") or row.get("statusText") or "闲") == "闲"
        and int(row.get("tili") or 0) > 0
    ]
    totals = starter_total_soldiers(sess)
    heavy = int(totals.get("重步兵") or 0)
    vehicles = int(totals.get("弩车") or 0)
    bows = int(totals.get("弩兵") or 0)
    cavalry = int(totals.get("轻骑兵") or 0)

    # Brand-new roles use one deterministic bootstrap route:
    # beginner pack -> one base vehicle camp -> 200 crossbow vehicles with
    # recruit-order acceleration -> dungeon stages 1/2/3. Only afterwards do
    # they return to the direct-search pre-30 bandit/development loop.
    if level < 30:
        bootstrap = dict(sess.get("starterBaseVehicleBootstrap") or {})
        bootstrap_completed = bool(bootstrap.get("completed"))
        completed_bandits = {
            int(value)
            for value in sess.get("starterEarlyBanditCompletedLevels") or []
            if int(value) in {1, 2, 3}
        }
        next_bandit_level = next((
            value for value in (1, 2, 3) if value not in completed_bandits
        ), None)
        early_dungeon_count = int(
            sess.get("starterEarlyDungeonCompletedStages") or 0
        )
        chosen = (
            max(idle, key=starter_rear_general_score)
            if idle and vehicles > 0 else None
        )
        early_count = min(
            vehicles,
            int((chosen or {}).get("troopLimit") or vehicles),
            200,
        )
        early_team = ({
            "team": 1,
            "early": True,
            "targetLevel": int(next_bandit_level),
            "formationCode": "",
            "roles": [{
                "general": starter_general_ref(chosen),
                "soldierType": "弩车",
                "desiredCount": early_count,
            }],
        } if (
            bootstrap_completed
            and early_dungeon_count >= 3
            and chosen and early_count > 0 and next_bandit_level
        ) else None)
        early_dungeon_ready = bool(
            bootstrap_completed
            and chosen and early_count >= 200
            and early_dungeon_count < 3
        )
        recommended = (
            "recruit-and-build" if not bootstrap_completed
            else "dungeon" if early_dungeon_ready
            else "bandit" if early_team
            else "recruit-and-build"
        )
        return {
            "policyVersion": STARTER_LEVELING_POLICY["version"],
            "level": level,
            "soldiers": totals,
            "idleGeneralCount": len(idle),
            "recommendedTask": recommended,
            "reason": (
                "先打开新手礼包，在基地建1座战车营并招满200弩车"
                if not bootstrap_completed else
                f"基地200弩车已准备，继续副本第{early_dungeon_count + 1}关"
                if early_dungeon_ready else
                f"副本1至3关已完成，挑战{next_bandit_level}级山贼"
                if early_team else
                "前期副本与山贼目标已完成，继续发展"
            ),
            "earlyBootstrap": {
                "firstPackOpened": starter_first_pack_opened(sess),
                "completed": bootstrap_completed,
                "state": bootstrap,
                "requiredBaseVehicleCount": 200,
                "requiredDungeonStages": 3,
            },
            "dungeon": {
                "ready": early_dungeon_ready,
                "mode": "early",
                "completedStageCount": early_dungeon_count,
                "roles": ([{
                    "role": "early-dungeon",
                    "general": starter_general_ref(chosen),
                    "soldierType": "弩车",
                    "desiredCount": early_count,
                }] if chosen and early_count > 0 else []),
            },
            "bandit": {
                "ready": bool(early_team),
                "directUnder30": True,
                "targetLevels": [int(next_bandit_level)] if next_bandit_level else [],
                "formationCode": "",
                "teams": [early_team] if early_team else [],
            },
            "lossless": {
                "enabled": False,
                "targetLevel": 10,
                "requiredTeams": 2,
                "requiredGenerals": 4,
            },
            "updatedAt": now_ms(),
        }

    # Mid bootstrap: before stage 3 rewards grant 150 heavy infantry and
    # 150 crossbows, use the initial cavalry plus newly produced crossbow
    # vehicles to clear that stage. Requiring the reward troops here would
    # create a circular deadlock.
    if (heavy < 150 or bows < 150) and cavalry > 0 and vehicles >= 150 and len(idle) >= 2:
        ranked = sorted(idle, key=starter_rear_general_score, reverse=True)
        cavalry_general, vehicle_general = ranked[:2]
        unlock_roles = [
            {
                "role": "stage3-front",
                "general": starter_general_ref(cavalry_general),
                "soldierType": "轻骑兵",
                "desiredCount": min(
                    cavalry,
                    int(cavalry_general.get("troopLimit") or cavalry),
                    200,
                ),
            },
            {
                "role": "stage3-rear",
                "general": starter_general_ref(vehicle_general),
                "soldierType": "弩车",
                "desiredCount": min(
                    vehicles,
                    int(vehicle_general.get("troopLimit") or vehicles),
                    200,
                ),
            },
        ]
        return {
            "policyVersion": STARTER_LEVELING_POLICY["version"],
            "level": level,
            "soldiers": totals,
            "idleGeneralCount": len(idle),
            "recommendedTask": "dungeon",
            "reason": "弩车已准备，使用轻骑兵和弩车推进三级副本以领取重步兵、弩兵",
            "dungeon": {
                "ready": True,
                "mode": "unlock-heavy",
                "roles": unlock_roles,
            },
            "bandit": {
                "ready": False,
                "targetLevels": [6, 7],
                "formationCode": "0500",
                "teams": [],
            },
            "lossless": {
                "enabled": False,
                "targetLevel": 10,
                "requiredTeams": 2,
                "requiredGenerals": 4,
            },
            "updatedAt": now_ms(),
        }

    # Build a three-general dungeon option first. It remains a proposal; the
    # command center decides whether to reserve these generals or run bandits.
    dungeon_roles = []
    available = list(idle)
    for soldier, preferred_kind in (("重步兵", ("步将", "勇士")), ("弩兵", ("弓将",)), ("弩车", ())):
        if not available:
            break
        ranked = sorted(
            available,
            key=lambda row: (
                1 if str(row.get("kind") or "") in preferred_kind else 0,
                starter_rear_general_score(row),
            ),
            reverse=True,
        )
        chosen = ranked[0]
        available.remove(chosen)
        desired = {"重步兵": 150, "弩兵": 150, "弩车": 200}[soldier]
        dungeon_roles.append({
            "role": "dungeon",
            "general": starter_general_ref(chosen),
            "soldierType": soldier,
            "desiredCount": min(desired, int(totals.get(soldier) or 0)),
        })
    dungeon_ready = (
        len(dungeon_roles) == 3 and heavy >= 150 and bows >= 150 and vehicles > 0
    )

    front_count = 199 if heavy >= 199 else 50
    bandit_level = 7 if front_count == 199 else 6
    max_policy_teams = 3
    team_count = min(max_policy_teams, heavy // front_count, len(idle) // 2)
    if vehicles <= 0:
        team_count = 0
    fronts = sorted(idle, key=starter_front_general_score, reverse=True)[:team_count]
    remaining = [row for row in idle if row not in fronts]
    rears = sorted(remaining, key=starter_rear_general_score, reverse=True)[:team_count]
    team_count = min(team_count, len(rears))
    vehicle_share = vehicles // team_count if team_count else 0
    bandit_teams = []
    for index in range(team_count):
        rear_limit = int(rears[index].get("troopLimit") or rears[index].get("daiBingLimit") or vehicle_share)
        bandit_teams.append({
            "team": index + 1,
            "targetLevel": bandit_level,
            "formationCode": "0500" if level >= 30 else "",
            "front": {
                "general": starter_general_ref(fronts[index]),
                "soldierType": "重步兵",
                "desiredCount": front_count,
            },
            "rear": {
                "general": starter_general_ref(rears[index]),
                "soldierType": "弩车",
                "desiredCount": min(vehicle_share, rear_limit),
            },
            "afterBattle": ["治疗全部伤兵", f"补满{front_count}重步兵"],
        })

    # Only a battle-result message that explicitly confirms defeat may stop
    # the dungeon route. Older versions set starterDungeonStoppedAfterDefeat
    # for generic protocol failures/no-stage states, which could permanently
    # disable a perfectly viable dungeon route.
    dungeon_stopped = bool(sess.get("starterDungeonDefeatConfirmed"))
    no_stage_at_level = int(sess.get("starterDungeonNoAvailableAtLevel") or 0)
    # “当前没有已解锁关卡”只对当时等级有效。刷黄升级后必须重新读取
    # 副本目录，否则一次暂时无关卡会让副本永久停止。
    dungeon_waiting_unlock = bool(
        sess.get("starterDungeonNoAvailableStage")
        and no_stage_at_level > 0
        and level <= no_stage_at_level
    )
    recommended = (
        "completed" if level >= 66
        else "dungeon" if dungeon_ready and not dungeon_stopped and not dungeon_waiting_unlock
        else "bandit" if bandit_teams
        else "heal" if starter_wounded_total(sess) > 0 and len(idle) >= 2
        else "recruit-and-build"
    )
    return {
        "policyVersion": STARTER_LEVELING_POLICY["version"],
        "level": level,
        "soldiers": totals,
        "idleGeneralCount": len(idle),
        "recommendedTask": recommended,
        "reason": {
            "completed": "角色已达到66级",
            "dungeon": "副本初始三将兵种已齐，优先推进至首次战败",
            "bandit": f"当前可组成{len(bandit_teams)}支{bandit_level}级山贼队",
            "heal": "将领已回闲但封地存在伤兵，先治疗并重建刷黄队",
            "recruit-and-build": "兵力或空闲将领不足，继续建筑和招兵",
        }[recommended],
        "dungeon": {
            "ready": dungeon_ready,
            "stoppedAfterDefeat": dungeon_stopped,
            "waitingUnlock": dungeon_waiting_unlock,
            "roles": dungeon_roles,
        },
        "bandit": {
            "ready": bool(bandit_teams),
            "targetLevels": [6, 7] if level >= 30 else [1, 2, 3],
            "formationCode": "0500" if level >= 30 else "",
            "teams": bandit_teams,
        },
        "lossless": {
            "enabled": level >= 10,
            "targetLevel": 10,
            "requiredTeams": 2,
            "requiredGenerals": 4,
            "reuseNormalFilter": True,
        },
        "updatedAt": now_ms(),
    }


def starter_job_row(row: sqlite3.Row | None) -> dict[str, Any] | None:
    if row is None:
        return None
    item = dict(row)
    for key in ("snapshot_json",):
        try:
            item[key.removesuffix("_json")] = json.loads(str(item.get(key) or "{}"))
        except json.JSONDecodeError:
            item[key.removesuffix("_json")] = {}
        item.pop(key, None)
    item["stageLabel"] = STARTER_STAGE_LABELS.get(
        str(item.get("current_stage") or ""),
        str(item.get("current_stage") or ""),
    )
    return item


def list_starter_jobs(account_id: str = "") -> list[dict[str, Any]]:
    sql = "SELECT * FROM starter_jobs"
    params: tuple[Any, ...] = ()
    if account_id:
        sql += " WHERE account_id=?"
        params = (str(account_id),)
    sql += " ORDER BY updated_at DESC"
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(sql, params).fetchall()
    return [starter_job_row(row) for row in rows if row is not None]


def enqueue_starter_action(
    job_id: str,
    action_key: str,
    action_type: str,
    payload: dict[str, Any],
    *,
    priority: int,
    not_before: int = 0,
) -> dict[str, Any]:
    """Idempotently place one planned action in the persistent queue."""
    at = now_ms()
    encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        existing = connection.execute(
            """
            SELECT * FROM starter_action_queue
            WHERE job_id=? AND action_key=? AND status IN ('queued','running')
            ORDER BY id DESC LIMIT 1
            """,
            (str(job_id), str(action_key)),
        ).fetchone()
        if existing:
            if str(existing["status"]) == "queued":
                connection.execute(
                    """
                    UPDATE starter_action_queue
                    SET action_type=?, priority=?, payload_json=?,
                        not_before=CASE
                            WHEN attempts=0 THEN ?
                            ELSE MAX(not_before,?)
                        END,
                        updated_at=?
                    WHERE id=?
                    """,
                    (
                        str(action_type), int(priority), encoded,
                        int(not_before or 0), int(not_before or 0),
                        at, int(existing["id"]),
                    ),
                )
                connection.commit()
            action_id = int(existing["id"])
        else:
            cursor = connection.execute(
                """
                INSERT INTO starter_action_queue(
                    job_id,action_key,action_type,priority,status,payload_json,
                    not_before,created_at,updated_at
                ) VALUES(?,?,?,?, 'queued', ?,?,?,?)
                """,
                (
                    str(job_id), str(action_key), str(action_type), int(priority),
                    encoded, int(not_before or 0), at, at,
                ),
            )
            connection.commit()
            action_id = int(cursor.lastrowid)
        row = connection.execute(
            "SELECT * FROM starter_action_queue WHERE id=?", (action_id,),
        ).fetchone()
    item = dict(row)
    item["payload"] = json.loads(str(item.pop("payload_json") or "{}"))
    try:
        item["result"] = json.loads(str(item.pop("result_json") or "{}"))
    except json.JSONDecodeError:
        item["result"] = {}
    return item


def list_starter_actions(job_id: str, *, limit: int = 100) -> list[dict[str, Any]]:
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT * FROM starter_action_queue
            WHERE job_id=?
            ORDER BY
                CASE status WHEN 'running' THEN 0 WHEN 'queued' THEN 1 ELSE 2 END,
                priority DESC,id DESC
            LIMIT ?
            """,
            (str(job_id), max(1, min(5000, int(limit)))),
        ).fetchall()
    result = []
    for row in rows:
        item = dict(row)
        for source, target in (("payload_json", "payload"), ("result_json", "result")):
            try:
                item[target] = json.loads(str(item.pop(source) or "{}"))
            except json.JSONDecodeError:
                item[target] = {}
        result.append(item)
    return result


def starter_last_action_finished_at(
    job_id: str, action_types: tuple[str, ...],
) -> int:
    if not action_types:
        return 0
    placeholders = ",".join("?" for _ in action_types)
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        row = connection.execute(
            f"""
            SELECT COALESCE(MAX(finished_at),0) AS finished_at
            FROM starter_action_queue
            WHERE job_id=? AND action_type IN ({placeholders})
              AND status IN ('success','failed')
            """,
            (str(job_id), *action_types),
        ).fetchone()
    return int((row or {})["finished_at"] or 0)


def starter_last_successful_action_type(
    job_id: str,
    action_types: tuple[str, ...],
) -> str:
    if not action_types:
        return ""
    placeholders = ",".join("?" for _ in action_types)
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        row = connection.execute(
            f"""
            SELECT action_type
            FROM starter_action_queue
            WHERE job_id=? AND action_type IN ({placeholders})
              AND status='success'
            ORDER BY finished_at DESC, id DESC
            LIMIT 1
            """,
            (str(job_id), *action_types),
        ).fetchone()
    return str(row["action_type"] or "") if row else ""


def starter_five_stage_combat_due(sess: dict[str, Any]) -> bool:
    """Return whether one short combat step can make progress right now."""
    current_time = now_ms()
    pending = dict(sess.get("starterFiveStageDungeonPending") or {})
    if pending and int(pending.get("nextPollAt") or 0) <= current_time:
        return True
    ready_100 = starter_five_stage_ready_cavalry_generals(
        sess, idle_only=True, minimum_count=100,
    )
    if not ready_100:
        return False
    ready_190_ids = {
        str(row.get("id") or row.get("idHex") or "")
        for row in starter_five_stage_ready_cavalry_generals(
            sess, idle_only=True, minimum_count=190,
        )
    }
    if ready_190_ids:
        return True
    retry_at = dict(sess.get("starterFiveStageBanditRetryAt") or {})
    return any(
        int(
            retry_at.get(
                str(general.get("id") or general.get("idHex") or ""),
            ) or 0
        ) <= current_time
        for general in ready_100
    )


def starter_five_stage_plan(job_id: str, sess: dict[str, Any]) -> dict[str, Any]:
    """Select one phase while alternating development and combat after stage 2."""
    starter_restore_five_stage_state_from_actions(job_id, sess)
    level = int(
        (sess.get("roleState") or {}).get("level")
        or (sess.get("role") or {}).get("level")
        or 0
    )
    general_count = len(sess.get("generals") or [])
    target_general_count = starter_target_general_count(level)
    target_fief_count = 1 + starter_allowed_extra_fief_count(level)
    cached_fief_count = int(
        (sess.get("starterFiefBuildings") or {}).get("fiefCount") or 0
    )
    today = time.strftime("%Y-%m-%d", time.localtime())
    onboarding_complete = bool(
        sess.get("starterFiveStageOnboardingComplete")
        or (
            level > 0
            and str(sess.get("starterDailySignInDate") or "") == today
        )
    )
    now = now_ms()
    last_reward = starter_last_action_finished_at(
        job_id, ("claim-rewards", "five-stage-onboarding"),
    )
    reward_due = last_reward <= 0 or now - last_reward >= 300_000
    development_level = int(
        sess.get("starterFiveStageDevelopmentLevel") or -1
    )
    development_at = int(
        sess.get("starterFiveStageDevelopmentAuditedAt") or 0
    )
    development_due = bool(
        development_level != level
        or development_at <= 0
        or now - development_at >= 300_000
        or general_count < target_general_count
        or (
            cached_fief_count > 0
            and cached_fief_count < target_fief_count
        )
    )
    combat_due = starter_five_stage_combat_due(sess)
    development_yields_to_combat = False

    if not onboarding_complete:
        stage = "five_stage_1"
        action_type = "five-stage-onboarding"
        reason = "进区角色已确认，先完成今日签到"
    elif not starter_initial_combat_complete(sess, job_id):
        stage = "five_stage_2"
        action_type = "five-stage-initial-combat"
        reason = "严格依次完成1/2/3级山贼和第一章第1/2关"
    elif combat_due:
        stage = "five_stage_4"
        action_type = "five-stage-growth"
        reason = "已有编队回闲或副本需要推进，优先完成战斗动作"
    elif reward_due:
        stage = "five_stage_5"
        action_type = "claim-rewards"
        reason = "距离上次活动/任务奖励巡检已满5分钟"
    elif development_due:
        last_cycle_action = starter_last_successful_action_type(
            job_id,
            ("five-stage-development", "five-stage-growth"),
        )
        development_yields_to_combat = (
            last_cycle_action == "five-stage-development"
        )
        if development_yields_to_combat:
            stage = "five_stage_4"
            action_type = "five-stage-growth"
            reason = "阶段3已执行一项发展动作，本轮让给配兵与出征"
        else:
            stage = "five_stage_3"
            action_type = "five-stage-development"
            reason = "核对当前等级对应的封地、建筑、征兵队列和将领数"
    else:
        stage = "five_stage_4"
        action_type = "five-stage-growth"
        reason = "执行基地建设、轻骑兵配兵、副本2和3级山贼循环"
    return {
        "policyVersion": STARTER_LEVELING_POLICY["version"],
        "stage": stage,
        "stageLabel": STARTER_STAGE_LABELS[stage],
        "actionType": action_type,
        "actionKey": f"ordered:{stage}:{action_type}",
        "reason": reason,
        "level": level,
        "generalCount": general_count,
        "targetGeneralCount": target_general_count,
        "cachedFiefCount": cached_fief_count,
        "targetFiefCount": target_fief_count,
        "rewardDue": reward_due,
        "developmentDue": development_due,
        "combatDue": combat_due,
        "developmentYieldedToCombat": development_yields_to_combat,
        "updatedAt": now,
    }


def sync_starter_planned_actions(job_id: str, sess: dict[str, Any]) -> list[dict[str, Any]]:
    """Persist the next primary action without letting maintenance erase it."""
    plan = starter_five_stage_plan(job_id, sess)
    desired_type = str(plan["actionType"])
    desired_key = str(plan["actionKey"])
    at = now_ms()
    # Reward checks are five-minute maintenance.  They may run before the next
    # combat tick, but must not cancel a deferred combat/development action and
    # force that action to restart from scratch.
    if desired_type != "claim-rewards":
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            connection.execute(
                """
                UPDATE starter_action_queue
                SET status='cancelled',finished_at=?,updated_at=?,
                    result_json='{"message":"五阶段顺序状态机取消旧计划动作"}'
                WHERE job_id=? AND status='queued'
                  AND action_type<>'claim-rewards'
                  AND (action_type<>? OR action_key<>?)
                """,
                (at, at, str(job_id), desired_type, desired_key),
            )
            connection.commit()
    action = enqueue_starter_action(
        job_id,
        desired_key,
        desired_type,
        {"plan": plan, "policyVersion": plan["policyVersion"]},
        priority=1100 if desired_type == "claim-rewards" else 1000,
    )
    return [action]


def claim_next_starter_action(job_id: str, supported_types: set[str]) -> dict[str, Any] | None:
    if not supported_types:
        return None
    placeholders = ",".join("?" for _ in supported_types)
    at = now_ms()
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            f"""
            SELECT * FROM starter_action_queue
            WHERE job_id=? AND status='queued' AND not_before<=?
              AND action_type IN ({placeholders})
            ORDER BY priority DESC,id ASC LIMIT 1
            """,
            (str(job_id), at, *sorted(supported_types)),
        ).fetchone()
        if not row:
            connection.commit()
            return None
        action_id = int(row["id"])
        connection.execute(
            """
            UPDATE starter_action_queue
            SET status='running',attempts=attempts+1,started_at=?,updated_at=?
            WHERE id=? AND status='queued'
            """,
            (at, at, action_id),
        )
        connection.commit()
        row = connection.execute(
            "SELECT * FROM starter_action_queue WHERE id=?", (action_id,),
        ).fetchone()
    item = dict(row)
    item["payload"] = json.loads(str(item.pop("payload_json") or "{}"))
    try:
        item["result"] = json.loads(str(item.pop("result_json") or "{}"))
    except json.JSONDecodeError:
        item["result"] = {}
    return item


def finish_starter_action(
    action_id: int,
    *,
    status: str,
    result: dict[str, Any],
    retry_after_sec: int = 0,
) -> None:
    at = now_ms()
    encoded = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
    if status == "queued":
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            connection.execute(
                """
                UPDATE starter_action_queue SET status='queued',result_json=?,
                    not_before=?,updated_at=?,started_at=NULL WHERE id=?
                """,
                (encoded, at + max(1, int(retry_after_sec)) * 1000, at, int(action_id)),
            )
            connection.commit()
        return
    if status not in {"success", "failed", "cancelled"}:
        raise RuntimeError(f"不支持的起号动作结束状态：{status}")
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute(
            """
            UPDATE starter_action_queue SET status=?,result_json=?,updated_at=?,
                finished_at=? WHERE id=?
            """,
            (status, encoded, at, at, int(action_id)),
        )
        connection.commit()


def starter_last_successful_dungeon_stage(job_id: str) -> tuple[int, int] | None:
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT result_json FROM starter_action_queue
            WHERE job_id=? AND action_type='dungeon-next' AND status='success'
            ORDER BY id DESC LIMIT 30
            """,
            (str(job_id),),
        ).fetchall()
    stages = []
    for row in rows:
        try:
            result = json.loads(str(row["result_json"] or "{}"))
            stage = result.get("stage") or {}
            if result.get("success"):
                stages.append((int(stage.get("chapter") or 0), int(stage.get("stage") or 0)))
        except Exception:
            continue
    return max(stages) if stages else None


def starter_next_dungeon_stage(
    sess: dict[str, Any],
    *,
    after_stage: tuple[int, int] | None = None,
) -> dict[str, Any] | None:
    catalog = query_dungeon_catalog(sess)
    if after_stage:
        chapter_id, display_stage = after_stage
        later = []
        for chapter in catalog.get("chapters") or []:
            cid = int(chapter.get("chapterId", -1))
            for row in chapter.get("stages") or []:
                stage_no = int(row.get("displayStage") or 0)
                if bool(row.get("available")) and (cid, stage_no) > (chapter_id, display_stage):
                    later.append((cid, stage_no, row))
        if later:
            next_chapter, next_display_stage, next_row = min(later, key=lambda item: (item[0], item[1]))
            return {
                "chapter": next_chapter,
                "chapterName": f"第{next_chapter + 1}章",
                "stage": next_display_stage,
                "stageCode": int(next_row.get("stageCode") or 0),
                "catalog": catalog,
            }
        return None
    for chapter in catalog.get("chapters") or []:
        if not chapter.get("detailFlag"):
            continue
        for stage in chapter.get("stages") or []:
            if bool(stage.get("available")) and int(stage.get("resultCode", 255)) == 255:
                return {
                    "chapter": int(chapter.get("chapterId") or 0),
                    "chapterName": f"第{int(chapter.get('chapterId') or 0) + 1}章",
                    "stage": int(stage.get("displayStage") or 1),
                    "stageCode": int(stage.get("stageCode") or 0),
                    "catalog": catalog,
                }
    return None


def starter_dungeon_defeat_confirmed(chest_result: dict[str, Any]) -> bool:
    """Only explicit server battle-result wording may terminate dungeons."""
    return dungeon_battle_defeat_confirmed({"chestResult": chest_result or {}})


def starter_heal_resource_deferred(
    exc: Exception,
    *,
    action_name: str,
) -> dict[str, Any] | None:
    """Turn a known resource shortage into a quiet durable wait.

    Resource production and reward claiming continue in their own workers.
    Retrying treatment every minute only repeats an impossible 100k-food
    exchange and can starve those useful requests.
    """
    message = str(exc)
    resource_shortage = (
        "铜钱不足" in message
        or "粮食转铜失败" in message
        or "当前粮食只有" in message
        or "资源转换失败状态 -3" in message
    )
    if not resource_shortage:
        return None
    return {
        "success": False,
        "deferred": True,
        "resourceBlocked": True,
        "retryAfterSec": 600,
        "message": (
            f"{action_name}等待治疗资源恢复；建筑、征兵和奖励领取继续运行。"
            f"详情：{message}"
        ),
    }


def execute_starter_dungeon_action(
    sess: dict[str, Any],
    action: dict[str, Any],
) -> dict[str, Any]:
    refresh_generals(sess)
    starter_refill_low_energy_generals(sess)
    # Bandit/lossless formations may have returned with wounded frontline
    # troops. Heal before planning so the dungeon route sees the real reusable
    # 150 heavy infantry rather than incorrectly falling back to development.
    try:
        heal_all_wounded_before_military_prepare(sess, "起号副本", force=True)
    except RuntimeError as exc:
        deferred = starter_heal_resource_deferred(exc, action_name="起号副本")
        if deferred:
            # Do not deadlock forever at 9/10 daily bandit wins: when there
            # are still enough *healthy idle* troops for a safe 0500 team,
            # dispatch one recovery team. Its activity-point reward can
            # provide the food/copper needed to heal every remaining wound.
            last_recovery = int(
                sess.get("starterResourceRecoveryBanditAt") or 0
            )
            recovery_plan = starter_military_plan(sess)
            if (
                int(recovery_plan.get("level") or 0) >= 30
                and (recovery_plan.get("bandit") or {}).get("teams")
                and now_ms() - last_recovery >= 10 * 60 * 1000
            ):
                recovered = execute_starter_bandit_action(
                    sess,
                    action,
                    skip_heal=True,
                    max_teams=1,
                )
                if recovered.get("success"):
                    sess["starterResourceRecoveryBanditAt"] = now_ms()
                    persist_runtime_state()
                    return {
                        **recovered,
                        "resourceRecovery": True,
                        "message": (
                            "治疗资源不足，已用健康闲兵派出1队刷黄以解锁"
                            "活跃奖励；战报返回后优先治疗全部伤兵"
                        ),
                        "healDeferred": deferred,
                    }
                # A scan miss is not a reason to go back to the ten-minute
                # treatment wait. Preserve the map cursor and retry the
                # healthy recovery team on its normal short scan cadence.
                return {
                    **recovered,
                    "deferred": True,
                    "resourceRecoveryAttempt": True,
                    "resourceBlocked": True,
                    "healDeferred": deferred,
                    "retryAfterSec": max(
                        5, min(30, int(recovered.get("retryAfterSec") or 5)),
                    ),
                }
            return deferred
        raise
    refresh_generals(sess)
    plan = starter_military_plan(sess)
    dungeon = plan.get("dungeon") or {}
    if not dungeon.get("ready"):
        return {
            "success": False,
            "deferred": True,
            "message": "副本三将或兵种尚未准备齐全",
            "plan": plan,
        }
    if dungeon.get("mode") == "early":
        role = (dungeon.get("roles") or [{}])[0]
        general_id = str((role.get("general") or {}).get("id") or "")
        unassigned = unassign_all_idle_generals(sess)
        assigned = execute_assign_troops(
            sess,
            general_id,
            role.get("soldierType") or "轻骑兵",
            int(role.get("desiredCount") or 0),
            confirm="assign-troops",
        )
        if not assigned.get("success"):
            return {
                "success": False,
                "deferred": True,
                "retryAfterSec": 30,
                "message": f"前期副本配兵失败：{assigned.get('message') or '无提示'}",
                "assignment": assigned,
            }
        next_stage = starter_next_dungeon_stage(sess)
        if not next_stage or int(next_stage.get("stage") or 0) > 3:
            sess["starterEarlyDungeonCompletedStages"] = 3
            persist_runtime_state()
            return {
                "success": True,
                "completed": True,
                "message": "前期副本第1、2、3关已经完成",
            }
        battle = execute_dungeon(sess, {
            "confirm": "dungeon",
            "starterMode": True,
            "generalIds": [general_id],
            "chapter": next_stage["chapterName"],
            "stage": next_stage["stage"],
            "chest": "右",
            "openChest": True,
            "maxWaitSec": 600,
            "minBattleSec": 5,
            "requiredIdleUpdates": 2,
        })
        # Early stages do not always expose the same chest slot. Do not replay
        # an already-finished battle merely because one 0x893e request returned
        # ff; try the other slots and then confirm stage progress from catalog.
        if (
            battle.get("success")
            and not (battle.get("chestResult") or {}).get("success")
        ):
            chest_attempts = [battle.get("chestResult") or {}]
            for chest_index in (0, 1):
                fallback = open_dungeon_chest(sess, chest_index)
                chest_attempts.append(fallback)
                if fallback.get("success"):
                    battle["chest"] = chest_index
                    battle["chestName"] = {
                        0: "左", 1: "中", 2: "右",
                    }[chest_index]
                    battle["chestResult"] = fallback
                    break
                time.sleep(0.2)
            battle["chestAttempts"] = chest_attempts
        stage_confirmed = False
        if battle.get("success"):
            refreshed_catalog = query_dungeon_catalog(sess)
            current_row = next((
                row
                for chapter in refreshed_catalog.get("chapters") or []
                if int(chapter.get("chapterId") or 0)
                    == int(next_stage.get("chapter") or 0)
                for row in chapter.get("stages") or []
                if int(row.get("displayStage") or 0)
                    == int(next_stage.get("stage") or 0)
            ), None)
            stage_confirmed = bool(
                current_row
                and int(current_row.get("resultCode", 255)) != 255
            )
            battle["postBattleStage"] = current_row
        success = bool(battle.get("success")) and bool(
            (battle.get("chestResult") or {}).get("success")
            or stage_confirmed
        )
        if success:
            sess["starterEarlyDungeonCompletedStages"] = max(
                int(sess.get("starterEarlyDungeonCompletedStages") or 0),
                int(next_stage.get("stage") or 0),
            )
            persist_runtime_state()
        return {
            "success": success,
            "deferred": not success,
            "retryAfterSec": 60 if not success else 0,
            "message": (
                f"前期副本第{next_stage['stage']}关完成并开箱"
                if success else
                f"前期副本第{next_stage['stage']}关未确认胜利"
            ),
            "stage": {k: v for k, v in next_stage.items() if k != "catalog"},
            "unassigned": unassigned,
            "assignment": assigned,
            "battle": battle,
        }
    next_stage = starter_next_dungeon_stage(
        sess,
        after_stage=starter_last_successful_dungeon_stage(str(action.get("job_id") or "")),
    )
    if not next_stage:
        sess["starterDungeonNoAvailableStage"] = True
        sess["starterDungeonNoAvailableAtLevel"] = int(
            (sess.get("roleState") or {}).get("level")
            or (sess.get("role") or {}).get("level")
            or 0
        )
        persist_runtime_state()
        return {
            "success": True,
            "completed": True,
            "message": "当前已没有已解锁的下一副本关卡，转入刷黄并等待后续解锁",
        }
    # Rebuild the team atomically from idle soldiers. Releasing all idle
    # generals first prevents one planned role from holding another role's
    # target troop type.
    unassigned = unassign_all_idle_generals(sess)
    assignments = []
    general_ids = []
    for role in dungeon.get("roles") or []:
        general_id = str((role.get("general") or {}).get("id") or "")
        desired = int(role.get("desiredCount") or 0)
        if not general_id or desired <= 0:
            continue
        assigned = execute_assign_troops(
            sess,
            general_id,
            role.get("soldierType"),
            desired,
            confirm="assign-troops",
        )
        assignments.append(assigned)
        if not assigned.get("success"):
            return {
                "success": False,
                "deferred": True,
                "message": f"副本自动配兵失败：{assigned.get('message') or '无提示'}",
                "unassigned": unassigned,
                "assignments": assignments,
            }
        general_ids.append(general_id)
    required_general_count = (
        2 if dungeon.get("mode") == "unlock-heavy" else 3
    )
    if len(general_ids) != required_general_count:
        return {
            "success": False,
            "deferred": True,
            "message": (
                f"副本只准备好{len(general_ids)}名将领，"
                f"需要{required_general_count}名"
            ),
            "assignments": assignments,
        }
    battle = execute_dungeon(sess, {
        "confirm": "dungeon",
        "starterMode": True,
        "generalIds": general_ids,
        "chapter": next_stage["chapterName"],
        "stage": next_stage["stage"],
        "chest": "左",
        "openChest": True,
        "maxWaitSec": 600,
        "minBattleSec": 8,
        "requiredIdleUpdates": 2,
    })
    chest = battle.get("chestResult") or {}
    defeat_confirmed = starter_dungeon_defeat_confirmed(chest)
    success = (
        bool(battle.get("success"))
        and bool(chest.get("success"))
        and not defeat_confirmed
    )
    if success:
        sess["starterDungeonNoAvailableStage"] = False
        sess["starterDungeonNoAvailableAtLevel"] = 0
        persist_runtime_state()
    return {
        # A confirmed defeat is a successfully observed terminal strategy
        # outcome, not a transport/protocol failure.
        "success": success or defeat_confirmed,
        "defeatConfirmed": defeat_confirmed,
        "message": (
            f"{next_stage['chapterName']}第{next_stage['stage']}关完成并开箱"
            if success else
            f"{next_stage['chapterName']}第{next_stage['stage']}关已确认战败，后续停止副本"
            if defeat_confirmed else
            f"{next_stage['chapterName']}第{next_stage['stage']}关未确认胜利"
        ),
        "stage": {k: v for k, v in next_stage.items() if k != "catalog"},
        "unassigned": unassigned,
        "assignments": assignments,
        "battle": battle,
    }


def starter_is_exact_all_crossbow_bandit(target: dict[str, Any]) -> bool:
    units = list(target.get("units") or [])
    composition = target.get("composition") or {}
    return (
        int(composition.get("foot") or 0) == 0
        and int(composition.get("bow") or 0) > 0
        and int(composition.get("bow") or 0) <= 5
        and int(composition.get("cavalry") or 0) == 0
        and int(composition.get("chariot") or 0) == 0
        and len(units) == int(composition.get("bow") or 0)
        and all(int(row.get("soldierTypeCode", -1)) == SOLDIER_TYPE_CODES["弩兵"] for row in units)
    )


def execute_starter_early_bandit_action(
    sess: dict[str, Any],
    action: dict[str, Any],
    plan: dict[str, Any],
) -> dict[str, Any]:
    team = ((plan.get("bandit") or {}).get("teams") or [{}])[0]
    role = (team.get("roles") or [{}])[0]
    target_level = int(team.get("targetLevel") or 0)
    general_id = str((role.get("general") or {}).get("id") or "")
    if target_level not in {1, 2, 3} or not general_id:
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 20,
            "message": "30级前刷黄队暂未准备完成",
        }
    unassigned = unassign_all_idle_generals(sess)
    assigned = execute_assign_troops(
        sess,
        general_id,
        "轻骑兵",
        int(role.get("desiredCount") or 0),
        confirm="assign-troops",
    )
    if not assigned.get("success"):
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 30,
            "message": f"前期轻骑兵配兵失败：{assigned.get('message') or '无提示'}",
            "unassigned": unassigned,
            "assignment": assigned,
        }
    center = recommend_brush_center(sess, [general_id])
    cursor_root = dict(sess.get("starterDirectBanditCursors") or {})
    scan_key = str(target_level)
    scan_state = {"cursor": int(cursor_root.get(scan_key) or 0)}
    report = search_targets(
        sess,
        {
            "startX": int(center.get("x") or 0),
            "startY": int(center.get("y") or 0),
            "scanLimit": 120,
            "batchSize": 6,
            "minimumTargetCount": 1,
            "targetKind": "山贼",
            "levels": [target_level],
            "refreshSharedMap": False,
            "directSearch": True,
        },
        scan_state=scan_state,
        allow_under30=True,
    )
    cursor_root[scan_key] = int(report.get("nextCursor") or 0)
    sess["starterDirectBanditCursors"] = cursor_root
    persist_runtime_state()
    targets = list(report.get("targets") or [])
    if not targets:
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 5,
            "message": f"30级前暂未找到{target_level}级山贼，继续直接搜索",
            "requestCount": report.get("requestCount"),
            "nextCursor": report.get("nextCursor"),
        }
    dispatch = execute_brush(
        sess,
        {
            "confirm": "brush-yellow",
            "target": targets[0],
            "generalIds": [general_id],
        },
        allow_under30=True,
    )
    if not dispatch.get("success"):
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 5,
            "message": (
                f"{target_level}级山贼出征未成功："
                f"{dispatch.get('failureReason') or dispatch.get('battleText') or '目标可能已失效'}"
            ),
            "dispatch": dispatch,
        }
    completed = {
        int(value)
        for value in sess.get("starterEarlyBanditCompletedLevels") or []
    }
    completed.add(target_level)
    sess["starterEarlyBanditCompletedLevels"] = sorted(completed)
    persist_runtime_state()
    return {
        "success": True,
        "message": f"30级前已派出轻骑兵挑战{target_level}级山贼",
        "targetLevel": target_level,
        "directSearch": True,
        "target": targets[0],
        "assignment": assigned,
        "dispatch": dispatch,
    }


def execute_starter_bandit_action(
    sess: dict[str, Any],
    action: dict[str, Any],
    *,
    skip_heal: bool = False,
    max_teams: int | None = None,
) -> dict[str, Any]:
    refresh_generals(sess)
    starter_refill_low_energy_generals(sess)
    # Do not issue treatment/unassign/assign requests on every five-second map
    # scan retry. Heal once only when the refreshed state actually reports
    # wounded troops; troop preparation is delayed until a usable target exists.
    if starter_wounded_total(sess) > 0 and not skip_heal:
        try:
            heal_all_wounded_before_military_prepare(
                sess, "起号刷黄", force=True,
            )
        except RuntimeError as exc:
            deferred = starter_heal_resource_deferred(
                exc, action_name="起号刷黄",
            )
            if deferred:
                return deferred
            raise
        refresh_generals(sess)
    plan = starter_military_plan(sess)
    if bool((plan.get("bandit") or {}).get("directUnder30")):
        return execute_starter_early_bandit_action(sess, action, plan)
    teams = list((plan.get("bandit") or {}).get("teams") or [])
    if max_teams is not None:
        teams = teams[:max(0, int(max_teams))]
    if not teams:
        return {
            "success": False,
            "deferred": True,
            "message": "当前兵力或空闲将领不足以组成刷黄队",
            "plan": plan,
        }
    general_ids = [
        str((role.get("general") or {}).get("id") or "")
        for team in teams
        for role in (team["front"], team["rear"])
    ]
    center = recommend_brush_center(sess, general_ids)
    target_level = int(teams[0].get("targetLevel") or 6)
    persisted_scan = dict(sess.get("starterBanditScanState") or {})
    scan_state: dict[str, Any] = (
        dict(persisted_scan.get("state") or {})
        if int(persisted_scan.get("targetLevel") or 0) == target_level
        else {}
    )
    exact_targets: list[dict[str, Any]] = []
    scan_reports = []
    # One action performs at most one coordinator-sized scan batch. If no exact
    # target is found the durable action is deferred and retried later; never
    # monopolize an account with a minutes-long synchronous full-map scan.
    for _ in range(1):
        report = search_targets(
            sess,
            {
                "startX": int(center.get("x") or 0),
                "startY": int(center.get("y") or 0),
                "scanLimit": 160,
                # Preserve the cursor between durable retries and scan several
                # coordinates per pass. The old 2-coordinate/reset-every-time
                # behavior repeatedly searched the same area and could leave
                # the account idle for tens of minutes.
                "batchSize": 6,
                "minimumTargetCount": 1,
                "targetKind": "山贼",
                "levels": [target_level],
                "compositionFilter": {
                    "maxFoot": 0,
                    "maxBow": 5,
                    "maxCavalry": 0,
                    "maxChariot": 0,
                },
                "refreshSharedMap": True,
                "scanOwner": f"starter-bandit:{action.get('job_id')}:{action.get('id')}",
            },
            scan_state=scan_state,
        )
        scan_reports.append({
            "requestCount": report.get("requestCount"),
            "matchedCount": report.get("matchedCount"),
            "cursor": report.get("cursor"),
        })
        sess["starterBanditScanState"] = {
            "targetLevel": target_level,
            "state": scan_state,
            "updatedAt": now_ms(),
        }
        persist_runtime_state()
        exact_targets = [
            row for row in report.get("targets") or []
            if starter_is_exact_all_crossbow_bandit(row)
        ]
        if len(exact_targets) >= len(teams):
            break
    if not exact_targets:
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 5,
            "message": f"暂未找到{target_level}级0500全弩兵山贼",
            "scanReports": scan_reports,
            "assignments": [],
        }
    # Only now spend write requests on formation preparation. This avoids
    # repeatedly unloading/reloading the same generals while the scanner is
    # still looking for the rare exact all-crossbow composition.
    unassigned = unassign_all_idle_generals(sess)
    assignments = []
    for team in teams:
        for role_name in ("front", "rear"):
            role = team[role_name]
            general_id = str((role.get("general") or {}).get("id") or "")
            assigned = execute_assign_troops(
                sess,
                general_id,
                role.get("soldierType"),
                int(role.get("desiredCount") or 0),
                confirm="assign-troops",
            )
            assignments.append(assigned)
            if not assigned.get("success"):
                return {
                    "success": False,
                    "deferred": True,
                    "message": f"刷黄自动配兵失败：{assigned.get('message') or '无提示'}",
                    "unassigned": unassigned,
                    "assignments": assignments,
                }
    dispatches = []
    attempted_targets = []
    target_index = 0
    dispatch_owner = f"starter-bandit:{action.get('job_id')}:{action.get('id')}"
    # A stale shared-map target must not consume a team. Keep that team idle and
    # let it try the next candidate until it is dispatched or candidates run out.
    for team in teams:
        ids = [
            str((team["front"].get("general") or {}).get("id") or ""),
            str((team["rear"].get("general") or {}).get("id") or ""),
        ]
        while target_index < len(exact_targets):
            target = exact_targets[target_index]
            target_index += 1
            if not reserve_shared_map_target(
                sess,
                "bandit",
                target,
                owner=dispatch_owner,
                task_id=str(action.get("id") or ""),
            ):
                continue
            attempted_targets.append(target)
            try:
                dispatch = execute_brush(
                    sess,
                    {
                        "confirm": "brush-yellow",
                        "target": target,
                        "generalIds": ids,
                    },
                )
            except Exception:
                update_shared_map_target_status(
                    sess, "bandit", target,
                    owner=dispatch_owner, status="available", reason="起号出征异常，释放目标",
                )
                raise
            dispatches.append(dispatch)
            update_shared_map_target_status(
                sess,
                "bandit",
                target,
                owner=dispatch_owner,
                status="dispatched" if dispatch.get("success") else "rejected",
                reason=dispatch.get("failureReason") or dispatch.get("battleText") or "",
            )
            if dispatch.get("success"):
                time.sleep(0.5)
                break
            # “目标不存在”等失败通常表示共享地图候选已过期；当前队伍继续
            # 使用后续候选，而不是中止本轮并浪费已经完成的治疗和配兵。
    successful_dispatches = sum(1 for row in dispatches if row.get("success"))
    complete = len(dispatches) == len(teams) and successful_dispatches == len(teams)
    success = successful_dispatches > 0
    return {
        "success": success,
        "partial": success and not complete,
        "complete": complete,
        "message": (
            f"已派出{len(dispatches)}支队伍挑战{target_level}级0500全弩兵山贼"
            if complete else
            f"刷黄本轮成功派出{successful_dispatches}/{len(teams)}队，其余队等待下轮目标"
        ),
        "targetLevel": target_level,
        "formationCode": "0500",
        "targets": attempted_targets,
        "unassigned": unassigned,
        "assignments": assignments,
        "dispatches": dispatches,
        "scanReports": scan_reports,
    }


def execute_starter_development_action(
    sess: dict[str, Any],
    action: dict[str, Any],
) -> dict[str, Any]:
    """Execute one bounded development step without blocking military work.

    Soldier recruitment/acceleration/abandon-fief are added as their captured
    protocols become verified. Until then this consumer safely advances the
    already verified building protocol and never touches either kind of hall.
    """
    # Recruitment has first refusal on every idle military building. In
    # particular, once the infantry camp reaches level 7 it must start heavy
    # infantry before the planner is allowed to occupy it with level 8.
    pre_plan = starter_refresh_fief_buildings(sess)
    role_level = int(
        (sess.get("roleState") or {}).get("level")
        or (sess.get("role") or {}).get("level")
        or 0
    )
    bootstrap_state = dict(sess.get("starterBaseVehicleBootstrap") or {})
    if 0 < role_level < 30 and not bootstrap_state.get("completed"):
        bootstrap = starter_base_vehicle_bootstrap_step(sess, pre_plan)
        if bootstrap.get("needsBuilding"):
            building = starter_execute_next_building_action(
                sess, confirm="starter-building-next",
            )
            return {
                "success": bool(building.get("success")),
                "message": (
                    building.get("message")
                    or "已执行基地战车营启动步骤"
                ),
                "earlyBootstrap": bootstrap,
                "building": building,
            }
        if not bootstrap.get("skipped") or bootstrap.get("deferred"):
            return {
                **bootstrap,
                "earlyBootstrap": True,
            }
        if bootstrap.get("completed"):
            return {
                **bootstrap,
                "earlyBootstrap": True,
            }
    base = next((
        row for row in pre_plan.get("fiefs") or [] if row.get("isBase")
    ), None)
    infantry = next((
        row for row in (base or {}).get("buildings") or []
        if int(row.get("type", -1)) == 4
    ), None)
    owned_heavy = int(starter_inventory_soldiers(sess).get("重步兵", 0))
    if (
        infantry
        and int(infantry.get("level") or 0) >= 7
        and bool(infantry.get("busy"))
        and not starter_building_has_recruit_queue(infantry)
        and owned_heavy < 600
    ):
        cancelled = execute_cancel_building_action(
            sess,
            int((base or {}).get("fiefId") or 0),
            int(infantry.get("slot") or 0),
            4,
        )
        return {
            "success": bool(cancelled.get("success")),
            "message": cancelled.get("message"),
            "cancelledInfantryUpgrade": cancelled,
            "recruitmentPriority": True,
        }
    pre_recruitment = starter_recruitment_step(sess, pre_plan)
    if not pre_recruitment.get("skipped"):
        result = {
            "success": bool(pre_recruitment.get("success")),
            "message": (
                pre_recruitment.get("message")
                or "已优先执行持续招兵计划"
            ),
            "recruitment": pre_recruitment,
            "recruitmentPriority": True,
        }
        if int(pre_recruitment.get("status") or 0) == 4:
            result.update({
                "deferred": True,
                "retryAfterSec": 15,
                "message": "征兵报价确认窗口已过，15秒后重新获取报价",
            })
        elif int(pre_recruitment.get("status") or 0) == 1:
            # Resource starvation is a waiting state, not a failed action.
            # Recreating a failed row every 30 seconds flooded the durable
            # queue while an account with only a few units of grain could not
            # possibly make progress. Rewards are polled independently.
            food = int((sess.get("roleState") or {}).get("food") or 0)
            food_per_hour = int(
                (sess.get("roleState") or {}).get("foodPerHour") or 0
            )
            retry_sec = 300
            if food_per_hour > 0 and food < 10_000:
                retry_sec = max(
                    300,
                    min(3600, ((10_000 - food) * 3600 + food_per_hour - 1)
                        // food_per_hour),
                )
            result.update({
                "deferred": True,
                "resourceBlocked": True,
                "retryAfterSec": retry_sec,
                "message": (
                    f"征兵资源不足，当前粮食{food}；"
                    f"{retry_sec}秒后复查，期间继续领取奖励"
                ),
            })
        return result
    building = starter_execute_next_building_action(
        sess, confirm="starter-building-next",
    )
    if building.get("skipped"):
        plan = building.get("plan") or {}
        if (
            int(plan.get("fiefCount") or 0) == 1
            and not bool(plan.get("hasTemporaryFief"))
        ):
            transfer = starter_verify_pending_transfers(sess)
            if not transfer.get("confirmed"):
                return {
                    "success": False,
                    "deferred": True,
                    "retryAfterSec": int(transfer.get("retryAfterSec") or 30),
                    "message": transfer.get("message"),
                    "building": building,
                    "transferVerification": transfer,
                }
            opened = starter_open_next_temporary_fief(sess)
            if opened.get("success") and not opened.get("skipped"):
                return {
                    "success": True,
                    "message": opened.get("message"),
                    "building": building,
                    "openFief": opened,
                }
            return {
                "success": False,
                "deferred": True,
                "retryAfterSec": int(opened.get("retryAfterSec") or 60),
                "message": opened.get("message") or "临时封地暂未开辟成功",
                "building": building,
                "openFief": opened,
            }
        # 临时封地填满一级战车营后，征弩车闭环优先于基地建筑加速。
        # 否则鲁公道具较多时会形成“升级→加速→再升级”的连续链，
        # 让已经具备条件的临时封地长时间不征兵，违背“招兵不要停”。
        recruitment = starter_recruitment_step(sess, plan)
        if not recruitment.get("skipped"):
            return {
                "success": bool(recruitment.get("success")),
                "message": recruitment.get("message") or "已执行一步持续招兵计划",
                "building": building,
                "recruitment": recruitment,
            }
        building_speed = starter_building_speed_step(sess, plan)
        if not building_speed.get("skipped"):
            return {
                "success": bool(building_speed.get("success")),
                "message": building_speed.get("message") or "已执行建筑加速",
                "building": building,
                "buildingSpeed": building_speed,
                "recruitment": recruitment,
            }
        return {
            "success": False,
            "deferred": True,
            "recruiting": bool(recruitment.get("recruiting")),
            "retryAfterSec": max(
                30,
                min(300, int(recruitment.get("retryAfterSec") or 60)),
            ),
            "message": (
                recruitment.get("message")
                if recruitment.get("recruiting")
                else "当前建筑队列没有可执行步骤，继续等待招兵/建筑状态变化"
            ),
            "building": building,
            "buildingSpeed": building_speed,
            "recruitment": recruitment,
        }
    return {
        "success": bool(building.get("success")),
        "message": str(building.get("message") or "已执行一步起号发展计划"),
        "building": building,
    }


def execute_starter_lossless_action(
    sess: dict[str, Any],
    action: dict[str, Any],
) -> dict[str, Any]:
    """Run one non-blocking step of the normal 10-level lossless workflow."""
    status = query_lossless_status(sess)
    if status.get("parseError"):
        raise RuntimeError(f"读取无损状态失败：{status.get('parseError')}")
    phase = lossless_status_phase(status)
    if phase == "settlement":
        settlement = settle_lossless_result(sess)
        if not settlement.get("success"):
            raise RuntimeError(
                f"无损结算失败：{settlement.get('message') or settlement.get('parseError') or '无提示'}"
            )
        return {
            "success": True,
            "message": settlement.get("message") or "无损战斗已结算",
            "phase": phase,
            "status": status,
            "settlement": settlement,
        }
    if phase == "daily_done":
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": min(3600, seconds_until_next_local_day()),
            "message": "今日无损次数已用完，跨日后自动恢复",
            "phase": phase,
            "status": status,
        }
    if phase == "cooldown":
        cooldown = max(5, int(status.get("cooldownSec") or 20))
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": min(600, cooldown),
            "message": f"10级无损冷却中，约{cooldown}秒后复查",
            "phase": phase,
            "status": status,
        }
    if phase == "fighting":
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 20,
            "message": "10级无损战斗进行中，等待结算",
            "phase": phase,
            "status": status,
        }
    if phase != "ready":
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 60,
            "message": (
                f"无损当前状态暂不可出征：mode={status.get('mode')}，"
                f"progress={status.get('progressCode')}"
            ),
            "phase": phase,
            "status": status,
        }

    refresh_generals(sess)
    starter_refill_low_energy_generals(sess)
    heal_all_wounded_before_military_prepare(sess, "起号无损", force=True)
    refresh_generals(sess)
    plan = starter_military_plan(sess)
    teams = list((plan.get("bandit") or {}).get("teams") or [])
    if len(teams) < 2:
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 30,
            "message": "10级无损需要2队共4名空闲将领，当前编队不足",
            "plan": plan,
        }
    # 无损按用户确认的固定策略：两支刷黄队一起进入，共4名将领。
    # 之前错误地在两队间轮换、每次只派2将，战力明显不足。
    lossless_teams = teams[:2]

    unassigned = unassign_all_idle_generals(sess)
    assignments = []
    general_ids = []
    selected_roles: list[dict[str, Any]] = []
    for selected_team in lossless_teams:
        for role_name in ("front", "rear"):
            role = selected_team[role_name]
            general_id = str((role.get("general") or {}).get("id") or "")
            assigned = execute_assign_troops(
                sess,
                general_id,
                role.get("soldierType"),
                int(role.get("desiredCount") or 0),
                confirm="assign-troops",
            )
            assignments.append(assigned)
            if not assigned.get("success"):
                return {
                    "success": False,
                    "deferred": True,
                    "retryAfterSec": 60,
                    "message": f"无损自动配兵失败：{assigned.get('message') or '无提示'}",
                    "unassigned": unassigned,
                    "assignments": assignments,
                }
            general_ids.append(general_id)
            selected_roles.append(role)

    pseudo_task = {
        "taskId": f"starter-lossless-{action.get('id')}",
        "type": "starter-lossless",
        "sessionId": str(sess.get("sessionId") or ""),
        "status": "running",
        "logs": [],
        "stopEvent": threading.Event(),
    }
    # 起号编队由策略引擎在上面动态卸兵、配兵，不能再经过普通辅助的
    # prepare_military_generals()。后者以用户保存的配兵规则为真值，
    # 会让无人值守起号错误地要求用户先去“军事-配兵”页面保存规则。
    selected: list[dict[str, Any]] = []
    for team_role, general_id in zip(
        selected_roles,
        general_ids,
    ):
        general = refresh_general_with_a110_status(sess, general_id)
        if not general:
            raise RuntimeError(f"起号无损配兵后未找到将领：{general_id}")
        block = dispatch_block_reason(general, {})
        if block:
            raise RuntimeError(
                f"起号无损配兵后检查未通过："
                f"{general.get('name') or general_id}；{block}"
            )
        expected_code = soldier_type_code(team_role.get("soldierType"))
        expected_count = int(team_role.get("desiredCount") or 0)
        current_code, current_count = _general_current_troops(general)
        if current_code != expected_code or current_count != expected_count:
            raise RuntimeError(
                f"起号无损配兵后校验未通过：{general.get('name') or general_id}；"
                f"期望{expected_count}{team_role.get('soldierType')}，"
                f"实际{current_count}{soldier_type_name(current_code)}"
            )
        selected.append(general)
    catalog = query_lossless_catalog(sess)
    if catalog.get("parseError"):
        raise RuntimeError(f"读取无损目录失败：{catalog.get('parseError')}")
    lineup = prepare_lossless_target_lineup(
        pseudo_task,
        sess,
        {"level": 10, "generalIds": general_ids, "maxLineupRerolls": 80},
        status,
    )
    stage = lossless_stage_context(status, catalog, lineup)
    dispatched = dispatch_lossless(sess, selected, task=pseudo_task)
    if not dispatched.get("success"):
        raise RuntimeError(
            f"无损出征未确认成功："
            f"{dispatched.get('failureReason') or dispatched.get('battleText') or '无提示'}"
        )
    persist_runtime_state()
    record_success_action(
        str(sess.get("sessionId") or ""),
        "无损",
        f"起号2队4将 > {stage.get('levelName')}-{stage.get('stageName')}战",
        detail={"stage": stage, "battleId": dispatched.get("battleId")},
    )
    return {
        "success": True,
        "message": (
            "起号无损2队共4将已出征："
            f"{stage.get('levelName')}-{stage.get('stageName')}"
        ),
        "configuredTeamCount": 2,
        "configuredGeneralCount": 4,
        "generalIds": general_ids,
        "stage": stage,
        "lineup": {
            key: value for key, value in lineup.items()
            if key not in {"packets", "rawHex"}
        },
        "dispatch": dispatched,
        "unassigned": unassigned,
        "assignments": assignments,
        "logs": list(pseudo_task.get("logs") or [])[-30:],
    }


def run_next_starter_action(
    job_id: str,
    *,
    supported_types: set[str] | None = None,
) -> dict[str, Any]:
    job = get_starter_job(job_id)
    sid = str(job.get("account_id") or "")
    sess = get_session(sid)
    action = claim_next_starter_action(
        job_id,
        supported_types or {
            "five-stage-onboarding", "five-stage-initial-combat",
            "five-stage-development", "five-stage-growth",
            "dungeon-next", "bandit-cycle", "recruit-and-build",
            "lossless-when-ready", "claim-rewards",
        },
    )
    if not action:
        return {"success": True, "idle": True, "message": "当前没有可执行的起号动作"}
    try:
        if action.get("action_type") == "five-stage-onboarding":
            result = execute_starter_five_stage_onboarding(sess, action)
        elif action.get("action_type") == "five-stage-initial-combat":
            result = execute_starter_five_stage_initial_combat(sess, action)
        elif action.get("action_type") == "five-stage-development":
            result = execute_starter_five_stage_development(sess, action)
        elif action.get("action_type") == "five-stage-growth":
            result = execute_starter_five_stage_growth(sess, action)
        elif action.get("action_type") == "dungeon-next":
            result = execute_starter_dungeon_action(sess, action)
        elif action.get("action_type") == "bandit-cycle":
            result = execute_starter_bandit_action(sess, action)
        elif action.get("action_type") == "recruit-and-build":
            result = execute_starter_development_action(sess, action)
        elif action.get("action_type") == "lossless-when-ready":
            result = execute_starter_lossless_action(sess, action)
        elif action.get("action_type") == "claim-rewards":
            result = execute_starter_reward_action(sess, action)
        else:
            raise RuntimeError(f"尚未实现的起号动作：{action.get('action_type')}")
        if result.get("deferred"):
            retry_floor = (
                1
                if action.get("action_type") in {
                    "five-stage-initial-combat", "five-stage-growth",
                }
                else 5
            )
            finish_starter_action(
                int(action["id"]), status="queued", result=result,
                retry_after_sec=max(
                    retry_floor,
                    int(result.get("retryAfterSec") or 30),
                ),
            )
        else:
            finish_starter_action(
                int(action["id"]),
                status="success" if result.get("success") else "failed",
                result=result,
            )
            if (
                action.get("action_type") == "dungeon-next"
                and result.get("defeatConfirmed")
            ):
                sess["starterDungeonDefeatConfirmed"] = True
                sess["starterDungeonStoppedAfterDefeat"] = True
                persist_runtime_state()
        return {"success": bool(result.get("success")), "action": action, "result": result}
    except Exception as exc:
        result = {"success": False, "errorType": type(exc).__name__, "message": str(exc)}
        # Most runtime failures (idle troops temporarily held by a returning
        # formation, stale map target, short-lived server rejection) are
        # transient. Keep the same durable action with backoff instead of
        # creating one failed row plus a replacement every scheduler tick.
        finish_starter_action(
            int(action["id"]), status="queued", result=result, retry_after_sec=60,
        )
        return {
            "success": False,
            "deferred": True,
            "action": action,
            "result": result,
        }


def starter_container_count() -> int:
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute("""
            CREATE TABLE IF NOT EXISTS starter_ui_state (
                state_key TEXT PRIMARY KEY,
                state_value TEXT NOT NULL,
                updated_at INTEGER NOT NULL
            )
        """)
        row = connection.execute(
            "SELECT state_value FROM starter_ui_state WHERE state_key='container_count'"
        ).fetchone()
    try:
        return max(1, int(row["state_value"] if row else 1))
    except (TypeError, ValueError):
        return 1


def save_starter_container_count(value: Any) -> int:
    count = max(1, min(100, int(value or 1)))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute("""
            CREATE TABLE IF NOT EXISTS starter_ui_state (
                state_key TEXT PRIMARY KEY,
                state_value TEXT NOT NULL,
                updated_at INTEGER NOT NULL
            )
        """)
        connection.execute("""
            INSERT INTO starter_ui_state(state_key,state_value,updated_at)
            VALUES('container_count',?,?)
            ON CONFLICT(state_key) DO UPDATE SET
                state_value=excluded.state_value,
                updated_at=excluded.updated_at
        """, (str(count), now_ms()))
    return count


def delete_starter_job(job_id: str) -> None:
    job = get_starter_job(job_id)
    if str(job.get("status") or "") == "running":
        control_starter_job(job_id, "stop")
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute("DELETE FROM starter_jobs WHERE job_id=?", (str(job_id),))


def starter_activity_rows(
    session: dict[str, Any],
    reward_sources: dict[str, Any],
    active_job: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    responses = (reward_sources.get("activities") or {}).get("responses") or []
    catalog = list(responses[0].get("entries") or []) if responses else []
    details = list((session.get("starterActivityDetails") or {}).get("details") or [])
    details_by_id = {int(item.get("id") or 0): item for item in details}
    claimed_by_id: dict[int, dict[str, Any]] = {}
    for step in (active_job or {}).get("steps") or []:
        result = step.get("result") if isinstance(step.get("result"), dict) else {}
        for claim in result.get("claims") or []:
            if not claim.get("success"):
                continue
            try:
                item_id = int(str(claim.get("idHex") or "0"), 16)
            except ValueError:
                continue
            claimed_by_id[item_id] = {
                "id": item_id,
                "idHex": f"{item_id:016x}",
                "title": claim.get("title") or f"活动{item_id:x}",
            }
    rows: list[dict[str, Any]] = []
    role_level = int((session.get("roleState") or {}).get("level") or (session.get("role") or {}).get("level") or 0)
    for entry in catalog:
        item_id = int(entry.get("id") or 0)
        detail = details_by_id.get(item_id) or {}
        fields = [
            str(field)
            for response in detail.get("responses") or []
            for field in response.get("textFields") or []
        ]
        text = "\n".join(fields)
        status = "无法领取"
        status_key = "unavailable"
        progress_matches = re.findall(r"(\d+)\s*/\s*(\d+)", text)
        progress_ready = bool(progress_matches) and all(int(cur) >= int(total) for cur, total in progress_matches)
        level_match = re.search(r"等级需至少\s*(\d+)\s*级", text)
        level_ready = not level_match or role_level >= int(level_match.group(1))
        explicit_ready = any(marker in text for marker in (
            "现在可以领取", "可以领取礼品", "完成本次签到，可以领取",
        ))
        if level_ready and (explicit_ready or progress_ready):
            status = "未领取"
            status_key = "unclaimed"
        rows.append({
            **entry,
            "claimStatus": status,
            "claimStatusKey": status_key,
            "detailText": fields[0] if fields else "",
        })
    existing_ids = {int(row.get("id") or 0) for row in rows}
    for item_id, entry in claimed_by_id.items():
        if item_id in existing_ids:
            for row in rows:
                if int(row.get("id") or 0) == item_id:
                    row.update({"claimStatus": "已领取", "claimStatusKey": "claimed"})
            continue
        rows.insert(0, {
            **entry,
            "claimStatus": "已领取",
            "claimStatusKey": "claimed",
            "detailText": "",
        })
    return rows


def starter_account_view(account_id: str) -> dict[str, Any]:
    account_id = str(account_id or "")
    with ACCOUNT_LOCK:
        acc = dict(ACCOUNTS.get(account_id) or {})
    if not acc:
        raise RuntimeError("起号账号不存在")
    sess = SESSIONS.get(account_id)
    session = dict(sess) if isinstance(sess, dict) else {
        "sessionId": account_id,
        "username": acc.get("username"),
        "platform": acc.get("platform"),
        "role": acc.get("role") or {},
        "roleState": acc.get("roleState") or {},
        "area": acc.get("area") or {},
        "generals": [],
        "army": [],
        "inventory": {"items": []},
    }
    summary = public_account_summary(acc)
    role = session.get("role") if isinstance(session.get("role"), dict) else {}
    role_state = (
        session.get("roleState")
        if isinstance(session.get("roleState"), dict)
        else {}
    )
    overview = current_task_overview(session)
    starter_sources = (
        session.get("starterRewardSources")
        if isinstance(session.get("starterRewardSources"), dict)
        else {}
    )
    reward_sources = (
        starter_sources.get("sources")
        if isinstance(starter_sources.get("sources"), dict)
        else {}
    )
    inventory = (
        session.get("inventory")
        if isinstance(session.get("inventory"), dict)
        else {"items": []}
    )
    jobs = list_starter_jobs(account_id)
    active_job = get_starter_job(str(jobs[0]["job_id"])) if jobs else None
    activity_rows = starter_activity_rows(session, reward_sources, active_job)
    priority_activities = []
    starter_level = int(role_state.get("level") or role.get("level") or 0)
    for configured in STARTER_PRIORITY_ACTIVITIES:
        matched = next((
            row for row in activity_rows
            if all(
                token in str(row.get("title") or row.get("name") or row.get("text") or "")
                for token in configured["match"]
            )
        ), None)
        priority_activities.append({
            **configured,
            "found": matched is not None,
            "activity": matched,
            "claimStatus": (matched or {}).get("claimStatus") or "未读取",
        })
    priority_by_key = {row["key"]: row for row in priority_activities}
    first_claimed = (
        priority_by_key.get("new_server_gifts", {}).get("claimStatus") == "已领取"
    )
    for row in priority_activities:
        prerequisite = row.get("prerequisite")
        if starter_level < int(row.get("requiredLevel") or 40):
            row["gateStatus"] = "等待40级"
            row["claimAllowedByStarter"] = False
        elif prerequisite and not first_claimed:
            row["gateStatus"] = "等待领取“贺新服，好礼抱回家”"
            row["claimAllowedByStarter"] = False
        else:
            row["gateStatus"] = "可按活动实际状态检查领取"
            row["claimAllowedByStarter"] = True
    task_responses = (reward_sources.get("growthTasks") or {}).get("responses") or []
    all_task_entries = list(task_responses[0].get("entries") or []) if task_responses else []
    task_groups = {
        "growth": [
            entry for entry in all_task_entries
            if 0x2700 <= int(entry.get("id") or 0) <= 0x28FF
        ],
        "country": [
            entry for entry in all_task_entries
            if 0x7900 <= int(entry.get("id") or 0) <= 0x79FF
        ],
        "special": [
            entry for entry in all_task_entries
            if not (
                0x2700 <= int(entry.get("id") or 0) <= 0x28FF
                or 0x7900 <= int(entry.get("id") or 0) <= 0x79FF
            )
        ],
    }
    daily_task_rows = list((session.get("dailyActivity") or {}).get("tasks") or [])
    bandit_victories = max([
        int(row.get("current") or 0)
        for row in daily_task_rows
        if "山贼" in str(row.get("text") or "")
    ] or [0])
    # 0x1130 only returns the visible task catalogue, not a separate textual
    # claim status.  For the starter's first “挑战山贼” task its completion is
    # deterministic: one recorded bandit victory satisfies the 0x1132 target.
    for entry in task_groups["growth"]:
        task_id = int(entry.get("id") or 0)
        bandit_task_claimable = (
            (task_id == 0x2721 and bandit_victories >= 1)
            or (task_id == 0x2740 and bandit_victories >= 2)
        )
        if bandit_task_claimable:
            entry["claimStatus"] = "可领取奖励"
            entry["claimStatusKey"] = "claimable"
        else:
            entry["claimStatus"] = "进行中"
            entry["claimStatusKey"] = "progress"
    account_key = account_storage_key(sess=session, acc=acc)
    account_records = database_read_account_logs(account_key, 300)
    starter_step_records = [{
        "time": int(step.get("finished_at") or step.get("started_at") or 0),
        "timeText": local_time_text(
            int(step.get("finished_at") or step.get("started_at") or 0)
        ),
        "source": "starter",
        "message": (
            f"起号/{STARTER_STAGE_LABELS.get(str(step.get('stage') or ''), step.get('stage'))}"
            f"/{step.get('step')}：{step.get('message') or step.get('status')}"
        ),
    } for step in ((active_job or {}).get("steps") or [])]
    starter_action_records = []
    for item in (active_job or {}).get("actions") or []:
        payload = item.get("payload") or {}
        result = item.get("result") or {}
        plan = payload.get("plan") or {}
        stage = str(plan.get("stage") or "")
        stage_label = STARTER_STAGE_LABELS.get(stage, stage or "动作")
        status = str(item.get("status") or "")
        action_time = int(
            item.get("finished_at")
            or item.get("started_at")
            or item.get("updated_at")
            or item.get("created_at")
            or 0
        )
        starter_action_records.append({
            "time": action_time,
            "timeText": local_time_text(action_time),
            "source": "starter-action",
            "message": (
                f"起号/{stage_label}/{item.get('action_type')}："
                f"{result.get('message') or status}"
            ),
            "status": status,
            "actionId": item.get("id"),
        })
    recruitment_states = []
    for state in (session.get("starterRecruitmentStates") or {}).values():
        item = dict(state or {})
        ready_at = int(item.get("readyAt") or 0)
        item["remainingSec"] = max(0, (ready_at - now_ms() + 999) // 1000)
        item["statusText"] = (
            "等待完成" if item["remainingSec"] > 0 else "已到完成复查时间"
        )
        recruitment_states.append(item)
    return {
        "account": {
            "sessionId": account_id,
            "username": summary.get("username"),
            "platform": platform_display_name(acc.get("platform")),
            "areaName": summary.get("areaName"),
            "status": summary.get("status"),
            "statusText": summary.get("statusText"),
            "roleName": summary.get("roleName"),
            "level": summary.get("level"),
            "countryShort": dashboard_country_short_name(role),
            "lastError": summary.get("lastError") or "",
        },
        "job": active_job,
        "basic": {
            "roleName": summary.get("roleName"),
            "level": summary.get("level"),
            "country": dashboard_country_short_name(role),
            "copper": role_state.get("copper"),
            "food": role_state.get("food"),
            "populationCurrent": role_state.get("populationCurrent"),
            "populationCap": role_state.get("populationCap"),
            "prestige": role_state.get("prestige"),
            "resourcePointCurrent": role_state.get("resourcePointCurrent"),
            "resourcePointCap": role_state.get("resourcePointCap"),
        },
        "taskRewards": {
            "taskStack": list(overview.get("taskStack") or []),
            "resident": list(overview.get("resident") or []),
            "growthTasks": list(
                task_groups["growth"]
            ),
            "groups": task_groups,
            "growthDetails": list(
                (session.get("starterGrowthTaskDetails") or {}).get("details") or []
            ),
            "dailyTasks": list(
                daily_task_rows
            ),
        },
        "activityRewards": {
            "daily": list(overview.get("daily") or []),
            "notices": list(overview.get("notices") or []),
            "activities": list(
                activity_rows
            ),
            "details": list(
                (session.get("starterActivityDetails") or {}).get("details") or []
            ),
            "priorityActivities": priority_activities,
            "priorityActivityGroup": {
                **STARTER_NEW_SERVER_DAY_ONE_ACTIVITY_GROUP,
                "currentLevel": starter_level,
                "firstActivityClaimed": first_claimed,
                "foundCount": sum(1 for row in priority_activities if row.get("found")),
                "registrationStartedAt": int((active_job or {}).get("created_at") or 0),
                "claimDueAt": (
                    int((active_job or {}).get("created_at") or 0)
                    + int(STARTER_NEW_SERVER_DAY_ONE_ACTIVITY_GROUP["claimDelayAfterRegistrationSec"]) * 1000
                    if int((active_job or {}).get("created_at") or 0) > 0
                    else 0
                ),
            },
        },
        "recruit": dict(session.get("starterRecruit") or {}),
        "development": {
            "recruitmentStates": recruitment_states,
            "pendingTransferChecks": list(
                (session.get("starterPendingTransferChecks") or {}).values()
            ),
            "currentBuildingAction": (
                (session.get("starterFiefBuildings") or {}).get("nextAction")
            ),
        },
        "buildingPolicy": starter_building_policy_snapshot(session),
        "treasury": {
            "items": list(inventory.get("items") or []),
            "parseError": inventory.get("parseError"),
        },
        "roleDetail": {
            "role": role,
            "state": role_state,
            "area": session.get("area") or {},
        },
        "military": {
            "generals": list(session.get("generals") or []),
            "army": list(session.get("army") or role_state.get("idleArmy") or []),
            "starterPlan": (
                starter_five_stage_plan(
                    str((active_job or {}).get("job_id") or ""),
                    session,
                )
                if active_job else
                {"policyVersion": STARTER_LEVELING_POLICY["version"]}
            ),
        },
        "records": sorted(
            [
                *account_records,
                *starter_step_records,
                *starter_action_records,
            ],
            key=lambda item: int(item.get("time") or 0),
            reverse=True,
        )[:5000],
        "updatedAt": now_ms(),
    }


def get_starter_job(job_id: str) -> dict[str, Any]:
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        row = connection.execute(
            "SELECT * FROM starter_jobs WHERE job_id=?",
            (str(job_id),),
        ).fetchone()
        steps = connection.execute(
            """
            SELECT id, stage, step, attempt, status, message, result_json,
                   started_at, finished_at
            FROM starter_step_runs WHERE job_id=? ORDER BY id DESC LIMIT 50
            """,
            (str(job_id),),
        ).fetchall()
    job = starter_job_row(row)
    if not job:
        raise RuntimeError("起号任务不存在")
    job["steps"] = []
    for row_step in steps:
        item = dict(row_step)
        try:
            item["result"] = json.loads(str(item.pop("result_json") or "{}"))
        except json.JSONDecodeError:
            item["result"] = {}
        job["steps"].append(item)
    job["actions"] = list_starter_actions(str(job_id), limit=5000)
    return job


def create_starter_job(account_id: str, target_level: int = 66) -> dict[str, Any]:
    account_id = str(account_id or "")
    with ACCOUNT_LOCK:
        account = ACCOUNTS.get(account_id)
        if not account:
            raise RuntimeError("请先添加起号账号")
        platform = platform_display_name(account.get("platform"))
        target_server = str(
            account.get("serverQuery")
            or (account.get("area") or {}).get("areaName")
            or default_server_query(platform)
        )
    target_level = max(1, min(200, int(target_level or 66)))
    job_id = "starter_" + uuid4().hex
    at = now_ms()
    with STARTER_LOCK, ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        active = connection.execute(
            """
            SELECT job_id FROM starter_jobs
            WHERE account_id=? AND status IN ('queued','running','paused','waiting')
            ORDER BY updated_at DESC LIMIT 1
            """,
            (account_id,),
        ).fetchone()
        if active:
            return get_starter_job(str(active["job_id"]))
        connection.execute(
            """
            INSERT INTO starter_jobs(
                job_id, account_id, platform, target_server, target_level,
                status, current_stage, current_step, progress, control_state,
                snapshot_json, created_at, updated_at
            ) VALUES(?,?,?,?,?,'queued','account_login','等待启动',0,'running','{}',?,?)
            """,
            (
                job_id, account_id, platform, target_server, target_level,
                at, at,
            ),
        )
        connection.commit()
    start_starter_worker(job_id)
    return get_starter_job(job_id)


def starter_step(
    job_id: str,
    stage: str,
    step: str,
    action: Callable[[], dict[str, Any] | None],
) -> dict[str, Any]:
    started = now_ms()
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        attempt_row = connection.execute(
            "SELECT COUNT(*) AS count FROM starter_step_runs WHERE job_id=? AND stage=? AND step=?",
            (job_id, stage, step),
        ).fetchone()
        attempt = int(attempt_row["count"] or 0) + 1
        cursor = connection.execute(
            """
            INSERT INTO starter_step_runs(
                job_id, stage, step, attempt, status, started_at
            ) VALUES(?,?,?,?, 'running', ?)
            """,
            (job_id, stage, step, attempt, started),
        )
        run_id = int(cursor.lastrowid)
        connection.execute(
            """
            UPDATE starter_jobs SET status='running', current_stage=?,
                current_step=?, started_at=COALESCE(started_at,?), updated_at=?
            WHERE job_id=?
            """,
            (stage, step, started, started, job_id),
        )
        connection.commit()
    try:
        result = action() or {}
        message = str(result.get("message") or "完成")
        status = "success"
    except Exception as exc:
        result = {"errorType": type(exc).__name__}
        message = str(exc)
        status = "failed"
    finished = now_ms()
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute(
            """
            UPDATE starter_step_runs
            SET status=?, message=?, result_json=?, finished_at=? WHERE id=?
            """,
            (
                status, message,
                json.dumps(result, ensure_ascii=False, separators=(",", ":")),
                finished, run_id,
            ),
        )
        if status == "failed":
            connection.execute(
                """
                UPDATE starter_jobs SET status='paused', control_state='paused',
                    last_error=?, updated_at=? WHERE job_id=?
                """,
                (message, finished, job_id),
            )
        connection.commit()
    if status == "failed":
        raise RuntimeError(message)
    return result


def starter_snapshot(sess: dict[str, Any]) -> dict[str, Any]:
    role = sess.get("role") or {}
    state = sess.get("roleState") or {}
    level = int(
        state.get("level")
        or state.get("roleLevel")
        or role.get("level")
        or 0
    )
    return {
        "level": level,
        "roleName": str(role.get("roleName") or role.get("name") or ""),
        "roleId": str(role.get("roleId") or ""),
        "generalCount": len(sess.get("generals") or []),
        "idleArmy": state.get("idleArmy") or sess.get("army") or [],
        "copper": int(state.get("copper") or 0),
        "food": int(state.get("food") or 0),
        "mapScope": (
            "direct-search"
            if level < 30
            else f"shared:{platform_profile(sess.get('platform')).get('key')}:"
                 f"{shared_map_server_key(sess)}"
        ),
        "capturedAt": now_ms(),
    }


def persist_starter_snapshot(job_id: str, sess: dict[str, Any]) -> dict[str, Any]:
    """Persist the live level/resources used by the long-running starter policy."""
    snapshot = starter_snapshot(sess)
    at = now_ms()
    target_level = int(get_starter_job(job_id).get("target_level") or 66)
    level = int(snapshot.get("level") or 0)
    progress = min(99, max(45, int(level * 100 / max(1, target_level))))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        previous = connection.execute(
            """
            SELECT level,captured_at FROM starter_snapshots
            WHERE job_id=? ORDER BY id DESC LIMIT 1
            """,
            (str(job_id),),
        ).fetchone()
        # The current snapshot lives on starter_jobs. History is sampled only
        # on level changes or every five minutes and capped, avoiding a new SQL
        # row for every 10-second scheduler tick.
        if (
            previous is None
            or int(previous["level"] or 0) != level
            or at - int(previous["captured_at"] or 0) >= 300_000
        ):
            connection.execute(
                """
                INSERT INTO starter_snapshots(job_id, level, snapshot_json, captured_at)
                VALUES(?,?,?,?)
                """,
                (
                    str(job_id), level,
                    json.dumps(snapshot, ensure_ascii=False, separators=(",", ":")), at,
                ),
            )
            connection.execute(
                """
                DELETE FROM starter_snapshots
                WHERE job_id=? AND id NOT IN (
                    SELECT id FROM starter_snapshots
                    WHERE job_id=? ORDER BY id DESC LIMIT 200
                )
                """,
                (str(job_id), str(job_id)),
            )
        connection.execute(
            """
            UPDATE starter_jobs SET snapshot_json=?,progress=?,updated_at=?
            WHERE job_id=?
            """,
            (
                json.dumps(snapshot, ensure_ascii=False, separators=(",", ":")),
                progress, at, str(job_id),
            ),
        )
        connection.commit()
    return snapshot


def recover_interrupted_starter_actions(job_id: str) -> None:
    """A process restart must not leave a durable action permanently running."""
    at = now_ms()
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute(
            """
            UPDATE starter_action_queue
            SET status='queued',not_before=?,started_at=NULL,updated_at=?,
                result_json=CASE
                    WHEN result_json='{}' THEN '{"message":"服务重启后恢复执行"}'
                    ELSE result_json
                END
            WHERE job_id=? AND status='running'
            """,
            (at + 5000, at, str(job_id)),
        )
        connection.commit()


def starter_loop_wait(job_id: str, seconds: float) -> bool:
    """Interruptible wait; returns False as soon as the job is paused/stopped."""
    deadline = time.monotonic() + max(0.0, float(seconds))
    while time.monotonic() < deadline:
        job = get_starter_job(job_id)
        if str(job.get("control_state") or "") != "running":
            return False
        time.sleep(min(1.0, max(0.05, deadline - time.monotonic())))
    return True


def starter_scheduler_wait_seconds(outcome: dict[str, Any]) -> int:
    """Keep combat responsive while respecting genuine long backoffs."""
    if outcome.get("idle"):
        return 2
    action_type = str((outcome.get("action") or {}).get("action_type") or "")
    result = outcome.get("result") or {}
    if action_type in {
        "five-stage-initial-combat", "five-stage-growth",
    }:
        if (
            result.get("deploymentSuccess")
            or result.get("settledPendingBattle")
            or result.get("scanMiss")
        ):
            return 1
        if result.get("deferred"):
            retry_sec = max(1, int(result.get("retryAfterSec") or 2))
            return min(5, retry_sec)
        return 2
    if result.get("deferred"):
        return max(5, min(300, int(result.get("retryAfterSec") or 10)))
    return 10


def run_starter_development_loop(job_id: str, sid: str) -> None:
    """Keep construction/recruitment moving independently from combat.

    Lossless lineup rerolls and battle settlement can occupy the military
    worker for minutes. A separate bounded worker prevents those operations
    from starving the user's invariant that recruitment must never stop.
    Account-level HTTP gating still serializes individual game requests.
    """
    while True:
        job = get_starter_job(job_id)
        if str(job.get("control_state") or "") != "running":
            return
        try:
            sess = get_session(sid)
            sync_starter_planned_actions(job_id, sess)
            outcome = run_next_starter_action(
                job_id,
                supported_types={"recruit-and-build"},
            )
            result = outcome.get("result") or {}
            wait_sec = (
                max(5, min(60, int(result.get("retryAfterSec") or 10)))
                if result.get("deferred") or result.get("recruiting")
                else 10
            )
        except Exception as exc:
            system_log(
                f"起号发展线程 {job_id} 本轮失败：{type(exc).__name__}: {exc}",
                level="error",
                source="starter",
            )
            wait_sec = 30
        if not starter_loop_wait(job_id, wait_sec):
            return


def run_continuous_starter_loop(job_id: str, sid: str) -> None:
    """Run the five stages serially so no background lane can jump a gate."""
    recover_interrupted_starter_actions(job_id)
    consecutive_errors = 0
    while True:
        job = get_starter_job(job_id)
        if str(job.get("control_state") or "") != "running":
            return
        sess = get_session(sid)
        try:
            refresh_generals(sess)
            snapshot = persist_starter_snapshot(job_id, sess)
            level = int(snapshot.get("level") or 0)
            target_level = int(job.get("target_level") or 66)
            if level >= target_level:
                at = now_ms()
                with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                    connection.execute(
                        """
                        UPDATE starter_jobs SET status='completed',
                            control_state='completed',current_stage='completed',
                            current_step=?,progress=100,last_error='',
                            updated_at=?,finished_at=? WHERE job_id=?
                        """,
                        (f"角色已达到{target_level}级，起号完成", at, at, str(job_id)),
                    )
                    connection.commit()
                system_log(
                    f"起号任务 {job_id} 已完成：角色达到{level}级",
                    source="starter",
                )
                return

            queued = sync_starter_planned_actions(job_id, sess)
            ordered_plan = starter_five_stage_plan(job_id, sess)
            at = now_ms()
            with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                connection.execute(
                    """
                    UPDATE starter_jobs SET status='running',
                        current_stage=?,current_step=?,
                        last_error='',updated_at=? WHERE job_id=?
                    """,
                    (
                        str(ordered_plan.get("stage") or "five_stage_4"),
                        (
                            f"{level}/{target_level}级："
                            f"{ordered_plan.get('reason') or '执行五阶段计划'}"
                        ),
                        at, str(job_id),
                    ),
                )
                connection.commit()
            outcome = run_next_starter_action(
                job_id,
                supported_types={
                    "five-stage-onboarding", "five-stage-initial-combat",
                    "five-stage-development", "five-stage-growth",
                    "claim-rewards",
                },
            )
            consecutive_errors = 0
            result = outcome.get("result") or {}
            message = str(
                result.get("message") or outcome.get("message") or "等待下一轮策略"
            )
            with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                connection.execute(
                    """
                    UPDATE starter_jobs SET current_step=?,last_error='',
                        updated_at=? WHERE job_id=?
                    """,
                    (message, now_ms(), str(job_id)),
                )
                connection.commit()
            wait_sec = starter_scheduler_wait_seconds(outcome)
        except Exception as exc:
            consecutive_errors += 1
            wait_sec = min(120, 10 * (2 ** min(3, consecutive_errors - 1)))
            message = f"{type(exc).__name__}: {exc}"
            with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                connection.execute(
                    """
                    UPDATE starter_jobs SET status='running',last_error=?,
                        current_step=?,updated_at=? WHERE job_id=?
                    """,
                    (
                        message,
                        f"本轮失败，{wait_sec}秒后自动重试",
                        now_ms(), str(job_id),
                    ),
                )
                connection.commit()
            system_log(
                f"起号任务 {job_id} 本轮失败，稍后重试：{message}",
                level="error",
                source="starter",
            )
        if not starter_loop_wait(job_id, wait_sec):
            return


def run_starter_job(job_id: str) -> None:
    try:
        job = get_starter_job(job_id)
        if job.get("control_state") != "running":
            return

        # Jobs that completed the bootstrap before the continuous engine was
        # introduced resume directly from their durable snapshot/action queue.
        if int(job.get("progress") or 0) >= 45:
            sid = str(job.get("account_id") or "")
            with ACCOUNT_LOCK:
                online = bool((ACCOUNTS.get(sid) or {}).get("started") and sid in SESSIONS)
            if not online:
                started = start_account(sid, starter_mode=True)
                new_sid = str(started.get("sessionId") or sid)
                if new_sid != sid:
                    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                        connection.execute(
                            "UPDATE starter_jobs SET account_id=?,updated_at=? WHERE job_id=?",
                            (new_sid, now_ms(), str(job_id)),
                        )
                        connection.commit()
                    sid = new_sid
            run_continuous_starter_loop(job_id, sid)
            return

        def ensure_login() -> dict[str, Any]:
            current = get_starter_job(job_id)
            sid = str(current.get("account_id") or "")
            with ACCOUNT_LOCK:
                account = ACCOUNTS.get(sid) or {}
                online = bool(account.get("started") and sid in SESSIONS)
            if online:
                return {"message": "账号已经在线", "sessionId": sid}
            started = start_account(sid, starter_mode=True)
            new_sid = str(started.get("sessionId") or sid)
            if new_sid != sid:
                with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                    connection.execute(
                        "UPDATE starter_jobs SET account_id=?, updated_at=? WHERE job_id=?",
                        (new_sid, now_ms(), job_id),
                    )
                    connection.commit()
            return {"message": "账号真实登录成功", "sessionId": new_sid}

        login_result = starter_step(
            job_id, "account_login", "真实登录并进入目标区服", ensure_login,
        )
        sid = str(login_result.get("sessionId") or get_starter_job(job_id)["account_id"])

        def capture_role() -> dict[str, Any]:
            sess = get_session(sid)
            snapshot = starter_snapshot(sess)
            at = now_ms()
            with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
                connection.execute(
                    """
                    INSERT INTO starter_snapshots(job_id, level, snapshot_json, captured_at)
                    VALUES(?,?,?,?)
                    """,
                    (
                        job_id, int(snapshot.get("level") or 0),
                        json.dumps(snapshot, ensure_ascii=False, separators=(",", ":")),
                        at,
                    ),
                )
                connection.execute(
                    """
                    UPDATE starter_jobs SET snapshot_json=?, progress=15,
                        updated_at=? WHERE job_id=?
                    """,
                    (
                        json.dumps(snapshot, ensure_ascii=False, separators=(",", ":")),
                        at, job_id,
                    ),
                )
                connection.commit()
            return {
                "message": f"角色状态读取成功，当前等级{snapshot.get('level', 0)}",
                "level": snapshot.get("level", 0),
            }

        starter_step(job_id, "role_snapshot", "读取等级、资源、将领和军队", capture_role)

        def configure_map_scope() -> dict[str, Any]:
            snapshot = get_starter_job(job_id).get("snapshot") or {}
            level = int(snapshot.get("level") or 0)
            scope = "direct-search" if level < 30 else "server-shared"
            return {
                "message": (
                    "30级前只直接搜索山贼并出征，不建立地图、缓存或目标占用"
                    if scope == "direct-search"
                    else "30级后使用同平台同区服共享山贼地图"
                ),
                "mapScope": scope,
            }

        starter_step(
            job_id,
            "map_scope",
            "确认30级前直接搜索，30级后再接入共享地图",
            configure_map_scope,
        )

        def read_initial_rewards() -> dict[str, Any]:
            starter_sess = get_session(sid)
            result = query_starter_reward_sources(starter_sess)
            sources = result.get("sources") or {}
            failed = [
                f"{name}:{source.get('error') or '无目标响应'}"
                for name, source in sources.items()
                if not source.get("success")
            ]
            if failed:
                raise RuntimeError("奖励列表读取不完整：" + "；".join(failed))
            activity_responses = (sources.get("activities") or {}).get("responses") or []
            activity_entries = (
                activity_responses[0].get("entries") or []
                if activity_responses else []
            )
            activity_details = query_starter_activity_details(
                starter_sess,
                [entry.get("id") for entry in activity_entries],
            )
            growth_responses = (sources.get("growthTasks") or {}).get("responses") or []
            all_task_entries = (
                growth_responses[0].get("entries") or []
                if growth_responses else []
            )
            growth_details = query_starter_growth_task_details(
                starter_sess,
                [
                    entry.get("id") for entry in all_task_entries
                    if 0x2700 <= int(entry.get("id") or 0) <= 0x28FF
                ],
                group=0,
            )
            claims = []
            for reward_id in (0x0DF639, 0x0DE2B1):
                claim = claim_starter_known_reward(
                    starter_sess,
                    reward_id,
                    confirm="starter-claim-known-reward",
                )
                claims.append({
                    "idHex": claim.get("idHex"),
                    "title": claim.get("title"),
                    "success": claim.get("success"),
                    "alreadyClaimed": claim.get("alreadyClaimed"),
                    "message": claim.get("message"),
                })
                if not claim.get("success"):
                    raise RuntimeError(
                        f"{claim.get('title') or reward_id}领取未确认："
                        f"{claim.get('message') or '未知响应'}"
                    )
                time.sleep(0.5)
            growth_claims = claim_available_starter_growth_rewards(
                starter_sess, max_rounds=12,
            )
            return {
                "message": (
                    "奖励列表读取成功，登录奖励已处理，"
                    f"成长任务领取{growth_claims.get('claimedCount', 0)}项"
                ),
                "sources": list(sources),
                "claims": claims,
                "growthClaims": growth_claims,
                "activityDetailCount": len(activity_details.get("details") or []),
                "growthDetailCount": len(growth_details.get("details") or []),
            }

        starter_step(
            job_id, "initial_rewards", "读取任务与活动奖励列表",
            read_initial_rewards,
        )
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            connection.execute(
                """
                UPDATE starter_jobs SET status='running',control_state='running',
                    current_stage='five_stage_1',
                    current_step='角色已进入区服，开始阶段1签到',
                    progress=45,last_error='',updated_at=? WHERE job_id=?
                """,
                (now_ms(), job_id),
            )
            connection.commit()
        run_continuous_starter_loop(job_id, sid)
    except Exception as exc:
        system_log(
            f"起号任务 {job_id} 暂停：{exc}",
            level="error",
            source="starter",
        )
    finally:
        with STARTER_LOCK:
            STARTER_WORKERS.pop(job_id, None)


def start_starter_worker(job_id: str) -> None:
    with STARTER_LOCK:
        worker = STARTER_WORKERS.get(job_id)
        if worker and worker.is_alive():
            return
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            connection.execute(
                """
                UPDATE starter_jobs SET control_state='running',
                    status=CASE WHEN status='completed' THEN status ELSE 'queued' END,
                    last_error='', updated_at=? WHERE job_id=?
                """,
                (now_ms(), str(job_id)),
            )
            connection.commit()
        worker = threading.Thread(
            target=run_starter_job,
            args=(str(job_id),),
            name=f"starter-{str(job_id)[-8:]}",
            daemon=True,
        )
        STARTER_WORKERS[str(job_id)] = worker
        worker.start()


def control_starter_job(job_id: str, action: str) -> dict[str, Any]:
    action = str(action or "").lower()
    if action == "resume":
        start_starter_worker(job_id)
    elif action in {"pause", "stop"}:
        status = "stopped" if action == "stop" else "paused"
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            cursor = connection.execute(
                """
                UPDATE starter_jobs SET status=?, control_state=?,
                    current_step=?, updated_at=? WHERE job_id=?
                """,
                (
                    status, action,
                    "已由用户停止" if action == "stop" else "已由用户暂停",
                    now_ms(), str(job_id),
                ),
            )
            connection.commit()
        if not cursor.rowcount:
            raise RuntimeError("起号任务不存在")
    else:
        raise RuntimeError("不支持的起号任务操作")
    return get_starter_job(job_id)


def refresh_generals(sess: dict[str, Any]) -> list[dict[str, Any]]:
    """Refresh 0x8004 role state and update sess['generals']."""
    role = sess.get("role") or {}
    role_id = int(role.get("roleId") or 0)
    if role_id <= 0:
        raise RuntimeError("当前 session 缺少 roleId，无法刷新将领状态")
    code, data, packets = post_game(sess["gameHttp"], [(0x1016, struct.pack(">q", role_id))], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    p8004 = next((p for p in packets if p.get("opcode") == 0x8004), None)
    if not p8004:
        raise RuntimeError("刷新将领状态未返回 0x8004：" + json.dumps(summarize_packets(packets), ensure_ascii=False)[:500])
    state8004 = p8004["payload"].hex()
    generals = recover_generals_from_8004(state8004)
    role_state_updated_at = now_ms()
    for general in generals:
        role_status_code = general.get("status")
        general["roleStateStatusCode"] = role_status_code
        general["roleStateStatusText"] = general_status_text_from_code(role_status_code)
        general["roleStateStatusUpdatedAt"] = role_state_updated_at
    army_state = parse_idle_army_from_8004(state8004, generals)
    sess["state8004PayloadHex"] = state8004
    sess["roleState"] = parse_8004_head(p8004["payload"], "live/0x1016/0x8004")
    sess["roleState"]["idleArmy"] = army_state
    sess["army"] = army_state
    if generals:
        sess["generals"] = generals
    enrich_generals_with_fief_names(sess)
    if not any(str(general.get("fiefName") or "").strip() for general in sess.get("generals") or []):
        last_attempt = int(sess.get("ownedFiefLocationsAttemptedAt") or 0)
        if now_ms() - last_attempt >= 5 * 60 * 1000:
            sess["ownedFiefLocationsAttemptedAt"] = now_ms()
            try:
                refresh_owned_fief_locations(sess)
            except Exception as exc:
                sess["ownedFiefLocationError"] = str(exc)
    apply_military_status_to_generals(sess)
    persist_runtime_state()
    return sess.get("generals") or []


def refresh_inventory(sess: dict[str, Any]) -> dict[str, Any]:
    code, data, packets = post_game(sess["gameHttp"], [(0x1104, b"\x00")], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    p8104 = next((p for p in packets if p.get("opcode") == 0x8104), None)
    if not p8104:
        raise RuntimeError("刷新宝物未返回 0x8104：" + json.dumps(summarize_packets(packets), ensure_ascii=False)[:500])
    inventory_state = parse_8104_inventory(p8104["payload"], "live/0x1104/0x8104")
    inventory_state["http"] = code
    sess["inventory"] = inventory_state
    persist_runtime_state()
    return inventory_state


def parse_status_message_payload(payload: bytes) -> dict[str, Any]:
    """Parse the common byte-status + UTF message prefix used by action replies."""
    if not payload:
        return {"success": False, "status": None, "message": "响应为空"}
    status = struct.unpack(">b", payload[:1])[0]
    try:
        message, offset = read_utf(payload, 1)
    except Exception:
        message, offset = printable(payload, 300), 1
    return {
        "success": status == 0,
        "status": status,
        "message": message,
        "remainingHex": payload[offset:].hex()[:4096],
    }


# ---------------------------------------------------------------------------
# Daily country features (protocols recovered from the latest desktop capture)
# ---------------------------------------------------------------------------

DAILY_GENERAL_PAGE_SIZE = 4
DAILY_NATIONAL_PAGE_SIZE = 10
DAILY_NATIONAL_CATEGORIES = (1, 2, 3)  # 州、郡、县；4=小城 intentionally excluded
DAILY_NATIONAL_MAX_PAGES = 100
DAILY_NATIONAL_MAX_ATTEMPTS = 20


def _daily_read_utf(payload: bytes, offset: int) -> tuple[str, int]:
    if offset < 0 or offset + 2 > len(payload):
        raise ValueError(f"UTF长度字段越界 offset={offset} size={len(payload)}")
    length = struct.unpack_from(">H", payload, offset)[0]
    offset += 2
    if offset + length > len(payload):
        raise ValueError(
            f"UTF字段越界 length={length} offset={offset} size={len(payload)}"
        )
    return payload[offset:offset + length].decode("utf-8", errors="replace"), offset + length


def _daily_i16(payload: bytes, offset: int) -> tuple[int, int]:
    if offset + 2 > len(payload):
        raise ValueError(f"short字段越界 offset={offset}")
    return struct.unpack_from(">h", payload, offset)[0], offset + 2


def _daily_u16(payload: bytes, offset: int) -> tuple[int, int]:
    if offset + 2 > len(payload):
        raise ValueError(f"unsigned short字段越界 offset={offset}")
    return struct.unpack_from(">H", payload, offset)[0], offset + 2


def _daily_i32(payload: bytes, offset: int) -> tuple[int, int]:
    if offset + 4 > len(payload):
        raise ValueError(f"int字段越界 offset={offset}")
    return struct.unpack_from(">i", payload, offset)[0], offset + 4


def _daily_i64(payload: bytes, offset: int) -> tuple[int, int]:
    if offset + 8 > len(payload):
        raise ValueError(f"long字段越界 offset={offset}")
    return struct.unpack_from(">q", payload, offset)[0], offset + 8


def build_salary_payload() -> bytes:
    """0x314b claim request: one byte mode=1."""
    return b"\x01"


def build_national_city_list_payload(category: int, page: int) -> bytes:
    if int(category) not in DAILY_NATIONAL_CATEGORIES:
        raise ValueError("国家征收只允许查询州城、郡城、县城，禁止查询小城")
    if int(page) < 1 or int(page) > 0x7FFF:
        raise ValueError("国家城池列表页码无效")
    return struct.pack(">qBH", 1, int(category), int(page))


def build_national_city_status_payload(city_name: str) -> bytes:
    name = str(city_name or "").strip()
    if not name:
        raise ValueError("国家征收状态查询缺少城池名称")
    return b"\x01" + utf(name)


def build_national_collect_payload(city_name: str) -> bytes:
    return build_national_city_status_payload(city_name)


def build_owned_city_list_payload(role_id: int | str | None = None) -> bytes:
    """0x1318 查询自己作为城主拥有的城池。

    2026-07-25 抓包（passive_pcap_hotspot_20260725_010719 flow #131）：
      req payload = i64(roleId?) + u16(0)
      实测 roleId=2 时返回小城「南化」(104,20)。
    头像 → 城池信息 走的就是这个接口，不是 0x1310 封地列表。
    """
    rid = int(role_id or 0)
    if rid < 0:
        raise ValueError("自有城池查询 roleId 无效")
    return struct.pack(">qH", rid, 0)


def build_city_lord_collect_payload(city_name: str) -> bytes:
    name = str(city_name or "").strip()
    if not name:
        raise ValueError("城主征收缺少城池名称")
    # 2026-07-25 抓包 flow #133：01 + UTF(南化) + 00
    return b"\x01" + utf(name) + b"\x00"


def parse_owned_city_list(payload: bytes) -> dict[str, Any]:
    """Parse 0x8318 自有城池列表/详情。

    证据：
      - 操作口述：头像→城池信息只返回自己当城主的城（当时仅小城南化）
      - 抓包 flow #131 resp：可解析出 name=南化, x=104, y=20, owner=宿代苑
      - 客户端 k.M0 对 0x8318 的首段读取：
          status:u8, count:u8, 然后每条 city 记录以
          long + byte + UTF(name) + short x + short y 开头
    当前实现先稳定提取征收所需的 cityName/x/y/owner；其余字段保留 raw。
    """
    raw = payload or b""
    if len(raw) < 2:
        return {
            "success": False,
            "status": None,
            "count": 0,
            "cities": [],
            "message": f"0x8318响应过短：{len(raw)}",
            "rawHex": raw.hex()[:4096],
        }
    status = raw[0]
    count = raw[1]
    offset = 2
    cities: list[dict[str, Any]] = []
    message = ""

    # status==1：客户端提示“没有城池”
    if int(status) == 1:
        return {
            "success": True,
            "status": int(status),
            "count": 0,
            "cities": [],
            "noCity": True,
            "message": "没有城池",
            "rawHex": raw.hex()[:4096],
            "parsedBytes": offset,
        }

    def read_city_record(start: int, index: int) -> tuple[dict[str, Any] | None, int]:
        p = start
        if p + 9 > len(raw):
            return None, start
        city_id = struct.unpack_from(">q", raw, p)[0]
        p += 8
        kind_or_flag = raw[p]
        p += 1
        try:
            name, p2 = _daily_read_utf(raw, p)
        except Exception:
            return None, start
        p = p2
        if p + 4 > len(raw):
            return None, start
        x = struct.unpack_from(">H", raw, p)[0]
        y = struct.unpack_from(">H", raw, p + 2)[0]
        p += 4
        owner = ""
        owner_level = None
        # 尽量吸收 owner/level，失败也不影响 cityName
        try:
            if p + 2 <= len(raw):
                # 中间还有若干固定宽字段；用“下一个中文 UTF”扫描 owner。
                probe = p
                found_owner_at = None
                while probe + 2 <= len(raw) and probe < p + 64:
                    n = struct.unpack_from(">H", raw, probe)[0]
                    if 1 <= n <= 30 and probe + 2 + n <= len(raw):
                        chunk = raw[probe + 2:probe + 2 + n]
                        try:
                            text = chunk.decode("utf-8")
                        except Exception:
                            probe += 1
                            continue
                        if any("一" <= ch <= "鿿" for ch in text):
                            found_owner_at = probe
                            owner = text
                            after = probe + 2 + n
                            if after < len(raw):
                                owner_level = raw[after]
                            break
                    probe += 1
                if found_owner_at is not None:
                    # 不强制推进主游标到 owner 后，避免未识别字段错位；
                    # 主游标只保证消费到 x/y 后的最小记录，便于 count>1 时继续。
                    pass
        except Exception:
            pass
        # 主记录最小前进：long+byte+utf+x+y；若 count 指示多城，尝试按
        # 下一条 long+byte+utf 的起点启发式推进。
        next_p = p
        record = {
            "index": index,
            "cityId": int(city_id),
            "cityIdHex": f"{int(city_id) & 0xFFFFFFFFFFFFFFFF:016x}",
            "kindCode": int(kind_or_flag),
            "name": name,
            "cityName": name,
            "city": name,
            "x": int(x),
            "y": int(y),
            "ownerName": owner,
            "ownerLevel": owner_level,
        }
        return record, next_p

    if int(count) > 0:
        cursor = offset
        for index in range(1, int(count) + 1):
            city, cursor2 = read_city_record(cursor, index)
            if city is None:
                break
            cities.append(city)
            # 尝试定位下一条：从当前 utf/x/y 之后扫描下一个“long + byte + utf中文名”
            scan = cursor2
            next_start = None
            while scan + 11 <= len(raw) and index < int(count):
                n = struct.unpack_from(">H", raw, scan + 9)[0] if scan + 11 <= len(raw) else 0
                # long(8)+byte(1)+utfLen(2)
                if 1 <= n <= 30 and scan + 11 + n <= len(raw):
                    chunk = raw[scan + 11:scan + 11 + n]
                    try:
                        text = chunk.decode("utf-8")
                    except Exception:
                        scan += 1
                        continue
                    if any("一" <= ch <= "鿿" for ch in text):
                        next_start = scan
                        break
                scan += 1
            if next_start is None:
                cursor = cursor2
                break
            cursor = next_start
        offset = cursor
    else:
        # count==0 但 body 仍可能带单城详情（抓包 #131 即此形态）：
        # status,count 后直接 long+byte+UTF(name)+x+y...
        city, offset2 = read_city_record(offset, 1)
        if city is not None:
            cities.append(city)
            offset = offset2
            count = 1

    return {
        "success": True,
        "status": int(status),
        "count": len(cities),
        "declaredCount": int(count) if raw[1:2] else 0,
        "cities": cities,
        "message": message,
        "rawHex": raw.hex()[:4096],
        "parsedBytes": offset,
        "trailingHex": raw[offset:].hex()[:4096],
    }


def query_owned_cities(sess: dict[str, Any]) -> dict[str, Any]:
    """Query cities where the current role is city lord via 0x1318/0x8318."""
    role = sess.get("role") if isinstance(sess.get("role"), dict) else {}
    state = sess.get("roleState") if isinstance(sess.get("roleState"), dict) else {}
    role_id = (
        role.get("roleId")
        or role.get("id")
        or state.get("roleId")
        or state.get("id")
        or sess.get("roleId")
        or 0
    )
    payload = build_owned_city_list_payload(role_id)
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x1318, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0x8318), None)
    if response is None:
        raise GameProtocolResponseError(f"自有城池列表未收到0x8318：http={code}")
    parsed = parse_owned_city_list(response.get("payload") or b"")
    parsed.update({
        "http": int(code),
        "opcode": "0x1318/0x8318",
        "requestPayloadHex": payload.hex(),
        "roleId": int(role_id or 0),
        "updatedAt": now_ms(),
    })
    sess["lastOwnedCities"] = parsed
    persist_runtime_state()
    return parsed


def build_general_visit_list_payload(page: int, page_size: int = DAILY_GENERAL_PAGE_SIZE) -> bytes:
    if int(page) < 1 or int(page) > 0x7FFF:
        raise ValueError("名将列表页码无效")
    if int(page_size) < 1 or int(page_size) > 0x7FFF:
        raise ValueError("名将列表页大小无效")
    return struct.pack(">HH", int(page), int(page_size))


def build_general_visit_payload(general_id: int | str, page: int, page_size: int = DAILY_GENERAL_PAGE_SIZE) -> bytes:
    return struct.pack(">qHH", int(general_id), int(page), int(page_size))


def parse_daily_status_utf_receipt(payload: bytes, *, success_status: int = 1) -> dict[str, Any]:
    """Parse compact daily receipts such as 0x8330 city-lord collect.

    Layout observed for city-lord success:
      status:u8 + UTF(message) + trailing longs
    """
    if not payload:
        return {"success": False, "status": None, "message": "响应为空", "remainingHex": ""}
    status = struct.unpack_from(">b", payload, 0)[0]
    try:
        message, offset = _daily_read_utf(payload, 1)
    except Exception:
        message, offset = printable(payload, 500), 1
    return {
        "success": status == int(success_status),
        "status": status,
        "message": clean_activity_result_message(message),
        "remainingHex": payload[offset:].hex()[:4096],
    }


def parse_salary_receipt(payload: bytes) -> dict[str, Any]:
    """Parse 0xA14B 国家俸禄回执。

    2026-07-25 真实抓包 flow #021：
      01 00 + UTF("领取国家俸禄成功，获得铜钱642850，粮食1190689。") + longs...
    即 status:u8 + extra:u8 + UTF(message) + trailing values。
    旧实现少读了 extra 字节，会把文案解析成空，最终只剩“服务器确认成功”。
    """
    raw = payload or b""
    if not raw:
        return {
            "success": False,
            "completed": False,
            "status": None,
            "extra": None,
            "message": "响应为空",
            "copper": None,
            "food": None,
            "remainingHex": "",
        }
    status = struct.unpack_from(">b", raw, 0)[0]
    extra = raw[1] if len(raw) >= 2 else None
    message = ""
    offset = 1
    # 优先按 status + extra + UTF 解析；若 extra 位置其实已是 UTF 长度高字节，再回退。
    if len(raw) >= 2:
        try:
            message, offset = _daily_read_utf(raw, 2)
        except Exception:
            try:
                message, offset = _daily_read_utf(raw, 1)
                extra = None
            except Exception:
                message, offset = printable(raw[1:], 500), 1
                extra = None
    cleaned = clean_activity_result_message(message)
    copper = None
    food = None
    copper_match = re.search(r"铜钱\s*([0-9,，]+)", cleaned)
    food_match = re.search(r"粮食\s*([0-9,，]+)", cleaned)
    if copper_match:
        copper = int(re.sub(r"[,，]", "", copper_match.group(1)))
    if food_match:
        food = int(re.sub(r"[,，]", "", food_match.group(1)))

    already = any(
        marker in cleaned
        for marker in (
            "无法再次领取",
            "已经领取",
            "已领取",
            "今日已领取",
            "本日已领取",
            "今天已经领取",
        )
    )
    no_office = any(
        marker in cleaned
        for marker in (
            "无官职",
            "没有官职",
            "只有官员才能领取",
            "官员才能领取俸禄",
            "当前不能领取俸禄",
        )
    )
    success_by_text = (
        "成功" in cleaned
        or "获得铜钱" in cleaned
        or (copper is not None or food is not None)
    )
    # 兼容两套回执：status==1 直接成功；或 status==0 且 extra==1/文案成功。
    success = (
        int(status) == 1
        or (int(status) == 0 and (extra == 1 or success_by_text) and not no_office)
        or already
    )
    if already:
        # 统一成用户可读短句
        summary = "无法再次领取"
    elif no_office:
        summary = "无官职无法领取"
        success = False
    elif success and (copper is not None or food is not None):
        copper_text = f"{copper}铜钱" if copper is not None else ""
        food_text = f"{food}粮食" if food is not None else ""
        joined = "、".join(part for part in (copper_text, food_text) if part)
        summary = f"领取成功{joined}" if joined else (cleaned or "领取俸禄成功")
    elif success:
        summary = cleaned or "领取俸禄成功"
    else:
        summary = cleaned or "领取俸禄失败"

    return {
        "success": bool(success),
        "completed": bool(success or already),
        "alreadyClaimed": bool(already),
        "noOffice": bool(no_office),
        "status": int(status),
        "extra": None if extra is None else int(extra),
        "message": summary,
        "rawMessage": cleaned,
        "copper": copper,
        "food": food,
        "remainingHex": raw[offset:].hex()[:4096],
    }


def parse_national_collect_status(payload: bytes) -> dict[str, Any]:
    if len(payload) < 36:
        raise ValueError(f"0x8332响应过短：{len(payload)}")
    status, availability, used_count, limit = payload[:4]
    current_copper = struct.unpack_from(">q", payload, 4)[0]
    copper_cap = struct.unpack_from(">q", payload, 12)[0]
    current_food = struct.unpack_from(">q", payload, 20)[0]
    food_cap = struct.unpack_from(">q", payload, 28)[0]
    return {
        "status": int(status),
        "availability": int(availability),
        "usedCount": int(used_count),
        "limit": int(limit),
        "currentCopper": int(current_copper),
        "copperCap": int(copper_cap),
        "currentFood": int(current_food),
        "foodCap": int(food_cap),
        "quotaExhausted": int(used_count) >= int(limit),
        "canCollect": (
            int(status) == 0
            and int(availability) == 0
            and int(used_count) < int(limit)
            and int(current_copper) > 0
        ),
    }


def _national_kind_from_wire(value: int) -> str:
    return {
        0: "state",
        1: "commandery",
        2: "county",
        3: "small",
    }.get(int(value), "unknown")


def _national_kind_from_category(value: int) -> str:
    return {
        1: "state",
        2: "commandery",
        3: "county",
        4: "small",
    }.get(int(value), "unknown")


def parse_national_city_page(payload: bytes, requested_category: int = 0) -> dict[str, Any]:
    # The captured 0x8404 body starts with a seven-byte header:
    #   status(1), response category(1), total pages(u16), page(u16), count(1)
    # Older code treated this as eight bytes and shifted every field by one,
    # which made real city pages look empty (and could turn a page count into
    # an enormous value).  Keep the offsets explicit because this parser is
    # also used by the national-collection selector.
    if len(payload) < 7:
        raise ValueError(f"0x8404响应过短：{len(payload)}")
    status = payload[0]
    response_category = payload[1]
    total_pages = struct.unpack_from(">H", payload, 2)[0]
    page = struct.unpack_from(">H", payload, 4)[0]
    count = payload[6]
    category = (
        int(response_category)
        if response_category in range(1, 6)
        else int(requested_category)
    )
    offset = 7
    cities: list[dict[str, Any]] = []
    for index in range(int(count)):
        name, offset = _daily_read_utf(payload, offset)
        if offset >= len(payload):
            raise ValueError(f"国家城池记录{index + 1}缺少类型")
        wire_kind = payload[offset]
        offset += 1
        x, offset = _daily_i16(payload, offset)
        y, offset = _daily_i16(payload, offset)
        owner, offset = _daily_read_utf(payload, offset)
        if offset + 34 > len(payload):
            raise ValueError(f"国家城池记录{index + 1}尾部不完整")
        tail = payload[offset:offset + 34]
        offset += 34
        kind = _national_kind_from_wire(wire_kind)
        if kind == "unknown":
            kind = _national_kind_from_category(category)
        cities.append({
            "index": index + 1,
            "name": name,
            "cityName": name,
            "kind": kind,
            "kindCode": int(wire_kind),
            "x": int(x),
            "y": int(y),
            "ownerLabel": owner,
            "listCategory": int(category),
            "rawTailHex": tail.hex(),
        })
    return {
        "status": int(status),
        "category": int(category),
        "responseCategory": int(response_category),
        "totalPages": max(1, int(total_pages)),
        "page": max(1, int(page)),
        "count": int(count),
        "cities": cities,
        "parsedBytes": offset,
    }


def _parse_general_visit_candidate(payload: bytes, offset: int) -> tuple[dict[str, Any], int]:
    general_id, offset = _daily_i64(payload, offset)
    name, offset = _daily_read_utf(payload, offset)
    if offset + 4 > len(payload):
        raise ValueError("名将记录基础字段不完整")
    unknown_a, unknown_b = payload[offset], payload[offset + 1]
    level, job = payload[offset + 2], payload[offset + 3]
    offset += 4
    portrait, offset = _daily_i16(payload, offset)
    fief_name, offset = _daily_read_utf(payload, offset)
    city_name, offset = _daily_read_utf(payload, offset)
    if offset >= len(payload):
        raise ValueError("名将记录缺少俘虏状态")
    captive_state = payload[offset]
    offset += 1
    owner_name, offset = _daily_read_utf(payload, offset)
    salary_stars, offset = _daily_i16(payload, offset)
    if offset >= len(payload):
        raise ValueError("名将记录缺少忠诚度")
    loyalty = payload[offset]
    offset += 1
    exp, offset = _daily_i64(payload, offset)
    exp_limit, offset = _daily_i64(payload, offset)
    # Two protocol fields are currently unknown, followed by the displayed stats.
    _unknown_1, offset = _daily_i16(payload, offset)
    _unknown_2, offset = _daily_i16(payload, offset)
    growth, offset = _daily_i16(payload, offset)
    breakout, offset = _daily_i16(payload, offset)
    strength_base, offset = _daily_i16(payload, offset)
    strength_total, offset = _daily_i16(payload, offset)
    intelligence_base, offset = _daily_i16(payload, offset)
    intelligence_total, offset = _daily_i16(payload, offset)
    command, offset = _daily_i16(payload, offset)
    troop_limit, offset = _daily_i16(payload, offset)
    return {
        "id": str(general_id),
        "idInt": int(general_id),
        "name": name,
        "level": int(level),
        "job": int(job),
        "portrait": int(portrait),
        "fiefName": fief_name,
        "cityName": city_name,
        "captiveState": int(captive_state),
        "ownerName": owner_name,
        "salaryStars": int(salary_stars),
        "loyalty": int(loyalty),
        "exp": int(exp),
        "expLimit": int(exp_limit),
        "growth": int(growth),
        "breakout": int(breakout),
        "strengthBase": int(strength_base),
        "strengthTotal": int(strength_total),
        "intelligenceBase": int(intelligence_base),
        "intelligenceTotal": int(intelligence_total),
        "command": int(command),
        "troopLimit": int(troop_limit),
        "force": int(strength_total),
        "intelligence": int(intelligence_total),
        "available": int(captive_state) == 0,
        "rawUnknown": [int(unknown_a), int(unknown_b)],
        "_pageOffset": offset,
    }, offset


def parse_general_visit_page(payload: bytes) -> dict[str, Any]:
    if len(payload) < 6:
        # Business rejections may contain only status + UTF text.  Three
        # bytes is therefore the minimum useful frame even though a normal
        # paged response is longer.
        if len(payload) < 3:
            raise ValueError(f"0xA271响应过短：{len(payload)}")
    status = struct.unpack_from(">b", payload, 0)[0]
    message, offset = _daily_read_utf(payload, 1)
    if offset + 5 > len(payload):
        return {
            "status": int(status),
            "message": clean_activity_result_message(message),
            "pageSize": 0,
            "page": 0,
            "count": 0,
            "candidates": [],
            "parsedBytes": offset,
            "shortReceipt": True,
        }
    page_size, offset = _daily_u16(payload, offset)
    page, offset = _daily_u16(payload, offset)
    if offset >= len(payload):
        raise ValueError("名将列表缺少数量")
    count = payload[offset]
    offset += 1
    candidates = []
    for _ in range(int(count)):
        candidate, offset = _parse_general_visit_candidate(payload, offset)
        candidates.append(candidate)
    return {
        "status": int(status),
        "message": clean_activity_result_message(message),
        "pageSize": int(page_size),
        "page": int(page),
        "count": int(count),
        "candidates": candidates,
        "parsedBytes": offset,
    }


def general_visit_already_visited(status: Any, message: Any) -> bool:
    return int(status or 0) == -2 and any(
        marker in str(message or "")
        for marker in ("本日已拜访", "今日已拜访", "已经拜访")
    )


def parse_general_visit_receipt(payload: bytes) -> dict[str, Any]:
    if len(payload) < 4:
        raise ValueError(f"0xA273响应过短：{len(payload)}")
    status = struct.unpack_from(">i", payload, 0)[0]
    message, offset = _daily_read_utf(payload, 4)
    cleaned_message = clean_activity_result_message(message)
    already_visited = general_visit_already_visited(status, cleaned_message)
    # 拜访交互本身是否完成：接受征召、拒绝征召都算“今天已经拜访过了”。
    # “名将已被俘虏/已被结交”等表示拜访没真正发生，可顺延下一个候选。
    invitation_resolved = int(status) == 0 and any(
        marker in cleaned_message
        for marker in (
            "拒绝了阁下的邀请",
            "接受了阁下的邀请",
            "愿意追随",
            "纳入帐下",
        )
    )
    visit_succeeded = int(status) == 1 or invitation_resolved
    return {
        "status": int(status),
        "message": cleaned_message,
        # 业务语义：只要成功完成一次拜访交互就算成功（含拒绝征召）。
        "success": visit_succeeded,
        "completed": visit_succeeded or already_visited,
        "recruited": int(status) == 1,
        "alreadyVisited": already_visited,
        "invitationResolved": invitation_resolved,
        "invitationRejected": invitation_resolved and "拒绝了阁下的邀请" in cleaned_message,
        "remainingHex": payload[offset:].hex()[:4096],
    }


def query_national_cities(
    sess: dict[str, Any],
    categories: tuple[int, ...] | list[int] | None = None,
) -> list[dict[str, Any]]:
    selected_categories = tuple(dict.fromkeys(
        int(category) for category in (categories or DAILY_NATIONAL_CATEGORIES)
    ))
    if any(int(category) not in DAILY_NATIONAL_CATEGORIES for category in selected_categories):
        raise ValueError("国家城池查询禁止包含小城分类4")
    cities_by_name: dict[str, dict[str, Any]] = {}
    for category in selected_categories:
        page = 1
        total_pages = 1
        while page <= total_pages and page <= DAILY_NATIONAL_MAX_PAGES:
            payload = build_national_city_list_payload(int(category), page)
            code, _data, packets = post_game(
                sess["gameHttp"],
                [(0x1404, payload)],
                int(sess["dm"]),
                account_id=str(sess.get("sessionId") or ""),
            )
            response = next((p for p in packets if p.get("opcode") == 0x8404), None)
            if response is None:
                raise GameProtocolResponseError(
                    f"国家城池列表未收到0x8404：category={category} page={page} http={code}"
                )
            parsed = parse_national_city_page(response.get("payload") or b"", int(category))
            if int(parsed.get("status") or 0) != 0:
                raise GameApplicationResponseError(
                    f"国家城池列表被服务器拒绝：category={category} status={parsed.get('status')}"
                )
            total_pages = max(1, int(parsed.get("totalPages") or 1))
            for city in parsed.get("cities") or []:
                name = str(city.get("name") or "").strip()
                kind = str(city.get("kind") or "unknown")
                if not name or kind not in {"state", "commandery", "county"}:
                    continue
                city["queryCategory"] = int(category)
                cities_by_name.setdefault(name, city)
            if not parsed.get("cities") and page >= total_pages:
                break
            page += 1
    return list(cities_by_name.values())


def _daily_city_name(city: dict[str, Any] | str) -> str:
    if isinstance(city, dict):
        # 0x8310 owned-fief records expose both a display fief name (for
        # example “广成关封地”) and the actual city name (“广成关”).  The
        # collection endpoints accept the latter.  National-city records
        # populate both fields with the same value, so preferring cityName is
        # safe for both callers and prevents城主征收 from submitting a fief
        # label that the game cannot resolve as a city.
        return str(city.get("cityName") or city.get("city") or city.get("name") or "").strip()
    return str(city or "").strip()


def query_national_collect_status(sess: dict[str, Any], city: dict[str, Any] | str) -> dict[str, Any]:
    city_name = _daily_city_name(city)
    payload = build_national_city_status_payload(city_name)
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x1332, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0x8332), None)
    if response is None:
        raise GameProtocolResponseError(f"{city_name}征收状态未收到0x8332：http={code}")
    parsed = parse_national_collect_status(response.get("payload") or b"")
    parsed["city"] = city_name
    return parsed


def collect_national_city(sess: dict[str, Any], city: dict[str, Any] | str) -> dict[str, Any]:
    city_name = _daily_city_name(city)
    payload = build_national_collect_payload(city_name)
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x1334, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0x8334), None)
    if response is None:
        raise GameProtocolResponseError(f"{city_name}国家征收未收到0x8334：http={code}")
    result = parse_daily_status_utf_receipt(response.get("payload") or b"", success_status=1)
    result.update({"city": city_name, "http": int(code), "responseOpcode": "0x8334"})
    return result


def claim_national_salary(sess: dict[str, Any]) -> dict[str, Any]:
    citizen_skip = national_citizen_daily_skip_result(sess)
    if citizen_skip is not None:
        return citizen_skip
    payload = build_salary_payload()
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x314B, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0xA14B), None)
    if response is None:
        raise GameProtocolResponseError(f"国家俸禄未收到0xA14B：http={code}")
    result = parse_salary_receipt(response.get("payload") or b"")
    result.update({"http": int(code), "responseOpcode": "0xA14B"})
    return result


def query_own_fiefs(sess: dict[str, Any]) -> dict[str, Any]:
    """兼容旧名：城主征收改为查询自有城池(0x1318)，不再用封地列表(0x1310)。"""
    owned = query_owned_cities(sess)
    cities = list(owned.get("cities") or [])
    return {
        **owned,
        # 旧调用方读 fiefs；这里返回的已是城池记录。
        "fiefs": cities,
    }


def collect_city_lord(sess: dict[str, Any], fief: dict[str, Any] | str) -> dict[str, Any]:
    city_name = _daily_city_name(fief)
    payload = build_city_lord_collect_payload(city_name)
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x1330, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0x8330), None)
    if response is None:
        raise GameProtocolResponseError(f"{city_name}城主征收未收到0x8330：http={code}")
    result = parse_daily_status_utf_receipt(response.get("payload") or b"", success_status=1)
    result.update({"city": city_name, "http": int(code), "responseOpcode": "0x8330"})
    return result


def query_general_visit_candidates(sess: dict[str, Any]) -> dict[str, Any]:
    citizen_skip = national_citizen_daily_skip_result(sess)
    if citizen_skip is not None:
        return {
            **citizen_skip,
            "generals": [],
            "candidates": [],
            "pages": 0,
            "updatedAt": now_ms(),
        }
    pages: list[dict[str, Any]] = []
    by_id: dict[str, dict[str, Any]] = {}
    page = 1
    page_size = DAILY_GENERAL_PAGE_SIZE
    while page <= DAILY_NATIONAL_MAX_PAGES:
        payload = build_general_visit_list_payload(page, page_size)
        code, _data, packets = post_game(
            sess["gameHttp"],
            [(0x3271, payload)],
            int(sess["dm"]),
            account_id=str(sess.get("sessionId") or ""),
        )
        response = next((p for p in packets if p.get("opcode") == 0xA271), None)
        if response is None:
            raise GameProtocolResponseError(f"名将列表未收到0xA271：page={page} http={code}")
        parsed = parse_general_visit_page(response.get("payload") or b"")
        if int(parsed.get("status") or 0) != 0 and not parsed.get("candidates"):
            if general_visit_already_visited(
                parsed.get("status"), parsed.get("message")
            ):
                return {
                    "success": True,
                    "completed": True,
                    "alreadyVisited": True,
                    "message": str(parsed.get("message") or "本日已拜访"),
                    "generals": [],
                    "candidates": [],
                    "pages": len(pages),
                    "updatedAt": now_ms(),
                }
            raise GameApplicationResponseError(
                f"名将列表被服务器拒绝：{parsed.get('message') or parsed.get('status')}"
            )
        pages.append(parsed)
        actual_page_size = int(parsed.get("pageSize") or page_size)
        for candidate in parsed.get("candidates") or []:
            candidate = dict(candidate)
            candidate["page"] = int(parsed.get("page") or page)
            candidate["pageSize"] = actual_page_size
            by_id.setdefault(str(candidate.get("id")), candidate)
        count = len(parsed.get("candidates") or [])
        if count < page_size or actual_page_size <= 0:
            break
        page += 1
    candidates = list(by_id.values())
    return {
        "success": True,
        "generals": candidates,
        "candidates": candidates,
        "pages": len(pages),
        "updatedAt": now_ms(),
    }


def visit_general(sess: dict[str, Any], candidate: dict[str, Any]) -> dict[str, Any]:
    general_id = int(candidate.get("idInt") or candidate.get("id") or 0)
    page = max(1, int(candidate.get("page") or 1))
    page_size = max(1, min(100, int(candidate.get("pageSize") or DAILY_GENERAL_PAGE_SIZE)))
    payload = build_general_visit_payload(general_id, page, page_size)
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x3273, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0xA273), None)
    if response is None:
        raise GameProtocolResponseError(f"拜访{candidate.get('name') or general_id}未收到0xA273：http={code}")
    result = parse_general_visit_receipt(response.get("payload") or b"")
    result.update({
        "generalId": str(general_id),
        "generalName": str(candidate.get("name") or general_id),
        "page": page,
        "pageSize": page_size,
        "http": int(code),
        "responseOpcode": "0xA273",
    })
    return result


ARENA_COINS_DUPLICATE_LOG = "领竞技币重复，22点后再领取！"
DAILY_SIGN_IN_DUPLICATE_LOG = "自动签到重复，本日已签到，明日再签到！"


def trailing_utf_message(payload: bytes) -> str:
    """Return a UTF field that exactly occupies the end of a packet payload."""
    raw = payload or b""
    for offset in range(len(raw) - 2, -1, -1):
        size = struct.unpack(">H", raw[offset:offset + 2])[0]
        if offset + 2 + size != len(raw):
            continue
        try:
            message = raw[offset + 2:].decode("utf-8")
        except UnicodeDecodeError:
            continue
        if message.strip():
            return message.strip()
    return ""


def clean_activity_result_message(message: Any) -> str:
    text = re.sub(r"(?i)<br\s*/?>", "；", str(message or ""))
    text = re.sub(r"<[^>]+>", "", text)
    return "；".join(
        part.strip()
        for part in re.split(r"[。；;]+", text)
        if part.strip()
    )


def parse_arena_coin_claim_response(payload: bytes) -> dict[str, Any]:
    """Normalize the observed 0xe266 duplicate-claim reply.

    Live evidence after a successful claim:
      fe 0000 01 00000000000325e4 0000012c
      ^^ ^^^^
      -2 empty UTF message

    The server uses status -2 with an empty UTF string and a fixed-size
    13-byte trailing reward-state block when the current arena reward has
    already been consumed. Treat this idempotently as today's task completed.
    """
    parsed = parse_status_message_payload(payload)
    duplicate = (
        parsed.get("status") == -2
        and not str(parsed.get("message") or "").strip()
        and len(payload or b"") == 16
        and (payload or b"")[1:3] == b"\x00\x00"
        and (payload or b"")[3:4] == b"\x01"
    )
    if duplicate:
        parsed.update({
            "success": True,
            "message": ARENA_COINS_DUPLICATE_LOG,
            "alreadyClaimed": True,
            "duplicateClaim": True,
            "serverStatus": -2,
        })
    return parsed


def parse_daily_sign_in_packets(packets: list[dict[str, Any]]) -> dict[str, Any]:
    """Parse the known reply shapes for 0x6202 daily sign-in.

    Current live servers return a complete 0x8134 activity list for both
    branches. A fresh sign-in ends with a UTF reward message such as
    “铜钱:10000获得成功。粮食:30000获得成功。”; a duplicate ends with
    “本日已签到”. Older servers may still acknowledge a fresh sign-in with
    0xe202.
    """
    activity_response: dict[str, Any] | None = None
    for packet in packets:
        if packet.get("opcode") != 0x8134:
            continue
        activity_response = packet
        payload = packet.get("payload") or b""
        server_message = trailing_utf_message(payload)
        raw_text = payload.decode("utf-8", errors="ignore")
        if "本日已签到" in raw_text or "本日已签到" in server_message:
            return {
                "success": True,
                "status": None,
                "message": DAILY_SIGN_IN_DUPLICATE_LOG,
                "alreadyClaimed": True,
                "duplicateClaim": True,
                "serverMessage": "本日已签到",
                "responseOpcode": "0x8134",
                "payloadHex": payload.hex(),
                "remainingHex": "",
            }
        if server_message and any(
            marker in server_message
            for marker in ("获得成功", "签到成功", "领取成功")
        ):
            return {
                "success": True,
                "status": 0,
                "message": clean_activity_result_message(server_message),
                "serverMessage": server_message,
                "alreadyClaimed": False,
                "duplicateClaim": False,
                "responseOpcode": "0x8134",
                "payloadHex": payload.hex(),
                "remainingHex": "",
            }
    response = next((p for p in packets if p.get("opcode") == 0xE202), None)
    if response is None:
        if activity_response is not None:
            payload = activity_response.get("payload") or b""
            server_message = trailing_utf_message(payload)
            return {
                "success": False,
                "status": None,
                "message": (
                    f"签到响应未能识别：{clean_activity_result_message(server_message)}"
                    if server_message else
                    "收到 0x8134 签到响应，但未找到成功或已签到标记"
                ),
                "serverMessage": server_message,
                "responseOpcode": "0x8134",
                "payloadHex": payload.hex(),
                "remainingHex": "",
            }
        return {
            "success": False,
            "status": None,
            "message": "未收到可识别的签到响应（0xe202/0x8134）",
            "responseOpcode": "",
            "payloadHex": "",
            "remainingHex": "",
        }
    payload = response.get("payload") or b""
    if not payload:
        return {
            "success": True,
            "status": 0,
            "message": "签到请求已由服务器确认",
            "responseOpcode": "0xe202",
            "payloadHex": "",
            "remainingHex": "",
        }
    parsed = parse_status_message_payload(payload)
    return {
        **parsed,
        "responseOpcode": "0xe202",
        "payloadHex": payload.hex(),
    }


def parse_daily_diamond_box_response(payload: bytes) -> dict[str, Any]:
    """Normalize the expired-activity reply as today's box already claimed.

    The live 0x8134 reply can contain a complete activity list followed by
    “操作失败，活动已过期。”, rather than the common status+UTF layout.
    For this daily action the expired entry means there is nothing left to
    claim today, so treat it as an idempotent success.
    """
    raw_text = (payload or b"").decode("utf-8", errors="ignore")
    trailing_message = trailing_utf_message(payload)
    combined_message = f"{raw_text}\n{trailing_message}"
    if "活动已过期" in raw_text:
        server_message = "操作失败，活动已过期。"
        return {
            "success": True,
            "status": struct.unpack(">b", payload[:1])[0] if payload else None,
            "message": "每日金钻宝箱已经领取过了！",
            "alreadyClaimed": True,
            "serverMessage": server_message,
            "normalizedFromExpiredActivity": True,
            "remainingHex": "",
        }
    if any(text in combined_message for text in ("已经领取", "已领取", "重复领取")):
        return {
            "success": True,
            "status": None,
            "message": "每日金钻宝箱已经领取过了！",
            "alreadyClaimed": True,
            "serverMessage": trailing_message or clean_activity_result_message(raw_text),
            "remainingHex": "",
        }
    if trailing_message and any(
        marker in trailing_message
        for marker in ("获得成功", "领取成功")
    ):
        return {
            "success": True,
            "status": 0,
            "message": clean_activity_result_message(trailing_message),
            "alreadyClaimed": False,
            "serverMessage": trailing_message,
            "remainingHex": "",
        }
    common_status_utf = (
        len(payload or b"") >= 3
        and struct.unpack(">H", (payload or b"")[1:3])[0] == len(payload or b"") - 3
    )
    if not common_status_utf:
        return {
            "success": False,
            "status": None,
            "message": (
                f"每日金钻宝箱响应未能识别：{clean_activity_result_message(trailing_message)}"
                if trailing_message else
                "每日金钻宝箱响应未包含可识别的结果"
            ),
            "serverMessage": trailing_message,
            "remainingHex": "",
        }
    parsed = parse_status_message_payload(payload)
    message = str(parsed.get("message") or "")
    if any(text in message for text in ("已经领取", "已领取", "重复领取")):
        parsed.update({
            "success": True,
            "message": "每日金钻宝箱已经领取过了！",
            "alreadyClaimed": True,
            "serverMessage": message,
        })
    return parsed


def use_inventory_item(sess: dict[str, Any], item_id: int, count: int = 1, *, item_name: str = "") -> dict[str, Any]:
    item_id = int(item_id)
    count = max(1, min(int(count), 65535))
    payload = struct.pack(">HH", item_id, count)
    purpose = f"开启{item_name}" if item_name else "使用道具"
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x3144, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0xA144), None)
    parsed = parse_status_message_payload(response["payload"]) if response else {
        "success": False,
        "status": None,
        "message": "未收到 0xa144 道具使用响应",
    }
    return {
        **parsed,
        "http": code,
        "itemId": item_id,
        "itemName": item_name,
        "count": count,
        "payloadHex": payload.hex(),
        "packets": summarize_packets(packets),
    }


AUTO_OPEN_KEY_REQUIREMENTS = {
    "青铜宝箱": "青铜钥匙",
    "精铁宝箱": "精铁钥匙",
}


def inventory_reward_log_text(message: Any) -> str:
    text = re.sub(r"(?i)<br\s*/?>", "；", str(message or ""))
    text = re.sub(r"<[^>]+>", "", text)
    return "；".join(part.strip() for part in re.split(r"[；;]", text) if part.strip())


def auto_open_inventory_items(sess: dict[str, Any], selected_names: list[str]) -> dict[str, Any]:
    selected = [name for name in dict.fromkeys(selected_names) if name in AUTO_OPEN_ITEM_NAMES]
    if not selected:
        return {"actions": [], "skipped": [], "opened": 0}
    inventory = refresh_inventory(sess)
    items = list(inventory.get("items") or [])

    def item_count(name: str) -> int:
        return sum(
            max(0, int(item.get("count") or 0))
            for item in items
            if str(item.get("name") or "") == name
        )

    def item_ref(name: str) -> dict[str, Any] | None:
        return next((
            item for item in items
            if str(item.get("name") or "") == name
            and int(item.get("count") or 0) > 0
        ), None)

    actions: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    max_items = 50
    attempted = 0
    opened = 0
    for name in selected:
        remaining = max_items - opened
        if remaining <= 0:
            skipped.append({"name": name, "reason": "本轮已达到50个上限，留待下轮"})
            continue
        item = item_ref(name)
        available = item_count(name)
        if available <= 0:
            skipped.append({"name": name, "reason": "背包中没有该物品"})
            continue
        required_key = AUTO_OPEN_KEY_REQUIREMENTS.get(name)
        key_count = item_count(required_key) if required_key else available
        open_count = min(available, key_count)
        if open_count <= 0:
            reason = f"缺少{required_key}，保持宝箱不动"
            skipped.append({"name": name, "reason": reason})
            account_log(str(sess.get("sessionId") or ""), f"自动开箱跳过：{name}；{reason}", source="automation")
            continue
        batch_count = min(open_count, remaining)
        result = use_inventory_item(
            sess,
            int(item.get("itemId") or 0),
            batch_count,
            item_name=name,
        )
        attempted += batch_count
        latest_inventory = refresh_inventory(sess)
        items = list(latest_inventory.get("items") or [])
        actual_opened = max(0, min(batch_count, available - item_count(name)))
        raw_message = str(result.get("message") or "")
        message_parts = [
            part for part in inventory_reward_log_text(raw_message).split("；")
            if part
        ]
        failure_parts = [
            part for part in message_parts
            if "开启失败" in part or "无法开启" in part
        ]
        reward_parts = [
            part for part in message_parts
            if part not in failure_parts
        ]
        reward_text = "；".join(reward_parts)
        failure_text = "；".join(failure_parts)
        action = {
            **result,
            "protocolSuccess": bool(result.get("success")),
            "success": actual_opened > 0,
            "requestedCount": batch_count,
            "openedCount": actual_opened,
            "partial": 0 < actual_opened < batch_count,
            "responseMessage": raw_message,
            "message": reward_text if actual_opened > 0 else raw_message,
        }
        actions.append(action)
        if actual_opened <= 0:
            quantity = f" ×{batch_count}" if batch_count > 1 else ""
            account_log(
                str(sess.get("sessionId") or ""),
                f"自动开箱中止：{name}{quantity}；"
                f"{raw_message or '服务器未确认成功'}",
                level="error",
                source="automation",
            )
            continue
        opened += actual_opened
        quantity = f" ×{actual_opened}" if actual_opened > 1 else ""
        account_log(
            str(sess.get("sessionId") or ""),
            f"自动开箱成功：{name}{quantity} → "
            f"{reward_text or '服务器确认成功，未返回奖励说明'}",
            source="automation",
        )
        if actual_opened < batch_count:
            reason = (
                f"请求{batch_count}个，实际开启{actual_opened}个"
                + (f"；{failure_text}" if failure_text else "")
            )
            skipped.append({"name": name, "reason": reason})
            account_log(
                str(sess.get("sessionId") or ""),
                f"自动开箱部分完成：{name}请求×{batch_count}，"
                f"成功×{actual_opened}"
                + (f"；{failure_text}" if failure_text else ""),
                level="warning",
                source="automation",
            )
        elif batch_count < open_count:
            skipped.append({
                "name": name,
                "reason": f"本轮已开启{batch_count}个，剩余{open_count - batch_count}个留待下轮",
            })
        time.sleep(0.35)
    return {
        "actions": actions,
        "skipped": skipped,
        "opened": opened,
        "attempted": attempted,
        "limited": opened >= max_items,
    }


def claim_arena_coins(sess: dict[str, Any]) -> dict[str, Any]:
    """Request the arena reward and retain enough wire evidence to classify replies."""
    sid = str(sess.get("sessionId") or "")
    read_code, _read_data, read_packets = post_game(
        sess["gameHttp"],
        [(0x6260, b"")],
        int(sess["dm"]),
        account_id=sid,
    )
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x6266, b"")],
        int(sess["dm"]),
        account_id=sid,
    )
    response = next((p for p in packets if p.get("opcode") == 0xE266), None)
    parsed = parse_arena_coin_claim_response(response["payload"]) if response else {
        "success": False,
        "status": None,
        "message": "未收到 0xe266 竞技奖励响应",
        "remainingHex": "",
    }
    if response and not parsed.get("success") and not str(parsed.get("message") or "").strip():
        parsed["message"] = "当前不可领取：竞技场每日奖励需在22点后领取，或今日已经领取"
    return {
        **parsed,
        "http": code,
        "responseOpcode": "0xe266" if response else "",
        "payloadHex": response["payload"].hex() if response else "",
        "packets": summarize_packets(packets),
        "readArena": {
            "http": read_code,
            "packets": summarize_packets(read_packets),
        },
    }


def claim_daily_sign_in(sess: dict[str, Any]) -> dict[str, Any]:
    """Request daily sign-in and expose the complete 0xe202 evidence."""
    sid = str(sess.get("sessionId") or "")
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(0x6202, b"")],
        int(sess["dm"]),
        account_id=sid,
    )
    parsed = parse_daily_sign_in_packets(packets)
    return {
        **parsed,
        "http": code,
        "packets": summarize_packets(packets),
    }


def log_arena_coin_claim_result(
    sess: dict[str, Any],
    result: dict[str, Any],
    *,
    source: str = "automation",
) -> None:
    sid = str(sess.get("sessionId") or "")
    if result.get("duplicateClaim"):
        message = ARENA_COINS_DUPLICATE_LOG
        level = "info"
    elif result.get("success"):
        message = f"领竞技币完成：{result.get('message') or '服务器确认成功'}"
        level = "info"
    else:
        message = f"领竞技币失败：{result.get('message') or '服务器未返回说明'}"
        level = "warn"
    account_log(sid, message, level=level, source=source, detail=result)
    account_key = account_storage_key(session_id=sid)
    if result.get("success"):
        database_resolve_important_notice(account_key, "daily:arenaCoins")
    else:
        database_upsert_important_notice(
            account_key,
            "daily:arenaCoins",
            severity="warning",
            title="领取竞技币未完成",
            message=message,
            source=source,
        )


