def _daily_exception_is_session_invalid(exc: BaseException) -> bool:
    return isinstance(exc, GameServerRejected) or is_session_invalid_message(str(exc))


def log_daily_feature_result(
    sess: dict[str, Any],
    task_key: str,
    result: dict[str, Any],
    *,
    source: str = "automation",
) -> None:
    """Write one feature's result without allowing logging to affect siblings."""
    sid = str(sess.get("sessionId") or "")
    name = DAILY_TASK_NAMES.get(str(task_key), str(task_key))
    success = bool(result.get("success"))
    message = f"{name}{'完成' if success else '失败'}：{str(result.get('message') or ('服务器确认成功' if success else '未完成')).strip()}"
    try:
        account_log(
            sid,
            message,
            level=("info" if success else "warn"),
            source=source,
            detail=result,
        )
        account_key = account_storage_key(session_id=sid)
        if success:
            database_resolve_important_notice(account_key, f"daily:{task_key}")
        else:
            database_upsert_important_notice(
                account_key,
                f"daily:{task_key}",
                severity="warning",
                title=f"{name}未完成",
                message=message,
                source=source,
            )
    except Exception as exc:
        # A notice/database outage is itself non-critical to game task flow.
        try:
            account_log(
                sid,
                f"{name}结果记录失败：{exc}",
                level="error",
                source="automation-log",
            )
        except Exception:
            pass


def _daily_feature_failure_result(task_key: str, exc: BaseException) -> dict[str, Any]:
    name = DAILY_TASK_NAMES.get(str(task_key), str(task_key))
    return {
        "success": False,
        "completed": False,
        "message": f"{name}异常：{str(exc) or type(exc).__name__}",
        "exception": type(exc).__name__,
    }


def execute_national_collect(sess: dict[str, Any]) -> dict[str, Any]:
    """Inspect state/commandery/county cities once and collect richest first.

    National collection uses one account-wide daily quota.  The selector first
    scans every eligible city exactly once, then sorts by collectable copper;
    hierarchy is only a tie-breaker (state, commandery, county).  Small cities
    are never queried by ``query_national_cities`` and are rejected again here
    defensively.
    """
    citizen_skip = national_citizen_daily_skip_result(sess)
    if citizen_skip is not None:
        return citizen_skip
    cities = query_national_cities(sess)
    unique: dict[str, dict[str, Any]] = {}
    for city in cities:
        name = _daily_city_name(city)
        kind = str(city.get("kind") or "unknown") if isinstance(city, dict) else "unknown"
        if not name or kind not in {"state", "commandery", "county"}:
            continue
        unique.setdefault(name, dict(city))
    if not unique:
        return {
            "success": True,
            "completed": True,
            "noTarget": True,
            "successfulCount": 0,
            "attemptedCount": 0,
            "failureCount": 0,
            "inspectedCount": 0,
            "candidateCount": 0,
            "message": "没有可执行的国家征收城池（已跳过小城）",
            "inspections": [],
            "attempts": [],
        }

    # A lower hierarchy rank wins only after copper amount is compared.
    hierarchy_rank = {"state": 0, "commandery": 1, "county": 2}
    hierarchy_label = {"state": "州城", "commandery": "郡城", "county": "县城"}
    inspections: list[dict[str, Any]] = []
    attempts: list[dict[str, Any]] = []
    ranked: list[dict[str, Any]] = []
    successful_count = 0
    successful_copper = 0
    failure_count = 0
    status_failure_count = 0
    inspected_count = 0
    quota_limits: list[int] = []
    quota_used_values: list[int] = []

    # Stage 1: inspect every state/commandery/county city once.  Keeping the
    # insertion order preserves the requested query preference (州→郡→县),
    # while the later sort still lets a richer lower-tier city win.
    for inspection_order, (name, city) in enumerate(unique.items(), start=1):
        kind = str(city.get("kind") or "unknown")
        try:
            state = query_national_collect_status(sess, city)
        except GameServerRejected:
            raise
        except Exception as exc:
            failure_count += 1
            status_failure_count += 1
            failure = {
                "city": name,
                "kind": kind,
                "kindLabel": hierarchy_label.get(kind, kind),
                "success": False,
                "stage": "status",
                "inspectionOrder": inspection_order,
                "message": str(exc) or "征收状态查询异常",
            }
            inspections.append(failure)
            attempts.append(failure)
            continue
        inspected_count += 1
        observed_limit = max(0, int(state.get("limit") or 0))
        observed_used = max(0, int(state.get("usedCount") or 0))
        if observed_limit > 0:
            quota_limits.append(observed_limit)
            quota_used_values.append(observed_used)
        can_collect = state.get("canCollect")
        if can_collect is None:
            can_collect = (
                int(state.get("status") or 0) == 0
                and int(state.get("availability") or 0) == 0
                and observed_limit > 0
                and observed_used < observed_limit
                and int(state.get("currentCopper") or 0) > 0
            )
        copper = max(0, int(state.get("currentCopper") or 0))
        inspection = {
            "city": name,
            "kind": kind,
            "kindLabel": hierarchy_label.get(kind, kind),
            "inspectionOrder": inspection_order,
            "success": True,
            "stage": "status",
            "status": int(state.get("status") or 0),
            "availability": int(state.get("availability") or 0),
            "usedCount": observed_used,
            "limit": observed_limit,
            "copper": copper,
            "food": max(0, int(state.get("currentFood") or 0)),
            "canCollect": bool(can_collect and copper > 0),
        }
        inspections.append(inspection)
        if inspection["canCollect"]:
            ranked.append({
                "city": city,
                "name": name,
                "kind": kind,
                "state": state,
                "copper": copper,
            })

    quota_limit = min(quota_limits) if quota_limits else None
    quota_used = max(quota_used_values) if quota_used_values else 0
    quota_remaining = (
        max(0, quota_limit - quota_used)
        if quota_limit is not None
        else DAILY_NATIONAL_MAX_ATTEMPTS
    )
    quota_exhausted = quota_limit is not None and quota_remaining <= 0

    # Stage 2: richest city first; only equal copper falls back to hierarchy.
    ranked.sort(key=lambda item: (
        -int(item["copper"]),
        hierarchy_rank.get(str(item["kind"]), 99),
        str(item["name"]),
    ))
    ranked_snapshot = [
        {
            "rank": index,
            "city": item["name"],
            "kind": item["kind"],
            "kindLabel": hierarchy_label.get(str(item["kind"]), str(item["kind"])),
            "copper": int(item["copper"]),
        }
        for index, item in enumerate(ranked, start=1)
    ]

    collect_attempt_count = 0
    if not quota_exhausted:
        for rank, item in enumerate(ranked, start=1):
            if collect_attempt_count >= DAILY_NATIONAL_MAX_ATTEMPTS:
                break
            if successful_count >= quota_remaining:
                quota_exhausted = quota_limit is not None
                break
            name = str(item["name"])
            city = item["city"]
            kind = str(item["kind"])
            state = item["state"]
            collect_attempt_count += 1
            try:
                result = collect_national_city(sess, city)
            except GameServerRejected:
                raise
            except Exception as exc:
                failure_count += 1
                attempts.append({
                    "city": name,
                    "kind": kind,
                    "kindLabel": hierarchy_label.get(kind, kind),
                    "success": False,
                    "stage": "collect",
                    "selectionRank": rank,
                    "copper": int(state.get("currentCopper") or 0),
                    "message": str(exc) or "征收请求异常",
                })
                continue
            result = dict(result or {})
            result.setdefault("city", name)
            result.setdefault("kind", kind)
            result.setdefault("kindLabel", hierarchy_label.get(kind, kind))
            result.setdefault("stage", "collect")
            result.setdefault("selectionRank", rank)
            result.setdefault("copper", int(state.get("currentCopper") or 0))
            attempts.append(result)
            if result.get("success"):
                successful_count += 1
                successful_copper += max(0, int(result.get("copper") or 0))
                if quota_limit is not None and quota_used + successful_count >= quota_limit:
                    quota_exhausted = True
                    break
            else:
                failure_count += 1

    if successful_count:
        message = (
            f"国家征收{'部分' if failure_count else ''}完成：成功{successful_count}次，"
            f"预计获得铜钱{successful_copper}，失败{failure_count}项，"
            f"检查{inspected_count}座州/郡/县城，已跳过小城"
        )
    elif quota_exhausted:
        message = "国家征收次数已用尽"
    elif inspected_count and not ranked and not status_failure_count:
        message = "当前州城、郡城、县城均没有可征收铜钱（已跳过小城）"
    elif status_failure_count and not ranked:
        message = f"国家征收筛选失败：{status_failure_count}座城池状态未能读取"
    else:
        message = f"国家征收未完成：失败{failure_count}次，已跳过小城"
    no_target = bool(inspected_count and not ranked and not status_failure_count)
    # A successful subset is not enough to mark the daily task complete: a
    # status/read or collect failure may have left a richer city unprocessed.
    # The only terminal shortcuts are a confirmed exhausted quota or a clean
    # no-target scan.  Otherwise every eligible city must have been attempted
    # successfully before the completion marker is written.
    all_ranked_processed = (
        not ranked
        or collect_attempt_count >= len(ranked)
    )
    terminal_quota = bool(quota_exhausted and status_failure_count == 0)
    completed = bool(
        terminal_quota
        or no_target
        or (
            all_ranked_processed
            and status_failure_count == 0
            and failure_count == 0
            and successful_count == collect_attempt_count
        )
    )
    # Completion and success are deliberately separate.  Reaching the quota
    # after falling back to another city is terminal for the day, but the
    # failed richer-city attempt must still surface as a warning.
    success = bool(completed and failure_count == 0)
    return {
        "success": success,
        "partialSuccess": successful_count > 0 and failure_count > 0,
        "completed": completed,
        "noTarget": no_target,
        "successfulCount": successful_count,
        "successfulCopper": successful_copper,
        "attemptedCount": collect_attempt_count,
        "eventCount": len(attempts),
        "failureCount": failure_count,
        "statusFailureCount": status_failure_count,
        "inspectedCount": inspected_count,
        "candidateCount": len(unique),
        "eligibleCount": len(ranked),
        "quotaUsed": quota_used,
        "quotaLimit": quota_limit,
        "quotaRemaining": max(0, quota_remaining - successful_count),
        "quotaExhausted": quota_exhausted,
        "skippedSmallCities": True,
        "message": message,
        "ranking": ranked_snapshot,
        "inspections": inspections,
        "attempts": attempts,
    }


def city_lord_collect_attempt_kind(result: dict[str, Any] | None) -> str:
    """Classify one 0x8330 city-lord attempt for daily completion semantics."""
    item = result if isinstance(result, dict) else {}
    message = str(item.get("message") or "")
    if item.get("success"):
        return "collected"
    # 这些是“目标本身不可征”的业务回执：不应算失败，也不应阻塞今日完成。
    ineligible_markers = (
        "都城及其周边与之相联的门户城池不能进行征收",
        "只有城主可以使用城主征收功能",
        "您不是城主",
        "不是城主",
    )
    if any(marker in message for marker in ineligible_markers):
        return "ineligible"
    # 当日已征过：交互已发生，记为已执行。
    already_markers = (
        "已经征收",
        "本日已征收",
        "今日已征收",
        "今天已经征收",
        "已经进行过征收",
    )
    if any(marker in message for marker in already_markers):
        return "already"
    return "failed"


def execute_city_lord_collect(sess: dict[str, Any]) -> dict[str, Any]:
    """对 0x1318 返回的自有城池逐城执行 0x1330 城主征收。"""
    raw = query_owned_cities(sess)
    cities = raw.get("cities") if isinstance(raw, dict) else raw
    unique: list[dict[str, Any]] = []
    seen: set[str] = set()
    for city in cities or []:
        if not isinstance(city, dict):
            continue
        city_name = _daily_city_name(city)
        if not city_name or city_name in seen:
            continue
        seen.add(city_name)
        unique.append(dict(city))
    attempts: list[dict[str, Any]] = []
    for city in unique:
        name = _daily_city_name(city)
        try:
            result = collect_city_lord(sess, city)
        except GameServerRejected:
            raise
        except Exception as exc:
            result = {"success": False, "city": name, "message": str(exc) or "征收请求异常"}
        kind = city_lord_collect_attempt_kind(result)
        attempts.append(dict(result or {}, city=name, attemptKind=kind))
    collected = [item for item in attempts if item.get("attemptKind") == "collected"]
    already = [item for item in attempts if item.get("attemptKind") == "already"]
    ineligible = [item for item in attempts if item.get("attemptKind") == "ineligible"]
    failed = [item for item in attempts if item.get("attemptKind") == "failed"]
    executed = collected + already
    if not unique:
        return {
            "success": True,
            "completed": True,
            "noTarget": True,
            "partialSuccess": False,
            "attemptedCount": 0,
            "successCount": 0,
            "failureCount": 0,
            "ineligibleCount": 0,
            "alreadyCount": 0,
            "ownedCityCount": int((raw or {}).get("count") or 0) if isinstance(raw, dict) else 0,
            "message": "没有查询到可执行城主征收的自有城池",
            "attempts": [],
            "ownedCities": list(cities or []),
            "listOpcode": "0x1318/0x8318",
        }
    if failed and not executed:
        message = f"城主征收失败：可尝试{len(unique)}座，失败{len(failed)}座"
        if ineligible:
            message += f"，不可征{len(ineligible)}座"
        success = False
        completed = False
        partial = False
    elif failed and executed:
        message = (
            f"城主征收部分完成：成功{len(collected)}座"
            f"{'，已征过' + str(len(already)) + '座' if already else ''}"
            f"，失败{len(failed)}座"
        )
        success = False
        completed = False
        partial = True
    else:
        parts = []
        if collected:
            parts.append(f"成功{len(collected)}座")
        if already:
            parts.append(f"已征过{len(already)}座")
        if ineligible:
            parts.append(f"不可征{len(ineligible)}座")
        message = "城主征收完成：" + ("，".join(parts) if parts else "无待征收城池")
        success = True
        completed = True
        partial = False
    return {
        "success": success,
        "partialSuccess": partial,
        "completed": completed,
        "attemptedCount": len(attempts),
        "successCount": len(collected),
        "alreadyCount": len(already),
        "ineligibleCount": len(ineligible),
        "failureCount": len(failed),
        "executedCount": len(executed),
        "ownedCityCount": len(unique),
        "message": message,
        "attempts": attempts,
        "ownedCities": [
            {
                "cityName": _daily_city_name(city),
                "x": city.get("x"),
                "y": city.get("y"),
                "ownerName": city.get("ownerName"),
            }
            for city in unique
        ],
        "listOpcode": "0x1318/0x8318",
    }


def execute_general_visit(sess: dict[str, Any], selected_ids: list[Any] | tuple[Any, ...] | None = None) -> dict[str, Any]:
    citizen_skip = national_citizen_daily_skip_result(sess)
    if citizen_skip is not None:
        return citizen_skip
    ordered_ids = list(dict.fromkeys(str(value).strip() for value in (selected_ids or []) if str(value).strip()))[:4]
    if not ordered_ids:
        return {
            "success": False,
            "completed": False,
            "message": "名将拜访未选择将领",
            "attempts": [],
        }
    query_result = query_general_visit_candidates(sess)
    if isinstance(query_result, dict) and query_result.get("alreadyVisited"):
        return {
            "success": True,
            "completed": True,
            "duplicateVisit": True,
            "attemptedCount": 0,
            "failureCount": 0,
            "message": str(query_result.get("message") or "本日已经完成名将拜访"),
            "attempts": [],
            "skipped": [],
        }
    candidates = query_result.get("generals") if isinstance(query_result, dict) else query_result
    by_id = {}
    for candidate in candidates or []:
        if isinstance(candidate, dict):
            for key in (candidate.get("id"), candidate.get("idInt"), candidate.get("idHex")):
                if key not in (None, ""):
                    by_id[str(key)] = candidate
    attempts: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for selected_id in ordered_ids:
        candidate = by_id.get(str(selected_id))
        if candidate is None:
            skipped.append({"generalId": str(selected_id), "message": "当前不可拜访，已顺延"})
            continue
        name = str(candidate.get("name") or selected_id)
        if int(candidate.get("captiveState") or 0) != 0:
            skipped.append({"generalId": str(selected_id), "generalName": name, "message": "当前不可拜访，已顺延"})
            continue
        try:
            result = visit_general(sess, candidate)
        except GameServerRejected:
            raise
        except Exception as exc:
            result = {"success": False, "generalId": str(selected_id), "generalName": name, "message": str(exc) or "拜访请求异常"}
        attempts.append(dict(result or {}, generalId=str(selected_id), generalName=name))
        if result.get("alreadyVisited"):
            return {
                "success": True,
                "completed": True,
                "duplicateVisit": True,
                "attemptedCount": len(attempts),
                "failureCount": sum(1 for item in attempts if not item.get("success")),
                "message": str(result.get("message") or "本日已经完成名将拜访"),
                "attempts": attempts,
                "skipped": skipped,
            }
        if result.get("success") or result.get("invitationResolved") or result.get("completed"):
            # 接受征召 / 拒绝征召 / 其它“拜访交互已完成”回执，都算今天拜访成功。
            recruited = bool(result.get("recruited") or (result.get("success") and not result.get("invitationRejected")))
            rejected = bool(result.get("invitationRejected"))
            if recruited and not rejected:
                summary = f"名将拜访成功：{name}已接受征召"
            elif rejected:
                summary = f"名将拜访成功：{name}已拜访（暂未接受征召）"
            else:
                summary = f"名将拜访成功：{name}"
            detail_message = str(result.get("message") or "").strip()
            if detail_message and detail_message not in summary:
                summary = f"{summary}；{detail_message}"
            return {
                "success": True,
                "completed": True,
                "visitResolved": True,
                "recruited": recruited and not rejected,
                "invitationRejected": rejected,
                "attemptedCount": len(attempts),
                "failureCount": 0,
                "message": summary,
                "attempts": attempts,
                "skipped": skipped,
            }
    return {
        "success": False,
        "partialSuccess": False,
        "completed": False,
        "noTarget": not bool(attempts),
        "attemptedCount": len(attempts),
        "failureCount": len(attempts),
        "skippedCount": len(skipped),
        "message": (
            "已按优先级尝试，未有名将拜访成功"
            if attempts else "没有可尝试拜访的已选名将"
        ),
        "attempts": attempts,
        "skipped": skipped,
    }


def execute_daily_once_tasks(sess: dict[str, Any], settings: dict[str, Any]) -> dict[str, Any]:
    completed = {
        item["key"]: item
        for item in current_daily_task_completions(sess)
        if isinstance(item, dict) and item.get("key")
    }
    results: dict[str, Any] = {}
    sid = str(sess.get("sessionId") or "")

    def should_run(key: str) -> bool:
        if not bool(settings.get(key)):
            return False
        # Re-read completion while holding the feature lock.  A manual button
        # or another scheduler callback may have completed this same feature
        # after the initial snapshot was taken.
        latest = {
            item["key"]: item
            for item in current_daily_task_completions(sess)
            if isinstance(item, dict) and item.get("key")
        }
        return not bool((latest.get(key) or completed.get(key) or {}).get("completed"))

    def record_if_completed(key: str, result: dict[str, Any]) -> None:
        if not bool(result.get("completed")):
            return
        if result.get("skipped"):
            record_daily_task_completion(sess, key, result=result)
        elif result.get("duplicateClaim"):
            record_daily_task_completion(sess, key, source="automation-duplicate")
        else:
            record_daily_task_completion(sess, key)

    def isolated(key: str, fn: Callable[[], dict[str, Any]], *, custom_log: Callable[[dict[str, Any]], None] | None = None) -> None:
        # Locks are per account *and* feature: a duplicate manual/scheduled
        # invocation is suppressed, while a failure in this feature never
        # holds up sibling daily features.
        with daily_feature_lock(sess, key):
            if not should_run(key):
                return
            try:
                result = dict(fn() or {})
            except GameServerRejected as exc:
                # The account circuit breaker is still updated by post_game,
                # but the task result is recorded locally and the next daily
                # feature is allowed to run and report its own outcome.
                mark_account_offline_if_session_invalid(sid, str(exc))
                result = _daily_feature_failure_result(key, exc)
                result["sessionInvalid"] = True
            except Exception as exc:
                if _daily_exception_is_session_invalid(exc):
                    mark_account_offline_if_session_invalid(sid, str(exc))
                    result = _daily_feature_failure_result(key, exc)
                    result["sessionInvalid"] = True
                else:
                    result = _daily_feature_failure_result(key, exc)
            results[key] = result
            if custom_log is not None:
                try:
                    custom_log(result)
                except Exception as exc:
                    try:
                        account_log(sid, f"{DAILY_TASK_NAMES.get(key, key)}结果记录异常：{exc}", level="error", source="automation-log")
                    except Exception:
                        pass
            else:
                log_daily_feature_result(sess, key, result)
            try:
                record_if_completed(key, result)
            except Exception as exc:
                try:
                    account_log(sid, f"{DAILY_TASK_NAMES.get(key, key)}每日状态记录失败：{exc}", level="error", source="automation-log")
                except Exception:
                    pass

    def sign_in_once() -> dict[str, Any]:
        sign_result = claim_daily_sign_in(sess)
        success = bool(sign_result.get("success"))
        log_daily_sign_in_result(sess, sign_result)
        box_code, _box_data, box_packets = post_game(
            sess["gameHttp"],
            [(0x1134, struct.pack(">qB", 0x0DE2B1, 0))],
            int(sess["dm"]),
            account_id=sid,
        )
        box_response = next((p for p in box_packets if p.get("opcode") == 0x8134), None)
        box_parsed = parse_daily_diamond_box_response(box_response["payload"]) if box_response else {
            "success": False,
            "status": None,
            "message": "未收到 0x8134 每日金钻宝箱响应",
        }
        box_result = {
            **box_parsed,
            "http": box_code,
            "responseOpcode": "0x8134" if box_response else "",
            "packets": summarize_packets(box_packets),
        }
        result = {
            **sign_result,
            "completed": success,
            "message": (
                f"{sign_result.get('message') or '签到未返回说明'}；每日金钻宝箱："
                f"{box_result.get('message') or ('领取成功' if box_result.get('success') else '领取失败')}"
            ),
            "signIn": sign_result,
            "dailyDiamondBox": box_result,
        }
        try:
            account_log(
                sid,
                f"自动签到后领取每日金钻宝箱：{box_result.get('message') or ('成功' if box_result.get('success') else '失败')}",
                level=("info" if box_result.get("success") else "error"),
                source="automation",
                detail=box_result,
            )
            if box_result.get("success"):
                database_resolve_important_notice(account_storage_key(session_id=sid), "daily:diamondBox")
            else:
                database_upsert_important_notice(
                    account_storage_key(session_id=sid),
                    "daily:diamondBox",
                    severity="warning",
                    title="每日金钻宝箱未领取",
                    message=str(box_result.get("message") or "服务器未确认领取结果"),
                    source="automation",
                )
        except Exception:
            pass
        return result

    def arena_once() -> dict[str, Any]:
        result = dict(claim_arena_coins(sess) or {})
        result["completed"] = bool(result.get("success"))
        return result

    def salary_once() -> dict[str, Any]:
        result = dict(claim_national_salary(sess) or {})
        result["completed"] = bool(result.get("success"))
        return result

    isolated("autoSignIn", sign_in_once, custom_log=lambda result: log_daily_feature_result(sess, "autoSignIn", result))
    isolated("arenaCoins", arena_once, custom_log=lambda result: log_arena_coin_claim_result(sess, result))
    isolated("autoDonate", lambda: execute_daily_country_donations(sess))
    isolated("salary", salary_once)
    isolated("nationalCollect", lambda: execute_national_collect(sess))
    isolated("cityLordCollect", lambda: execute_city_lord_collect(sess))
    selected_ids = settings.get("generalVisitGeneralIds")
    if not isinstance(selected_ids, (list, tuple)):
        selected_ids = []
    isolated("generalVisit", lambda: execute_general_visit(sess, list(selected_ids)))
    return results


def execute_scheduled_daily_tasks_once(sess: dict[str, Any], settings: dict[str, Any]) -> dict[str, Any]:
    """Run daily automation only once after login or after the local date changes."""
    today = time.strftime("%Y-%m-%d", time.localtime())
    if str(sess.get("dailyAutomationAttemptDate") or "") == today:
        return {}
    # Mark before network I/O so a timeout cannot create a retry loop.
    sess["dailyAutomationAttemptDate"] = today
    persist_runtime_state()
    return execute_daily_once_tasks(sess, settings)


def newly_enabled_daily_task_settings(
    old_config: dict[str, Any] | None,
    new_config: dict[str, Any] | None,
) -> dict[str, Any]:
    """Return only daily task keys that flipped from off to on in this save."""
    old_cfg = old_config if isinstance(old_config, dict) else {}
    new_cfg = new_config if isinstance(new_config, dict) else {}
    old_daily = old_cfg.get("dailyTasks") if isinstance(old_cfg.get("dailyTasks"), dict) else {}
    new_daily = new_cfg.get("dailyTasks") if isinstance(new_cfg.get("dailyTasks"), dict) else {}
    enabled: dict[str, Any] = {
        key: True
        for key in DAILY_TASK_NAMES
        if bool(new_daily.get(key)) and not bool(old_daily.get(key))
    }
    if not enabled:
        return {}
    if enabled.get("generalVisit"):
        enabled["generalVisitGeneralIds"] = normalize_general_visit_ids(
            new_cfg.get("generalVisitGeneralIds")
        )
    return enabled


def execute_newly_enabled_daily_tasks_on_save(
    sess: dict[str, Any],
    old_config: dict[str, Any] | None,
    new_config: dict[str, Any] | None,
) -> dict[str, Any]:
    """补跑本次保存里新开启的日常项，不重跑原本已开启的项。

    登录/跨日仍走 execute_scheduled_daily_tasks_once（一日一次）。
    这里故意不碰 dailyAutomationAttemptDate：只补用户刚打开的开关。
    """
    settings = newly_enabled_daily_task_settings(old_config, new_config)
    if not settings:
        return {}
    sid = str(sess.get("sessionId") or "")
    labels = "、".join(
        DAILY_TASK_NAMES[key]
        for key in DAILY_TASK_NAMES
        if settings.get(key)
    )
    reason = account_state_block_reason(sid) if sid else "账号 session 无效"
    if reason:
        try:
            account_log(
                sid,
                f"日常设置新开启{labels}，但账号当前不可执行：{reason}",
                level="warning",
                source="automation",
            )
        except Exception:
            pass
        return {"skipped": True, "reason": reason, "enabledKeys": [
            key for key in DAILY_TASK_NAMES if settings.get(key)
        ]}
    try:
        account_log(
            sid,
            f"日常设置新开启{labels}，立即补跑本次新开项",
            source="automation",
        )
    except Exception:
        pass
    return execute_daily_once_tasks(sess, settings)


def execute_arena_automation_after_22_boundary(sess: dict[str, Any]) -> bool:
    cycle = arena_coins_cycle_date()
    if str(sess.get("arenaAutomationAttemptCycle") or "") == cycle:
        return False
    sess["arenaAutomationAttemptCycle"] = cycle
    settings = dict((SAVED_CONFIGS.get(str(sess.get("sessionId") or "")) or {}).get("dailyTasks") or {})
    if bool(settings.get("arenaCoins")):
        execute_daily_once_tasks(sess, {"arenaCoins": True})
    persist_runtime_state()
    return True


def country_donation_limits(sess: dict[str, Any]) -> dict[str, int]:
    level = int((sess.get("role") or {}).get("level") or (sess.get("roleState") or {}).get("level") or 0)
    if level <= 0:
        raise RuntimeError("无法读取当前角色等级，不能计算最高捐献额")
    return {
        "level": level,
        "copper": level * 1000,
        "food": level * 3000,
    }


def build_fief_query_payload(fief_id: int, mode: int = 0) -> bytes:
    return struct.pack(">Bq", int(mode), int(fief_id))


def build_building_action_payload(fief_id: int, slot: int, building_type: int, action: int = 0) -> bytes:
    if not (0 <= int(slot) <= 0xFFFF and 0 <= int(building_type) <= 0xFFFF):
        raise RuntimeError("建筑槽位或类型超出范围")
    return struct.pack(">BqHH", int(action), int(fief_id), int(slot), int(building_type))


def build_technology_upgrade_payload(
    fief_id: int, academy_slot: int, technology_id: int, target_level: int,
    mode: int = 0, use_gold: int = 0,
) -> bytes:
    return struct.pack(
        ">qBHBBB", int(fief_id), int(academy_slot), int(technology_id),
        int(target_level), int(mode), int(use_gold),
    )


def parse_building_list(payload: bytes, offset: int) -> tuple[list[dict[str, Any]], int]:
    if offset < 0 or offset >= len(payload):
        raise RuntimeError("建筑列表偏移无效")
    count = payload[offset]
    if count > 32:
        raise RuntimeError(f"建筑数量异常：{count}")
    p = offset + 1
    buildings: list[dict[str, Any]] = []
    for index in range(count):
        if p + 28 > len(payload):
            raise RuntimeError(f"第 {index + 1} 条建筑记录不完整")
        slot = payload[p]
        instance_id = struct.unpack(">q", payload[p + 1:p + 9])[0]
        building_type = struct.unpack(">b", payload[p + 9:p + 10])[0]
        level = payload[p + 10]
        timer_ms = struct.unpack(">i", payload[p + 11:p + 15])[0]
        progress = struct.unpack(">i", payload[p + 15:p + 19])[0]
        state_sign = struct.unpack(">q", payload[p + 19:p + 27])[0]
        nested_action = payload[p + 27]
        p += 28
        nested: dict[str, Any] = {"action": nested_action}
        if nested_action == 0:
            if p + 8 > len(payload):
                raise RuntimeError("建筑嵌套清理块不完整")
            nested["ownerId"] = struct.unpack(">q", payload[p:p + 8])[0]
            p += 8
        elif nested_action == 1:
            if p + 9 > len(payload):
                raise RuntimeError("建筑嵌套任务头不完整")
            nested["ownerId"] = struct.unpack(">q", payload[p:p + 8])[0]
            task_count = payload[p + 8]
            p += 9
            nested["taskCount"] = task_count
            nested["tasks"] = []
            for _ in range(task_count):
                if p + 32 > len(payload):
                    raise RuntimeError("建筑嵌套任务记录不完整")
                nested["tasks"].append({
                    "taskId": struct.unpack(">q", payload[p:p + 8])[0],
                    "state": payload[p + 8],
                    "targetType": struct.unpack(">H", payload[p + 9:p + 11])[0],
                    "current": struct.unpack(">i", payload[p + 11:p + 15])[0],
                    "target": struct.unpack(">i", payload[p + 15:p + 19])[0],
                    "remainingMs": struct.unpack(">q", payload[p + 19:p + 27])[0],
                    "flag": payload[p + 27],
                    "tickMs": struct.unpack(">i", payload[p + 28:p + 32])[0],
                })
                p += 32
        else:
            raise RuntimeError(f"未知建筑嵌套动作：{nested_action}")
        buildings.append({
            "slot": slot, "instanceId": instance_id, "type": building_type,
            "name": BUILDING_TYPE_NAMES.get(building_type, f"建筑{building_type}"),
            "level": level, "timerMs": timer_ms, "busy": timer_ms > 0,
            "progress": progress, "stateSign": state_sign, "nested": nested,
        })
    return buildings, p


def parse_fief_base_block(payload: bytes, offset: int, end: int) -> dict[str, Any]:
    p = offset

    def take(size: int) -> bytes:
        nonlocal p
        if p + size > end:
            raise RuntimeError("封地基础状态不完整")
        value = payload[p:p + size]
        p += size
        return value

    flag1 = take(1)[0]
    flag2 = take(1)[0]
    name, p = read_utf(payload, p)
    if p > end:
        raise RuntimeError("封地名称越界")
    base = {
        "flag1": flag1,
        "flag2": flag2,
        "fiefName": name,
        "longValue": struct.unpack(">q", take(8))[0],
        "intValue1": struct.unpack(">i", take(4))[0],
        "intValue2": struct.unpack(">i", take(4))[0],
        "shortValue1": struct.unpack(">h", take(2))[0],
        "shortValue2": struct.unpack(">h", take(2))[0],
        "baseBuildQueueCapacity": take(1)[0],
        "shortValue3": struct.unpack(">h", take(2))[0],
        "shortValue4": struct.unpack(">h", take(2))[0],
        "flag3": take(1)[0],
    }

    def parse_buff_group() -> list[dict[str, int]]:
        rows = []
        for _ in range(take(1)[0]):
            rows.append({
                "value": take(1)[0],
                "remainingMs": struct.unpack(">q", take(8))[0],
                "type": take(1)[0],
            })
        return rows

    base["copperBoosts"] = parse_buff_group()
    base["grainBoosts"] = parse_buff_group()
    queue_boosts = parse_buff_group()
    base["buildQueueBoosts"] = queue_boosts

    def consume_byte_int_rows() -> list[dict[str, int]]:
        return [
            {"type": take(1)[0], "value": struct.unpack(">i", take(4))[0]}
            for _ in range(take(1)[0])
        ]

    base["list1"] = consume_byte_int_rows()
    base["list2"] = consume_byte_int_rows()
    if p != end:
        raise RuntimeError(f"封地基础状态有未解析尾部：{end - p}B")
    active_capacities = [
        int(row["value"]) for row in queue_boosts
        if int(row.get("remainingMs") or 0) > 0 and int(row.get("value") or 0) > 0
    ]
    base["buildQueueCapacity"] = (
        active_capacities[0] if active_capacities
        else max(1, int(base["baseBuildQueueCapacity"] or 2))
    )
    base["buildQueueRemainingMs"] = max(
        (int(row.get("remainingMs") or 0) for row in queue_boosts),
        default=0,
    )
    return base


def parse_8200_building_result(payload: bytes) -> dict[str, Any]:
    if len(payload) < 11:
        raise RuntimeError("0x8200 建筑响应过短")
    status = struct.unpack(">b", payload[:1])[0]
    substatus = struct.unpack(">b", payload[1:2])[0]
    fief_id = struct.unpack(">q", payload[2:10])[0]
    buildings, end = parse_building_list(payload, 10)
    if end != len(payload):
        raise RuntimeError(f"0x8200 建筑响应有未解析尾部：{len(payload) - end}B")
    return {
        "success": status == 0 and substatus == 0, "status": status,
        "substatus": substatus, "fiefId": fief_id, "buildings": buildings,
    }


def parse_8246_fief_result(payload: bytes, expected_fief_id: int | None = None) -> dict[str, Any]:
    if len(payload) < 12:
        raise RuntimeError("0x8246 封地响应过短")
    status = struct.unpack(">b", payload[:1])[0]
    fief_id = struct.unpack(">q", payload[1:9])[0]
    if expected_fief_id is not None and fief_id != int(expected_fief_id):
        raise RuntimeError(f"0x8246 封地不匹配：期望{expected_fief_id}，实际{fief_id}")
    candidates = []
    for offset in range(9, len(payload)):
        if payload[offset] > 16:
            continue
        try:
            buildings, end = parse_building_list(payload, offset)
        except Exception:
            continue
        slots = [int(item["slot"]) for item in buildings]
        if end == len(payload) and len(slots) == len(set(slots)) and all(slot <= 31 for slot in slots):
            if all(int(item["type"]) in BUILDING_TYPE_NAMES for item in buildings):
                try:
                    base = parse_fief_base_block(payload, 9, offset)
                except Exception:
                    continue
                candidates.append((offset, buildings, base))
    if len(candidates) != 1:
        raise RuntimeError(f"0x8246 建筑列表定位不唯一：候选{len(candidates)}个")
    offset, buildings, base = candidates[0]
    return {
        "success": status == 0, "status": status, "fiefId": fief_id,
        "buildingOffset": offset, "buildings": buildings, **base,
    }


def parse_technology_states_from_8004(payload: bytes) -> list[dict[str, Any]]:
    """Locate the verified 22-entry technology table in a role-state payload."""
    candidates: list[list[dict[str, Any]]] = []
    count = 22
    record_size = 27
    for offset in range(0, max(0, len(payload) - count * record_size + 1)):
        if any(payload[offset + index * record_size] != index for index in range(count)):
            continue
        rows = []
        plausible = True
        for index in range(count):
            p = offset + index * record_size
            level = payload[p + 1]
            state = payload[p + 2]
            fief_id = struct.unpack(">q", payload[p + 3:p + 11])[0]
            academy_id = struct.unpack(">q", payload[p + 11:p + 19])[0]
            deadline_ms = struct.unpack(">q", payload[p + 19:p + 27])[0]
            if level > 15 or state > 10:
                plausible = False
                break
            rows.append({
                "technologyId": index,
                "name": TECHNOLOGY_NAMES.get(index, f"科技{index}"),
                "level": level,
                "state": state,
                "researching": fief_id >= 0 and academy_id >= 0 and deadline_ms > 0,
                "fiefId": None if fief_id < 0 else fief_id,
                "academyInstanceId": None if academy_id < 0 else academy_id,
                "deadlineMs": deadline_ms,
                "offset": p,
            })
        if plausible:
            candidates.append(rows)
    if len(candidates) != 1:
        raise RuntimeError(f"0x8004 科技状态表定位不唯一：候选{len(candidates)}个")
    return candidates[0]


def current_technology_states(sess: dict[str, Any]) -> list[dict[str, Any]]:
    payload_hex = str(sess.get("state8004PayloadHex") or "")
    if not payload_hex:
        raise RuntimeError("当前账号没有可用的 0x8004 科技状态")
    states = parse_technology_states_from_8004(bytes.fromhex(payload_hex))
    sess["technologyStates"] = states
    return states


def owned_fief_ids(sess: dict[str, Any]) -> list[int]:
    ids: list[int] = []
    for general in sess.get("generals") or []:
        try:
            value = int(general.get("fiefId") or general.get("placeID") or 0)
        except (TypeError, ValueError):
            continue
        if value > 0 and value not in ids:
            ids.append(value)
    return ids


def query_all_owned_fief_ids(sess: dict[str, Any]) -> list[int]:
    ids = owned_fief_ids(sess)
    fief_names: dict[int, str] = {}
    role_name = str(
        (sess.get("roleState") or {}).get("roleName")
        or (sess.get("role") or {}).get("roleName")
        or ""
    ).strip()
    if role_name:
        own_fiefs = query_raid_fiefs(sess, role_name)
        for fief in own_fiefs.get("fiefs") or []:
            try:
                fief_id = int(fief.get("targetId") or 0)
            except (TypeError, ValueError):
                continue
            fief_name = str(fief.get("fiefName") or fief.get("name") or "").strip()
            if fief_id > 0 and fief_name:
                fief_names[fief_id] = fief_name
            if fief_id > 0 and fief_id not in ids:
                ids.append(fief_id)
    sess["ownedFiefNames"] = {str(key): value for key, value in fief_names.items()}
    enrich_generals_with_fief_names(sess)
    return ids


def fief_display_name(sess: dict[str, Any], fief_id: int) -> str:
    name = str((sess.get("ownedFiefNames") or {}).get(str(int(fief_id))) or "").strip()
    return f"{name}（ID {int(fief_id)}）" if name else f"封地ID {int(fief_id)}"


def query_fief_buildings(sess: dict[str, Any], fief_id: int) -> dict[str, Any]:
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1246, build_fief_query_payload(fief_id))], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((packet for packet in packets if packet.get("opcode") == 0x8246), None)
    if code != 200 or not response:
        raise RuntimeError("读取封地建筑未收到 0x8246")
    return {
        **parse_8246_fief_result(response["payload"], fief_id),
        "fiefName": (sess.get("ownedFiefNames") or {}).get(str(int(fief_id)), ""),
        "http": code,
    }


def summarize_role_queues(
    fief_states: list[dict[str, Any]],
    technology_states: list[dict[str, Any]],
) -> dict[str, Any]:
    """Build the two queue totals shown by the original role trends page."""
    building_current = 0
    building_capacity = 0
    research_capacity = 0
    for state in fief_states:
        busy, capacity = fief_build_queue_state(state)
        building_current += busy
        building_capacity += capacity
        research_capacity += sum(
            1
            for building in state.get("buildings") or []
            if int(building.get("type", -1)) == 3
        )
    research_current = sum(
        1 for technology in technology_states if technology.get("researching")
    )
    return {
        "buildingQueue": {
            "current": building_current,
            "capacity": building_capacity,
        },
        "researchQueue": {
            "current": research_current,
            "capacity": research_capacity,
        },
        "fiefCount": len(fief_states),
        "updatedAt": now_ms(),
        "source": "0x1246/0x8246+0x1016/0x8004",
    }


def refresh_role_queue_summary(sess: dict[str, Any]) -> dict[str, Any]:
    fief_ids = query_all_owned_fief_ids(sess)
    fief_states = [query_fief_buildings(sess, fief_id) for fief_id in fief_ids]
    technology_states = current_technology_states(sess)
    summary = summarize_role_queues(fief_states, technology_states)
    sess["roleQueueSummary"] = summary
    sess.pop("roleQueueSummaryError", None)
    return summary


def building_action_was_applied(
    buildings: list[dict[str, Any]], slot: int, building_type: int,
    previous_level: int | None,
) -> bool:
    building = next((item for item in buildings if int(item.get("slot", -1)) == int(slot)), None)
    if not building or int(building.get("type", -1)) != int(building_type):
        return False
    if previous_level is None:
        return True
    return int(building.get("level", 0)) > int(previous_level) or bool(building.get("busy"))


def execute_building_action(
    sess: dict[str, Any], fief_id: int, slot: int, building_type: int,
    previous_level: int | None = None,
) -> dict[str, Any]:
    payload = build_building_action_payload(fief_id, slot, building_type)
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1200, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((packet for packet in packets if packet.get("opcode") == 0x8200), None)
    if code != 200 or not response:
        return {"success": False, "message": "建筑操作未收到 0x8200", "http": code}
    result = {**parse_8200_building_result(response["payload"]), "http": code, "payloadHex": payload.hex()}
    if building_action_was_applied(result.get("buildings") or [], slot, building_type, previous_level):
        return {**result, "success": True, "confirmedBy": "0x8200建筑同步"}
    try:
        checked = query_fief_buildings(sess, fief_id)
        applied = building_action_was_applied(
            checked.get("buildings") or [], slot, building_type, previous_level,
        )
        return {
            **result, "success": applied,
            "confirmedBy": "提交后复查" if applied else "",
            "checkedBuildings": checked.get("buildings") or [],
        }
    except Exception as exc:
        return {**result, "success": False, "verifyError": str(exc)}


def execute_cancel_building_action(
    sess: dict[str, Any], fief_id: int, slot: int, building_type: int,
) -> dict[str, Any]:
    """Captured 0x1200 action=2: cancel one current build/upgrade task."""
    payload = build_building_action_payload(
        fief_id, slot, building_type, action=2,
    )
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1200, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next(
        (packet for packet in packets if packet_opcode(packet) == 0x8200),
        None,
    )
    parsed = (
        parse_8200_building_result(packet_payload_bytes(response))
        if response else
        {"success": False, "message": "取消建筑任务未收到0x8200"}
    )
    checked = query_fief_buildings(sess, fief_id) if response else {}
    building = next((
        row for row in checked.get("buildings") or []
        if int(row.get("slot", -1)) == int(slot)
        and int(row.get("type", -1)) == int(building_type)
    ), None)
    cancelled = bool(building) and not bool(building.get("busy"))
    return {
        **parsed,
        "success": cancelled,
        "message": (
            "已取消建筑升级，为重步兵招募腾出兵营"
            if cancelled else
            str(parsed.get("message") or "建筑升级取消后仍未确认空闲")
        ),
        "fiefId": int(fief_id),
        "slot": int(slot),
        "buildingType": int(building_type),
        "http": code,
        "payloadHex": payload.hex(),
        "checkedBuilding": building,
        "packets": summarize_packets(packets),
    }


def execute_demolish_building_action(
    sess: dict[str, Any], fief_id: int, slot: int, building_type: int,
) -> dict[str, Any]:
    """Captured 0x1200 action=1: demolish one existing building."""
    payload = build_building_action_payload(
        fief_id, slot, building_type, action=1,
    )
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1200, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next(
        (packet for packet in packets if packet_opcode(packet) == 0x8200),
        None,
    )
    parsed = (
        parse_8200_building_result(packet_payload_bytes(response))
        if response else
        {"success": False, "message": "拆除建筑未收到0x8200"}
    )
    checked: dict[str, Any] = {}
    remaining: dict[str, Any] | None = None
    demolished = False
    verify_error = ""
    for attempt in range(3):
        try:
            checked = query_fief_buildings(sess, fief_id)
            remaining = next((
                row for row in checked.get("buildings") or []
                if int(row.get("slot", -1)) == int(slot)
            ), None)
            demolished = (
                remaining is None
                or int(remaining.get("type", -1)) != int(building_type)
            )
            if demolished:
                break
        except Exception as exc:
            verify_error = str(exc)
        if attempt < 2:
            time.sleep(0.5)
    return {
        **parsed,
        "success": demolished,
        "message": (
            f"已拆除第{int(slot)}槽{BUILDING_TYPE_NAMES.get(int(building_type), '建筑')}"
            if demolished else
            f"第{int(slot)}槽建筑拆除尚未确认"
        ),
        "fiefId": int(fief_id),
        "slot": int(slot),
        "buildingType": int(building_type),
        "http": code,
        "payloadHex": payload.hex(),
        "checkedBuilding": remaining,
        "verifyError": verify_error,
        "confirmedBy": "提交后封地复查" if demolished else "",
        "packets": summarize_packets(packets),
    }


def execute_technology_upgrade(
    sess: dict[str, Any], fief_id: int, academy_slot: int,
    technology_id: int, target_level: int,
) -> dict[str, Any]:
    payload = build_technology_upgrade_payload(fief_id, academy_slot, technology_id, target_level)
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x123F, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((packet for packet in packets if packet.get("opcode") == 0x823F), None)
    parsed = parse_status_message_payload(response["payload"]) if response else {
        "success": False, "status": None, "message": "科技升级未收到 0x823f",
    }
    return {**parsed, "http": code, "payloadHex": payload.hex()}


def build_country_donation_payload(*, copper: int = 0, food: int = 0, technology: int = 0) -> bytes:
    values = [int(copper), int(food), int(technology)]
    if sum(value > 0 for value in values) != 1:
        raise RuntimeError("每次国家捐献必须且只能指定一种资源")
    if any(value < 0 for value in values):
        raise RuntimeError("国家捐献数量不能为负数")
    return struct.pack(">qqq", *values)


def build_technology_donation_payload(amount: int) -> bytes:
    """0x140a payload: mode byte 0 + signed int amount."""
    value = int(amount)
    if value <= 0:
        raise RuntimeError("科技积分捐献数量必须大于0")
    return struct.pack(">Bi", 0, value)


def execute_country_donation(
    sess: dict[str, Any],
    *,
    resource: str,
    amount: int,
) -> dict[str, Any]:
    key = str(resource or "")
    if key not in {"copper", "food", "technology"}:
        raise RuntimeError(f"当前不支持捐献资源：{resource}")
    payload = (
        build_technology_donation_payload(int(amount))
        if key == "technology"
        else build_country_donation_payload(**{key: int(amount)})
    )
    opcode = 0x140A if key == "technology" else 0x140C
    response_opcode = 0x840A if key == "technology" else 0x840C
    code, data, packets = post_game(
        sess["gameHttp"],
        [(opcode, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((packet for packet in packets if packet.get("opcode") == response_opcode), None)
    response_payload = response.get("payload") if response else b""
    # Donation replies are role-state packets whose leading status byte is 0
    # on the captured successful path.  Presence alone is not enough when the
    # game returns a business rejection with the same response opcode.
    confirmed = bool(response is not None and response_payload and response_payload[0] == 0)
    label = {"copper": "铜钱", "food": "粮食", "technology": "科技积分"}[key]
    return {
        "success": code == 200 and confirmed,
        "resource": key,
        "amount": int(amount),
        "http": code,
        "opcode": f"0x{opcode:04x}/0x{response_opcode:04x}",
        "payloadHex": payload.hex(),
        "message": (
            f"已按最高额度捐献{label}{amount}"
            if confirmed
            else f"未确认{label}捐献成功（响应状态={response_payload[0] if response_payload else '无'}）"
        ),
        "packets": summarize_packets(packets),
    }


def execute_daily_country_donations(sess: dict[str, Any]) -> dict[str, Any]:
    """Attempt all three donation endpoints; one rejection never skips siblings."""
    limits = country_donation_limits(sess)
    limits["technology"] = int(limits.get("level") or 0) * 1000
    specs = (
        ("copper", limits["copper"]),
        ("food", limits["food"]),
        ("technology", limits["technology"]),
    )
    actions: list[dict[str, Any]] = []
    for resource, amount in specs:
        try:
            action = execute_country_donation(sess, resource=resource, amount=amount)
        except GameServerRejected:
            raise
        except Exception as exc:
            action = {
                "success": False,
                "resource": resource,
                "amount": int(amount),
                "message": str(exc) or "捐献请求异常",
                "exception": type(exc).__name__,
            }
        actions.append(action)
    success_count = sum(1 for action in actions if action.get("success"))
    failed = [action for action in actions if not action.get("success")]
    labels = {"copper": "铜钱", "food": "粮食", "technology": "科技积分"}
    summary = "、".join(
        f"{labels.get(str(action.get('resource')), action.get('resource'))}{'成功' if action.get('success') else '失败'}"
        for action in actions
    )
    return {
        "success": success_count == len(specs),
        "partialSuccess": 0 < success_count < len(specs),
        # Do not persist a daily-completion marker after a partial or wholly
        # failed three-endpoint donation.  This keeps a transient failure
        # retryable and makes the warning visible instead of silently hiding
        # an unfinished resource donation.
        "completed": success_count == len(specs),
        "attemptedCount": len(actions),
        "successCount": success_count,
        "failureCount": len(failed),
        "message": f"自动捐献完成：{summary}",
        "limits": limits,
        "actions": actions,
    }


def execute_max_country_donations(sess: dict[str, Any]) -> dict[str, Any]:
    """Legacy/manual path kept compatible with the old resource preflight.

    The scheduled daily task uses execute_daily_country_donations(), which
    deliberately attempts all three endpoints independently.  Manual callers
    retain the old no-spend-on-known-shortage behavior.
    """
    refresh_generals(sess)
    limits = country_donation_limits(sess)
    role_state = sess.get("roleState") or {}
    available_copper = int(role_state.get("copper") or 0)
    available_food = int(role_state.get("food") or 0)
    if available_copper < limits["copper"]:
        return {
            "success": False,
            "message": f"铜钱不足最高捐献额：当前{available_copper}，需要{limits['copper']}；本次未捐献",
            "limits": limits,
            "actions": [],
        }
    if available_food < limits["food"]:
        return {
            "success": False,
            "message": f"粮食不足最高捐献额：当前{available_food}，需要{limits['food']}；本次未捐献",
            "limits": limits,
            "actions": [],
        }
    actions = [
        execute_country_donation(sess, resource="copper", amount=limits["copper"]),
    ]
    if not actions[-1].get("success"):
        return {"success": False, "message": actions[-1].get("message"), "limits": limits, "actions": actions}
    time.sleep(1.0)
    actions.append(execute_country_donation(sess, resource="food", amount=limits["food"]))
    success = all(action.get("success") for action in actions)
    return {
        "success": success,
        "message": (
            f"自动捐献完成：{limits['copper']}铜钱、{limits['food']}粮食"
            if success else actions[-1].get("message") or "自动捐献失败"
        ),
        "limits": limits,
        "actions": actions,
    }


def query_hubu_plant_state(sess: dict[str, Any]) -> dict[str, Any]:
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x6320, b"")],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    responses = [p for p in packets if p.get("opcode") == 0xE320]
    return {
        "http": code,
        "success": bool(responses),
        "responseBytes": len(data),
        "packets": summarize_packets(packets),
        "payloadHexes": [p["payload"].hex() for p in responses],
    }


def execute_hubu_batch_plant(sess: dict[str, Any], *, confirm: str = "") -> dict[str, Any]:
    if confirm != "hubu-batch-plant":
        raise RuntimeError("真实批量种菜需要 confirm=hubu-batch-plant")
    # Exact payload observed repeatedly in the 20260711 original-client capture.
    payload = b"\x01\x00\x00\x00\x01"
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x6328, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == 0xE328), None)
    parsed = parse_status_message_payload(response["payload"]) if response else {
        "success": False,
        "status": None,
        "message": "未收到 0xe328 批量种菜响应",
    }
    result = {
        **parsed,
        "http": code,
        "payloadHex": payload.hex(),
        "responseBytes": len(data),
        "packets": summarize_packets(packets),
    }
    if result.get("success"):
        record_success_action(
            str(sess.get("sessionId") or ""),
            "六部",
            f"种菜 > {result.get('message') or '批量种菜成功'}",
            detail=result,
        )
    return result


def refresh_daily_activity(sess: dict[str, Any]) -> dict[str, Any]:
    """Refresh 0x6200/0xe200 daily activity/task progress for user-facing role stats."""
    # This endpoint is intentionally attempted at most once per login/day. Record the
    # attempt before network I/O so a transient failure cannot turn heartbeat into a
    # repeated 0x6200 request loop.
    sess["dailyActivityDate"] = time.strftime("%Y-%m-%d", time.localtime())
    persist_runtime_state()
    try:
        code, data, packets = post_game(sess["gameHttp"], [(0x6200, b"")], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
        e200_packets = [p for p in packets if p.get("opcode") == 0xE200 and "payload" in p]
        if not e200_packets:
            raise RuntimeError("日常进度未返回 0xe200：" + json.dumps(summarize_packets(packets), ensure_ascii=False)[:500])
        merged: dict[str, Any] = {
            "sourceOpcode": "live/0x6200/0xe200",
            "updatedAt": now_ms(),
            "http": code,
            "treasureOccupied": {},
            "tasks": [],
        }
        for pkt in e200_packets:
            parsed = parse_e200_daily_activity(pkt["payload"], "live/0x6200/0xe200")
            merged["tasks"].extend(parsed.get("tasks") or [])
            if parsed.get("treasureOccupied"):
                merged["treasureOccupied"] = parsed["treasureOccupied"]
        sess["dailyActivity"] = merged
        persist_runtime_state()
        return merged
    except Exception as e:
        existing = sess.get("dailyActivity") or {}
        existing.update({
            "sourceOpcode": "live/0x6200/0xe200",
            "updatedAt": now_ms(),
            "parseError": str(e),
        })
        sess["dailyActivity"] = existing
        persist_runtime_state()
        return existing


def query_starter_reward_sources(sess: dict[str, Any]) -> dict[str, Any]:
    """Read the three reward sources needed by starter mode without claiming anything."""
    requests = (
        ("growthTasks", 0x1130, b"\x00", 0x8130),
        ("dailyTasks", 0x6200, b"", 0xE200),
        ("activities", 0x3940, b"", 0xA940),
    )
    result: dict[str, Any] = {"updatedAt": now_ms(), "sources": {}}
    sid = str(sess.get("sessionId") or "")
    for key, opcode, payload, response_opcode in requests:
        source: dict[str, Any] = {
            "requestOpcode": f"0x{opcode:04x}",
            "responseOpcode": f"0x{response_opcode:04x}",
        }
        try:
            code, data, packets = post_game(
                sess["gameHttp"], [(opcode, payload)], int(sess["dm"]),
                account_id=sid,
            )
            responses = [
                packet for packet in packets
                if int(packet.get("opcode") or -1) == response_opcode
            ]
            source.update({
                "success": bool(responses),
                "http": code,
                "responseBytes": len(data),
                "packets": summarize_packets(packets),
                "responses": [{
                    "payloadHex": (packet.get("payload") or b"").hex(),
                    "textFields": [
                        field.get("text") for field in
                        extract_utf_fields(packet.get("payload") or b"", min_len=1, max_len=220)
                    ],
                    "entries": (
                        parse_reward_catalog_entries(packet.get("payload") or b"")
                        if key in {"growthTasks", "activities"} else []
                    ),
                } for packet in responses],
            })
            if key == "dailyTasks" and responses:
                merged = {"tasks": [], "updatedAt": now_ms(), "sourceOpcode": "live/0x6200/0xe200"}
                for packet in responses:
                    parsed = parse_e200_daily_activity(packet.get("payload") or b"")
                    merged["tasks"].extend(parsed.get("tasks") or [])
                sess["dailyActivity"] = merged
        except Exception as exc:
            source.update({"success": False, "error": str(exc)})
        result["sources"][key] = source
        time.sleep(0.35)
    sess["starterRewardSources"] = result
    persist_runtime_state()
    return result


def parse_reward_catalog_entries(payload: bytes) -> list[dict[str, Any]]:
    """Recover id/title/state tuples shared by 0x8130 and 0xa940 catalogs.

    Both catalogs place an i64 id immediately before the title UTF. 0x8130
    additionally places a one-byte state after the title; 0xa940 places an
    image URL there instead. Keeping the raw state lets us calibrate claim
    eligibility without guessing and accidentally claiming the wrong entry.
    """
    entries: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    for field in extract_utf_fields(payload, min_len=2, max_len=220):
        title = str(field.get("text") or "")
        offset = int(field.get("offset") or 0)
        if offset < 8 or not any("\u4e00" <= char <= "\u9fff" for char in title):
            continue
        item_id = int.from_bytes(payload[offset - 8:offset], "big")
        if item_id <= 0:
            continue
        key = (offset, item_id)
        if key in seen:
            continue
        seen.add(key)
        end = offset + 2 + int(field.get("length") or 0)
        state = payload[end] if end < len(payload) else None
        entries.append({
            "id": item_id,
            "idHex": f"{item_id:016x}",
            "title": title,
            "stateByte": state,
            "offset": offset,
        })
    return entries


def query_starter_activity_details(
    sess: dict[str, Any],
    activity_ids: list[Any],
) -> dict[str, Any]:
    """Read 0x3941 details for catalog IDs; this endpoint never claims rewards."""
    ids: list[int] = []
    for value in activity_ids[:30]:
        try:
            item_id = int(str(value), 0)
        except ValueError:
            try:
                item_id = int(str(value), 16)
            except ValueError:
                continue
        if item_id > 0 and item_id not in ids:
            ids.append(item_id)
    sid = str(sess.get("sessionId") or "")
    details: list[dict[str, Any]] = []
    for item_id in ids:
        detail: dict[str, Any] = {"id": item_id, "idHex": f"{item_id:016x}"}
        try:
            code, data, packets = post_game(
                sess["gameHttp"],
                [(0x3941, struct.pack(">q", item_id))],
                int(sess["dm"]),
                account_id=sid,
            )
            responses = [
                packet for packet in packets
                if int(packet.get("opcode") or -1) == 0xA941
            ]
            detail.update({
                "success": bool(responses),
                "http": code,
                "responseBytes": len(data),
                "packets": summarize_packets(packets),
                "responses": [{
                    "payloadHex": (packet.get("payload") or b"").hex(),
                    "textFields": [
                        field.get("text") for field in extract_utf_fields(
                            packet.get("payload") or b"", min_len=1, max_len=500,
                        )
                    ],
                    "textPreview": printable(packet.get("payload") or b"", 4000),
                } for packet in responses],
            })
        except Exception as exc:
            detail.update({"success": False, "error": str(exc)})
        details.append(detail)
        time.sleep(0.3)
    result = {"updatedAt": now_ms(), "details": details}
    sess["starterActivityDetails"] = result
    persist_runtime_state()
    return result


def query_starter_growth_task_details(
    sess: dict[str, Any],
    task_ids: list[Any],
    *,
    group: int = 0,
) -> dict[str, Any]:
    """Read 0x1132 task details without performing the 0x1134 claim."""
    ids: list[int] = []
    for value in task_ids[:30]:
        try:
            item_id = int(str(value), 0)
        except ValueError:
            try:
                item_id = int(str(value), 16)
            except ValueError:
                continue
        if item_id > 0 and item_id not in ids:
            ids.append(item_id)
    group = max(0, min(255, int(group or 0)))
    sid = str(sess.get("sessionId") or "")
    details: list[dict[str, Any]] = []
    for item_id in ids:
        detail: dict[str, Any] = {
            "group": group, "id": item_id, "idHex": f"{item_id:016x}",
        }
        try:
            code, data, packets = post_game(
                sess["gameHttp"],
                [(0x1132, struct.pack(">Bq", group, item_id))],
                int(sess["dm"]),
                account_id=sid,
            )
            responses = [
                packet for packet in packets
                if int(packet.get("opcode") or -1) == 0x8132
            ]
            detail.update({
                "success": bool(responses),
                "http": code,
                "responseBytes": len(data),
                "packets": summarize_packets(packets),
                "responses": [{
                    "payloadHex": (packet.get("payload") or b"").hex(),
                    "tailHex": (packet.get("payload") or b"")[-32:].hex(),
                    "textFields": [
                        field.get("text") for field in extract_utf_fields(
                            packet.get("payload") or b"", min_len=1, max_len=500,
                        )
                    ],
                    "textPreview": printable(packet.get("payload") or b"", 4000),
                } for packet in responses],
            })
        except Exception as exc:
            detail.update({"success": False, "error": str(exc)})
        details.append(detail)
        time.sleep(0.25)
    result = {"updatedAt": now_ms(), "group": group, "details": details}
    sess["starterGrowthTaskDetails"] = result
    persist_runtime_state()
    return result


STARTER_RECRUIT_KIND_NAMES = {
    0: "勇士",
    1: "步将",
    2: "骑将",
    3: "弓将",
    4: "智将",
}


def parse_starter_recruit_candidates(payload: bytes) -> list[dict[str, Any]]:
    """Parse captured 0x821b candidate rows.

    Row layout confirmed by the 2026-07-19 full capture:
    i64 candidateId + UTF name + i32 portrait + i16 portraitVariant +
    u8 profession + i16 growth + i16 attack + i16 intelligence + i16 command.
    """
    rows: list[dict[str, Any]] = []
    offset = 0
    while offset + 27 <= len(payload):
        candidate_id = struct.unpack(">q", payload[offset:offset + 8])[0]
        name_len = struct.unpack(">H", payload[offset + 8:offset + 10])[0]
        end = offset + 10 + name_len
        if not (1_000_000 <= candidate_id <= 1_000_000_000 and 2 <= name_len <= 30 and end + 15 <= len(payload)):
            offset += 1
            continue
        try:
            name = payload[offset + 10:end].decode("utf-8")
        except UnicodeDecodeError:
            offset += 1
            continue
        portrait = struct.unpack(">I", payload[end:end + 4])[0]
        portrait_variant = struct.unpack(">H", payload[end + 4:end + 6])[0]
        profession = int(payload[end + 6])
        growth, attack, intelligence, command = struct.unpack(
            ">HHHH", payload[end + 7:end + 15],
        )
        if not (0 < growth <= 200 and all(0 <= value <= 500 for value in (attack, intelligence, command))):
            offset += 1
            continue
        rows.append({
            "id": candidate_id,
            "idHex": f"{candidate_id:016x}",
            "name": name,
            "portrait": portrait,
            "portraitVariant": portrait_variant,
            "professionCode": profession,
            "kind": STARTER_RECRUIT_KIND_NAMES.get(profession, f"类型{profession}"),
            "growth": growth,
            "quality": "普通",
            "attack": attack,
            "intelligence": intelligence,
            "command": command,
        })
        offset = end + 15
    return rows[:6]

def starter_recruit_score(candidate: dict[str, Any], generals: list[dict[str, Any]]) -> tuple[int, int, int]:
    existing_kinds = {str(row.get("kind") or "") for row in generals}
    kind = str(candidate.get("kind") or "")
    # First secure a front-line general, then a bow general.  Vehicle duty is
    # assigned later to the recruited general with the highest command limit.
    role_bonus = 0
    if "步将" not in existing_kinds and kind == "步将":
        role_bonus = 300
    elif "步将" not in existing_kinds and kind == "勇士":
        role_bonus = 240
    elif "弓将" not in existing_kinds and kind == "弓将":
        role_bonus = 200
    return (
        role_bonus + int(candidate.get("growth") or 0),
        int(candidate.get("command") or 0),
        int(candidate.get("attack") or 0),
    )


def query_starter_recruit_list(sess: dict[str, Any]) -> dict[str, Any]:
    """Read the recruit-general window.

    The captured request is 0x121b with one mode byte ``0x00``.  It is not an
    empty-payload command: sending an empty payload makes the game server reply
    with the single rejection byte ``0x01`` instead of a 0x821b list.
    """
    sid = str(sess.get("sessionId") or "")
    game_urls = [str(sess["gameHttp"])]
    last_error: Exception | None = None
    code, data, packets = 0, b"", []
    attempts: list[dict[str, Any]] = []
    for game_url in game_urls:
        try:
            code, data, packets = post_game(
                game_url,
                [(0x121B, b"\x00")],
                int(sess["dm"]),
                account_id=sid,
            )
            attempts.append({
                "url": game_url,
                "http": code,
                "responseBytes": len(data),
                "opcodes": [
                    f"0x{int(packet_opcode(packet) or 0):04x}"
                    for packet in packets if packet_opcode(packet) is not None
                ],
            })
            if any(packet_opcode(packet) == 0x821B for packet in packets):
                break
        except GameProtocolResponseError as exc:
            last_error = exc
            code = int(exc.code or 0)
            data = bytes(exc.data or b"")
            packets = list(exc.packets or [])
            attempts.append({
                "url": game_url,
                "http": code,
                "responseBytes": len(data),
                "opcodes": [
                    f"0x{int(packet_opcode(packet) or 0):04x}"
                    for packet in packets if packet_opcode(packet) is not None
                ],
                "parseErrors": [
                    str(packet.get("parseError") or "")
                    for packet in packets if packet.get("parseError")
                ],
                "rawHexPrefix": data.hex()[:512],
                "error": str(exc),
            })
            if any(packet_opcode(packet) == 0x821B for packet in packets):
                break
            continue
    responses = [
        packet for packet in packets
        if int(packet.get("opcode") or -1) == 0x821B
    ]
    text_fields = [
        field.get("text")
        for packet in responses
        for field in extract_utf_fields(
            packet.get("payload") or b"", min_len=1, max_len=100,
        )
        if str(field.get("text") or "").strip()
    ]
    candidates = [
        row
        for packet in responses
        for row in parse_starter_recruit_candidates(packet.get("payload") or b"")
    ]
    generals = list(sess.get("generals") or [])
    candidates.sort(key=lambda row: starter_recruit_score(row, generals), reverse=True)
    for index, candidate in enumerate(candidates):
        candidate["recommended"] = index == 0
        candidate["score"] = starter_recruit_score(candidate, generals)[0]
    ignored = {"刷新成功", "购买", "皇榜", "招贤金榜", "招贤令"}
    names = [
        str(value).strip() for value in text_fields
        if str(value).strip() not in ignored
        and 2 <= len(str(value).strip()) <= 8
        and not any(ch.isdigit() for ch in str(value))
    ]
    names = list(dict.fromkeys(names))[:6]
    result = {
        "updatedAt": now_ms(),
        "success": bool(responses),
        "source": "live/0x121b" if responses else "live-request-failed",
        "warning": (
            ""
            if responses
            else (
                "游戏服本次未返回实时招将候选，页面已清空旧抓包数据；"
                "请稍后点击刷新重试"
                if data == b"\x01"
                else str(last_error or "游戏服未返回0x821b实时招将列表")
            )
        ),
        "http": code,
        "responseBytes": len(data),
        "generalCount": len(generals),
        "generalLimit": max(
            len(generals),
            int((sess.get("roleState") or {}).get("generalLimit") or 0),
            int((sess.get("role") or {}).get("generalLimit") or 0),
        ),
        "refreshText": (
            "刚刚从服务器刷新" if responses else "实时读取失败"
        ),
        "royalCount": 0,
        "goldListCount": 0,
        "recruitOrderCount": 0,
        "candidates": candidates or [{"name": name} for name in names],
        "textFields": text_fields,
        "packets": summarize_packets(packets),
        "attempts": attempts,
    }
    sess["starterRecruit"] = result
    persist_runtime_state()
    return result


def starter_recruit_general(
    sess: dict[str, Any],
    candidate_id: Any,
    *,
    confirm: str = "",
) -> dict[str, Any]:
    if confirm != "starter-recruit-general":
        raise RuntimeError("招募将领需要明确确认")
    candidate_id = int(str(candidate_id), 0)
    recruit = sess.get("starterRecruit") or {}
    candidate = next((
        row for row in recruit.get("candidates") or []
        if int(row.get("id") or 0) == candidate_id
    ), None)
    if not candidate:
        raise RuntimeError("候选将领不在最近一次招将列表中，请先刷新")
    generals = list(sess.get("generals") or [])
    fief_id = int(
        (generals[0].get("fiefId") if generals else 0)
        or (sess.get("roleState") or {}).get("baseFiefId")
        or 0
    )
    if fief_id <= 0:
        raise RuntimeError("无法识别基地封地ID，已阻止招将")
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x1228, struct.pack(">qq", fief_id, candidate_id))],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    responses = [packet for packet in packets if packet_opcode(packet) == 0x8228]
    success = bool(responses) and not any(
        word in printable(packet_payload_bytes(packet), 300)
        for packet in responses for word in ("失败", "不足", "已满")
    )
    return {
        "success": success,
        "candidate": candidate,
        "fiefId": fief_id,
        "http": code,
        "responseBytes": len(data),
        "packets": summarize_packets(packets),
    }


def build_starter_open_fief_payload(
    city_id: int, *, city_option: int = 0, use_open_order: bool = False,
) -> bytes:
    return struct.pack(
        ">BBqBB",
        0, 0, int(city_id), int(city_option), 1 if use_open_order else 0,
    )


def starter_open_fief(
    sess: dict[str, Any],
    city_id: Any,
    *,
    city_option: Any = 0,
    use_open_order: bool = False,
    confirm: str = "",
) -> dict[str, Any]:
    """Open a fief using captured 0x130b(b,b,q cityId,b option,b order)."""
    if confirm != "starter-open-fief":
        raise RuntimeError("开辟封地需要明确确认")
    city_id = int(str(city_id), 0)
    if not (1 <= city_id <= 1_000_000):
        raise RuntimeError("城池ID不合法")
    city_option = int(city_option or 0)
    if not (0 <= city_option <= 255):
        raise RuntimeError("开辟封地选项不合法")
    payload = build_starter_open_fief_payload(
        city_id, city_option=city_option, use_open_order=use_open_order,
    )
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x130B, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    responses = [packet for packet in packets if packet_opcode(packet) == 0x830B]
    text = " ".join(printable(packet_payload_bytes(packet), 1000) for packet in responses)
    response_payload = packet_payload_bytes(responses[0]) if responses else b""
    status = (
        struct.unpack(">b", response_payload[:1])[0]
        if response_payload else None
    )
    success = (
        bool(responses)
        and status == 0
        and not any(word in text for word in ("失败", "不足", "已满"))
    )
    status_messages = {
        0: "开辟封地成功",
        -1: "指定城池没有空封地",
        -2: "封地数量已达上限",
        -3: "铜钱不足",
        -4: "开辟封地所需资金不足",
        -5: "等待城主任命/城池暂不可申请",
        -11: "缺少开封令",
    }
    return {
        "success": success,
        "status": status,
        "cityId": city_id,
        "cityOption": city_option,
        "useOpenOrder": bool(use_open_order),
        "payloadHex": payload.hex(),
        "message": status_messages.get(status, f"开辟封地申请失败(status={status})"),
        "http": code,
        "responseBytes": len(data),
        "text": text,
        "packets": summarize_packets(packets),
    }


def starter_building_policy_snapshot(sess: dict[str, Any]) -> dict[str, Any]:
    """Expose the five-stage base/vehicle/house-fief layout."""
    cached = sess.get("starterFiefBuildings") or {}
    fiefs = list(
        cached.get("fiefs")
        or
        (sess.get("roleState") or {}).get("fiefs")
        or sess.get("fiefs")
        or []
    )
    priorities: list[dict[str, Any]] = []
    for fief in fiefs:
        name = str(fief.get("name") or fief.get("fiefName") or "")
        fief_id = int(fief.get("id") or fief.get("fiefId") or 0)
        is_base = bool(fief.get("isBase")) or "基地" in name
        buildings = list(fief.get("buildings") or [])
        hall = next((
            row for row in buildings
            if str(row.get("name") or row.get("buildingName") or "") in {"大厅", "官府", "城主府"}
            or int(row.get("type") or row.get("buildingType") or -1) == 0
        ), None)
        priorities.append({
            "fiefId": fief_id,
            "fiefName": name,
            "isBase": is_base,
            "hallLevel": int((hall or {}).get("level") or 0),
            "fiveStageRole": fief.get("fiveStageRole") or (
                "base" if is_base else "extra"
            ),
            "hallPolicy": (
                "never-upgrade"
                if is_base
                or fief.get("fiveStageRole") == "vehicle"
                else "upgrade-first"
            ),
            "fiefPolicy": (
                "fixed-base-layout"
                if is_base else
                "level-1-vehicle-camps"
                if fief.get("fiveStageRole") == "vehicle" else
                "slot3-academy-other-houses"
            ),
        })
    return {
        "baseHallUpgradeAllowed": False,
        "firstVehicleFiefHallUpgradeAllowed": False,
        "firstVehicleFiefCampUpgradeAllowed": False,
        "otherFiefHallUpgradeAllowed": True,
        "fiefs": priorities,
        "nextAction": cached.get("nextAction"),
        "updatedAt": cached.get("updatedAt"),
        "levelingPolicy": STARTER_LEVELING_POLICY,
    }


def starter_refresh_fief_buildings(sess: dict[str, Any]) -> dict[str, Any]:
    """Read every owned fief and produce the next safe starter building action.

    This planner never returns a hall upgrade. In a temporary fief it only
    builds a level-1 vehicle camp on an empty slot.
    """
    fief_ids = query_all_owned_fief_ids(sess)
    if not fief_ids:
        raise RuntimeError("未读取到当前账号封地")
    base_fief_id = int(next((
        general.get("fiefId") or general.get("placeID")
        for general in sess.get("generals") or []
        if "基地" in str(general.get("fiefName") or "")
    ), 0) or (sess.get("generals") or [{}])[0].get("fiefId") or 0)
    states: list[dict[str, Any]] = []
    base_actions: list[tuple[int, dict[str, Any]]] = []
    temporary_actions: list[dict[str, Any]] = []
    owned_heavy_infantry = int(
        starter_inventory_soldiers(sess).get("重步兵", 0)
    )
    role_state = sess.get("roleState") or {}
    role_level = int(
        role_state.get("level")
        or (sess.get("role") or {}).get("level")
        or 0
    )
    base_vehicle_bootstrap = dict(sess.get("starterBaseVehicleBootstrap") or {})
    bootstrap_active = bool(
        0 < role_level < 30
        and not base_vehicle_bootstrap.get("completed")
    )
    first_pack_opened = starter_first_pack_opened(sess)
    population_current = int(role_state.get("populationCurrent") or 0)
    for fief_id in fief_ids:
        state = query_fief_buildings(sess, fief_id)
        name = str(state.get("fiefName") or (sess.get("ownedFiefNames") or {}).get(str(fief_id)) or "")
        is_base = int(fief_id) == base_fief_id or "基地" in name
        buildings = list(state.get("buildings") or [])
        busy_count, capacity = fief_build_queue_state(state)
        item = {
            **state,
            "fiefName": name,
            "isBase": is_base,
            "busyQueueCount": busy_count,
            "queueCapacity": capacity,
            "hallPolicy": "never-upgrade",
            "fiefPolicy": "base-production" if is_base else "temporary-level-1-vehicle-camps",
        }
        states.append(item)
        if is_base and busy_count < capacity:
            infantry = next((
                row for row in buildings if int(row.get("type", -1)) == 4
            ), None)
            bow = next((
                row for row in buildings if int(row.get("type", -1)) == 5
            ), None)
            # 0x8246 只返回已有建筑，不会为未使用槽位返回 type=-1
            # 占位记录。与普通内政建筑流程保持一致，从 1..12 反推出空地。
            occupied_slots = {
                int(row.get("slot") or 0) for row in buildings
                if int(row.get("slot") or 0) > 0
            }
            empty_slots = [
                {"slot": slot, "type": -1, "busy": False}
                for slot in range(1, 13) if slot not in occupied_slots
            ]
            base_vehicle = next((
                row for row in buildings
                if int(row.get("type", -1)) == 6
            ), None)
            if bootstrap_active:
                if (
                    first_pack_opened
                    and base_vehicle is None
                    and empty_slots
                ):
                    slot = empty_slots[0]
                    base_actions.append((
                        -20,
                        {
                            "kind": "build-building",
                            "reason": "打开新手礼包后，基地只先建1座战车营",
                            "fiefId": int(fief_id),
                            "fiefName": name,
                            "slot": int(slot.get("slot") or 0),
                            "buildingType": 6,
                            "buildingName": "战车营",
                            "previousLevel": None,
                        },
                    ))
                # During this bootstrap, do not spend the base queue on infantry,
                # bow camps or houses before the 200-cart dungeon force is ready.
                continue
            houses = [
                row for row in buildings
                if int(row.get("type", -1)) == 1
            ]
            # populationCurrent is the currently usable population (not
            # cap-current). Expand houses only when fewer than one 200-man
            # recruitment batch is available.
            if 0 < population_current < 200:
                house = min(
                    (
                        row for row in houses
                        if not bool(row.get("busy"))
                    ),
                    key=lambda row: int(row.get("level") or 0),
                    default=None,
                )
                if house is not None:
                    base_actions.append((
                        2,
                        {
                            "kind": "upgrade-building",
                            "reason": (
                                "人口不足，优先升级基地房屋以保持持续招兵"
                            ),
                            "fiefId": int(fief_id),
                            "fiefName": name,
                            "slot": int(house.get("slot") or 0),
                            "buildingType": 1,
                            "buildingName": "房屋",
                            "previousLevel": int(house.get("level") or 0),
                        },
                    ))
            # First establish one infantry and one bow camp. Afterwards drive
            # infantry to level 7, then keep the lower-level one upgrading so
            # neither production line is starved indefinitely.
            for building_type, building_name, building in (
                (4, "步兵营", infantry),
                (5, "弓兵营", bow),
            ):
                if building is None and empty_slots:
                    slot = empty_slots.pop(0)
                    base_actions.append((
                        0 if building_type == 4 else 1,
                        {
                            "kind": "build-building",
                            "reason": f"基地建立持续招兵所需的{building_name}",
                            "fiefId": int(fief_id),
                            "fiefName": name,
                            "slot": int(slot.get("slot") or 0),
                            "buildingType": building_type,
                            "buildingName": building_name,
                            "previousLevel": None,
                        },
                    ))
            infantry_level = int((infantry or {}).get("level") or 0)
            bow_level = int((bow or {}).get("level") or 0)
            # Level 7 already unlocks heavy infantry. Before three 199-man
            # front lines (597, rounded to 600) exist, the infantry camp must
            # be left idle for recruitment instead of immediately consuming
            # its queue with level 8/9 upgrades.
            may_upgrade_infantry = (
                infantry_level < 7 or owned_heavy_infantry >= 600
            )
            if (
                infantry is not None
                and not bool(infantry.get("busy"))
                and may_upgrade_infantry
            ):
                base_actions.append((
                    10 if infantry_level < 7 else 30 + infantry_level,
                    {
                        "kind": "upgrade-building",
                        "reason": (
                            "优先把基地步兵营升到7级以解锁重步兵"
                            if infantry_level < 7
                            else "持续升级基地步兵营"
                        ),
                        "fiefId": int(fief_id),
                        "fiefName": name,
                        "slot": int(infantry.get("slot") or 0),
                        "buildingType": 4,
                        "buildingName": "步兵营",
                        "previousLevel": infantry_level,
                    },
                ))
            if (
                bow is not None
                and not bool(bow.get("busy"))
                and infantry_level >= 7
            ):
                # Once heavy infantry is unlocked, upgrade whichever production
                # building currently lags; the lower level gets lower priority.
                base_actions.append((
                    30 + bow_level,
                    {
                        "kind": "upgrade-building",
                        "reason": "持续升级基地弓兵营",
                        "fiefId": int(fief_id),
                        "fiefName": name,
                        "slot": int(bow.get("slot") or 0),
                        "buildingType": 5,
                        "buildingName": "弓兵营",
                        "previousLevel": bow_level,
                    },
                ))
        if not is_base and not bootstrap_active and busy_count < capacity:
            occupied_slots = {
                int(row.get("slot") or 0) for row in buildings
                if int(row.get("slot") or 0) > 0
            }
            empty_slot = next((
                {"slot": slot, "type": -1, "busy": False}
                for slot in range(1, 13) if slot not in occupied_slots
            ), None)
            if empty_slot:
                temporary_actions.append({
                    "kind": "build-building",
                    "reason": "临时封地空地只建1级战车营",
                    "fiefId": int(fief_id),
                    "fiefName": name,
                    "slot": int(empty_slot.get("slot") or 0),
                    "buildingType": 6,
                    "buildingName": "战车营",
                    "previousLevel": None,
                })
    # Base production is strategic: unlock heavy infantry first. Temporary
    # vehicle camps are filled whenever the base has no immediately safe step.
    next_action = (
        min(base_actions, key=lambda row: row[0])[1]
        if base_actions else
        (temporary_actions[0] if temporary_actions else None)
    )
    result = {
        "updatedAt": now_ms(),
        "baseFiefId": base_fief_id,
        "fiefCount": len(states),
        "hasTemporaryFief": any(not bool(row.get("isBase")) for row in states),
        "baseHallUpgradeAllowed": False,
        "temporaryFiefHallUpgradeAllowed": False,
        "temporaryFiefVehicleCampUpgradeAllowed": False,
        "fiefs": states,
        "nextAction": next_action,
    }
    sess["starterFiefBuildings"] = result
    return result


def starter_five_stage_fief_states(sess: dict[str, Any]) -> dict[str, Any]:
    """Refresh and classify the base, first vehicle fief and later house fiefs."""
    fief_ids = query_all_owned_fief_ids(sess)
    if not fief_ids:
        raise RuntimeError("未读取到当前账号封地")
    base_fief_id = int(next((
        general.get("fiefId") or general.get("placeID")
        for general in sess.get("generals") or []
        if "基地" in str(general.get("fiefName") or "")
    ), 0) or 0)
    states: list[dict[str, Any]] = []
    for fief_id in fief_ids:
        state = query_fief_buildings(sess, int(fief_id))
        name = str(
            state.get("fiefName")
            or (sess.get("ownedFiefNames") or {}).get(str(int(fief_id)))
            or ""
        )
        is_base = int(fief_id) == base_fief_id or "基地" in name
        if is_base and base_fief_id <= 0:
            base_fief_id = int(fief_id)
        busy_count, capacity = fief_build_queue_state(state)
        states.append({
            **state,
            "fiefId": int(fief_id),
            "fiefName": name,
            "isBase": is_base,
            "busyQueueCount": busy_count,
            "queueCapacity": capacity,
        })
    if base_fief_id <= 0:
        base_fief_id = int(states[0]["fiefId"])
        states[0]["isBase"] = True
    extras = [row for row in states if not row.get("isBase")]
    first_vehicle_fief_id = int(
        sess.get("starterFirstVehicleFiefId") or 0
    )
    if extras and first_vehicle_fief_id not in {
        int(row.get("fiefId") or 0) for row in extras
    }:
        first_vehicle_fief_id = int(extras[0].get("fiefId") or 0)
        sess["starterFirstVehicleFiefId"] = first_vehicle_fief_id
        persist_runtime_state()
    for row in states:
        row["fiveStageRole"] = (
            "base"
            if row.get("isBase") else
            "vehicle"
            if int(row.get("fiefId") or 0) == first_vehicle_fief_id else
            "house"
        )
    result = {
        "updatedAt": now_ms(),
        "baseFiefId": base_fief_id,
        "firstVehicleFiefId": first_vehicle_fief_id,
        "fiefCount": len(states),
        "fiefs": states,
    }
    sess["starterFiefBuildings"] = result
    return result


def starter_five_stage_required_fief_action(
    plan: dict[str, Any],
) -> dict[str, Any] | None:
    """Return one missing-layout action; optional upgrades are marked separately."""
    required_actions: list[dict[str, Any]] = []
    optional_actions: list[tuple[int, int, dict[str, Any]]] = []
    for fief in plan.get("fiefs") or []:
        role = str(fief.get("fiveStageRole") or "")
        buildings = list(fief.get("buildings") or [])
        by_slot = {
            int(row.get("slot") or 0): row
            for row in buildings if int(row.get("slot") or 0) > 0
        }
        busy_count = int(fief.get("busyQueueCount") or 0)
        capacity = max(1, int(fief.get("queueCapacity") or 1))
        if busy_count >= capacity:
            continue
        if role == "vehicle":
            for slot in range(1, 13):
                building = by_slot.get(slot)
                if building is None:
                    required_actions.append({
                        "kind": "build-building",
                        "reason": "第一个额外封地全部空地建1级战车营",
                        "fiefId": int(fief["fiefId"]),
                        "fiefName": fief.get("fiefName"),
                        "slot": slot,
                        "buildingType": 6,
                        "buildingName": "战车营",
                        "previousLevel": None,
                    })
                elif int(building.get("type", -1)) != 6:
                    required_actions.append({
                        "kind": "demolish-building",
                        "reason": "第一个额外封地清理非战车营建筑",
                        "fiefId": int(fief["fiefId"]),
                        "fiefName": fief.get("fiefName"),
                        "slot": slot,
                        "buildingType": int(building.get("type") or 0),
                        "buildingName": building.get("name"),
                        "previousLevel": int(building.get("level") or 0),
                    })
            continue
        if role != "house":
            continue
        for slot in range(1, 13):
            desired_type = 3 if slot == 3 else 1
            desired_name = "书院" if slot == 3 else "房屋"
            building = by_slot.get(slot)
            if building is None:
                required_actions.append({
                    "kind": "build-building",
                    "reason": (
                        "普通封地第3槽固定建书院"
                        if slot == 3 else
                        "普通封地其余空地全部建房屋"
                    ),
                    "fiefId": int(fief["fiefId"]),
                    "fiefName": fief.get("fiefName"),
                    "slot": slot,
                    "buildingType": desired_type,
                    "buildingName": desired_name,
                    "previousLevel": None,
                })
            elif int(building.get("type", -1)) != desired_type:
                required_actions.append({
                    "kind": "demolish-building",
                    "reason": f"普通封地第{slot}槽改建{desired_name}",
                    "fiefId": int(fief["fiefId"]),
                    "fiefName": fief.get("fiefName"),
                    "slot": slot,
                    "buildingType": int(building.get("type") or 0),
                    "buildingName": building.get("name"),
                    "previousLevel": int(building.get("level") or 0),
                })
        hall = next(
            (row for row in buildings if int(row.get("type", -1)) == 0),
            None,
        )
        if hall is not None and not bool(hall.get("busy")):
            optional_actions.append((
                0,
                int(hall.get("level") or 0),
                {
                    "kind": "upgrade-building",
                    "reason": "普通封地优先升级大厅",
                    "fiefId": int(fief["fiefId"]),
                    "fiefName": fief.get("fiefName"),
                    "slot": int(hall.get("slot") or 0),
                    "buildingType": 0,
                    "buildingName": "大厅",
                    "previousLevel": int(hall.get("level") or 0),
                    "optional": True,
                },
            ))
        for house in buildings:
            if int(house.get("type", -1)) == 1 and not bool(house.get("busy")):
                optional_actions.append((
                    1,
                    int(house.get("level") or 0),
                    {
                        "kind": "upgrade-building",
                        "reason": "普通封地大厅之后升级最低级房屋",
                        "fiefId": int(fief["fiefId"]),
                        "fiefName": fief.get("fiefName"),
                        "slot": int(house.get("slot") or 0),
                        "buildingType": 1,
                        "buildingName": "房屋",
                        "previousLevel": int(house.get("level") or 0),
                        "optional": True,
                    },
                ))
    if required_actions:
        return required_actions[0]
    if optional_actions:
        return min(optional_actions, key=lambda row: (row[0], row[1]))[2]
    return None


def execute_starter_five_stage_building_action(
    sess: dict[str, Any], action: dict[str, Any],
) -> dict[str, Any]:
    kind = str(action.get("kind") or "")
    if kind == "demolish-building":
        result = execute_demolish_building_action(
            sess,
            int(action["fiefId"]),
            int(action["slot"]),
            int(action["buildingType"]),
        )
    elif kind in {"build-building", "upgrade-building"}:
        previous = action.get("previousLevel")
        result = execute_building_action(
            sess,
            int(action["fiefId"]),
            int(action["slot"]),
            int(action["buildingType"]),
            previous_level=(
                int(previous) if previous is not None else None
            ),
        )
    else:
        raise RuntimeError(f"未知五阶段建筑动作：{kind}")
    return {
        "success": bool(result.get("success")),
        "message": (
            f"{action.get('fiefName') or '封地'}第{action.get('slot')}槽"
            f"{action.get('reason') or action.get('buildingName') or kind}"
            + ("已提交" if result.get("success") else "未确认")
        ),
        "buildingAction": action,
        "protocol": result,
    }


# Exact city ids returned by the captured world-city directory (0x6444).
# City ids are sparse; iterating arbitrary integers mostly produces status -9.
STARTER_TEMPORARY_FIEF_CITY_CANDIDATES = (
    609, 608, 571, 533, 607, 570, 532, 531, 606, 569, 530, 605,
    568, 529, 604, 567, 528, 493, 454, 492, 453, 452, 491, 451,
    490, 489, 450, 488, 449, 415, 414, 413, 412, 411, 410,
)


def starter_open_next_temporary_fief(sess: dict[str, Any]) -> dict[str, Any]:
    """Try one bounded city candidate and verify that a new owned fief exists."""
    before_ids = query_all_owned_fief_ids(sess)
    if len(before_ids) > 1:
        return {
            "success": True,
            "skipped": True,
            "message": "已有临时封地，不再重复开辟",
            "fiefIds": before_ids,
        }
    cursor = int(sess.get("starterTemporaryFiefCityCursor") or 0)
    city_id = STARTER_TEMPORARY_FIEF_CITY_CANDIDATES[
        cursor % len(STARTER_TEMPORARY_FIEF_CITY_CANDIDATES)
    ]
    sess["starterTemporaryFiefCityCursor"] = cursor + 1
    opened = starter_open_fief(
        sess, city_id, confirm="starter-open-fief",
    )
    time.sleep(1.0)
    after_ids = query_all_owned_fief_ids(sess)
    new_ids = [fief_id for fief_id in after_ids if fief_id not in before_ids]
    success = bool(new_ids)
    persist_runtime_state()
    return {
        "success": success,
        "message": (
            f"已在城池{city_id}开辟临时封地"
            if success else
            f"城池{city_id}未能开辟封地，下轮尝试其他城池"
        ),
        "cityId": city_id,
        "newFiefIds": new_ids,
        "beforeFiefIds": before_ids,
        "afterFiefIds": after_ids,
        "protocol": opened,
        "retryAfterSec": (
            600
            if not success
            and (cursor + 1) % len(STARTER_TEMPORARY_FIEF_CITY_CANDIDATES) == 0
            else 60
        ),
    }


def starter_open_next_required_fief(
    sess: dict[str, Any], target_total_fiefs: int,
) -> dict[str, Any]:
    """Open one additional fief until the level-derived total is reached."""
    before_ids = query_all_owned_fief_ids(sess)
    target_total = max(1, int(target_total_fiefs or 1))
    if len(before_ids) >= target_total:
        return {
            "success": True,
            "skipped": True,
            "message": f"当前已有{len(before_ids)}个封地，达到等级要求",
            "fiefIds": before_ids,
        }
    cursor = int(sess.get("starterTemporaryFiefCityCursor") or 0)
    city_id = STARTER_TEMPORARY_FIEF_CITY_CANDIDATES[
        cursor % len(STARTER_TEMPORARY_FIEF_CITY_CANDIDATES)
    ]
    sess["starterTemporaryFiefCityCursor"] = cursor + 1
    opened = starter_open_fief(
        sess, city_id, confirm="starter-open-fief",
    )
    time.sleep(1.0)
    after_ids = query_all_owned_fief_ids(sess)
    new_ids = [fief_id for fief_id in after_ids if fief_id not in before_ids]
    if new_ids and not int(sess.get("starterFirstVehicleFiefId") or 0):
        sess["starterFirstVehicleFiefId"] = int(new_ids[0])
    persist_runtime_state()
    return {
        "success": bool(new_ids),
        "message": (
            f"已开辟第{len(after_ids) - 1}个额外封地"
            if new_ids else
            f"城池{city_id}暂未开出封地，下轮继续换城池"
        ),
        "cityId": city_id,
        "newFiefIds": new_ids,
        "beforeFiefIds": before_ids,
        "afterFiefIds": after_ids,
        "targetTotalFiefs": target_total,
        "protocol": opened,
        "retryAfterSec": 60,
    }


def build_soldier_recruit_preview_payload(
    fief_id: int, soldier_type: int, count: int,
) -> bytes:
    """Captured 0x1248: q fiefId, i soldierType, i count, q reserved."""
    return struct.pack(">qiiq", int(fief_id), int(soldier_type), int(count), 0)


def build_soldier_recruit_payload(
    fief_id: int, soldier_type: int, count: int, *, urgent: bool = False,
) -> bytes:
    """Captured 0x123d: q fiefId, b average(-2), h type, i count, b urgent."""
    return struct.pack(
        ">qbh i b",
        int(fief_id), -2, int(soldier_type), int(count), 1 if urgent else 0,
    )


def query_soldier_recruit_preview(
    sess: dict[str, Any], fief_id: int, soldier_type: int, count: int,
) -> dict[str, Any]:
    payload = build_soldier_recruit_preview_payload(fief_id, soldier_type, count)
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1248, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((row for row in packets if packet_opcode(row) == 0x8248), None)
    raw = packet_payload_bytes(response) if response else b""
    text = printable(raw, 1000)
    camp_match = re.search(r"共有\s*(\d+)\s*个.+?营", text)
    average_match = re.search(r"平均每个.+?营可以招募\s*(\d+)\s*个", text)
    camp_count = int(camp_match.group(1)) if camp_match else 0
    average_count = int(average_match.group(1)) if average_match else 0
    return {
        "success": code == 200 and response is not None and "可以" in text,
        "http": code,
        "fiefId": int(fief_id),
        "soldierTypeCode": int(soldier_type),
        "soldierType": soldier_type_name(int(soldier_type)),
        "count": int(count),
        "message": text,
        "campCount": camp_count,
        "averagePerCamp": average_count,
        "estimatedCapacity": camp_count * average_count,
        "payloadHex": payload.hex(),
        "packets": summarize_packets(packets),
    }


def parse_recruit_duration_seconds(message: str) -> int:
    """Extract the server's H:MM:SS recruitment estimate."""
    matches = re.findall(r"(\d{1,3})\s*[:：]\s*(\d{1,2})\s*[:：]\s*(\d{1,2})", str(message or ""))
    if not matches:
        return 0
    hours, minutes, seconds = matches[-1]
    return int(hours) * 3600 + int(minutes) * 60 + int(seconds)


def parse_recruit_success_823d(raw: bytes) -> dict[str, Any]:
    """Parse the queue synchronization returned by a successful 0x823d.

    U1 reads: status, fief id, T5 block count, then that many T5 blocks.
    A newly-created T5 block contains one or more queue rows.  ``bn`` is the
    actual soldier count in that building's queue; it must not be inferred
    from the preview text.
    """
    if len(raw) < 13:
        return {"status": None, "fiefId": 0, "queues": [], "totalCount": 0}
    offset = 0
    status = struct.unpack_from(">b", raw, offset)[0]
    offset += 1
    fief_id = struct.unpack_from(">q", raw, offset)[0]
    offset += 8
    block_count = struct.unpack_from(">i", raw, offset)[0]
    offset += 4
    queues: list[dict[str, Any]] = []
    try:
        for _ in range(max(0, block_count)):
            action = struct.unpack_from(">b", raw, offset)[0]
            offset += 1
            owner_id = struct.unpack_from(">q", raw, offset)[0]
            offset += 8
            if action != 1:
                continue
            row_count = struct.unpack_from(">B", raw, offset)[0]
            offset += 1
            for _ in range(row_count):
                task_id = struct.unpack_from(">q", raw, offset)[0]
                offset += 8
                task_type = struct.unpack_from(">b", raw, offset)[0]
                offset += 1
                soldier_type = struct.unpack_from(">h", raw, offset)[0]
                offset += 2
                soldier_count = struct.unpack_from(">i", raw, offset)[0]
                offset += 4
                queue_count = struct.unpack_from(">i", raw, offset)[0]
                offset += 4
                duration_ms = struct.unpack_from(">q", raw, offset)[0]
                offset += 8
                queue_state = struct.unpack_from(">b", raw, offset)[0]
                offset += 1
                unit_duration_ms = struct.unpack_from(">i", raw, offset)[0]
                offset += 4
                queues.append({
                    "ownerId": owner_id,
                    "taskId": task_id,
                    "taskType": task_type,
                    "soldierTypeCode": soldier_type,
                    "count": soldier_count,
                    "queueCount": queue_count,
                    "durationMs": duration_ms,
                    "state": queue_state,
                    "unitDurationMs": unit_duration_ms,
                })
    except (IndexError, struct.error):
        return {
            "status": status,
            "fiefId": fief_id,
            "blockCount": block_count,
            "queues": queues,
            "totalCount": sum(max(0, int(row["count"])) for row in queues),
            "truncated": True,
        }
    return {
        "status": status,
        "fiefId": fief_id,
        "blockCount": block_count,
        "queues": queues,
        "totalCount": sum(max(0, int(row["count"])) for row in queues),
        "trailingBytes": max(0, len(raw) - offset - 16),
    }


def execute_soldier_recruit(
    sess: dict[str, Any],
    fief_id: int,
    soldier_type: int,
    count: int,
    *,
    confirm_delay_sec: float = 0.35,
    submit_preview_average: bool = False,
) -> dict[str, Any]:
    """Submit normal recruitment only; urgent recruitment is intentionally off."""
    sid = str(sess.get("sessionId") or "")
    # 0x1248 creates a short-lived quote consumed by 0x123d. Keep both
    # requests in one account transaction so a long map/reward request cannot
    # interleave and make the server return status=4 (quote timeout).
    with account_game_transaction_lock(sid):
        preview = query_soldier_recruit_preview(
            sess, fief_id, soldier_type, count,
        )
        if not preview.get("success"):
            return {
                "success": False,
                "message": preview.get("message") or "征兵条件检查未通过",
                "preview": preview,
            }
        # Normal recruitment confirms the desired total. The first vehicle
        # fief is different: its five-minute policy cares that every camp has
        # a queue, and the captured client confirms preview.averagePerCamp.
        # That response contains one queue block per eligible camp.
        camp_count = int(preview.get("campCount") or 0)
        per_camp_count = int(preview.get("averagePerCamp") or 0)
        submitted_count = int(count)
        if submit_preview_average and per_camp_count > 0:
            submitted_count = min(submitted_count, per_camp_count)
        payload_count = submitted_count
        if submitted_count <= 0 or payload_count <= 0:
            return {
                "success": False,
                "message": "当前兵营没有可用征兵容量",
                "preview": preview,
            }
        # Most established camps accept a prompt confirmation. A newly-built
        # single camp is different: the live server returns status=4 when its
        # 200-cart quote is confirmed immediately, while the captured client
        # flow succeeds after the confirmation dialog has remained open for
        # about eight seconds. Allow that route to opt into the captured wait
        # without slowing every later recruitment order.
        applied_confirm_delay_sec = max(0.0, float(confirm_delay_sec))
        time.sleep(applied_confirm_delay_sec)
        payload = build_soldier_recruit_payload(
            fief_id, soldier_type, payload_count, urgent=False,
        )
        code, _data, packets = post_game(
            sess["gameHttp"], [(0x123D, payload)], int(sess["dm"]),
            account_id=sid,
        )
    response = next((row for row in packets if packet_opcode(row) == 0x823D), None)
    raw = packet_payload_bytes(response) if response else b""
    status = struct.unpack(">b", raw[:1])[0] if raw else None
    parsed_success = parse_recruit_success_823d(raw) if raw else {}
    accepted_count = int(parsed_success.get("totalCount") or 0)
    queue_duration_sec = max(
        (
            int(row.get("durationMs") or 0) + 999
        ) // 1000
        for row in parsed_success.get("queues") or []
    ) if parsed_success.get("queues") else 0
    success = (
        code == 200 and response is not None and len(raw) >= 21
        and status == 0 and accepted_count > 0
    )
    status_messages = {
        1: "征兵资源不足",
        2: "征兵队列已满",
        3: "兵营已满",
        4: "征兵确认超时或尚未就绪",
    }
    return {
        "success": success,
        "message": (
            f"已普通招募{accepted_count}{soldier_type_name(int(soldier_type))}"
            if success else
            status_messages.get(
                status,
                f"招募{soldier_type_name(int(soldier_type))}未收到有效0x823d确认",
            )
        ),
        "status": status,
        "urgent": False,
        "fiefId": int(fief_id),
        "soldierTypeCode": int(soldier_type),
        "soldierType": soldier_type_name(int(soldier_type)),
        "requestedCount": int(count),
        "count": int(accepted_count),
        "submittedCount": int(submitted_count),
        "submittedPreviewAverage": bool(
            submit_preview_average and submitted_count < int(count)
        ),
        "campCount": camp_count,
        "perCampCount": payload_count,
        "confirmDelaySec": applied_confirm_delay_sec,
        # The confirmation may differ from the preview (as happened when an
        # old client submitted 16 after previewing 200). The accepted queue
        # synchronization is authoritative for the real completion time.
        "estimatedDurationSec": (
            queue_duration_sec
            or parse_recruit_duration_seconds(str(preview.get("message") or ""))
        ),
        "http": code,
        "payloadHex": payload.hex(),
        "responsePayloadHex": raw.hex(),
        "queueSync": parsed_success,
        "preview": preview,
        "packets": summarize_packets(packets),
    }


def refresh_session_inventory(sess: dict[str, Any]) -> dict[str, Any]:
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1104, b"\x00")], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((row for row in packets if packet_opcode(row) == 0x8104), None)
    if code != 200 or not response:
        raise RuntimeError("刷新宝库未收到0x8104")
    inventory = parse_8104_inventory(
        packet_payload_bytes(response), "0x1104/0x8104",
    )
    sess["inventory"] = inventory
    return inventory


def execute_recruit_speed_item(
    sess: dict[str, Any],
    fief_id: int,
    building_instance_id: int,
    item_id: int,
    *,
    quantity: int = 1,
) -> dict[str, Any]:
    """Captured 0x1240: q fief, h item, q recruit-building instance, h qty."""
    payload = struct.pack(
        ">qHqH",
        int(fief_id), int(item_id), int(building_instance_id), int(quantity),
    )
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1240, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((row for row in packets if packet_opcode(row) == 0x8240), None)
    raw = packet_payload_bytes(response) if response else b""
    # Verified captures return a full queue+inventory synchronization payload;
    # one-byte negative statuses are never accepted as success.
    success = code == 200 and response is not None and len(raw) >= 20
    return {
        "success": success,
        "message": (
            f"已使用{item_names_by_id().get(int(item_id), f'道具#{item_id}')}加速征兵"
            if success else "征兵加速未收到完整0x8240确认"
        ),
        "fiefId": int(fief_id),
        "buildingInstanceId": int(building_instance_id),
        "itemId": int(item_id),
        "itemName": item_names_by_id().get(int(item_id), f"道具#{item_id}"),
        "quantity": int(quantity),
        "http": code,
        "payloadHex": payload.hex(),
        "responsePayloadHex": raw.hex(),
        "packets": summarize_packets(packets),
    }


def execute_building_speed_item(
    sess: dict[str, Any],
    fief_id: int,
    building_instance_id: int,
    item_id: int,
    *,
    quantity: int = 1,
) -> dict[str, Any]:
    """DEX-confirmed buildItemUse opcode 0x1208, same q/H/q/H envelope."""
    payload = struct.pack(
        ">qHqH",
        int(fief_id), int(item_id), int(building_instance_id), int(quantity),
    )
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1208, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((row for row in packets if packet_opcode(row) == 0x8208), None)
    raw = packet_payload_bytes(response) if response else b""
    success = code == 200 and response is not None and len(raw) >= 1
    return {
        "success": success,
        "message": (
            f"已使用{item_names_by_id().get(int(item_id), f'道具#{item_id}')}加速建筑"
            if success else "建筑加速未收到0x8208确认"
        ),
        "fiefId": int(fief_id),
        "buildingInstanceId": int(building_instance_id),
        "itemId": int(item_id),
        "itemName": item_names_by_id().get(int(item_id), f"道具#{item_id}"),
        "quantity": int(quantity),
        "http": code,
        "payloadHex": payload.hex(),
        "responsePayloadHex": raw.hex(),
        "packets": summarize_packets(packets),
    }


def starter_building_speed_step(
    sess: dict[str, Any], plan: dict[str, Any],
) -> dict[str, Any]:
    base = next((row for row in plan.get("fiefs") or [] if row.get("isBase")), None)
    if not base:
        return {"success": True, "skipped": True, "message": "未找到基地建筑"}
    busy = next((
        row for row in base.get("buildings") or []
        if int(row.get("type", -1)) in {4, 5}
        and bool(row.get("busy"))
        and int(row.get("instanceId") or 0) > 0
    ), None)
    if not busy:
        return {"success": True, "skipped": True, "message": "步兵营和弓兵营没有升级任务"}
    inventory = refresh_session_inventory(sess)
    item_id = next((
        candidate for candidate in (26, 25, 24, 23, 22)
        if starter_inventory_item_count(inventory, candidate) > 0
    ), None)
    if item_id is None:
        return {"success": True, "skipped": True, "message": "暂无鲁公类建筑加速道具"}
    return execute_building_speed_item(
        sess,
        int(base.get("fiefId") or 0),
        int(busy.get("instanceId") or 0),
        item_id,
        quantity=1,
    )


def starter_building_has_recruit_queue(building: dict[str, Any]) -> bool:
    nested = building.get("nested") or {}
    return (
        int(nested.get("taskCount") or 0) > 0
        or bool(nested.get("tasks"))
    )


def starter_inventory_item_count(inventory: dict[str, Any], item_id: int) -> int:
    return sum(
        int(row.get("count") or row.get("amount") or 0)
        for row in inventory.get("items") or []
        if int(row.get("itemId") or -1) == int(item_id)
    )


def starter_select_recruit_speed_item(
    inventory: dict[str, Any], remaining_sec: int,
) -> int | None:
    """Use the smallest recruit order that can finish the current queue."""
    durations = {27: 3_600, 28: 18_000, 29: 36_000}
    available = [
        item_id for item_id in (27, 28, 29)
        if starter_inventory_item_count(inventory, item_id) > 0
    ]
    if not available:
        return None
    sufficient = [
        item_id for item_id in available
        if durations[item_id] >= max(1, int(remaining_sec or 0))
    ]
    if sufficient:
        return min(sufficient, key=lambda item_id: durations[item_id])
    return max(available, key=lambda item_id: durations[item_id])


def starter_affordable_recruit_batch(
    sess: dict[str, Any], desired_count: int, soldier_type: int,
) -> int:
    """Keep recruitment alive on low-resource starter accounts.

    A rejected large quote makes no progress and is especially harmful for
    temporary cart fiefs.  Submit a conservative rolling batch instead; the
    next scheduler pass will continue toward the persisted target.
    """
    desired = max(1, int(desired_count or 1))
    food = int((sess.get("roleState") or {}).get("food") or 0)
    if food <= 0:
        ceiling = 200
    elif food < 10_000:
        ceiling = 10
    elif food < 20_000:
        ceiling = 25
    elif food < 50_000:
        ceiling = 50
    else:
        ceiling = 200
    if int(soldier_type) == SOLDIER_TYPE_CODES["弩车"]:
        # Twelve simultaneous level-1 camps make a 200-cart quote large and
        # its confirmation repeatedly expired on the live server. Rolling
        # batches of at most 50 have been confirmed reliable and still
        # converge to the same persisted ~200 target.
        ceiling = min(ceiling, 50)
    return min(desired, ceiling)


def starter_base_vehicle_bootstrap_step(
    sess: dict[str, Any],
    plan: dict[str, Any],
) -> dict[str, Any]:
    """Build the exact early force requested for dungeon stages 1/2/3.

    The route is intentionally base-only and durable: one level-1 vehicle camp,
    one 200-cart target, then consume available recruit orders until the server
    confirms the carts in the base fief.
    """
    level = int(
        (sess.get("roleState") or {}).get("level")
        or (sess.get("role") or {}).get("level")
        or 0
    )
    state = dict(sess.get("starterBaseVehicleBootstrap") or {})
    if level <= 0 or level >= 30 or state.get("completed"):
        return {
            "success": True,
            "skipped": True,
            "completed": bool(state.get("completed")),
            "message": "基地200弩车启动阶段已完成或不适用",
            "state": state,
        }
    if not starter_first_pack_opened(sess):
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 10,
            "message": "等待先打开新手礼包，再建设基地战车营",
            "state": state,
        }
    base = next(
        (row for row in plan.get("fiefs") or [] if row.get("isBase")),
        None,
    )
    if not base:
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 10,
            "message": "等待读取基地建筑状态",
            "state": state,
        }
    camp = next((
        row for row in base.get("buildings") or []
        if int(row.get("type", -1)) == 6
    ), None)
    if camp is None or int(camp.get("level") or 0) < 1:
        return {
            "success": True,
            "skipped": True,
            "needsBuilding": True,
            "message": "等待在基地建成1座一级战车营",
            "state": state,
        }

    fief_id = int(base.get("fiefId") or 0)
    instance_id = int(camp.get("instanceId") or 0)
    soldier_type = SOLDIER_TYPE_CODES["弩车"]
    baseline = int(state.get("baselineBaseIdle") or 0)
    current_base_idle = starter_fief_idle_soldier_count(base, soldier_type)
    if not state.get("targetBaseIdle"):
        baseline = current_base_idle
        state.update({
            "fiefId": fief_id,
            "buildingInstanceId": instance_id,
            "baselineBaseIdle": baseline,
            "targetBaseIdle": baseline + 200,
            "targetCount": 200,
            "startedAt": now_ms(),
        })
    target_base_idle = int(state.get("targetBaseIdle") or (baseline + 200))

    def mark_completed(observed: int) -> dict[str, Any]:
        state.update({
            "completed": True,
            "completedAt": now_ms(),
            "observedBaseIdle": int(observed),
            "pending": {},
        })
        sess["starterBaseVehicleBootstrap"] = state
        persist_runtime_state()
        return {
            "success": True,
            "completed": True,
            "message": f"基地200弩车已准备完成：{observed}/{target_base_idle}",
            "state": state,
        }

    if current_base_idle >= target_base_idle:
        return mark_completed(current_base_idle)

    pending = dict(state.get("pending") or {})
    if pending:
        refreshed = query_fief_buildings(sess, fief_id)
        refreshed_camp = next((
            row for row in refreshed.get("buildings") or []
            if int(row.get("type", -1)) == 6
        ), camp)
        current_base_idle = starter_fief_idle_soldier_count(
            refreshed, soldier_type,
        )
        if current_base_idle >= target_base_idle:
            return mark_completed(current_base_idle)
        queue_progress = starter_fief_recruit_queue_progress(
            refreshed, soldier_type,
        )
        remaining_sec = max(
            0,
            (
                int(queue_progress.get("remainingMs") or 0) + 999
            ) // 1000,
        )
        if remaining_sec <= 0:
            remaining_sec = max(
                0,
                (
                    int(pending.get("readyAt") or 0) - now_ms() + 999
                ) // 1000,
            )
        if (
            starter_building_has_recruit_queue(refreshed_camp)
            or remaining_sec > 0
        ):
            inventory = refresh_session_inventory(sess)
            speed_item_id = starter_select_recruit_speed_item(
                inventory, max(1, remaining_sec),
            )
            if speed_item_id is not None:
                accelerated = execute_recruit_speed_item(
                    sess,
                    fief_id,
                    int(
                        pending.get("buildingInstanceId")
                        or refreshed_camp.get("instanceId")
                        or instance_id
                    ),
                    speed_item_id,
                    quantity=1,
                )
                if accelerated.get("success"):
                    reduced = {27: 3_600, 28: 18_000, 29: 36_000}[
                        speed_item_id
                    ]
                    pending["readyAt"] = max(
                        now_ms(),
                        int(pending.get("readyAt") or now_ms())
                        - reduced * 1000,
                    )
                    pending.setdefault("speedItems", []).append({
                        "itemId": speed_item_id,
                        "usedAt": now_ms(),
                        "reducedSec": reduced,
                    })
                    state["pending"] = pending
                    sess["starterBaseVehicleBootstrap"] = state
                    persist_runtime_state()
                return {
                    **accelerated,
                    "recruiting": True,
                    "bootstrap": True,
                    "state": state,
                }
            state["pending"] = pending
            sess["starterBaseVehicleBootstrap"] = state
            persist_runtime_state()
            return {
                "success": True,
                "deferred": True,
                "recruiting": True,
                "retryAfterSec": max(10, min(300, remaining_sec or 30)),
                "message": (
                    f"基地200弩车正在招募：{current_base_idle}/"
                    f"{target_base_idle}，暂无可用招募令"
                ),
                "state": state,
            }
        # The queue is gone but the exact target is not yet visible. Submit only
        # the missing tail; never start a second full 200-cart order.
        state["pending"] = {}

    missing = max(1, target_base_idle - current_base_idle)
    recruited = execute_soldier_recruit(
        sess,
        fief_id,
        soldier_type,
        missing,
        # Captured one-camp recruitment waited 8.2s between 0x1248 and
        # 0x123d. Immediate confirmation repeatedly returns status=4 on the
        # fresh base camp, so only this exact bootstrap route uses that wait.
        confirm_delay_sec=8.0,
    )
    if recruited.get("success"):
        duration_sec = max(
            30, int(recruited.get("estimatedDurationSec") or 0),
        )
        submitted_count = int(recruited.get("count") or missing)
        state["pending"] = {
            "count": submitted_count,
            "submittedAt": now_ms(),
            "readyAt": now_ms() + (duration_sec + 15) * 1000,
            "estimatedDurationSec": duration_sec,
            "buildingInstanceId": instance_id,
            "speedItems": [],
        }
        state["submittedTotal"] = (
            int(state.get("submittedTotal") or 0) + submitted_count
        )
        sess["starterBaseVehicleBootstrap"] = state
        persist_runtime_state()
    return {
        **recruited,
        "bootstrap": True,
        "message": (
            f"基地战车营已提交招募{submitted_count}弩车"
            if recruited.get("success")
            else recruited.get("message") or "基地200弩车招募未确认"
        ),
        "state": state,
    }


def starter_fief_idle_soldier_count(
    fief_state: dict[str, Any], soldier_type: int,
) -> int:
    """Read completed idle troops from 0x8246 list1, excluding recruit queues."""
    return sum(
        max(0, int(row.get("value", row.get("amount", row.get("count", 0))) or 0))
        for row in fief_state.get("list1") or []
        if int(row.get("type", row.get("soldierTypeCode", -1)) or -1)
        == int(soldier_type)
    )


def starter_fief_recruit_queue_progress(
    fief_state: dict[str, Any], soldier_type: int,
) -> dict[str, int]:
    """Summarize live T5 recruitment tasks embedded in 0x8246 buildings."""
    tasks = [
        task
        for building in fief_state.get("buildings") or []
        for task in (building.get("nested") or {}).get("tasks") or []
        if int(task.get("targetType", -1)) == int(soldier_type)
    ]
    return {
        "taskCount": len(tasks),
        "queuedCount": sum(
            max(0, int(task.get("target") or task.get("current") or 0))
            for task in tasks
        ),
        "remainingMs": max(
            [max(0, int(task.get("remainingMs") or 0)) for task in tasks]
            or [0]
        ),
    }


def starter_five_stage_base_building_action(
    plan: dict[str, Any],
) -> dict[str, Any] | None:
    """Return one base-layout action, preserving the level-1 cavalry camp."""
    base = next(
        (row for row in plan.get("fiefs") or [] if row.get("isBase")),
        None,
    )
    if not base:
        return None
    buildings = list(base.get("buildings") or [])
    by_slot = {
        int(row.get("slot") or 0): row
        for row in buildings if int(row.get("slot") or 0) > 0
    }
    busy_count = int(base.get("busyQueueCount") or 0)
    capacity = max(1, int(base.get("queueCapacity") or 1))
    if busy_count >= capacity:
        return None

    fixed_slots = {3: (3, "书院"), 4: (8, "骑兵营"), 11: (5, "弓兵营"), 12: (4, "步兵营")}
    for slot, (desired_type, desired_name) in fixed_slots.items():
        current = by_slot.get(slot)
        if current is None:
            return {
                "kind": "build-building",
                "reason": f"基地第{slot}槽固定新建{desired_name}",
                "fiefId": int(base["fiefId"]),
                "fiefName": base.get("fiefName"),
                "slot": slot,
                "buildingType": desired_type,
                "buildingName": desired_name,
                "previousLevel": None,
            }
        if int(current.get("type", -1)) != desired_type:
            return {
                "kind": "demolish-building",
                "reason": (
                    "基地第3槽先拆除原有1级农场"
                    if slot == 3 and int(current.get("type", -1)) == 2 else
                    f"基地第{slot}槽清理后改建{desired_name}"
                ),
                "fiefId": int(base["fiefId"]),
                "fiefName": base.get("fiefName"),
                "slot": slot,
                "buildingType": int(current.get("type") or 0),
                "buildingName": current.get("name"),
                "previousLevel": int(current.get("level") or 0),
            }
    for slot in range(1, 13):
        if slot in fixed_slots or slot in by_slot:
            continue
        return {
            "kind": "build-building",
            "reason": "基地其余空闲槽全部新建房屋",
            "fiefId": int(base["fiefId"]),
            "fiefName": base.get("fiefName"),
            "slot": slot,
            "buildingType": 1,
            "buildingName": "房屋",
            "previousLevel": None,
        }
    return None


def starter_five_stage_base_optional_upgrade(
    plan: dict[str, Any],
) -> dict[str, Any] | None:
    base = next(
        (row for row in plan.get("fiefs") or [] if row.get("isBase")),
        None,
    )
    if not base:
        return None
    if int(base.get("busyQueueCount") or 0) >= max(
        1, int(base.get("queueCapacity") or 1),
    ):
        return None
    candidates: list[tuple[int, int, dict[str, Any]]] = []
    for building in base.get("buildings") or []:
        building_type = int(building.get("type", -1))
        if bool(building.get("busy")):
            continue
        if building_type not in {1, 4, 5}:
            continue
        priority = 0 if building_type in {4, 5} else 1
        candidates.append((
            priority,
            int(building.get("level") or 0),
            {
                "kind": "upgrade-building",
                "reason": (
                    f"基地优先升级{BUILDING_TYPE_NAMES.get(building_type)}"
                    if priority == 0 else
                    "基地升级当前最低级房屋"
                ),
                "fiefId": int(base["fiefId"]),
                "fiefName": base.get("fiefName"),
                "slot": int(building.get("slot") or 0),
                "buildingType": building_type,
                "buildingName": BUILDING_TYPE_NAMES.get(building_type),
                "previousLevel": int(building.get("level") or 0),
                "optional": True,
            },
        ))
    return min(candidates, key=lambda row: (row[0], row[1]))[2] if candidates else None


def starter_five_stage_base_cavalry_step(
    sess: dict[str, Any], plan: dict[str, Any],
) -> dict[str, Any]:
    """Recruit exactly 200 extra light cavalry and use two ordinary orders."""
    base = next(
        (row for row in plan.get("fiefs") or [] if row.get("isBase")),
        None,
    )
    cavalry_camp = next((
        row for row in (base or {}).get("buildings") or []
        if int(row.get("slot") or 0) == 4
        and int(row.get("type", -1)) == 8
    ), None)
    if not base or not cavalry_camp:
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 10,
            "message": "等待基地第4槽1级骑兵营准备完成",
        }
    state = dict(sess.get("starterFiveStageBaseCavalry") or {})
    soldier_type = SOLDIER_TYPE_CODES["轻骑兵"]
    current_idle = starter_fief_idle_soldier_count(base, soldier_type)
    current_owned = int(
        starter_inventory_soldiers(sess).get("轻骑兵") or current_idle
    )
    if not state.get("targetBaseIdle"):
        state.update({
            "fiefId": int(base["fiefId"]),
            "buildingInstanceId": int(cavalry_camp.get("instanceId") or 0),
            "baselineBaseIdle": current_idle,
            "targetBaseIdle": current_idle + 200,
            "baselineOwned": current_owned,
            "targetCount": 200,
            "speedOrdersUsed": 0,
            "startedAt": now_ms(),
        })
    target_idle = int(state.get("targetBaseIdle") or current_idle + 200)
    if state.get("completed"):
        return {
            "success": True,
            "completed": True,
            "message": (
                "基地额外200轻骑兵历史记录已确认完成，"
                f"当前基地闲兵{current_idle}"
            ),
            "state": state,
        }
    if (
        current_idle >= target_idle
        and int(state.get("speedOrdersUsed") or 0) >= 2
    ):
        state.update({
            "completed": True,
            "completedAt": now_ms(),
            "observedBaseIdle": current_idle,
        })
        sess["starterFiveStageBaseCavalry"] = state
        persist_runtime_state()
        return {
            "success": True,
            "completed": True,
            "message": (
                f"基地额外200轻骑兵完成，已使用"
                f"{int(state.get('speedOrdersUsed') or 0)}/2个招募令"
            ),
            "state": state,
        }
    queue_progress = starter_fief_recruit_queue_progress(
        base, soldier_type,
    )
    queue_active = (
        starter_building_has_recruit_queue(cavalry_camp)
        or int(queue_progress.get("remainingMs") or 0) > 0
    )
    if queue_active:
        used = int(state.get("speedOrdersUsed") or 0)
        if used < 2:
            inventory = refresh_session_inventory(sess)
            ordinary_count = sum(
                int(row.get("count") or row.get("amount") or 0)
                for row in inventory.get("items") or []
                if int(row.get("itemId") or -1) == 27
            )
            if ordinary_count <= 0:
                state["waitingForOrdinaryRecruitOrder"] = True
                sess["starterFiveStageBaseCavalry"] = state
                persist_runtime_state()
                return {
                    "success": False,
                    "deferred": True,
                    "retryAfterSec": 300,
                    "message": f"轻骑兵正在招募，等待普通招募令加速({used}/2)",
                    "state": state,
                }
            accelerated = execute_recruit_speed_item(
                sess,
                int(base["fiefId"]),
                int(cavalry_camp.get("instanceId") or 0),
                27,
                quantity=1,
            )
            if accelerated.get("success"):
                state["speedOrdersUsed"] = used + 1
                state.setdefault("speedOrderActions", []).append({
                    "itemId": 27,
                    "usedAt": now_ms(),
                })
                sess["starterFiveStageBaseCavalry"] = state
                persist_runtime_state()
            return {
                **accelerated,
                "recruiting": True,
                "message": (
                    f"基地200轻骑兵已使用第{used + 1}个招募令加速"
                    if accelerated.get("success") else
                    "基地轻骑兵招募令加速未确认"
                ),
                "state": state,
            }
        remaining = max(
            10,
            min(
                300,
                (int(queue_progress.get("remainingMs") or 0) + 999) // 1000
                or 30,
            ),
        )
        return {
            "success": True,
            "deferred": True,
            "recruiting": True,
            "retryAfterSec": remaining,
            "message": "基地200轻骑兵正在招募，2个招募令已使用",
            "state": state,
        }
    if state.get("submittedAt"):
        refreshed = query_fief_buildings(sess, int(base["fiefId"]))
        observed = starter_fief_idle_soldier_count(refreshed, soldier_type)
        observed_owned = int(
            starter_inventory_soldiers(sess).get("轻骑兵") or observed
        )
        accepted_count = int(state.get("acceptedCount") or 0)
        speed_orders_used = int(state.get("speedOrdersUsed") or 0)
        # A completed queue means the server has produced the accepted order.
        # Idle-base count is not a valid completion condition because the same
        # scheduler immediately assigns those cavalry to generals and dispatches
        # them.  Requiring idle troops to stay at baseline+200 created a
        # permanent wait after successful recruitment.
        if accepted_count >= 200 and speed_orders_used >= 2:
            state.update({
                "completed": True,
                "observedBaseIdle": observed,
                "observedOwned": observed_owned,
                "completedAt": now_ms(),
                "confirmedBy": "accepted-order-and-empty-queue",
            })
            sess["starterFiveStageBaseCavalry"] = state
            persist_runtime_state()
            return {
                "success": True,
                "completed": True,
                "message": (
                    "基地200轻骑兵征兵队列已完成并使用2个招募令；"
                    f"当前闲兵{observed}、账号总轻骑兵{observed_owned}"
                ),
                "state": state,
            }
        return {
            "success": False,
            "deferred": True,
            "retryAfterSec": 30,
            "message": (
                "征兵队列已结束，但提交或加速记录不完整："
                f"已确认招募{accepted_count}/200，招募令{speed_orders_used}/2"
            ),
            "state": state,
        }
    recruited = execute_soldier_recruit(
        sess,
        int(base["fiefId"]),
        soldier_type,
        200,
        confirm_delay_sec=8.0,
    )
    immediate_speed_results: list[dict[str, Any]] = []
    if recruited.get("success"):
        state.update({
            "submittedAt": now_ms(),
            "acceptedCount": int(recruited.get("count") or 200),
            "estimatedDurationSec": int(
                recruited.get("estimatedDurationSec") or 0
            ),
        })
        # Use both ordinary recruit orders immediately while the fresh queue is
        # guaranteed to exist. Deferring them to later scheduler passes risks
        # observing an already-finished queue and can no longer satisfy the
        # user's exact two-order requirement.
        for _ in range(2):
            inventory = refresh_session_inventory(sess)
            ordinary_count = sum(
                int(row.get("count") or row.get("amount") or 0)
                for row in inventory.get("items") or []
                if int(row.get("itemId") or -1) == 27
            )
            if ordinary_count <= 0:
                break
            accelerated = execute_recruit_speed_item(
                sess,
                int(base["fiefId"]),
                int(cavalry_camp.get("instanceId") or 0),
                27,
                quantity=1,
            )
            immediate_speed_results.append(accelerated)
            if not accelerated.get("success"):
                break
            state["speedOrdersUsed"] = (
                int(state.get("speedOrdersUsed") or 0) + 1
            )
            state.setdefault("speedOrderActions", []).append({
                "itemId": 27,
                "usedAt": now_ms(),
            })
            time.sleep(0.25)
        sess["starterFiveStageBaseCavalry"] = state
        persist_runtime_state()
    return {
        **recruited,
        "message": (
            (
                "基地第4槽骑兵营已提交招募200轻骑兵，"
                f"立即使用{int(state.get('speedOrdersUsed') or 0)}/2个招募令"
            )
            if recruited.get("success") else
            recruited.get("message") or "基地200轻骑兵招募未确认"
        ),
        "state": state,
        "immediateSpeedOrders": immediate_speed_results,
    }


def starter_five_stage_assign_one_general(
    sess: dict[str, Any],
    *,
    minimum_count: int = 100,
) -> dict[str, Any]:
    """Make one more idle general deployable without starving other generals."""
    generals = refresh_generals(sess)
    light_cavalry = SOLDIER_TYPE_CODES["轻骑兵"]
    idle_cavalry = int(idle_soldier_counts(sess).get(light_cavalry, 0))

    def cavalry_count(general: dict[str, Any]) -> int:
        current_type = soldier_type_code(
            general.get("soldierTypeCode")
            if general.get("soldierTypeCode") is not None
            else general.get("soldierType")
        )
        if current_type != light_cavalry:
            return 0
        return int(
            general.get("soldierCount")
            or general.get("currentSoldierCount")
            or 0
        )

    idle_eligible = [
        row for row in generals
        if (row.get("displayStatus") or row.get("statusText") or "未知") == "闲"
        and int(row.get("troopLimit") or row.get("daiBingLimit") or 0)
        >= int(minimum_count)
    ]
    ready_100 = [
        row for row in idle_eligible
        if int(row.get("troopLimit") or row.get("daiBingLimit") or 0) >= 100
        and cavalry_count(row) >= 100
    ]
    ready_190 = [
        row for row in idle_eligible
        if int(row.get("troopLimit") or row.get("daiBingLimit") or 0) >= 190
        and cavalry_count(row) >= 190
    ]

    if int(minimum_count) >= 190:
        assignment_candidates = [
            (row, 190)
            for row in idle_eligible
            if int(row.get("troopLimit") or row.get("daiBingLimit") or 0) >= 190
            and cavalry_count(row) < 190
            and idle_cavalry + cavalry_count(row) >= 190
        ]
    else:
        # First create as many 100-cavalry teams as possible. Only after every
        # currently affordable general has a usable team do we spend another
        # 90 cavalry upgrading a high-capacity general for level-3 bandits.
        bootstrap = [
            (row, 100)
            for row in idle_eligible
            if cavalry_count(row) < 100
            and idle_cavalry + cavalry_count(row) >= 100
        ]
        upgrades = [
            (row, 190)
            for row in idle_eligible
            if int(row.get("troopLimit") or row.get("daiBingLimit") or 0) >= 190
            and 100 <= cavalry_count(row) < 190
            and idle_cavalry + cavalry_count(row) >= 190
        ]
        assignment_candidates = bootstrap or upgrades

    if not assignment_candidates:
        return {
            "success": True,
            "skipped": True,
            "troopShortage": bool(idle_eligible),
            "ready100GeneralCount": len(ready_100),
            "ready190GeneralCount": len(ready_190),
            "message": (
                f"当前{len(ready_100)}名将领满足100轻骑兵条件，"
                f"其中{len(ready_190)}名满足190轻骑兵条件"
            ),
        }
    chosen, target_count = max(
        assignment_candidates,
        key=lambda row: starter_rear_general_score(row[0]),
    )
    assigned = execute_assign_troops(
        sess,
        str(chosen.get("id") or chosen.get("idHex") or ""),
        "轻骑兵",
        target_count,
        confirm="assign-troops",
    )
    return {
        **assigned,
        "message": (
            f"已给{chosen.get('name') or chosen.get('id')}配置"
            f"{target_count}轻骑兵"
            if assigned.get("success") else
            assigned.get("message") or f"{target_count}轻骑兵配兵未确认"
        ),
        "general": starter_general_ref(chosen),
        "targetCavalryCount": target_count,
        "ready100GeneralCountBefore": len(ready_100),
        "ready190GeneralCountBefore": len(ready_190),
    }


def starter_plan_owned_soldier_count(
    plan: dict[str, Any], soldier_type: int,
) -> int:
    """Count idle+assigned troops from refreshed 0x8246 fief lists."""
    return sum(
        max(0, int(row.get("value", row.get("amount", row.get("count", 0))) or 0))
        for fief in plan.get("fiefs") or []
        for list_name in ("list1", "list2")
        for row in fief.get(list_name) or []
        if int(row.get("type", row.get("soldierTypeCode", -1)) or -1)
        == int(soldier_type)
    )


def execute_starter_abandon_temporary_fief(
    sess: dict[str, Any], fief_id: int, *, base_fief_id: int,
) -> dict[str, Any]:
    """Captured fiefRemove opcode 0x1213 with q fiefId; verify ownership removal."""
    if int(fief_id) <= 0 or int(fief_id) == int(base_fief_id):
        raise RuntimeError("安全规则阻止放弃基地或无效封地")
    recruitment_states_before = dict(sess.get("starterRecruitmentStates") or {})
    pending_recruitment = next((
        dict(state or {})
        for state in recruitment_states_before.values()
        if int((state or {}).get("fiefId") or 0) == int(fief_id)
        and int((state or {}).get("soldierTypeCode") or -1)
        == SOLDIER_TYPE_CODES["弩车"]
    ), {})
    before_ids = query_all_owned_fief_ids(sess)
    if int(fief_id) not in before_ids:
        return {
            "success": True,
            "alreadyRemoved": True,
            "message": "临时封地已不存在",
            "beforeFiefIds": before_ids,
        }
    payload = struct.pack(">q", int(fief_id))
    code, _data, packets = post_game(
        sess["gameHttp"], [(0x1213, payload)], int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((row for row in packets if packet_opcode(row) == 0x8213), None)
    time.sleep(1.0)
    after_ids = query_all_owned_fief_ids(sess)
    success = int(fief_id) not in after_ids
    transfer_check: dict[str, Any] = {}
    if success:
        submitted = dict(sess.get("starterTemporaryFiefRecruitSubmitted") or {})
        submitted.pop(str(int(fief_id)), None)
        sess["starterTemporaryFiefRecruitSubmitted"] = submitted
        recruitment_states = dict(sess.get("starterRecruitmentStates") or {})
        for key, state in list(recruitment_states.items()):
            if int((state or {}).get("fiefId") or 0) == int(fief_id):
                recruitment_states.pop(key, None)
        sess["starterRecruitmentStates"] = recruitment_states
        try:
            refresh_generals(sess)
            observed_total = int(
                starter_inventory_soldiers(sess).get("弩车", 0)
            )
            baseline_total = int(
                pending_recruitment.get("baselineOwnedTotal") or 0
            )
            recruited_count = int(pending_recruitment.get("count") or 0)
            expected_total = baseline_total + recruited_count
            transfer_check = {
                "baselineOwnedTotal": baseline_total,
                "recruitedCount": recruited_count,
                "expectedMinimumTotal": expected_total,
                "observedOwnedTotal": observed_total,
                "confirmed": (
                    expected_total > 0 and observed_total >= expected_total
                ),
            }
        except Exception as exc:
            transfer_check = {
                "confirmed": False,
                "error": str(exc),
            }
        pending_transfers = dict(sess.get("starterPendingTransferChecks") or {})
        transfer_key = str(int(fief_id))
        if transfer_check.get("confirmed"):
            pending_transfers.pop(transfer_key, None)
        else:
            baseline_total = int(
                pending_recruitment.get("baselineOwnedTotal") or 0
            )
            recruited_count = int(pending_recruitment.get("count") or 0)
            pending_transfers[transfer_key] = {
                "fiefId": int(fief_id),
                "baselineOwnedTotal": baseline_total,
                "recruitedCount": recruited_count,
                "expectedMinimumTotal": baseline_total + recruited_count,
                "createdAt": now_ms(),
                "lastCheck": transfer_check,
            }
        sess["starterPendingTransferChecks"] = pending_transfers
        persist_runtime_state()
    return {
        "success": success,
        "message": (
            (
                f"已放弃临时封地{fief_id}，"
                + (
                    f"已确认{transfer_check.get('recruitedCount')}弩车转回基地"
                    if transfer_check.get("confirmed")
                    else "封地已移除，但弩车总量尚未达到预期，已记录核查"
                )
            )
            if success else
            f"放弃临时封地{fief_id}未通过封地列表确认"
        ),
        "fiefId": int(fief_id),
        "baseFiefId": int(base_fief_id),
        "http": code,
        "payloadHex": payload.hex(),
        "responseOpcode": (
            f"0x{int(packet_opcode(response)):04x}" if response else None
        ),
        "responsePayloadHex": packet_payload_bytes(response).hex() if response else "",
        "beforeFiefIds": before_ids,
        "afterFiefIds": after_ids,
        "transferCheck": transfer_check,
        "packets": summarize_packets(packets),
    }


def starter_verify_pending_transfers(sess: dict[str, Any]) -> dict[str, Any]:
    pending = dict(sess.get("starterPendingTransferChecks") or {})
    if not pending:
        return {
            "success": True,
            "skipped": True,
            "confirmed": True,
            "message": "没有待确认的弃地转兵",
        }
    refresh_generals(sess)
    observed_total = int(starter_inventory_soldiers(sess).get("弩车", 0))
    confirmed_keys: list[str] = []
    for key, raw_check in list(pending.items()):
        check = dict(raw_check or {})
        expected = int(check.get("expectedMinimumTotal") or 0)
        if expected > 0 and observed_total >= expected:
            confirmed_keys.append(key)
            continue
        check["lastCheckedAt"] = now_ms()
        check["observedOwnedTotal"] = observed_total
        pending[key] = check
    for key in confirmed_keys:
        pending.pop(key, None)
    sess["starterPendingTransferChecks"] = pending
    persist_runtime_state()
    if pending:
        expected = max(
            int((check or {}).get("expectedMinimumTotal") or 0)
            for check in pending.values()
        )
        return {
            "success": True,
            "skipped": True,
            "confirmed": False,
            "retryAfterSec": 30,
            "message": (
                f"弃地已完成，等待弩车转回基地确认："
                f"{observed_total}/{expected}，暂不开新封地"
            ),
            "observedOwnedTotal": observed_total,
            "expectedMinimumTotal": expected,
            "pending": list(pending.values()),
        }
    return {
        "success": True,
        "confirmed": True,
        "message": f"已确认弃地弩车转回基地，当前共有{observed_total}弩车",
        "observedOwnedTotal": observed_total,
        "confirmedFiefIds": [int(key) for key in confirmed_keys],
    }


def starter_recruitment_step(
    sess: dict[str, Any], plan: dict[str, Any],
) -> dict[str, Any]:
    """Run one recruitment or recruitment-speed step, temporary fief first."""
    fiefs = list(plan.get("fiefs") or [])
    temporary = next((row for row in fiefs if not row.get("isBase")), None)
    base = next((row for row in fiefs if row.get("isBase")), None)
    recruitment_states = dict(sess.get("starterRecruitmentStates") or {})
    base_infantry = next((
        row for row in (base or {}).get("buildings") or []
        if int(row.get("type", -1)) == 4
        and int(row.get("level") or 0) >= 7
        and not bool(row.get("busy"))
    ), None)
    base_heavy_state_key = (
        f"{int((base or {}).get('fiefId') or 0)}:"
        f"{SOLDIER_TYPE_CODES['重步兵']}"
    )
    role_state = sess.get("roleState") or {}
    known_population = int(role_state.get("populationCurrent") or 0)
    available_population = known_population if known_population > 0 else 200
    base_can_start_recruit = bool(
        base_infantry
        and available_population >= 50
        and not recruitment_states.get(base_heavy_state_key)
        and not starter_building_has_recruit_queue(base_infantry)
    )

    candidates: list[tuple[dict[str, Any], dict[str, Any], int, int]] = []
    if temporary:
        temporary_buildings = list(temporary.get("buildings") or [])
        occupied_slots = {
            int(row.get("slot") or 0) for row in temporary_buildings
            if int(row.get("slot") or 0) > 0
        }
        # 先把临时封地全部空地建成一级战车营，再开始约200弩车的
        # 招募闭环；这样不会因为第一座战车营刚完成就提前征兵、弃地。
        temporary_filled = all(slot in occupied_slots for slot in range(1, 13))
        vehicle = next((
            row for row in temporary_buildings
            if int(row.get("type", -1)) == 6
            and int(row.get("level") or 0) >= 1
            and not bool(row.get("busy"))
        ), None)
        if vehicle and temporary_filled:
            fief_id = int(temporary.get("fiefId") or 0)
            state_key = f"{fief_id}:{SOLDIER_TYPE_CODES['弩车']}"
            pending = dict(recruitment_states.get(state_key) or {})
            if pending:
                if int(pending.get("baselineOwnedTotal") or 0) <= 0:
                    pending["baselineOwnedTotal"] = max(
                        int(starter_inventory_soldiers(sess).get("弩车", 0)),
                        starter_plan_owned_soldier_count(
                            plan, SOLDIER_TYPE_CODES["弩车"],
                        ),
                    )
                    recruitment_states[state_key] = pending
                    sess["starterRecruitmentStates"] = recruitment_states
                    persist_runtime_state()
                ready_at = int(pending.get("readyAt") or 0)
                if now_ms() < ready_at:
                    remaining = max(1, (ready_at - now_ms() + 999) // 1000)
                    pending_count = int(pending.get("count") or 0)
                    waiting_result = {
                        "success": True,
                        "skipped": True,
                        "recruiting": True,
                        "retryAfterSec": min(300, remaining),
                        "message": (
                            f"临时封地正在普通招募{pending_count}弩车，"
                            f"约{remaining}秒后完成"
                        ),
                        "state": pending,
                        "baseRecruitDiagnostic": {
                            "canStart": base_can_start_recruit,
                            "hasInfantry": bool(base_infantry),
                            "availablePopulation": available_population,
                            "hasPendingHeavy": bool(
                                recruitment_states.get(base_heavy_state_key)
                            ),
                            "hasInfantryQueue": bool(
                                starter_building_has_recruit_queue(
                                    base_infantry or {},
                                )
                            ),
                        },
                    }
                    # Temporary and base camps are independent. A cart queue
                    # must never prevent an idle level-7 infantry camp from
                    # starting heavy-infantry recruitment.
                    if base_can_start_recruit:
                        return starter_recruitment_step(
                            sess,
                            {
                                **plan,
                                "fiefs": [base],
                                "hasTemporaryFief": False,
                            },
                        )
                    return waiting_result
                # A local timer is not proof that recruitment completed. Read
                # the temporary fief's 0x8246 idle-soldier list and only
                # abandon after the expected carts are actually present.
                refreshed_fief = query_fief_buildings(sess, fief_id)
                queue_progress = starter_fief_recruit_queue_progress(
                    refreshed_fief, SOLDIER_TYPE_CODES["弩车"],
                )
                if int(queue_progress.get("remainingMs") or 0) > 0:
                    remaining = max(
                        1,
                        (int(queue_progress["remainingMs"]) + 999) // 1000,
                    )
                    pending["count"] = max(
                        int(pending.get("count") or 0),
                        int(queue_progress.get("queuedCount") or 0),
                    )
                    pending["readyAt"] = now_ms() + remaining * 1000
                    recruitment_states[state_key] = pending
                    sess["starterRecruitmentStates"] = recruitment_states
                    persist_runtime_state()
                    waiting_result = {
                        "success": True,
                        "skipped": True,
                        "recruiting": True,
                        "retryAfterSec": min(300, remaining),
                        "message": (
                            f"临时封地弩车队列尚未完成："
                            f"已接受{queue_progress.get('queuedCount')}，"
                            f"约{remaining}秒后完成"
                        ),
                        "state": pending,
                        "queueProgress": queue_progress,
                    }
                    if base_can_start_recruit:
                        return starter_recruitment_step(
                            sess,
                            {
                                **plan,
                                "fiefs": [base],
                                "hasTemporaryFief": False,
                            },
                        )
                    return waiting_result
                completed_count = starter_fief_idle_soldier_count(
                    refreshed_fief, SOLDIER_TYPE_CODES["弩车"],
                )
                expected_count = int(pending.get("count") or 0)
                if expected_count <= 0 or completed_count < expected_count:
                    waiting_result = {
                        "success": True,
                        "skipped": True,
                        "recruiting": True,
                        "retryAfterSec": 30,
                        "message": (
                            "本地征兵计时已结束，但服务器尚未确认弩车完成："
                            f"{completed_count}/{expected_count}，暂不放弃封地"
                        ),
                        "state": pending,
                        "serverCompletedCount": completed_count,
                        "serverCompletionConfirmed": False,
                    }
                    if base_can_start_recruit:
                        return starter_recruitment_step(
                            sess,
                            {
                                **plan,
                                "fiefs": [base],
                                "hasTemporaryFief": False,
                            },
                        )
                    return waiting_result
                target_count = max(1, int(pending.get("targetCount") or 200))
                # “约200”允许因多兵营平均分配产生少量尾差。若这次只
                # 招到了很少数量（例如曾误把每营均值作为总量提交），
                # 保留封地并继续补招，绝不能直接弃地。
                minimum_to_abandon = max(1, int(target_count * 0.9))
                if completed_count < minimum_to_abandon:
                    recruitment_states.pop(state_key, None)
                    sess["starterRecruitmentStates"] = recruitment_states
                    persist_runtime_state()
                    candidates.append((
                        temporary,
                        vehicle,
                        SOLDIER_TYPE_CODES["弩车"],
                        starter_affordable_recruit_batch(
                            sess,
                            max(1, target_count - completed_count),
                            SOLDIER_TYPE_CODES["弩车"],
                        ),
                    ))
                else:
                    return execute_starter_abandon_temporary_fief(
                        sess,
                        fief_id,
                        base_fief_id=int((base or {}).get("fiefId") or plan.get("baseFiefId") or 0),
                    )
            else:
                candidates.append((
                    temporary,
                    vehicle,
                    SOLDIER_TYPE_CODES["弩车"],
                    starter_affordable_recruit_batch(
                        sess, 200, SOLDIER_TYPE_CODES["弩车"],
                    ),
                ))
    if base_infantry and available_population >= 50:
        # A fresh account often has too little grain for a 200-man order.
        # Keep recruitment moving in affordable 50-man batches rather than
        # repeatedly submitting a large quote that the server rejects.
        heavy_batch_count = starter_affordable_recruit_batch(
            sess, 200, SOLDIER_TYPE_CODES["重步兵"],
        )
        # Heavy infantry is the limiting frontline resource, so when both the
        # temporary cart fief and base are ready, start the base queue first.
        candidates.insert(
            0,
            (
                base, base_infantry,
                SOLDIER_TYPE_CODES["重步兵"], heavy_batch_count,
            ),
        )
    if not candidates:
        return {
            "success": True,
            "skipped": True,
            "message": "尚无可招募弩车或重步兵的兵营",
        }

    # Both sites can recruit independently. Alternation prevents accelerated
    # heavy-infantry queues from monopolising every scheduler pass and leaving
    # the temporary fief stuck forever at its first cart batch.
    candidate_types = {int(row[2]) for row in candidates}
    last_type = int(sess.get("starterLastRecruitTypeCode") or -1)
    preferred_type = (
        SOLDIER_TYPE_CODES["弩车"]
        if last_type == SOLDIER_TYPE_CODES["重步兵"]
        else SOLDIER_TYPE_CODES["重步兵"]
    )
    selected_candidate = (
        next(
            (row for row in candidates if int(row[2]) == preferred_type),
            candidates[0],
        )
        if len(candidate_types) > 1
        else candidates[0]
    )
    # If one site already has a live queue, use this pass to start the other
    # site rather than returning early just to report the first queue's timer.
    # This is what makes “招兵不要停” true for both fiefs.
    idle_candidates = [
        row for row in candidates
        if not recruitment_states.get(
            f"{int(row[0].get('fiefId') or 0)}:{int(row[2])}"
        )
        and not starter_building_has_recruit_queue(row[1])
    ]
    if idle_candidates:
        selected_candidate = next(
            (
                row for row in idle_candidates
                if int(row[2]) == preferred_type
            ),
            idle_candidates[0],
        )
    fief, building, soldier_type, count = selected_candidate
    fief_id = int(fief.get("fiefId") or 0)
    instance_id = int(building.get("instanceId") or 0)
    state_key = f"{fief_id}:{soldier_type}"
    pending = dict(recruitment_states.get(state_key) or {})
    if pending:
        ready_at = int(pending.get("readyAt") or 0)
        if now_ms() < ready_at:
            # 重步兵要尽快形成199前排。基地只有一个步兵营，招募令可
            # 精确作用于这个队列；按高级→普通顺序持续加速。
            if not bool(pending.get("temporary")):
                inventory = refresh_session_inventory(sess)
                speed_item_id = starter_select_recruit_speed_item(
                    inventory,
                    max(1, (ready_at - now_ms() + 999) // 1000),
                )
                if speed_item_id is not None:
                    accelerated = execute_recruit_speed_item(
                        sess,
                        fief_id,
                        int(pending.get("buildingInstanceId") or instance_id),
                        speed_item_id,
                        quantity=1,
                    )
                    if accelerated.get("success"):
                        speed_seconds = {29: 36_000, 28: 18_000, 27: 3_600}[speed_item_id]
                        pending["readyAt"] = max(
                            now_ms(), ready_at - speed_seconds * 1000,
                        )
                        pending.setdefault("speedItems", []).append({
                            "itemId": speed_item_id,
                            "usedAt": now_ms(),
                            "reducedSec": speed_seconds,
                        })
                        recruitment_states[state_key] = pending
                        sess["starterRecruitmentStates"] = recruitment_states
                        persist_runtime_state()
                    return {
                        **accelerated,
                        "recruiting": True,
                        "state": pending,
                    }
            remaining = max(1, (ready_at - now_ms() + 999) // 1000)
            return {
                "success": True,
                "skipped": True,
                "recruiting": True,
                "retryAfterSec": min(300, remaining),
                "message": f"{soldier_type_name(soldier_type)}正在普通招募，约{remaining}秒后完成",
                "state": pending,
            }
        recruitment_states.pop(state_key, None)
        sess["starterRecruitmentStates"] = recruitment_states
        persist_runtime_state()
    if starter_building_has_recruit_queue(building):
        inventory = refresh_session_inventory(sess)
        speed_item_id = starter_select_recruit_speed_item(inventory, 3600)
        if speed_item_id is None:
            return {
                "success": True,
                "skipped": True,
                "message": f"{soldier_type_name(soldier_type)}正在招募，暂无招募令可加速",
            }
        return execute_recruit_speed_item(
            sess, fief_id, instance_id, speed_item_id, quantity=1,
        )
    recruited = execute_soldier_recruit(
        sess, fief_id, soldier_type, count,
    )
    if recruited.get("success"):
        duration_sec = max(30, int(recruited.get("estimatedDurationSec") or 0))
        submitted_count = int(recruited.get("count") or count)
        recruitment_states[state_key] = {
            "fiefId": fief_id,
            "soldierTypeCode": int(soldier_type),
            "soldierType": soldier_type_name(soldier_type),
            "count": submitted_count,
            "targetCount": 200 if temporary is fief else submitted_count,
            "submittedAt": now_ms(),
            # A small cushion avoids abandoning on the exact server boundary.
            "readyAt": now_ms() + (duration_sec + 15) * 1000,
            "estimatedDurationSec": duration_sec,
            "temporary": temporary is fief,
            "buildingInstanceId": instance_id,
            "baselineOwnedTotal": int(
                max(
                    int(starter_inventory_soldiers(sess).get(
                        soldier_type_name(soldier_type), 0,
                    )),
                    starter_plan_owned_soldier_count(plan, soldier_type),
                )
            ),
        }
        sess["starterRecruitmentStates"] = recruitment_states
        sess["starterLastRecruitTypeCode"] = int(soldier_type)
        # Preserve the old marker for UI/backward compatibility.
        if temporary is fief:
            submitted = dict(sess.get("starterTemporaryFiefRecruitSubmitted") or {})
            submitted[str(fief_id)] = (
                int(submitted.get(str(fief_id)) or 0) + submitted_count
            )
            sess["starterTemporaryFiefRecruitSubmitted"] = submitted
        persist_runtime_state()
    return recruited


def starter_execute_next_building_action(
    sess: dict[str, Any], *, confirm: str = "",
) -> dict[str, Any]:
    if confirm != "starter-building-next":
        raise RuntimeError("执行起号建筑计划需要明确确认")
    plan = starter_refresh_fief_buildings(sess)
    action = plan.get("nextAction")
    if not action:
        return {"success": True, "skipped": True, "message": "当前没有可安全执行的建筑动作", "plan": plan}
    if int(action.get("buildingType", -1)) == 0 and int(action.get("fiefId") or 0) == int(plan.get("baseFiefId") or 0):
        raise RuntimeError("安全规则阻止升级基地大厅")
    if int(action.get("buildingType", -1)) == 0:
        raise RuntimeError("安全规则阻止升级临时封地大厅")
    if int(action.get("buildingType", -1)) == 6 and action.get("previousLevel") is not None:
        raise RuntimeError("安全规则阻止升级临时封地战车营")
    previous_level = action.get("previousLevel")
    result = execute_building_action(
        sess,
        int(action["fiefId"]),
        int(action["slot"]),
        int(action["buildingType"]),
        previous_level=(int(previous_level) if previous_level is not None else None),
    )
    return {
        "success": bool(result.get("success")),
        "message": (
            f"已提交{action.get('fiefName') or '临时封地'}{action.get('buildingName') or '建筑'}建造"
            if result.get("success") else "临时封地战车营建造未确认"
        ),
        "action": action,
        "result": result,
    }


